type ServerPacketRecord = Record<string, unknown>;

interface WorldBlockReconciliationOptions {
  authoritative_pending?: boolean;
  reason?: unknown;
}

interface WorldPersistenceOwnership {
  require_owner: boolean;
  server_instance: string;
  ownership_token: string;
  ownership_epoch: number;
  fallback: boolean;
  verified: boolean;
}

interface WorldUnpersistedRevision {
  revision: number;
  ownership_token: string;
  ownership_epoch: number;
}

interface WorldMutationRollback {
  existed: boolean;
  state: ServerPacketRecord;
  unpersisted: WorldUnpersistedRevision | null;
}

interface WorldSaveOptions {
  critical?: boolean;
  mutation?: boolean;
  reason?: unknown;
  // Marks a save whose only content is regenerating machine state (oil refineries,
  // battery chargers, livestock). No inventory is coupled to it, so it may be coalesced
  // through the debounce even while PostgreSQL is authoritative. Never set this on a path
  // that also commits inventory.
  coalesce?: boolean;
}

interface WorldLoadedAuthority {
  server_instance: string;
  ownership_token: string;
  ownership_epoch: number;
  persisted_revision: number;
}

interface WorldEntrySnapshotCacheEntry {
  cache_key: string;
  world: string;
  world_revision: number;
  block_revision: number;
  ownership_token: string;
  ownership_epoch: number;
  static_payload: ServerPacketRecord;
  prepared_sections: unknown;
  build_ms: number;
  created_at_ms: number;
}

interface ServerInboundMessageEnvelope {
  data: ServerPacketRecord;
  enqueuedAt: number;
  messageBytes: number;
  messageType: string;
  queueDepthAtEnqueue: number;
  started: boolean;
}

type ServerGridPoint = {
  x: number;
  y: number;
};

type ServerGridCandidate = ServerGridPoint & {
  dist: number;
};

interface ServerAreaLockRecord extends ServerPacketRecord {
  lock_id: string;
  lock_grid_x: number;
  lock_grid_y: number;
}

interface ServerCctvEventRecord extends ServerPacketRecord {
  event_type: string;
  event: string;
  username: string;
  player_name: string;
  display_name: string;
  at: string;
}

interface ServerInventoryDeltaRecord extends ServerPacketRecord {
  item_type?: unknown;
  item_category?: unknown;
}

interface ServerSaleRecord extends ServerPacketRecord {
  item_id: string;
  item_category: string;
  amount: number;
  sell_value: number;
}

interface ServerDonationBoxTransactionOptions {
  inventory_deltas?: unknown[];
}

interface ServerDonationBoxEntry extends ServerPacketRecord {
  donation_id: string;
  donor_username: string;
  donor_name: string;
  donor_account_id: string;
  donor_player_id: string;
  item_id: string;
  item_category: string;
  amount: number;
  donated_at: string;
}

interface ServerDonationBoxState extends ServerPacketRecord, ServerGridPoint {
  action: "donation_box_state";
  world: string;
  owner_username: string;
  owner_name: string;
  owner_account_id: string;
  owner_player_id: string;
  donations: ServerDonationBoxEntry[];
  updated_at: string;
}

interface ServerDonationBoxClientState extends ServerPacketRecord, ServerGridPoint {
  action: "donation_box_state";
  world: string;
  owner_username: string;
  owner_name: string;
  donations: ServerDonationBoxEntry[];
  donation_count: number;
  max_donations: number;
  has_donations: boolean;
  can_manage: boolean;
  can_donate: boolean;
}

interface ServerKilledTargetRecord {
  playerId: string;
  username: string;
  player: unknown;
  socket: unknown;
}

type ServerWebSocket = import("ws").WebSocket & {
  playerId?: string;
  userAgent?: string;
  remoteAddress?: string;
  rateLimits?: Map<unknown, unknown>;
  rateLimitWarnings?: Map<unknown, unknown>;
  rateLimitSecurityWarnings?: Map<unknown, unknown>;
  authRequiredNotices?: Map<unknown, unknown>;
  inboundMessageQueue?: Promise<void>;
  inboundMessageQueueDepth?: number;
  pendingInboundMessageTail?: ServerInboundMessageEnvelope | null;
  closeCleanupStarted?: boolean;
};

interface ServerRouteContext {
  playerId: string;
  routeType: string;
  usedActionPosition: boolean;
}

type WorldHonorPeriod = "today" | "yesterday" | "overall";

interface WorldHonorVisitSession {
  playerId: string;
  username: string;
  world: string;
  startedAtMs: number;
  startedAtIso: string;
  networkHash: string;
  timer: ReturnType<typeof setTimeout> | null;
  recordPromise: Promise<boolean> | null;
  completed: boolean;
}

interface WorldHonorLeaderboardEntry {
  rank: number;
  world_name: string;
  honor_score: number;
  qualified_visitors: number;
  last_honored_on: string;
}

interface WorldHonorLeaderboardCacheEntry {
  expiresAtMs: number;
  entries: WorldHonorLeaderboardEntry[];
}

type ServerRouteHandler = (
  socket: unknown,
  player: ServerPacketRecord,
  data: ServerPacketRecord,
  context: ServerRouteContext,
) => unknown | Promise<unknown>;

function isBrokenStdIoError(error: unknown) {
  return ServerPhase11aRuntimeModule.isBrokenStdIoError(error);
}

function getErrorMessage(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

function getErrorStack(error: unknown): string {
  return error instanceof Error && error.stack ? error.stack : getErrorMessage(error);
}

function installConsoleWriteGuard() {
  return ServerPhase11aRuntimeModule.installConsoleWriteGuard(process, console);
}

installConsoleWriteGuard();

