let serverIapRoutes: any = null;

function getServerIapRoutes() {
  if (!serverIapRoutes) {
    // Required lazily (not at module load) because the IAP feature is still
    // in progress and its module is intentionally not committed yet.
    const ServerIapRoutesModule = require("./server_iap_routes");
    let stripeClient: any = null;
    let stripeClientInitAttempted = false;
    let androidPublisherClient: any = null;
    let androidPublisherInitAttempted = false;

    serverIapRoutes = ServerIapRoutesModule.createServerIapRoutes({
      cleanAccountName,
      doesAccountExist,
      ensureWritablePlayerState,
      addItemToState,
      commitPlayerInventoryState,
      findOnlinePlayerByUsername,
      sendJson,
      sendInventoryTransactionResult,
      sendHttpJson: (response: any, statusCode: any, payload: any) => ServerPhase11aRuntime.sendHttpJson(response, statusCode, payload),
      postgresStore,
      cloneJson,
      buildPlayerStateForClient,
      makeRequestId,
      getErrorMessage,
      publicBaseUrl: PUBLIC_BASE_URL,
      googlePlayPackageName: process.env.GOOGLE_PLAY_PACKAGE_NAME || "",
      stripeWebhookSecret: process.env.STRIPE_WEBHOOK_SECRET || "",
      getStripeClient: () => {
        if (stripeClient || stripeClientInitAttempted) return stripeClient;
        stripeClientInitAttempted = true;
        if (!process.env.STRIPE_SECRET_KEY) return null;
        try {
          const Stripe = require("stripe");
          stripeClient = new Stripe(process.env.STRIPE_SECRET_KEY);
        } catch (error) {
          console.error("[iap] stripe module unavailable (run `npm install stripe`):", getErrorMessage(error));
          stripeClient = null;
        }
        return stripeClient;
      },
      getGooglePlayPublisher: () => {
        if (androidPublisherClient || androidPublisherInitAttempted) return androidPublisherClient;
        androidPublisherInitAttempted = true;
        if (!process.env.GOOGLE_PLAY_SERVICE_ACCOUNT_JSON || !process.env.GOOGLE_PLAY_PACKAGE_NAME) return null;
        try {
          const { google } = require("googleapis");
          const credentials = JSON.parse(process.env.GOOGLE_PLAY_SERVICE_ACCOUNT_JSON);
          const auth = new google.auth.GoogleAuth({
            credentials,
            scopes: ["https://www.googleapis.com/auth/androidpublisher"],
          });
          androidPublisherClient = google.androidpublisher({ version: "v3", auth });
        } catch (error) {
          console.error("[iap] googleapis module unavailable (run `npm install googleapis`):", getErrorMessage(error));
          androidPublisherClient = null;
        }
        return androidPublisherClient;
      },
    });
  }
  return serverIapRoutes;
}

let serverLandfillEventSystem: any = null;

function getServerLandfillEventSystem() {
  if (!serverLandfillEventSystem) {
    serverLandfillEventSystem = ServerLandfillEventModule.createLandfillEventSystem({
      cleanAccountName,
      ensureWritablePlayerState,
      canAddItemToState,
      addItemToState,
      commitPlayerInventoryState,
      cloneJson,
      postgresStore,
      getWorldPopulationCount,
      sendJson,
      makeRequestId,
      getErrorMessage,
      minPlayersToStart: LANDFILL_MIN_PLAYERS_TO_START,
      maxPlayersPerInstance: LANDFILL_MAX_PLAYERS_PER_INSTANCE,
      isEventWindowOpen: () => getServerCalendarEventScheduler().isEventActive("landfill"),
      // Phase 2.5: used only once per instance, at creation time, to compute+cache the entry
      // holding-pen bounds around that world's real join spawn point -- see
      // computeEntryPenBounds in server_landfill_event.ts. Never called from the per-tick
      // movement path.
      getJoinWorldSpawnForWorld,
      entryPenRadiusPixels: LANDFILL_ENTRY_PEN_RADIUS_TILES * TILE_SIZE,
      // Vertical extent is split from the horizontal radius: a square box put four rows of wall
      // underground where they were invisible. height = above + spawn row + below, so above is
      // height - 2 and below is the single floor row.
      entryPenAbovePixels: Math.max(0, LANDFILL_ENTRY_PEN_HEIGHT_TILES - 2) * TILE_SIZE,
      entryPenBelowPixels: TILE_SIZE,
      // Task: Landfill worlds must get a fresh seed/regeneration every time -- see
      // resetWorldStateForFreshInstance and createNewInstance in server_landfill_event.ts.
      resetLandfillWorldState: resetWorldStateForFreshInstance,
      // Race session tunables.
      countdownMs: LANDFILL_COUNTDOWN_SECONDS * 1000,
      raceDurationMs: LANDFILL_RACE_SECONDS * 1000,
      resultsDisplayMs: LANDFILL_RESULTS_DISPLAY_SECONDS * 1000,
      sessionTickIntervalMs: LANDFILL_SESSION_TICK_MS,
      broadcastMinIntervalMs: LANDFILL_RACE_BROADCAST_MIN_INTERVAL_MS,
      placementBonusKilograms: LANDFILL_PLACEMENT_BONUS_KILOGRAMS,
      participationBonusKilograms: LANDFILL_PARTICIPATION_BONUS_KILOGRAMS,
      // Read-only roster reader. Same underlying source getWorldPopulationCount already uses, so
      // it inherits its self-healing of stale entries -- returning identities instead of a count
      // is what lets the session know WHO arrived and who left without hooking the join/leave
      // pipeline that server_landfill_event.ts's scope note forbids touching.
      getWorldPlayerIdentities: (worldName: unknown) =>
        // getWorldPlayerRecords returns {playerId, player} WRAPPER objects, not flat player
        // records -- reading account_username/name directly off `record` (rather than
        // record.player) silently resolves every username to "" and the race never sees anyone.
        // This exact bug shipped once already this event; if player counts go to 0 again, check
        // here first.
        getWorldPlayerRecords(cleanWorld(worldName)).map((record: { player?: { account_username?: unknown; name?: unknown } }) => ({
          username: cleanAccountName(record.player?.account_username || record.player?.name || ""),
          displayName: cleanName(record.player?.name || ""),
        })),
      // World-scoped push for live race state. Deliberately broadcastToWorld and not
      // broadcastSystemToWorld (which is chat) or a global fan-out.
      broadcastToWorld,
      // Builds/tears down the visible shifty-block starting pen.
      setLandfillEntryPenBlocks,
    });
  }
  return serverLandfillEventSystem;
}

let serverCalendarEventScheduler: any = null;

function getServerCalendarEventScheduler() {
  if (!serverCalendarEventScheduler) {
    serverCalendarEventScheduler = ServerCalendarEventsModule.createCalendarEventScheduler({
      logger: console,
    });
    serverCalendarEventScheduler.registerEvent({
      key: "landfill",
      label: "Landfill",
      enabled: LANDFILL_EVENT_ENABLED,
      cronStart: LANDFILL_EVENT_CRON_START,
      cronEnd: LANDFILL_EVENT_CRON_END,
      onWindowStart: () => {
        getServerLandfillEventSystem().resetInstancesForNewWindow();
        console.log("[landfill] event window opened; instance registry reset for the new season.");
      },
      onWindowEnd: () => {
        console.log("[landfill] event window closed for this season. Existing instances stay playable; new joins are refused.");
      },
    });
  }
  return serverCalendarEventScheduler;
}

function startCalendarEventScheduler(): void {
  getServerCalendarEventScheduler().start();
  getServerLandfillEventSystem().startInstancePolling();
}

