wss.on("connection", (socket: ServerWebSocket, request: import("node:http").IncomingMessage | null = null) => {
  const playerId = crypto.randomUUID();

  players.set(playerId, {
    id: playerId,
    name: "Guest",
    account_username: "",
    account_email: "",
    account_id: "",
    profile_id: "",
    authenticated: false,
    disconnected: false,
    role: "player",
    world: "START",
    current_world: "START",
    current_world_id: "START",
    joined_world: false,
    x: 0,
    y: 0,
    facing: 1,
    animation_state: "idle",
    velocity_x: 0,
    velocity_y: 0,
    on_floor: true,
	    in_water: false,
	    in_lava_fire: false,
	    movement_mode: MOVEMENT_MODE_WEBSOCKET,
	    netfox_peer_id: 0,
    custom_peer_id: 0,
    custom_player_node_path: "",
    trusted_movement_baseline: null,
    last_action_at_by_type: new Map(),
    damage_flash_expires_at: 0,
    damage_flash_token: 0,
    equipment_slots: {},
    client_version: "",
    indexed_world: "",
    redis_admission_world: "",
    world_entry_session_id: "",
    world_entry_state: "",
    world_entry_world: "",
    world_entry_join_request_id: "",
    world_entry_previous_world: "",
    world_entry_revision: 0,
    world_entry_block_revision: 0,
    world_entry_started_at_msec: 0,
    world_entry_snapshot_queued: false,
    world_entry_catchup_attempts: 0,
    world_entry_catchup_last_client_block_revision: 0,
    last_world_admission_warning_at: 0,
    last_position_at: 0,
    movement_sequence: 0,
    action_sequence: 0,
    movement_client_time_msec: 0,
    movement_server_time_msec: 0,
    last_player_position_broadcast_signature: "",
    last_player_position_broadcast_heartbeat_at: 0,
    last_presence_at: 0,
    last_block_break_at: 0,
    last_block_place_at: 0,
    noclip_enabled: false,
    developer_pin_unlocked_until: 0,
    admin_2fa_verified_until: 0,
    developer_command_cooldowns: new Map(),
    pending_admin_confirmations: new Map(),
  });

  socket.playerId = playerId;
  socketByPlayerId.set(playerId, socket);
  socket.userAgent = String(request?.headers?.["user-agent"] || "");
  socket.remoteAddress = ServerAccountSessionHelpersModule.resolveTrustedProxyClientAddress(request);
  socket.rateLimits = new Map();
  socket.rateLimitWarnings = new Map();
  socket.rateLimitSecurityWarnings = new Map();
  socket.authRequiredNotices = new Map();
  socket.inboundMessageQueue = Promise.resolve();
  socket.inboundMessageQueueDepth = 0;
  socket.pendingInboundMessageTail = null;

  socket.on("error", (error: Error) => {
    console.warn("[socket_error]", {
      player_id: playerId,
      message: error && error.message ? error.message : String(error),
    });
  });

  sendJson(socket, {
    type: "connected",
    player_id: playerId,
  });

  socket.on("message", (raw: import("ws").RawData) => {
    const enqueuedAt = Date.now();
    const messageBytes = getRawLength(raw);
    playerNetworkStats.inbound_messages_received += 1;
    playerNetworkStats.inbound_bytes_received += Math.max(0, Math.trunc(messageBytes || 0));
    if (isPacketTypeTelemetryEnabled()) {
      recordPacketTypeSize("inbound", "raw", messageBytes);
    }
    if (messageBytes > MAX_PACKET_BYTES) {
      playerNetworkStats.inbound_messages_oversize_rejected += 1;
      if (shouldLogSocketPacketWarning(socket, "inbound_oversize")) {
        console.warn("[socket_oversize_receive]", {
          player_id: playerId,
          world: cleanWorld(playerId && players.get(playerId) ? players.get(playerId).world || "START" : "START"),
          packet_bytes: messageBytes,
          max_packet_bytes: MAX_PACKET_BYTES,
        });
      }
      socket.close(1009, "Packet too large");
      return;
    }

    let parsedData: unknown;
    try {
      parsedData = JSON.parse(String(raw));
    } catch {
      return;
    }
    if (!parsedData || typeof parsedData !== "object" || Array.isArray(parsedData)) return;

    const data = parsedData as ServerPacketRecord;
    const incomingMessageType = ServerMessageRouterHelpers.getInboundMessageType(data);
    recordPacketTypeSize("inbound", incomingMessageType, messageBytes);
    const envelope: ServerInboundMessageEnvelope = {
      data,
      enqueuedAt,
      messageBytes,
      messageType: incomingMessageType,
      queueDepthAtEnqueue: 0,
      started: false,
    };

    if (ServerMessageRouterHelpers.coalesceQueuedPlayerPosition(socket.pendingInboundMessageTail, envelope)) {
      playerNetworkStats.coalesced_inbound_player_position_messages += 1;
      return;
    }

    const queueDepthAtEnqueue = Math.max(
      1,
      Math.trunc(Number(socket.inboundMessageQueueDepth) || 0) + 1,
    );
    envelope.queueDepthAtEnqueue = queueDepthAtEnqueue;
    socket.inboundMessageQueueDepth = queueDepthAtEnqueue;
    socket.pendingInboundMessageTail = envelope;
    playerNetworkStats.inbound_message_queue_pending = Math.max(
      0,
      Math.trunc(Number(playerNetworkStats.inbound_message_queue_pending) || 0) + 1,
    );
    playerNetworkStats.inbound_message_queue_pending_max = Math.max(
      Number(playerNetworkStats.inbound_message_queue_pending_max) || 0,
      playerNetworkStats.inbound_message_queue_pending,
    );
    playerNetworkStats.inbound_message_queue_max_socket_depth = Math.max(
      Number(playerNetworkStats.inbound_message_queue_max_socket_depth) || 0,
      queueDepthAtEnqueue,
    );

    const processMessage = async () => {
      envelope.started = true;
      if (socket.pendingInboundMessageTail === envelope) socket.pendingInboundMessageTail = null;
      const processingStartedAt = Date.now();
      const queueWaitMs = Math.max(0, processingStartedAt - envelope.enqueuedAt);
      const data = envelope.data;
      const incomingMessageType = envelope.messageType;
      socket.inboundMessageQueueDepth = Math.max(
        0,
        Math.trunc(Number(socket.inboundMessageQueueDepth) || 0) - 1,
      );
      playerNetworkStats.inbound_message_queue_pending = Math.max(
        0,
        Math.trunc(Number(playerNetworkStats.inbound_message_queue_pending) || 0) - 1,
      );
      playerNetworkStats.inbound_message_queue_wait_samples += 1;
      playerNetworkStats.inbound_message_queue_wait_total_ms += queueWaitMs;
      playerNetworkStats.inbound_message_queue_wait_max_ms = Math.max(
        Number(playerNetworkStats.inbound_message_queue_wait_max_ms) || 0,
        queueWaitMs,
      );
    try {
      if (incomingMessageType === "player_position") {
        playerNetworkStats.player_position_queue_wait_samples += 1;
        playerNetworkStats.player_position_queue_wait_total_ms += queueWaitMs;
        playerNetworkStats.player_position_queue_wait_max_ms = Math.max(
          Number(playerNetworkStats.player_position_queue_wait_max_ms) || 0,
          queueWaitMs,
        );
        if (queueWaitMs >= 250) {
          playerNetworkStats.player_position_queue_wait_over_250ms += 1;
          playerNetworkStats.player_position_queue_last_delay = {
            at: new Date(processingStartedAt).toISOString(),
            player_id: playerId,
            queue_wait_ms: queueWaitMs,
            queue_depth_at_enqueue: envelope.queueDepthAtEnqueue,
            socket_queue_depth_at_start: socket.inboundMessageQueueDepth,
          };
        }
      }

      const player = players.get(playerId);
      if (!player || player.disconnected) return;

      if (!(await checkMessageRateLimit(socket, player, String(data.type || "unknown"), data))) return;
      if (player.disconnected) return;
      if (!(await checkBotActionRateLimit(socket, player, String(data.type || "unknown"), data))) return;
      if (player.disconnected) return;

      const clientVersion = getClientVersion(data);
      if (!isClientVersionAllowed(clientVersion)) {
        sendClientUpdateRequired(socket, data, clientVersion);
        return;
      }
      player.client_version = clientVersion || player.client_version;

      if (rejectIfPostgresAuthorityUnavailable(socket, player, incomingMessageType, data)) {
        return;
      }

      if (!(await enforceMessageIdempotency(socket, player, data))) {
        return;
      }

      try {
        const phase7Dispatch = await ServerPhase7Dispatcher.dispatch(socket, player, data, {
          playerId,
        });
        if (phase7Dispatch.handled) return;
        return;
      } finally {
        completeMessageIdempotency(player, data);
      }
    } catch (error) {
      console.warn("[socket_message_error]", getErrorMessage(error));
    }
    };
    socket.inboundMessageQueue = Promise.resolve(socket.inboundMessageQueue).then(processMessage, processMessage);
  });

  socket.on("close", () => {
    if (socket.closeCleanupStarted) return;
    socket.closeCleanupStarted = true;
    socket.pendingInboundMessageTail = null;
    ServerSocketDeliveryHelpers.clearPlayerPositionDeliveryState(socket);

    void (async () => {
      const player = players.get(playerId);
      const closedUsername = player ? player.account_username : "";
      const closedWorld = player && player.joined_world ? cleanWorld(player.world || "START") : "";
      const closedAdmissionWorld = player
        ? cleanIndexedWorldName(player.redis_admission_world || (player.joined_world ? player.world : ""))
        : "";

      if (player) {
        player.disconnected = true;
        cancelActiveTradeForPlayer(playerId, "Trade canceled because a player disconnected.");
        activeFishingSessions.delete(playerId);
        clearPlayerFishingPresence(player);
        clearNetfoxTrustedPlayerState(player);
        if (player.joined_world) {
          clearPlayerWorldIndex(player);
          broadcastToWorld(player.world, buildPublicPlayerPresencePayload("player_left", player, player.world), playerId);
          broadcastSystemToWorld(player.world, `${player.name} left ${player.world}`, playerId);
        }
      }

      players.delete(playerId);
      socketByPlayerId.delete(playerId);
      clearPlayerInterestState(playerId);
      worldHonorTopCommandCooldowns.delete(playerId);
      if (closedWorld !== "") {
        broadcastWorldPopulationUpdate(closedWorld);
      }
      if (closedUsername) {
        notifyOnlineFriendsOfFriendState(closedUsername);
      }

      await Promise.resolve(socket.inboundMessageQueue).catch((error: unknown) => {
        console.warn("[socket_message_queue] disconnect drain failed:", getErrorMessage(error));
      });

      if (player) {
        const reindexedWorld = cleanIndexedWorldName(player.indexed_world || "");
        cancelActiveTradeForPlayer(playerId, "Trade canceled because a player disconnected.");
        activeFishingSessions.delete(playerId);
        clearPlayerFishingPresence(player);
        clearNetfoxTrustedPlayerState(player);
        clearPlayerWorldIndex(player);
        players.delete(playerId);
        socketByPlayerId.delete(playerId);
        clearPlayerInterestState(playerId);
        if (reindexedWorld !== "") {
          broadcastToWorld(reindexedWorld, buildPublicPlayerPresencePayload("player_left", player, reindexedWorld), playerId);
          broadcastWorldPopulationUpdate(reindexedWorld);
        }

        if (player.joined_world) {
          try {
            await removeWorldLockKeysFromPlayerInventory(socket, player, player.world, "disconnect", { silent: true });
          } catch (error) {
            console.warn("[world-lock-key] disconnect cleanup failed:", getErrorMessage(error));
          }
        }

        const persistenceFlush = await flushPendingSessionPersistence(
          player.account_username,
          closedWorld,
          "disconnect"
        );
        if (!persistenceFlush.ok) {
          console.warn("[persistence] disconnect flush failed:", {
            username: player.account_username || "",
            world: closedWorld,
            reason: persistenceFlush.reason || "unknown",
          });
        }
        await endWorldHonorVisit(player, closedWorld, "disconnect");

        markAccountSeen(player.account_username);
        releaseActiveAccountSession(player);

        // playerStates had five .set() sites and no .delete() anywhere in src/ -- the only
        // removal was a startup-time clear() -- so every account that logged in during a
        // process lifetime was retained forever, each holding a full inventory dictionary
        // (up to MAX_PLAYER_INVENTORY_KEYS entries). Against max_memory_restart: 512M that
        // is a slow-motion restart loop, and every restart costs a world-route lockout plus
        // a login storm.
        //
        // Evict only when it is provably safe: the disconnect flush persisted the state, no
        // pending debounced save is still queued for the key, and no other live socket is
        // using the account. Set PLAYER_STATE_DISCONNECT_EVICTION_ENABLED=0 to keep the old
        // retain-forever behaviour if an offline-lookup path turns out to depend on it.
        if (PLAYER_STATE_DISCONNECT_EVICTION_ENABLED && persistenceFlush.ok) {
          const evictionKey = accountKey(player.account_username);
          if (
            evictionKey !== ""
            && !playerSaveTimers.has(evictionKey)
            && !findOnlinePlayerByUsername(player.account_username)
          ) {
            playerStates.delete(evictionKey);
          }
        }
        if (closedAdmissionWorld !== "") {
          await releasePlayerWorldAdmission(player, closedAdmissionWorld).catch((error) => {
            console.warn("[redis] world admission disconnect cleanup failed:", error.message);
          });
          await releaseOwnedWorldRouteIfEmpty(closedAdmissionWorld).catch((error) => {
            console.warn("[redis] world route disconnect cleanup failed:", error.message);
          });
        }
        if (player.joined_world) {
          await appendCctvWorldEvent(player.world, player, "leave", { reason: "disconnect" }).catch((error) => {
            console.warn("[cctv] failed to record disconnect:", error.message);
          });
        }
      }
    })().catch((error) => {
      console.warn("[socket_close_cleanup_error]", error.message);
    });
  });
});

