function sanitizeRejectedActionMetadata(extra: any) {
  const raw = extra && typeof extra === "object" && !Array.isArray(extra) ? extra : {};
  const metadata: any = {};
  for (const [key, value] of Object.entries<any>(raw)) {
    if (value === undefined) continue;
    const cleanKey = cleanName(key);
    if (cleanKey === "" || cleanKey === "player_data" || cleanKey === "account" || cleanKey === "session_token") continue;
    if (typeof value === "string" || typeof value === "number" || typeof value === "boolean" || value === null) {
      metadata[cleanKey] = value;
    } else if (Array.isArray(value)) {
      metadata[cleanKey] = value.slice(0, 20).map((entry) => (
        typeof entry === "string" || typeof entry === "number" || typeof entry === "boolean" || entry === null
          ? entry
          : cleanName(JSON.stringify(entry)).slice(0, 500)
      ));
    } else if (typeof value === "object") {
      try {
        metadata[cleanKey] = JSON.parse(JSON.stringify(value));
      } catch (_) {
        metadata[cleanKey] = cleanName(String(value)).slice(0, 500);
      }
    }
  }
  return metadata;
}

function queueFailedTransactionLedger(socket: any, action: any, message: any, extra: any = null) {
  if (!isPostgresAuthoritativeReady()) return;
  if (!shouldRecordFailedTransactionLedgerAction(action)) return;

  const player = socket?.playerId ? players.get(socket.playerId) : null;
  const username = cleanAccountName(player?.account_username || player?.name || "");
  if (!player?.authenticated || username === "") return;

  const metadata = sanitizeRejectedActionMetadata(extra);
  const account = accounts.get(accountKey(username)) || null;
  const worldName = cleanWorld(metadata.world || metadata.world_name || player.world || "START");
  const itemType = cleanName(metadata.item_type || metadata.item_id || metadata.block_type || metadata.seed_type || "");
  const itemCategory = cleanInventoryCategory(metadata.item_category || metadata.category || "");
  const publicItemInstanceId = cleanName(metadata.public_item_instance_id || metadata.item_instance_public_id || metadata.item_instance_id || "");
  const requestId = cleanName(metadata.request_id || metadata.requestId || "");

  postgresStore.runDetached("transaction ledger failed action", () => postgresStore.recordTransactionLedgerEvent({
    transaction_type: failedTransactionLedgerTypeForAction(action),
    status: "failed",
    account_username: username,
    world: worldName,
    item_type: itemType,
    item_category: itemCategory,
    public_item_instance_id: publicItemInstanceId,
    quantity: 0,
    request_id: requestId,
    source: failedTransactionLedgerSourceForAction(action),
    action,
    ip_address: getSocketAddress(socket),
    user_agent: String(socket?.userAgent || ""),
    session_token_hash: cleanAccountName(account?.session_token_hash || ""),
    device_info: {
      user_agent: String(socket?.userAgent || ""),
      player_id: String(player?.id || ""),
    },
    metadata: {
      reason: cleanName(message || "action_rejected"),
      rejection_payload: metadata,
    },
  }));
}

function sendActionRejected(socket: any, action: any, message: any, extra: any = null) {
  if (!socket || socket.readyState !== WebSocket.OPEN) return;
  queueFailedTransactionLedger(socket, action, message, extra);
  if (String(action || "") === "world_block_update") {
    logPhase7ActionResult(socket, "REJECT", extra?.reason || message || "rejected", {
      reason: extra?.reason || message || "rejected",
      item: extra?.block_type || extra?.item_id || socket?._phase7BlockActionContext?.item || "",
    });
  }

  const payload: any = {
    type: "action_rejected",
    action,
    message,
  };
  if (extra && typeof extra === "object" && !Array.isArray(extra)) {
    for (const [key, value] of Object.entries<any>(extra)) {
      if (value !== undefined) {
        payload[key] = value;
      }
    }
  }

  if (String(action || "") === "world_block_update") {
    const context = socket?._phase7BlockActionContext || null;
    const fallbackRequestId = clampString(payload.request_id || payload.action_id || socket?.activeActionRequestId || "", MAX_ITEM_ID_LENGTH);
    if (fallbackRequestId !== "") {
      payload.request_id = fallbackRequestId;
      payload.action_id = fallbackRequestId;
    }
    if (context && context.active === true) {
      if (!payload.request_id && context.request_id) payload.request_id = context.request_id;
      if (!payload.action_id && context.request_id) payload.action_id = context.request_id;
      if (!payload.world && context.world) payload.world = context.world;
      if (!payload.layer && context.layer) payload.layer = context.layer;
      if (!Object.prototype.hasOwnProperty.call(payload, "x")) payload.x = Math.trunc(Number(context.target_x) || 0);
      if (!Object.prototype.hasOwnProperty.call(payload, "y")) payload.y = Math.trunc(Number(context.target_y) || 0);
      if (!payload.block_type && context.item) payload.block_type = context.item;
      if (!payload.block_action && context.action) payload.block_action = context.action;
    }
  }

  sendJson(socket, payload);
}

function requireSameWorld(socket: any, player: any, worldName: any, action: any) {
  if (!player) return false;

  const currentWorld = cleanWorld(player.world || "START");
  const targetWorld = cleanWorld(worldName || "START");
  if (currentWorld === targetWorld) return true;

  sendActionRejected(socket, action, "Join that world before sending actions for it.", {
    reason: "wrong_world",
    current_world: currentWorld,
    requested_world: targetWorld,
  });
  return false;
}

function isGridInWorld(x: any, y: any) {
  return (
    Number.isInteger(x) &&
    Number.isInteger(y) &&
    x >= 0 &&
    x < WORLD_WIDTH &&
    y >= 0 &&
    y < WORLD_HEIGHT
  );
}

function isPositionInWorldBounds(x: any, y: any) {
  const min = -POSITION_MARGIN_PIXELS;
  const maxX = WORLD_WIDTH * TILE_SIZE + POSITION_MARGIN_PIXELS;
  const maxY = WORLD_HEIGHT * TILE_SIZE + POSITION_MARGIN_PIXELS;
  return Number.isFinite(x) && Number.isFinite(y) && x >= min && x <= maxX && y >= min && y <= maxY;
}

function parseBlockVector2(value: any, fallbackX: any, fallbackY: any) {
  if (Array.isArray(value) && value.length >= 2) {
    return {
      x: Number.isFinite(Number(value[0])) ? Number(value[0]) : fallbackX,
      y: Number.isFinite(Number(value[1])) ? Number(value[1]) : fallbackY,
    };
  }

  if (value && typeof value === "object" && !Array.isArray(value)) {
    return {
      x: Number.isFinite(Number(value.x)) ? Number(value.x) : fallbackX,
      y: Number.isFinite(Number(value.y)) ? Number(value.y) : fallbackY,
    };
  }

  return { x: fallbackX, y: fallbackY };
}

function blockOccupiesCollisionArea(blockType: any) {
  const definition = ItemDatabase.getItemDefinition(blockType);
  return Boolean(definition?.occupies_collision_area);
}

function blockRequiresFullAreaClear(blockType: any) {
  const definition = ItemDatabase.getItemDefinition(blockType);
  return Boolean(definition?.requires_full_area_clear);
}

function blockRequiresWorldLock(blockType: any) {
  const definition = ItemDatabase.getItemDefinition(blockType);
  return Boolean(definition?.requires_world_lock);
}

function isEntranceBlockType(blockType: any) {
  const definition = ItemDatabase.getItemDefinition(clampString(blockType || ""));
  return Boolean(definition && definition.category === "block" && definition.entrance_block);
}

function isDoorBlockType(blockType: any) {
  const definition = ItemDatabase.getItemDefinition(clampString(blockType || ""));
  return Boolean(definition && definition.category === "block" && definition.door_block);
}

function isPasswordDoorBlockType(blockType: any) {
  const definition = ItemDatabase.getItemDefinition(clampString(blockType || ""));
  return Boolean(definition && definition.category === "block" && definition.password_door);
}

function isSignBlockType(blockType: any) {
  const definition = ItemDatabase.getItemDefinition(clampString(blockType || ""));
  return Boolean(definition && definition.category === "block" && definition.sign_block);
}

function isToggleBlockType(blockType: any) {
  const definition = ItemDatabase.getItemDefinition(clampString(blockType || ""));
  return Boolean(definition && definition.category === "block" && definition.toggle_block);
}

function isPersistentInteractionBlockType(blockType: any) {
  return (
    isDoorBlockType(blockType)
    || isEntranceBlockType(blockType)
    || isSignBlockType(blockType)
    || isToggleBlockType(blockType)
    || isBulletinBoardBlockType(blockType)
    || isDisplayBlockType(blockType)
    || isDonationBoxBlockType(blockType)
    || MAILBOX_BLOCK_TYPES.has(clampString(blockType || ""))
    || isTackleBoxBlockType(blockType)
    || isChickenBlockType(blockType)
    || isCowBlockType(blockType)
    || isDuckBlockType(blockType)
    || isWaterWellBlockType(blockType)
    || isDiceBlockType(blockType)
    || isAntiPunchBlockType(blockType)
    || isAntiTalkBlockType(blockType)
    || isAntiGravityBlockType(blockType)
    || isThemeMachineBlockType(blockType)
    || isOilRefineryBlockType(blockType)
    || isBatteryChargerBlockType(blockType)
  );
}

function getBlockCollisionRectForGrid(x: any, y: any, blockType: any) {
  const definition = ItemDatabase.getItemDefinition(blockType) || {};
  const size = parseBlockVector2(definition.collision_size || definition.visual_size, TILE_SIZE, TILE_SIZE);
  const offset = parseBlockVector2(definition.collision_offset || definition.visual_offset, 0, 0);
  const centerX = (Number(x) || 0) * TILE_SIZE + offset.x;
  const centerY = (Number(y) || 0) * TILE_SIZE + offset.y;

  return {
    x: centerX - size.x * 0.5,
    y: centerY - size.y * 0.5,
    width: size.x,
    height: size.y,
  };
}

function getGridPositionsOverlappingRect(rect: any) {
  const positions: any = [];
  const halfTile = TILE_SIZE * 0.5;
  const epsilon = 0.01;
  const minX = Math.floor((rect.x + halfTile + epsilon) / TILE_SIZE);
  const minY = Math.floor((rect.y + halfTile + epsilon) / TILE_SIZE);
  const maxX = Math.floor((rect.x + rect.width - epsilon + halfTile) / TILE_SIZE);
  const maxY = Math.floor((rect.y + rect.height - epsilon + halfTile) / TILE_SIZE);

  for (let y: any = minY; y <= maxY; y += 1) {
    for (let x: any = minX; x <= maxX; x += 1) {
      positions.push({ x, y });
    }
  }

  return positions;
}

function rectsIntersect(a: any, b: any) {
  if (!a || !b) return false;
  return (
    a.x < b.x + b.width &&
    a.x + a.width > b.x &&
    a.y < b.y + b.height &&
    a.y + a.height > b.y
  );
}

function doesPlacementOverlapReservedObject(state: any, x: any, y: any, blockType: any) {
  if (!state) return false;

  const proposedRect = getBlockCollisionRectForGrid(x, y, blockType);
  for (const block of state.foreground.values()) {
    const existingType = clampString(block?.block_type || "");
    if (!blockOccupiesCollisionArea(existingType)) continue;

    const existingRect = getBlockCollisionRectForGrid(block.x, block.y, existingType);
    if (rectsIntersect(proposedRect, existingRect)) {
      return true;
    }
  }

  return false;
}

function doesPlacementOverlapReservedObjectExcept(state: any, x: any, y: any, blockType: any, ignoredGridKey: any = "") {
  if (!state) return false;

  const proposedRect = getBlockCollisionRectForGrid(x, y, blockType);
  for (const block of state.foreground.values()) {
    const blockKey = gridKey(block.x, block.y);
    if (blockKey === ignoredGridKey) continue;

    const existingType = clampString(block?.block_type || "");
    if (!blockOccupiesCollisionArea(existingType)) continue;

    const existingRect = getBlockCollisionRectForGrid(block.x, block.y, existingType);
    if (rectsIntersect(proposedRect, existingRect)) {
      return true;
    }
  }

  return false;
}

function validateFullCollisionAreaPlacement(socket: any, state: any, update: any) {
  const collisionRect = getBlockCollisionRectForGrid(update.x, update.y, update.block_type);
  const occupiedPositions = getGridPositionsOverlappingRect(collisionRect);

  for (const position of occupiedPositions) {
    if (!isGridInWorld(position.x, position.y)) {
      sendActionRejected(socket, "world_block_update", "Need enough empty space.", {
        reason: "outside_world_bounds",
        block_type: update.block_type,
      });
      return false;
    }

    const key = gridKey(position.x, position.y);
    if (state.foreground.has(key) || state.seeds.has(key)) {
      sendActionRejected(socket, "world_block_update", "Need enough empty space.", {
        reason: "occupied",
        block_type: update.block_type,
      });
      return false;
    }
  }

  if (doesPlacementOverlapReservedObject(state, update.x, update.y, update.block_type)) {
    sendActionRejected(socket, "world_block_update", "Need enough empty space.", {
      reason: "reserved_space",
      block_type: update.block_type,
    });
    return false;
  }

  return true;
}

function clampInteger(value: any, min: any, max: any) {
  return TextHelpers.clampInteger(value, min, max);
}

function clampString(value: any, limit: any = MAX_ITEM_ID_LENGTH) {
  return TextHelpers.clampString(value, limit);
}

function sanitizeProfileBio(value: unknown) {
  const normalized = String(value || "")
    .replace(/\r\n?/g, "\n")
    .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, "")
    .split("\n")
    .map((line) => line.replace(/[ \t]+/g, " ").trim())
    .join("\n")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
  return Array.from(normalized).slice(0, MAX_PROFILE_BIO_LENGTH).join("");
}

function cleanText(value: any, limit: any = 500) {
  return TextHelpers.clampString(value, limit);
}

function cleanDoorId(value: any) {
  return TextHelpers.cleanDoorId(value, MAX_DOOR_ID_LENGTH);
}

function cleanDoorDestination(value: any) {
  return TextHelpers.cleanDoorDestination(value, MAX_DOOR_DESTINATION_LENGTH);
}

function cleanDoorName(value: any) {
  return TextHelpers.cleanDoorName(value, MAX_DOOR_NAME_LENGTH);
}

function cleanDoorPassword(value: any) {
  return TextHelpers.cleanDoorPassword(value, MAX_DOOR_PASSWORD_LENGTH);
}

function parseDoorDestination(value: any, sourceWorld: any = "START") {
  const destination = cleanDoorDestination(value);
  const fallbackWorld = cleanWorld(sourceWorld || "START");
  if (destination === "") {
    return {
      destination,
      target_world: "",
      target_door_id: "",
    };
  }

  const parts = destination
    .split(":")
    .map((part: unknown) => String(part || "").trim())
    .filter((part: string) => part !== "");
  let targetWorld: any = fallbackWorld;
  let targetDoorId: any = "";

  if (parts.length >= 3 && parts[1].toLowerCase() === "door") {
    targetWorld = cleanWorld(parts[0]);
    targetDoorId = cleanDoorId(parts[2]);
  } else if (parts.length >= 2) {
    if (parts[0].toLowerCase() === "door") {
      targetDoorId = cleanDoorId(parts[1]);
    } else {
      targetWorld = cleanWorld(parts[0]);
      targetDoorId = cleanDoorId(parts[1]);
    }
  } else {
    targetWorld = cleanWorld(parts[0] || destination);
  }

  return {
    destination,
    target_world: cleanWorld(targetWorld || fallbackWorld),
    target_door_id: targetDoorId,
  };
}

function canPlayerControlWorldLock(player: any, worldName: any) {
  if (isAdmin(player)) return true;
  if (!player || !player.authenticated) return false;

  const state = ensureWorldState(worldName);
  const lock: any = getEffectiveWorldLockStateInState(state);
  if (!lock.is_locked) return false;
  return lockOwnerMatchesPlayer(lock, player);
}

function isPlayerWorldOwner(player: any, worldName: any) {
  if (!player || !player.authenticated) return false;

  const state = ensureWorldState(worldName);
  const lock: any = getEffectiveWorldLockStateInState(state);
  if (!lock.is_locked) return false;
  return lockOwnerMatchesPlayer(lock, player);
}

function canPlayerBuildInWorld(player: any, worldName: any) {
  if (isAdmin(player)) return true;
  if (!player || !player.authenticated) return false;

  const state = ensureWorldState(worldName);
  const lock: any = getEffectiveWorldLockStateInState(state);
  if (!lock.is_locked) return true;

  const playerKey = accountKey(player.account_username);
  if (playerKey === "") return false;
  if (lockOwnerMatchesPlayer(lock, player)) return true;
  if (Boolean(lock.public_build)) return true;

  return canWorldLockRoleBuild(getWorldLockRoleForPlayer(lock, player));
}

function canPlayerConfigureDoor(player: any, worldName: any) {
  if (isAdmin(player)) return true;
  if (!player || !player.authenticated) return false;

  const state = ensureWorldState(worldName);
  const lock: any = getEffectiveWorldLockStateInState(state);
  if (!lock.is_locked) return true;

  if (lockOwnerMatchesPlayer(lock, player)) return true;
  return canWorldLockRoleBuild(getWorldLockRoleForPlayer(lock, player));
}

function canPlayerEditPasswordDoor(player: any, worldName: any) {
  if (isAdmin(player)) return true;
  if (!player || !player.authenticated) return false;

  const state = ensureWorldState(worldName);
  const lock: any = getEffectiveWorldLockStateInState(state);
  if (!lock.is_locked) return false;
  return lockOwnerMatchesPlayer(lock, player);
}

function canPlayerToggleDoorLock(player: any, worldName: any) {
  if (isAdmin(player)) return true;
  if (!player || !player.authenticated) return false;

  const state = ensureWorldState(worldName);
  const lock: any = getEffectiveWorldLockStateInState(state);
  if (!lock.is_locked) return true;

  if (lockOwnerMatchesPlayer(lock, player)) return true;
  return canWorldLockRoleToggleWoodenEntrance(getWorldLockRoleForPlayer(lock, player));
}

function canPlayerPassDoor(player: any, worldName: any) {
  if (isAdmin(player)) return true;
  if (!player || !player.authenticated) return false;

  const state = ensureWorldState(worldName);
  const lock: any = getEffectiveWorldLockStateInState(state);
  if (!lock.is_locked) return true;

  if (lockOwnerMatchesPlayer(lock, player)) return true;
  return getWorldLockRoleForPlayer(lock, player) !== "";
}

function requireBuildPermission(socket: any, player: any, worldName: any, action: any) {
  if (canPlayerBuildInWorld(player, worldName)) return true;

  sendActionRejected(socket, action, "This world is locked.");
  return false;
}

function requireBuildPermissionAtGrid(socket: any, player: any, worldName: any, x: any, y: any, action: any) {
  if (canPlayerBuildAtGrid(player, worldName, x, y)) return true;

  sendActionRejected(socket, action, "This area is locked.");
  return false;
}

function canPlayerUseThemeMachineAtGrid(player: any, worldName: any, x: any, y: any) {
  if (isAdmin(player)) return true;
  if (!player || !player.authenticated) return false;

  const state = ensureWorldState(worldName);
  const lock: any = getEffectiveWorldLockStateInState(state);
  const playerKey = accountKey(player.account_username);
  const hasWorldAccess = Boolean(lock.is_locked)
    && playerKey !== ""
    && (
      lockOwnerMatchesPlayer(lock, player)
      || Boolean(lock.public_build)
      || canWorldLockRoleBuild(getWorldLockRoleForPlayer(lock, player))
    );

  const areaLock = getAreaLockCoveringGrid(state, x, y);
  const hasAreaAccess = Boolean(areaLock) && canPlayerBuildInAreaLock(player, worldName, areaLock);
  return hasWorldAccess || hasAreaAccess;
}

function getGridCenterPixels(x: any, y: any) {
  return {
    x: (Number(x) || 0) * TILE_SIZE,
    y: (Number(y) || 0) * TILE_SIZE,
  };
}

function isPlayerNearPoint(player: any, x: any, y: any, maxDistance: any = MAX_GRID_ACTION_DISTANCE_PIXELS, options: any = {}) {
  if (!player) return false;
  const position = getPlayerValidationPosition(player, {
    action: options.action || "point_reach",
    world: options.world || getPlayerCurrentWorldName(player),
  });
  if (!position.ok) {
    debugNetfoxAction("reach rejected before point check", {
      player_id: String(player?.id || ""),
      reason: position.reason,
      action: position.action,
      expected_world: position.expected_world,
      state_world: position.state_world,
      age_ms: position.age_ms,
    });
    return false;
  }

  const px = Number(position.x);
  const py = Number(position.y);
  const tx = Number(x);
  const ty = Number(y);
  if (![px, py, tx, ty].every(Number.isFinite)) return false;
  const distance = Math.hypot(px - tx, py - ty);
  const ok = distance <= maxDistance;
  debugNetfoxAction("reach point check", {
    player_id: String(player?.id || ""),
    action: options.action || "point_reach",
    source: position.source,
    world: position.world,
    player_x: Math.round(px),
    player_y: Math.round(py),
    target_x: Math.round(tx),
    target_y: Math.round(ty),
    distance: Math.round(distance),
    max_distance: Math.round(maxDistance),
    allowed: ok,
  });
  return ok;
}

function isPlayerNearGrid(player: any, x: any, y: any, maxDistance: any = MAX_GRID_ACTION_DISTANCE_PIXELS, options: any = {}) {
  const center = getGridCenterPixels(x, y);
  return isPlayerNearPoint(player, center.x, center.y, maxDistance, {
    action: options.action || "grid_reach",
    world: options.world || getPlayerCurrentWorldName(player),
  });
}

function getPlayerGridPosition(player: any) {
  const position = getPlayerValidationPosition(player, {
    action: "grid_position",
    world: getPlayerCurrentWorldName(player),
  });
  if (!position.ok) return null;
  const px = Number(position.x);
  const py = Number(position.y);
  if (!Number.isFinite(px) || !Number.isFinite(py)) return null;
  return {
    x: Math.round(px / TILE_SIZE),
    y: Math.round(py / TILE_SIZE),
  };
}

function isPlayerStandingOnGrid(player: any, x: any, y: any) {
  const playerGrid = getPlayerGridPosition(player);
  if (!playerGrid) return false;
  const deltaX = Math.abs(playerGrid.x - Math.trunc(Number(x) || 0));
  const deltaY = Math.abs(playerGrid.y - Math.trunc(Number(y) || 0));
  return deltaX === 0 && deltaY === 0;
}

function getPlayerGridPositionInWorld(player: any, worldName: any, action: any = "grid_position") {
  if (!player) return null;
  const position = getPlayerValidationPosition(player, {
    action,
    world: cleanWorld(worldName || getPlayerCurrentWorldName(player)),
  });
  if (!position.ok) return null;
  const px = Number(position.x);
  const py = Number(position.y);
  if (!Number.isFinite(px) || !Number.isFinite(py)) return null;
  return {
    x: Math.round(px / TILE_SIZE),
    y: Math.round(py / TILE_SIZE),
  };
}

function isPlayerOverlappingGridInWorld(player: any, worldName: any, gridX: any, gridY: any, blockType: any, action: any = "grid_overlap") {
  if (!player) return false;
  const targetX = Math.trunc(Number(gridX) || 0);
  const targetY = Math.trunc(Number(gridY) || 0);
  const position = getPlayerValidationPosition(player, {
    action,
    world: cleanWorld(worldName || getPlayerCurrentWorldName(player)),
  });
  if (position.ok) {
    const px = Number(position.x);
    const py = Number(position.y);
    if (Number.isFinite(px) && Number.isFinite(py)) {
      const playerRect = getPlayerMovementCollisionRect({ x: px, y: py });
      const blockRect = getBlockCollisionRectForGrid(targetX, targetY, blockType);
      if (rectsIntersect(playerRect, blockRect)) return true;
    }
  }

  const grid: any = getPlayerGridPositionInWorld(player, worldName, action);
  return Boolean(grid && grid.x === targetX && grid.y === targetY);
}

function buildPunchToggleInstantDeathTargets(worldName: any, update: any, validation: any) {
  if (!validation || validation.toggledBlock !== true || validation.toggled_to_solid !== true) return [];
  if (!update || update.action !== "place" || update.layer !== "foreground") return [];
  if (!isSolidMovementCollisionBlock(update.block_type)) return [];

  const targetX = Math.trunc(Number(update.x) || 0);
  const targetY = Math.trunc(Number(update.y) || 0);
  const killed: any = [];
  for (const { player: target, socket: client, playerId } of getWorldPlayerRecords(worldName, { includeSocket: true })) {
    if (!isPlayerOverlappingGridInWorld(target, worldName, targetX, targetY, update.block_type, "death_gate_crush")) continue;
    killed.push({
      playerId: String(playerId || target?.id || client?.playerId || ""),
      username: cleanAccountName(target?.account_username || target?.name || ""),
      player: target,
      socket: client,
    });
  }

  if (killed.length > 0) {
    update.instant_death = true;
    update.kill_reason = "death_gate_crush";
    update.kill_block_type = update.block_type;
    update.kill_player_ids = killed
      .map((entry: ServerKilledTargetRecord) => entry.playerId)
      .filter((id: string) => id !== "");
    update.kill_usernames = killed
      .map((entry: ServerKilledTargetRecord) => entry.username)
      .filter((username: string) => username !== "");
  }

  return killed;
}

function applyPunchToggleInstantDeathPresence(killedTargets: any, worldName: any) {
  if (!Array.isArray(killedTargets) || killedTargets.length === 0) return;
  const now = Date.now();
  for (const target of killedTargets) {
    const player = target?.player;
    if (!player) continue;
    player.animation_state = "dead";
    player.velocity_x = 0;
    player.velocity_y = 0;
    player.damage_flash_expires_at = now + Math.min(300, MAX_DAMAGE_FLASH_MS);
    player.damage_flash_token = clampInteger(player.damage_flash_token || 0, 0, 2147483646) + 1;
    publishPlayerPresenceUpdate(target.socket || getSocketByPlayerId(player.id), player, worldName, "player_position");
  }
}

function buildInventoryDeltasBetweenStates(beforeState: any, afterState: any) {
  return ServerInventoryTransactionHelpers.buildInventoryDeltasBetweenStates(beforeState, afterState);
}

function buildInventoryDeltaClientPayloads(deltas: any = [], state: any = null) {
  return ServerInventoryTransactionHelpers.buildInventoryDeltaClientPayloads(deltas, state);
}

function hasProgressionPayload(payload: any) {
  return payload && typeof payload === "object" && !Array.isArray(payload) && Number(payload.xp_gained || 0) > 0;
}

function writePlayerStateJsonBackup(username: any, state: any) {
  const clean = cleanAccountName(username);
  if (clean === "" || !state) return;

  // writeJsonFileAtomic is synchronous (mkdirSync + writeFileSync + renameSync) and
  // this runs on every player save, so it stalls the event loop for every socket on
  // the instance -- including a player mid-join. When PostgreSQL is authoritative
  // the JSON file is only an emergency-recovery artefact, so it is gated exactly
  // like the world backup already is. Set PLAYER_JSON_BACKUP_WHEN_PG_READY=1 to
  // restore the unconditional write.
  if (!PLAYER_JSON_BACKUP_WHEN_PG_READY && isPostgresAuthoritativeReady()) {
    return;
  }

  writeJsonFileAtomic(getPlayerSavePath(clean), {
    player_state_version: 1,
    username: clean,
    saved_at: new Date().toISOString(),
    player_data: state,
  });
}

// The world JSON backup is skipped entirely while PostgreSQL is authoritative, so any
// serializeWorldState() call made *as an argument* to writeWorldStateJsonBackup is pure
// waste in the default production config -- arguments are evaluated before the callee's
// early return. Callers must gate on this helper instead of serializing eagerly.
function isWorldStateJsonBackupEnabled() {
  return WORLD_JSON_BACKUP_WHEN_PG_READY || !isPostgresAuthoritativeReady();
}

function writeWorldStateJsonBackup(worldName: any, serialized: any = null) {
  const clean = cleanWorld(worldName);
  if (!isWorldStateJsonBackupEnabled()) {
    return;
  }

  const worldState = serialized && typeof serialized === "object" && !Array.isArray(serialized)
    ? serialized
    : serializeWorldState(clean);
  pendingWorldJsonBackups.set(clean, PersistenceHelpers.clonePersistenceSnapshot(worldState));

  const shouldDebounce = isPostgresAuthoritativeReady() && WORLD_JSON_BACKUP_DEBOUNCE_MS > 0;
  if (!shouldDebounce) {
    flushWorldStateJsonBackup(clean);
    return;
  }

  const existingTimer = worldJsonBackupTimers.get(clean);
  if (existingTimer) clearTimeout(existingTimer);

  const timer = setTimeout(() => {
    flushWorldStateJsonBackup(clean);
  }, WORLD_JSON_BACKUP_DEBOUNCE_MS);
  if (typeof timer.unref === "function") timer.unref();
  worldJsonBackupTimers.set(clean, timer);
}

function flushWorldStateJsonBackup(worldName: any, options: any = {}) {
  const clean = cleanWorld(worldName);
  const timer = worldJsonBackupTimers.get(clean);
  if (timer) {
    clearTimeout(timer);
    worldJsonBackupTimers.delete(clean);
  }

  const worldState = pendingWorldJsonBackups.get(clean);
  if (!worldState) return;
  pendingWorldJsonBackups.delete(clean);

  if (options.sync === true) {
    writeJsonFileAtomic(getWorldSavePath(clean), worldState);
    return;
  }

  trackPersistenceWrite(writeJsonFileAtomicAsync(getWorldSavePath(clean), worldState), `world JSON backup ${clean}`);
}

function flushWorldStateJsonBackups(options: any = {}) {
  const worlds: any = new Set([
    ...worldJsonBackupTimers.keys(),
    ...pendingWorldJsonBackups.keys(),
  ]);
  for (const worldName of worlds) {
    flushWorldStateJsonBackup(worldName, options);
  }
}

function persistWorldStateAfterInventoryCommit(worldName: any, postgresCommitted: any, serialized: any = null) {
  void serialized;
  if (postgresCommitted) {
    // serializeWorldState is a full world rebuild plus a structuredClone (~12ms on a
    // mature world). It used to be evaluated unconditionally here even though
    // writeWorldStateJsonBackup discards it immediately while PostgreSQL is
    // authoritative, i.e. on every block placement in production.
    if (isWorldStateJsonBackupEnabled()) {
      writeWorldStateJsonBackup(worldName, serializeWorldState(worldName));
    }
    return;
  }

  queueWorldSave(worldName, { mutation: false, reason: "inventory_world_transaction_fallback" });
}

/**
 * @param {string} worldName
 * @param {Record<string, unknown> | null} serialized
 * @param {string} reason
 * @returns {Promise<PixelMania.WorldStateCommitResult>}
 */
async function persistAuthoritativeWorldState(worldName: any, serialized: any = null, reason: any = "world_state_update") {
  const clean = cleanWorld(worldName);
  void serialized;
  if (!shouldPersistWholeWorldState(clean, reason)) {
    return { ok: false, reason: "world_ownership_unverified" };
  }
  advanceAuthoritativeWorldRevision(clean, reason);
  const worldState = serializeWorldState(clean);
  if (!isPostgresAuthoritativeReady()) {
    if (POSTGRES_ENABLED && POSTGRES_AUTHORITATIVE) {
      return { ok: false, reason: "postgres_unavailable" };
    }
    writeWorldStateJsonBackup(clean, worldState);
    markWorldRevisionPersisted(clean, worldState.world_revision);
    return { ok: true, postgres_committed: false };
  }

  const persistence = await runOwnedWorldPersistence(clean, reason, (ownership) => (
    postgresStore.saveWorldState(clean, worldState, ownership)
  ));
  if (!persistence.ok || persistence.value !== true) {
    console.warn("[postgres] authoritative world state save failed", { world: clean, reason });
    return { ok: false, reason: persistence.reason || "database_error" };
  }
  markWorldRevisionPersisted(clean, worldState.world_revision);
  writeWorldStateJsonBackup(clean, worldState);
  return { ok: true, postgres_committed: true };
}

function countSerializedWorldCollection(value: any) {
  if (Array.isArray(value)) return value.length;
  if (value && typeof value === "object") return Object.keys(value).length;
  return 0;
}

function summarizeSerializedWorldStateForLog(state: any) {
  const data = state && typeof state === "object" ? state : {};
  const foreground = countSerializedWorldCollection(data.foreground);
  const background = countSerializedWorldCollection(data.background);
  const seeds = countSerializedWorldCollection(data.seeds);
  const drops = countSerializedWorldCollection(data.drops || data.item_drops);
  const doors = countSerializedWorldCollection(data.doors);
  return {
    foreground,
    background,
    seeds,
    drops,
    doors,
    total_blocks: foreground + background + seeds,
  };
}

/**
 * @param {PixelMania.WorldName | string} worldName
 * @param {string} reason
 * @returns {Promise<PixelMania.RefreshWorldStateFromPostgresResult | Record<string, unknown>>}
 */
const worldStateRefreshesInFlight = new Map<string, Promise<Record<string, unknown>>>();

function elapsedWorldEntryMs(startedAt: bigint): number {
  return Math.round((Number(process.hrtime.bigint() - startedAt) / 1_000_000) * 1000) / 1000;
}

async function refreshWorldStateFromPostgres(
  worldName: unknown,
  reason: string = "world_state_send"
): Promise<Record<string, unknown>> {
  const clean = cleanWorld(worldName);
  const waitStartedAt = process.hrtime.bigint();
  const existingRefresh = worldStateRefreshesInFlight.get(clean);
  if (existingRefresh) {
    const result = await existingRefresh;
    return {
      ...(result && typeof result === "object" ? result : {}),
      coalesced: true,
      coalesced_wait_ms: elapsedWorldEntryMs(waitStartedAt),
    } as Record<string, unknown>;
  }

  const refreshPromise = refreshWorldStateFromPostgresUncoalesced(clean, reason);
  worldStateRefreshesInFlight.set(clean, refreshPromise);
  try {
    const result = await refreshPromise;
    return {
      ...(result && typeof result === "object" ? result : {}),
      coalesced: false,
      refresh_total_ms: elapsedWorldEntryMs(waitStartedAt),
    } as Record<string, unknown>;
  } finally {
    if (worldStateRefreshesInFlight.get(clean) === refreshPromise) {
      worldStateRefreshesInFlight.delete(clean);
    }
  }
}

async function refreshWorldStateFromPostgresUncoalesced(
  clean: string,
  reason: string
): Promise<Record<string, unknown>> {
  const refreshStartedAt = process.hrtime.bigint();
  const timings: Record<string, number> = {};
  const finish = (result: Record<string, unknown>) => {
    timings.refresh_core_ms = elapsedWorldEntryMs(refreshStartedAt);
    return { ...result, timings };
  };
  if (!isPostgresAuthoritativeReady()) return finish({ ok: true, skipped: true, reason: "postgres_unavailable" });
  if (typeof postgresStore.loadWorldState !== "function") {
    console.warn("[postgres] authoritative world refresh unavailable; postgresStore.loadWorldState is missing", {
      world: clean,
      reason,
    });
    return finish({ ok: false, reason: "unsupported" });
  }

  // Ownership is verified first because it is the only input the warm-memory
  // decision needs, and it is a no-op unless world route enforcement is on. The
  // persistence flush and the per-world coordinator wait only exist to make
  // PostgreSQL current before we read it, so they are deferred until we actually
  // know we are going to read it. A world that is already live in memory on this
  // instance must never pay for a database round trip it will not use.
  let phaseStartedAt = process.hrtime.bigint();
  const ownershipVerification = await verifyWorldPersistenceOwnership(clean);
  timings.ownership_verify_ms = elapsedWorldEntryMs(phaseStartedAt);
  if (!ownershipVerification.ok) {
    return finish({ ok: false, reason: ownershipVerification.reason || "world_ownership_unverified" });
  }

  phaseStartedAt = process.hrtime.bigint();
  const warmState = worldStates.get(clean);
  const warmRevision = warmState
    ? PersistenceHelpers.normalizeWorldRevision(warmState.world_revision)
    : 0;
  const warmPersistedRevision = PersistenceHelpers.normalizeWorldRevision(worldPersistedRevisions.get(clean));
  const warmAuthorityMatches = Boolean(
    warmState
    && worldPersistedRevisions.has(clean)
    && doesLoadedWorldAuthorityMatch(clean, ownershipVerification.ownership)
  );
  // Memory may legitimately be AHEAD of PostgreSQL: a block placed a moment ago is
  // accepted into memory immediately and persisted on a debounce. In that window the
  // in-memory state is the authoritative one, so reloading from the database would
  // hand the joining player an older world. Provided this instance still owns the
  // world under the same ownership epoch it was loaded on, warm memory is correct
  // whether it is level with the database or ahead of it. The queued save still runs
  // on its own schedule; the join simply stops waiting for it.
  const warmMemoryIsCurrent = warmAuthorityMatches && warmRevision >= warmPersistedRevision;
  const warmMemoryIsLevel = warmAuthorityMatches
    && !worldUnpersistedRevisions.has(clean)
    && warmPersistedRevision >= warmRevision
    && PersistenceHelpers.normalizeWorldRevision(
      worldLoadedAuthorities.get(clean)?.persisted_revision
    ) >= warmRevision;
  const canReuseWarmMemory = warmMemoryIsLevel
    || (WORLD_ENTRY_WARM_MEMORY_AHEAD_ENABLED && warmMemoryIsCurrent);
  timings.warm_memory_check_ms = elapsedWorldEntryMs(phaseStartedAt);
  if (canReuseWarmMemory) {
    scheduleWorldEventEnd(clean);
    console.log("[world-entry]", JSON.stringify({
      event: "warm_memory_reuse",
      world_id: clean,
      server_instance: SERVER_INSTANCE_ID,
      ownership_token: ownershipVerification.ownership.ownership_token || "",
      ownership_epoch: ownershipVerification.ownership.ownership_epoch || 0,
      loaded_revision: warmRevision,
      persisted_revision: warmPersistedRevision,
      warm_memory_ahead: warmRevision > warmPersistedRevision,
      cache_result: "authoritative_memory_hit",
    }));
    return finish({
      ok: true,
      found: true,
      world: clean,
      source: "memory_warm",
      warm_memory_ahead: warmRevision > warmPersistedRevision,
      world_revision: warmRevision,
      foreground: warmState.foreground instanceof Map ? warmState.foreground.size : 0,
      background: warmState.background instanceof Map ? warmState.background.size : 0,
      seeds: warmState.seeds instanceof Map ? warmState.seeds.size : 0,
      drops: warmState.drops instanceof Map ? warmState.drops.size : 0,
      doors: warmState.interactions instanceof Map ? warmState.interactions.size : 0,
    });
  }

  // Warm memory was not usable, so PostgreSQL is about to become the source of
  // truth for this world. Only now is it worth making the database current: drain
  // this world's pending save and wait behind any in-flight write for it.
  phaseStartedAt = process.hrtime.bigint();
  const persistenceFlush = await flushPendingSessionPersistence("", clean, `before_${reason}_world_refresh`);
  timings.persistence_flush_ms = elapsedWorldEntryMs(phaseStartedAt);
  if (!persistenceFlush.ok) {
    return finish({ ok: false, reason: persistenceFlush.reason || "world_persistence_flush_failed" });
  }
  phaseStartedAt = process.hrtime.bigint();
  await worldPersistenceCoordinator.wait(clean);
  timings.persistence_wait_ms = elapsedWorldEntryMs(phaseStartedAt);

  phaseStartedAt = process.hrtime.bigint();
  const result: any = await postgresStore.loadWorldState(clean);
  timings.postgres_query_ms = elapsedWorldEntryMs(phaseStartedAt);
  if (!result || !result.ok) {
    console.warn("[postgres] authoritative world refresh failed", {
      world: clean,
      reason,
      failure_reason: result?.reason || "unknown",
      message: result?.message || "",
    });
    return finish({ ok: false, reason: result?.reason || "database_error" });
  }
  phaseStartedAt = process.hrtime.bigint();
  const postLoadOwnershipVerification = await verifyWorldPersistenceOwnership(clean);
  timings.post_load_ownership_verify_ms = elapsedWorldEntryMs(phaseStartedAt);
  if (!postLoadOwnershipVerification.ok) {
    return finish({ ok: false, reason: postLoadOwnershipVerification.reason || "world_ownership_changed_during_load" });
  }

  phaseStartedAt = process.hrtime.bigint();
  // Read memory after the database await. A world mutation may have completed
  // while PostgreSQL was loading, and that accepted revision must not be
  // replaced by the older result that just arrived.
  const memoryExists = worldStates.has(clean);
  const memoryRevision = memoryExists ? getWorldRevision(clean) : 0;
  const databaseRevision = PersistenceHelpers.normalizeWorldRevision(
    result.world_revision ?? result.state?.world_revision
  );
  worldPersistedRevisions.set(clean, databaseRevision);
  const memoryAuthoritative = isMemoryWorldRevisionAuthoritative(
    clean,
    memoryRevision,
    postLoadOwnershipVerification.ownership
  );
  const loadDecision = PersistenceHelpers.resolveWorldLoadRevision({
    memory_exists: memoryExists,
    memory_revision: memoryRevision,
    database_found: result.found === true,
    database_revision: databaseRevision,
    memory_authoritative: memoryAuthoritative,
  });
  timings.revision_resolution_ms = elapsedWorldEntryMs(phaseStartedAt);
  console.log("[world-persistence]", JSON.stringify({
    event: "load",
    world_id: clean,
    server_instance: SERVER_INSTANCE_ID,
    ownership_token: postLoadOwnershipVerification.ownership?.ownership_token || "",
    ownership_epoch: postLoadOwnershipVerification.ownership?.ownership_epoch || 0,
    loaded_revision: databaseRevision,
    mutation_revision: memoryRevision,
    requested_save_revision: 0,
    persisted_revision: databaseRevision,
    affected_row_count: 0,
    save_result: `${loadDecision.source}:${loadDecision.reason}`,
  }));

  if (loadDecision.source === "memory") {
    phaseStartedAt = process.hrtime.bigint();
    const reconciled = await saveWorldState(clean, {
      mutation: false,
      reason: `reconcile_${loadDecision.reason}`,
    });
    timings.memory_reconcile_ms = elapsedWorldEntryMs(phaseStartedAt);
    if (reconciled !== true) {
      return finish({ ok: false, reason: "newer_memory_reconcile_failed" });
    }
    scheduleWorldEventEnd(clean);
    phaseStartedAt = process.hrtime.bigint();
    const memoryState = serializeWorldState(clean);
    const memorySummary = summarizeSerializedWorldStateForLog(memoryState);
    timings.memory_serialize_ms = elapsedWorldEntryMs(phaseStartedAt);
    return finish({
      ok: true,
      found: true,
      world: clean,
      source: "memory",
      world_revision: getWorldRevision(clean),
      ...memorySummary,
    });
  }

  if (loadDecision.source === "empty") {
    phaseStartedAt = process.hrtime.bigint();
    invalidateWorldEntrySnapshotCache(clean, "database_empty_load");
    worldUnpersistedRevisions.delete(clean);
    worldPersistedRevisions.set(clean, 0);
    worldStates.set(clean, createEmptyWorldState());
    rememberLoadedWorldAuthority(clean, postLoadOwnershipVerification.ownership, 0);
    scheduleWorldEventEnd(clean);
    console.warn("[postgres] authoritative world row missing; using empty world state", {
      world: clean,
      reason,
      had_local_state: memoryExists,
      memory_revision: memoryRevision,
    });
    timings.initialize_empty_ms = elapsedWorldEntryMs(phaseStartedAt);
    return finish({ ok: true, found: false, world: clean, had_local_state: memoryExists });
  }

  phaseStartedAt = process.hrtime.bigint();
  invalidateWorldEntrySnapshotCache(clean, "database_world_load");
  const seedTimestampMigrationNeeded = WorldStateHelpers.needsSeedTimestampMigration(result.state || {});
  const state = deserializeWorldState(clean, result.state || {});
  worldUnpersistedRevisions.delete(clean);
  worldStates.set(clean, state);
  rememberLoadedWorldAuthority(clean, postLoadOwnershipVerification.ownership, databaseRevision);
  scheduleWorldEventEnd(clean);
  if (seedTimestampMigrationNeeded) {
    queueWorldSave(clean, { critical: true });
    console.log("[world-state] queued legacy seed timestamp migration", {
      world: clean,
      seeds: state.seeds instanceof Map ? state.seeds.size : 0,
    });
  }
  timings.deserialize_ms = elapsedWorldEntryMs(phaseStartedAt);
  const summary = summarizeSerializedWorldStateForLog(result.state || {});
  if (WORLD_STATE_REFRESH_TRACE || summary.total_blocks === 0) {
    const logMethod = summary.total_blocks === 0 ? "warn" : "log";
    console[logMethod]("[postgres] refreshed authoritative world state", {
      world: clean,
      reason,
      updated_at: result.updated_at || "",
      last_saved_at: result.last_saved_at || "",
      ...summary,
    });
  }
  return finish({
    ok: true,
    found: true,
    world: clean,
    source: "database",
    world_revision: getWorldRevision(clean),
    ...summary,
  });
}

async function refreshPlayerStateFromPostgres(username: any, reason: any = "player_state_send") {
  const refreshStartedAt = process.hrtime.bigint();
  const timings: Record<string, number> = {};
  const finish = (result: Record<string, unknown>) => {
    timings.refresh_total_ms = elapsedWorldEntryMs(refreshStartedAt);
    return { ...result, timings };
  };
  const clean = cleanAccountName(username);
  if (clean === "") return finish({ ok: false, found: false, reason: "invalid_username" });
  if (!isPostgresAuthoritativeReady()) return finish({ ok: true, skipped: true, reason: "postgres_unavailable" });
  if (typeof postgresStore.loadPlayerState !== "function") {
    console.warn("[postgres] authoritative player refresh unavailable; postgresStore.loadPlayerState is missing", {
      username: clean,
      reason,
    });
    return finish({ ok: false, found: false, reason: "unsupported" });
  }

  let phaseStartedAt = process.hrtime.bigint();
  const persistenceFlush = await flushPendingSessionPersistence(clean, "", `before_${reason}_player_refresh`);
  timings.persistence_flush_ms = elapsedWorldEntryMs(phaseStartedAt);
  if (!persistenceFlush.ok) {
    return finish({ ok: false, found: false, reason: persistenceFlush.reason || "player_persistence_flush_failed" });
  }

  phaseStartedAt = process.hrtime.bigint();
  const result: any = await postgresStore.loadPlayerState(clean);
  timings.postgres_query_ms = elapsedWorldEntryMs(phaseStartedAt);
  if (!result || !result.ok) {
    console.warn("[postgres] authoritative player refresh failed", {
      username: clean,
      reason,
      failure_reason: result?.reason || "unknown",
      message: result?.message || "",
    });
    return finish({ ok: false, found: false, reason: result?.reason || "database_error" });
  }
  if (!result.found) {
    return finish({ ok: true, found: false, username: clean });
  }

  phaseStartedAt = process.hrtime.bigint();
  const state = sanitizePlayerState(result.state || {}, result.username || clean);
  timings.deserialize_ms = elapsedWorldEntryMs(phaseStartedAt);
  if (!state) {
    return finish({ ok: false, found: true, reason: "invalid_player_state" });
  }
  setPlayerState(clean, state);
  return finish({ ok: true, found: true, username: clean, state });
}

/**
 * @param {PixelMania.WorldName | string} worldName
 * @param {string} reason
 * @returns {Promise<PixelMania.RefreshWorldDropsFromPostgresResult>}
 */
async function refreshWorldDropsFromPostgres(worldName: any, reason: any = "world_state_send") {
  const clean = cleanWorld(worldName);
  if (!isPostgresAuthoritativeReady()) return { ok: true, skipped: true, reason: "postgres_unavailable" };
  if (typeof postgresStore.loadActiveWorldDrops !== "function") return { ok: true, skipped: true, reason: "unsupported" };

  const result: any = await postgresStore.loadActiveWorldDrops(clean);
  if (!result || !result.ok) {
    console.warn("[postgres] active world drops refresh failed", {
      world: clean,
      reason,
      failure_reason: result?.reason || "unknown",
      message: result?.message || "",
    });
    return { ok: false, reason: result?.reason || "database_error" };
  }
  if (result.skipped) return { ok: true, skipped: true, reason: result.reason || "no_world_drop_rows" };

  const state = ensureWorldState(clean);
  state.drops.clear();
  loadDropsIntoMap(state.drops, result.drops || []);
  return { ok: true, drop_count: state.drops.size };
}

function getPostgresInventoryFailureMessage(result: any, fallback: any = "Server inventory changed. Try again.") {
  return ServerInventoryTransactionHelpers.getPostgresInventoryFailureMessage(result, fallback);
}

/**
 * @param {unknown} socket
 * @param {Record<string, any> | null | undefined} player
 * @param {string} username
 * @param {PixelMania.RuntimePlayerState | null | undefined} beforeState
 * @param {PixelMania.RuntimePlayerState | null | undefined} afterState
 * @param {PixelMania.InventoryCommitOptions} options
 * @returns {Promise<PixelMania.InventoryCommitResult>}
 */
async function commitPlayerInventoryState(socket: any, player: any, username: any, beforeState: any, afterState: any, options: any = {}) {
  if (!afterState) {
    return InventoryContracts.buildInventoryCommitFailure({ message: "Could not load your server inventory." });
  }

  const cleanUsername = cleanAccountName(username || afterState.account_username || player?.account_username || "");
  if (cleanUsername === "") {
    return InventoryContracts.buildInventoryCommitFailure({ message: "Could not load your server inventory." });
  }

  let inventoryLock: any = null;
  if (options.skip_inventory_lock !== true) {
    inventoryLock = await acquirePlayerInventoryLocks([cleanUsername], options.inventory_lock_owner || options.action || "inventory_commit");
    if (!inventoryLock.acquired) {
      return InventoryContracts.buildInventoryCommitFailure({
        reason: "inventory_locked",
        message: "Your inventory is busy. Try again.",
      });
    }
  }

  try {
  clearUnavailableEquipmentInState(afterState);
  afterState.saved_at = new Date().toISOString();
  const deltas = buildInventoryDeltasBetweenStates(beforeState || {}, afterState);

  if (isPostgresAuthoritativeReady()) {
    const worldName = cleanWorld(options.world || player?.world || "START");
    const worldChanges = Array.isArray(options.world_changes) ? options.world_changes : [];
    const requestedWorldState = options.world_state && typeof options.world_state === "object"
      ? options.world_state
      : {};
    const includesWorldMutation = Object.keys(requestedWorldState).length > 0 || worldChanges.length > 0;
    let worldStateForCommit: ServerPacketRecord = {};
    const transactionMetadata: ServerPacketRecord = options.metadata && typeof options.metadata === "object"
      ? options.metadata
      : {};

    if (includesWorldMutation) {
      if (!shouldPersistWholeWorldState(worldName, options.action || "inventory_world_transaction")) {
        return InventoryContracts.buildInventoryCommitFailure({
          reason: "world_ownership_unverified",
          message: "That world is changing servers. Try again.",
        });
      }
      advanceAuthoritativeWorldRevision(worldName, options.action || "inventory_world_transaction");
      worldStateForCommit = serializeWorldState(worldName);
    }

    const buildTransaction = (ownership: WorldPersistenceOwnership | null = null) => (
      postgresStore.applyInventoryDeltaTransaction(InventoryContracts.buildPostgresInventoryDeltaTransactionEntry({
      accountUsername: cleanUsername,
      world: worldName,
      source: options.source || options.source_type || options.action || "system",
      action: options.action || "update",
      reason: options.reason || options.action || "update",
      requestId: options.request_id || "",
      correlationId: options.correlation_id || "",
      metadata: ownership ? { ...transactionMetadata, world_persistence: ownership } : transactionMetadata,
      ipAddress: options.ip_address || getSocketAddress(socket),
      userAgent: options.user_agent || "",
      sessionTokenHash: options.session_token_hash || "",
      deviceInfo: options.device_info || {},
      deltas,
      playerState: afterState,
      worldState: worldStateForCommit,
      worldChanges,
      allowStateRepair: options.allow_state_repair === true,
      at: new Date().toISOString(),
      }))
    );

    let result: ServerPacketRecord | null = null;
    if (includesWorldMutation) {
      const persistence = await runOwnedWorldPersistence(
        worldName,
        options.action || "inventory_world_transaction",
        (ownership) => buildTransaction(ownership)
      );
      result = persistence.ok && persistence.value && typeof persistence.value === "object"
        ? persistence.value as ServerPacketRecord
        : {
          ok: false,
          reason: persistence.reason || "world_persistence_failed",
        };
    } else {
      result = await buildTransaction();
    }

    if (!result || !result.ok) {
      logSecurityEvent(socket, player, "postgres_inventory_commit_failed", {
        username: cleanUsername,
        action: options.action || "",
        source: options.source || "",
        reason: result?.reason || "unknown",
        item_type: result?.item_type || "",
      }, "warning");
      return InventoryContracts.buildInventoryCommitFailure({
        reason: result?.reason || "postgres_failed",
        message: getPostgresInventoryFailureMessage(result, options.failure_message || "Server inventory changed. Try again."),
      });
    }

    if (Array.isArray(result.ledger_entries) && result.ledger_entries.length > 0) {
      if (!applyInventoryLedgerToState(afterState, result.ledger_entries)) {
        return InventoryContracts.buildInventoryCommitFailure({
          reason: "state_reconcile_failed",
          message: "Inventory reconciliation failed.",
        });
      }
      clearUnavailableEquipmentInState(afterState);
    }

    setPlayerState(cleanUsername, afterState);
    writePlayerStateJsonBackup(cleanUsername, afterState);
    if (includesWorldMutation) {
      markWorldRevisionPersisted(worldName, worldStateForCommit.world_revision);
      writeWorldStateJsonBackup(worldName, worldStateForCommit);
    }
    const equipmentChanged = syncPlayerEquipmentSlotsFromState(player, afterState, cleanUsername);
    if (equipmentChanged && player) {
      publishPlayerPresenceUpdate(socket, player, options.world || player.world || "START", "player_position");
    }
    return InventoryContracts.buildInventoryCommitSuccess({
      state: afterState,
      postgresCommitted: true,
      deltas,
      equipmentChanged,
    });
  }

  if (POSTGRES_ENABLED && POSTGRES_AUTHORITATIVE && !shouldAllowPhase7DevJsonFallback(player, null, options)) {
    return InventoryContracts.buildInventoryCommitFailure({
      reason: "postgres_unavailable",
      message: "PostgreSQL is not ready.",
    });
  }

  const persistedState = persistPlayerInventoryChange(cleanUsername, afterState);
  const equipmentChanged = syncPlayerEquipmentSlotsFromState(player, persistedState, cleanUsername);
  if (equipmentChanged && player) {
    publishPlayerPresenceUpdate(socket, player, options.world || player.world || "START", "player_position");
  }
  return InventoryContracts.buildInventoryCommitSuccess({
    state: persistedState,
    postgresCommitted: false,
    deltas,
    equipmentChanged,
  });
  } finally {
    releasePlayerInventoryLocks(inventoryLock);
  }
}

function persistPlayerInventoryChange(username: any, state: any, options: any = {}) {
  if (!state) return null;
  state.saved_at = new Date().toISOString();
  setPlayerState(username, state);
  if (options.postgresCommitted) {
    writePlayerStateJsonBackup(username, state);
  } else {
    queuePlayerSave(username);
  }
  return state;
}

/**
 * @param {string} username
 * @param {PixelMania.InventorySpendCost | null | undefined} cost
 * @param {PixelMania.SpendServerInventoryCostOptions} options
 * @returns {Promise<PixelMania.SpendServerInventoryCostResult>}
 */
async function spendServerInventoryCost(username: any, cost: any, options: any = {}) {
  if (!cost || Number(cost.amount) <= 0) return { ok: true, state: null };

  const state = ensureWritablePlayerState(username);
  if (!state) {
    return { ok: false, reason: "inventory_unavailable", message: "Could not load your server inventory." };
  }

  if (!ItemDatabase.hasItem(cost.item_id) || !ItemDatabase.canStoreItemInCategory(cost.item_id, cost.item_category)) {
    return { ok: false, reason: "invalid_item", message: "That item is not valid on the server." };
  }

  if (getInventoryCount(state, cost.item_id, cost.item_category) < cost.amount) {
    return { ok: false, reason: "insufficient_inventory", message: `Not enough ${cost.item_id}.` };
  }

  const beforeState = cloneJson(state);
  const stagedState = cloneJson(state);
  if (!spendItemFromState(stagedState, cost.item_id, cost.item_category, cost.amount)) {
    return { ok: false, reason: "inventory_changed", message: "Server inventory changed. Try again." };
  }

  if (options.defer_commit === true) {
    return {
      ok: true,
      state: stagedState,
      postgres_committed: false,
      deferred_inventory_commit: InventoryContracts.buildDeferredInventoryCommit({
        username,
        beforeState,
        afterState: stagedState,
        options: {
          source: options.source || "system",
          action: options.action || "spend_inventory_cost",
          reason: options.reason || "inventory_cost",
          request_id: options.request_id || "",
          correlation_id: options.correlation_id || "",
          world: options.world || options.player?.world || "",
          allow_dev_json_fallback: options.allow_dev_json_fallback === true,
          metadata: {
            ...(options.metadata || {}),
            item_id: cost.item_id,
            item_category: cost.item_category,
            amount: cost.amount,
          },
          failure_message: options.failure_message || "Server inventory changed. Try again.",
        },
      }),
    };
  }

  const commit = await commitPlayerInventoryState(options.socket || null, options.player || null, username, beforeState, stagedState, {
    source: options.source || "system",
    action: options.action || "spend_inventory_cost",
    reason: options.reason || "inventory_cost",
    request_id: options.request_id || "",
    correlation_id: options.correlation_id || "",
    world: options.world || options.player?.world || "",
    allow_dev_json_fallback: options.allow_dev_json_fallback === true,
    metadata: {
      ...(options.metadata || {}),
      item_id: cost.item_id,
      item_category: cost.item_category,
      amount: cost.amount,
    },
    failure_message: options.failure_message || "Server inventory changed. Try again.",
  });
  if (!commit.ok) {
    return { ok: false, message: commit.message, reason: commit.reason };
  }

  return { ok: true, state: commit.state, postgres_committed: commit.postgres_committed, deltas: commit.deltas };
}

/**
 * @param {PixelMania.InventoryCommitOptions} options
 * @returns {Promise<PixelMania.WorldInventoryValidationResult>}
 */
async function prepareWaterBucketScoopInventoryReturn(socket: any, player: any, worldName: any, update: any, requestId: any = "", options: any = {}) {
  const username = cleanAccountName(player?.account_username || player?.name || "");
  const state = ensureWritablePlayerState(username);
  if (!state) {
    sendActionRejected(socket, "world_block_update", "Could not load your server inventory.", {
      reason: "inventory_unavailable",
      block_type: update.block_type,
    });
    return { ok: false };
  }

  if (getInventoryCount(state, WATER_BUCKET_ITEM_TYPE, "block") <= 0) {
    sendActionRejected(socket, "world_block_update", "Equip a Water Bucket first.", {
      reason: "water_bucket_required",
      block_type: update.block_type,
    });
    return { ok: false };
  }

  if (!canAddItemToState(state, WATER_BUCKET_ITEM_TYPE, "block", 1)) {
    sendActionRejected(socket, "world_block_update", "Your inventory cannot hold more Water Buckets.", {
      reason: "inventory_full",
      block_type: update.block_type,
      item_id: WATER_BUCKET_ITEM_TYPE,
    });
    return { ok: false };
  }

  const beforeState = cloneJson(state);
  const stagedState = cloneJson(state);
  const addResult = addItemToState(stagedState, WATER_BUCKET_ITEM_TYPE, "block", 1);
  if (!addResult) {
    sendActionRejected(socket, "world_block_update", "Could not add water to your bucket stack.", {
      reason: "inventory_add_failed",
      block_type: update.block_type,
      item_id: WATER_BUCKET_ITEM_TYPE,
    });
    return { ok: false };
  }

  const metadata: any = {
    x: update.x,
    y: update.y,
    removed_block: WATER_BLOCK_TYPE,
    layer: update.layer,
    item_id: WATER_BUCKET_ITEM_TYPE,
    item_category: "block",
    amount: 1,
  };

  if (isPostgresAuthoritativeReady()) {
    return {
      ok: true,
      playerState: stagedState,
      postgres_committed: false,
      inventoryDeltas: buildInventoryDeltasBetweenStates(beforeState, stagedState),
      deferred_inventory_commit: InventoryContracts.buildDeferredInventoryCommit({
        username,
        beforeState,
        afterState: stagedState,
        options: {
          source: "world_block_break",
          action: "water_bucket_scoop",
          reason: "water_bucket_scoop",
          request_id: requestId,
          world: worldName,
          allow_dev_json_fallback: options.allow_dev_json_fallback === true,
          metadata,
          failure_message: "Server inventory changed. Try again.",
        },
      }),
      message: "Collected water.",
    };
  }

  const commit = await commitPlayerInventoryState(socket, player, username, beforeState, stagedState, {
    source: "world_block_break",
    action: "water_bucket_scoop",
    reason: "water_bucket_scoop",
    request_id: requestId,
    world: worldName,
    allow_dev_json_fallback: options.allow_dev_json_fallback === true,
    metadata,
    failure_message: "Server inventory changed. Try again.",
  });

  if (!commit.ok) {
    sendActionRejected(socket, "world_block_update", commit.message || "Could not add water to your bucket stack.", {
      reason: commit.reason || "inventory_commit_failed",
      block_type: update.block_type,
      item_id: WATER_BUCKET_ITEM_TYPE,
    });
    return { ok: false };
  }

  return {
    ok: true,
    playerState: commit.state,
    inventoryDeltas: Array.isArray(commit.deltas) ? commit.deltas : [],
    postgres_committed: commit.postgres_committed,
    message: "Collected water.",
  };
}

/**
 * @param {PixelMania.InventoryCommitOptions} options
 * @returns {Promise<PixelMania.WorldInventoryValidationResult>}
 */
async function prepareDirectBlockBreakInventoryReturn(socket: any, player: any, worldName: any, update: any, requestId: any = "", options: any = {}) {
  const returnedItem = getDirectBreakInventoryReturn(update?.block_type);
  if (!returnedItem) {
    return { ok: true, playerState: null, inventoryDeltas: [], message: "" };
  }

  const username = cleanAccountName(player?.account_username || player?.name || "");
  const state = ensureWritablePlayerState(username);
  if (!state) {
    sendActionRejected(socket, "world_block_update", "Could not load your server inventory.", {
      reason: "inventory_unavailable",
      block_type: update.block_type,
      item_id: returnedItem.item_id,
    });
    return { ok: false };
  }

  if (!canAddItemToState(state, returnedItem.item_id, returnedItem.item_category, returnedItem.amount)) {
    sendActionRejected(socket, "world_block_update", "Your inventory cannot hold that machine.", {
      reason: "inventory_full",
      block_type: update.block_type,
      item_id: returnedItem.item_id,
    });
    return { ok: false };
  }

  const beforeState = cloneJson(state);
  const stagedState = cloneJson(state);
  const addResult = addItemToState(stagedState, returnedItem.item_id, returnedItem.item_category, returnedItem.amount);
  if (!addResult) {
    sendActionRejected(socket, "world_block_update", "Could not return that machine to your inventory.", {
      reason: "inventory_add_failed",
      block_type: update.block_type,
      item_id: returnedItem.item_id,
    });
    return { ok: false };
  }

  const transactionId = makeAuditId("machine_break");
  const definition = ItemDatabase.getItemDefinition(returnedItem.item_id);
  const displayName = clampString(definition?.display_name || returnedItem.item_id, MAX_ITEM_ID_LENGTH);
  const metadata: any = {
    transaction_id: transactionId,
    x: update.x,
    y: update.y,
    layer: update.layer,
    removed_block: update.block_type,
    item_id: returnedItem.item_id,
    item_category: returnedItem.item_category,
    amount: returnedItem.amount,
  };
  const postCommitLogs: any = {
    itemLedgerEntries: [{
      item_id: returnedItem.item_id,
      item_category: returnedItem.item_category,
      amount: returnedItem.amount,
      source_type: "machine_break_return",
      source_id: transactionId,
      reason: "machine_break_recovery",
      details: {
        x: update.x,
        y: update.y,
        removed_block: update.block_type,
      },
    }],
  };

  if (isPostgresAuthoritativeReady()) {
    return {
      ok: true,
      playerState: stagedState,
      postgres_committed: false,
      inventoryDeltas: buildInventoryDeltasBetweenStates(beforeState, stagedState),
      deferred_inventory_commit: InventoryContracts.buildDeferredInventoryCommit({
        username,
        beforeState,
        afterState: stagedState,
        options: {
          source: "world_block_break",
          action: "machine_break_return",
          reason: "machine_break_recovery",
          request_id: requestId,
          world: worldName,
          allow_dev_json_fallback: options.allow_dev_json_fallback === true,
          metadata,
          failure_message: "Server inventory changed. Try again.",
        },
      }),
      postCommitLogs,
      message: `Returned ${displayName} to your inventory.`,
    };
  }

  const commit = await commitPlayerInventoryState(socket, player, username, beforeState, stagedState, {
    source: "world_block_break",
    action: "machine_break_return",
    reason: "machine_break_recovery",
    request_id: requestId,
    world: worldName,
    allow_dev_json_fallback: options.allow_dev_json_fallback === true,
    metadata,
    failure_message: "Server inventory changed. Try again.",
  });
  if (!commit.ok) {
    sendActionRejected(socket, "world_block_update", commit.message || "Could not return that machine to your inventory.", {
      reason: commit.reason || "inventory_commit_failed",
      block_type: update.block_type,
      item_id: returnedItem.item_id,
    });
    return { ok: false };
  }

  return {
    ok: true,
    playerState: commit.state,
    inventoryDeltas: Array.isArray(commit.deltas) ? commit.deltas : [],
    postgres_committed: commit.postgres_committed,
    postCommitLogs,
    message: `Returned ${displayName} to your inventory.`,
  };
}

function makeServerDropId(worldName: any, itemType: any) {
  const cleanWorldName = safeFileName(cleanWorld(worldName), "START");
  const cleanItem = safeFileName(clampString(itemType || "drop"), "drop");
  const suffix = `${Date.now()}_${crypto.randomBytes(4).toString("hex")}`;
  const hash = crypto
    .createHash("sha1")
    .update(`${cleanWorldName}:${cleanItem}`)
    .digest("hex")
    .slice(0, 8);
  const readableBudget = Math.max(1, MAX_DROP_ID_LENGTH - `server__${suffix}_${hash}`.length);
  const readable = safeFileName(`${cleanWorldName}_${cleanItem}`, "drop");
  const clippedReadable = clampString(readable, readableBudget).replace(/_+$/g, "") || "drop";
  return clampString(`server_${clippedReadable}_${suffix}_${hash}`, MAX_DROP_ID_LENGTH);
}

function randomChance(chance: any) {
  const safeChance = Math.max(0, Math.min(1, Number(chance) || 0));
  if (safeChance <= 0) return false;
  if (safeChance >= 1) return true;
  return crypto.randomInt(0, 1000000) < Math.floor(safeChance * 1000000);
}

function randomRangeInclusive(min: any, max: any) {
  const safeMin = Math.trunc(Number(min) || 0);
  const safeMax = Math.trunc(Number(max) || safeMin);
  if (safeMax <= safeMin) return safeMin;
  return crypto.randomInt(safeMin, safeMax + 1);
}

function validateBlockBreakPace(socket: any, player: any, update: any = null) {
  if (isAdmin(player)) return true;

  const now = Date.now();
  const lastBreakAt = Number(player.last_block_break_at || 0);
  if (lastBreakAt > 0 && now - lastBreakAt < MIN_BLOCK_BREAK_INTERVAL_MS) {
    sendActionRejected(socket, "world_block_update", "Slow down a little.", {
      reason: "break_rate_limited",
      cooldown_ms: MIN_BLOCK_BREAK_INTERVAL_MS,
      x: update ? Math.trunc(Number(update.x) || 0) : undefined,
      y: update ? Math.trunc(Number(update.y) || 0) : undefined,
      layer: update ? clampString(update.layer || "") : undefined,
      block_type: update ? clampString(update.block_type || "") : undefined,
    });
    return false;
  }

  player.last_block_break_at = now;
  return true;
}

function validateBlockHitPace(
  socket: unknown,
  player: ServerPacketRecord,
  update: ServerPacketRecord | null = null,
) {
  if (isAdmin(player)) return true;

  const now = Date.now();
  const lastHitAt = Number(player.last_block_hit_at || 0);
  if (lastHitAt > 0 && now - lastHitAt < MIN_BLOCK_HIT_INTERVAL_MS) {
    sendActionRejected(socket, "world_block_update", "Slow down a little.", {
      reason: "block_hit_rate_limited",
      cooldown_ms: MIN_BLOCK_HIT_INTERVAL_MS,
      x: update ? Math.trunc(Number(update.x) || 0) : undefined,
      y: update ? Math.trunc(Number(update.y) || 0) : undefined,
      layer: update ? clampString(update.layer || "") : undefined,
      block_type: update ? clampString(update.block_type || "") : undefined,
    });
    return false;
  }

  player.last_block_hit_at = now;
  return true;
}

function validateBlockPlacePace(socket: any, player: any, update: any = null) {
  if (isAdmin(player)) return true;

  const now = Date.now();
  const lastPlaceAt = Number(player.last_block_place_at || 0);
  if (lastPlaceAt > 0 && now - lastPlaceAt < MIN_BLOCK_PLACE_INTERVAL_MS) {
    sendActionRejected(socket, "world_block_update", "Slow down a little.", {
      reason: "place_rate_limited",
      cooldown_ms: MIN_BLOCK_PLACE_INTERVAL_MS,
      x: update ? Math.trunc(Number(update.x) || 0) : undefined,
      y: update ? Math.trunc(Number(update.y) || 0) : undefined,
      layer: update ? clampString(update.layer || "") : undefined,
      block_type: update ? clampString(update.block_type || "") : undefined,
    });
    return false;
  }

  player.last_block_place_at = now;
  return true;
}

function getPunchToggleBlockDefinition(blockType: any) {
  const clean = clampString(blockType || "");
  if (clean === "") return null;
  const definition = ItemDatabase.getItemDefinition(clean);
  if (!definition || definition.category !== "block" || definition.punch_toggle_block !== true) return null;
  return definition;
}

function isPunchToggleBlockType(blockType: any) {
  return getPunchToggleBlockDefinition(blockType) !== null;
}

function getPunchToggleInactiveBlockType(blockType: any) {
  const clean = clampString(blockType || "");
  const definition = getPunchToggleBlockDefinition(clean);
  if (!definition) return "";
  return clampString(definition.toggle_inactive_block || definition.toggle_drop_block || clean);
}

function getPunchToggleActiveBlockType(blockType: any) {
  const definition = getPunchToggleBlockDefinition(blockType);
  if (!definition) return "";
  return clampString(definition.toggle_active_block || "");
}

function getPunchToggleNextBlockType(blockType: any) {
  const clean = clampString(blockType || "");
  const inactive = getPunchToggleInactiveBlockType(clean);
  const active = getPunchToggleActiveBlockType(clean);
  if (inactive === "" || active === "") return "";
  if (!ItemDatabase.hasItem(inactive) || !ItemDatabase.hasItem(active)) return "";
  return clean === active ? inactive : active;
}

function getBlockDamageIdentityBlockType(blockType: any) {
  const clean = clampString(blockType || "");
  if (clean === "") return "";
  if (!isPunchToggleBlockType(clean)) return clean;
  return getPunchToggleInactiveBlockType(clean) || clean;
}

function arePunchToggleBlockVariants(leftBlockType: any, rightBlockType: any) {
  const left = clampString(leftBlockType || "");
  const right = clampString(rightBlockType || "");
  if (left === "" || right === "") return false;
  if (!isPunchToggleBlockType(left) || !isPunchToggleBlockType(right)) return false;
  return getBlockDamageIdentityBlockType(left) === getBlockDamageIdentityBlockType(right);
}

function makeBlockDamageKey(worldName: any, update: any) {
  return `${cleanWorld(worldName)}:${update.layer}:${Math.trunc(Number(update.x) || 0)},${Math.trunc(Number(update.y) || 0)}:${getBlockDamageIdentityBlockType(update.block_type || "")}`;
}

function getWorldBlockActionLockResource(worldName: any, update: any) {
  const clean = cleanWorld(worldName || update?.world || "START");
  const layer = clampString(update?.layer || "foreground") || "foreground";
  let x: any = Math.trunc(Number(update?.x) || 0);
  let y: any = Math.trunc(Number(update?.y) || 0);

  if ((update?.action === "break" || update?.action === "hit") && layer === "foreground") {
    const anchorBlock = getCollisionAreaAnchorInState(ensureWorldState(clean), x, y);
    if (anchorBlock) {
      x = Math.trunc(Number(anchorBlock.x) || x);
      y = Math.trunc(Number(anchorBlock.y) || y);
    }
  }

  return `${clean}:${layer}:${x},${y}`;
}

function clearServerBlockDamage(worldName: any, update: any) {
  if (!update) return;
  blockDamage.delete(makeBlockDamageKey(worldName, update));
}

function getPlayerBreakPower(player: any, blockType: any) {
  const handItem = clampString(player?.equipment_slots?.hand || "");
  return ItemDatabase.getBreakPower(handItem, blockType);
}

function applyServerBlockDamage(player: any, worldName: any, update: any) {
  const key = makeBlockDamageKey(worldName, update);
  const now = Date.now();
  const handItem = clampString(player?.equipment_slots?.hand || "");
  const requiredDamage = ItemDatabase.getRequiredBreakDamage(handItem, update.block_type);
  const hitPower = getPlayerBreakPower(player, update.block_type);
  const previous = blockDamage.get(key);
  const currentDamage = previous && now - previous.updatedAt <= BLOCK_DAMAGE_RESET_MS
    ? Math.max(0, Math.trunc(Number(previous.damage) || 0))
    : 0;
  const nextDamage = Math.min(requiredDamage, currentDamage + hitPower);

  if (nextDamage < requiredDamage) {
    blockDamage.set(key, {
      damage: nextDamage,
      updatedAt: now,
    });
    return {
      ok: true,
      shouldBreak: false,
      damage: nextDamage,
      required: requiredDamage,
      hitPower,
    };
  }

  blockDamage.delete(key);
  return {
    ok: true,
    shouldBreak: true,
    damage: requiredDamage,
    required: requiredDamage,
    hitPower,
  };
}

function getGemDropRangeForRarity(rarity: any) {
  switch (String(rarity || "common").toLowerCase()) {
    case "uncommon":
      return [1, 3];
    case "rare":
      return [2, 6];
    case "epic":
      return [5, 12];
    case "legendary":
      return [15, 40];
    case "common":
    default:
      return [0, 1];
  }
}

function getBlockDropChanceForRarity(rarity: any) {
  switch (String(rarity || "common").toLowerCase()) {
    case "uncommon":
      return 0.8;
    case "rare":
      return 0.65;
    case "epic":
      return 0.45;
    case "legendary":
      return 0.25;
    case "common":
    default:
      return 0.9;
  }
}

function getSeedDropChanceForRarity(rarity: any) {
  switch (String(rarity || "common").toLowerCase()) {
    case "uncommon":
      return 0.6;
    case "rare":
      return 0.4;
    case "epic":
      return 0.2;
    case "legendary":
      return 0.1;
    case "common":
    default:
      return 0.8;
  }
}

function shouldSuppressRarityGemDrop(rules: any) {
  if (!rules || typeof rules !== "object" || !Array.isArray(rules.gem_range)) return false;
  const max = Math.trunc(Number(rules.gem_range[1]) || 0);
  return max <= 0;
}

function shouldSuppressRaritySeedDrop(rules: any) {
  if (!rules || typeof rules !== "object" || !Object.prototype.hasOwnProperty.call(rules, "seed_chance")) return false;
  return Number(rules.seed_chance) <= 0;
}

function shouldAlwaysReturnBlockOnBreak(itemId: any, definition: any, rules: any) {
  if (isVendBlockType(itemId)) return true;
  if (itemId === "crafting_station") return true;
  if (rules && rules.drops_self === true) return true;
  if (Number(definition?.shop_price || 0) > 0) return true;
  return false;
}

function getDirectBreakInventoryReturn(blockType: any) {
  const itemId = clampString(blockType || "", MAX_ITEM_ID_LENGTH);
  const definition = ItemDatabase.getItemDefinition(itemId);
  if (!definition || definition.category !== "block" || definition.break_return_to_inventory !== true) {
    return null;
  }

  const returnItemId = clampString(definition.break_return_item_id || itemId, MAX_ITEM_ID_LENGTH);
  if (returnItemId === "" || !ItemDatabase.hasItem(returnItemId)) return null;

  const itemCategory = resolveInventoryCategory(returnItemId, "block");
  if (!ItemDatabase.canStoreItemInCategory(returnItemId, itemCategory)) return null;

  return {
    item_id: returnItemId,
    item_category: itemCategory,
    amount: 1,
  };
}

function isGemCurrencyDrop(itemType: any, itemCategory: any = "") {
  const cleanItemId = clampString(itemType || "", MAX_ITEM_ID_LENGTH);
  const resolvedCategory = String(resolveInventoryCategory(cleanItemId, itemCategory || "") || "").trim().toLowerCase();
  return cleanItemId === "gem" && resolvedCategory === "currency";
}

function getGemDropTotalAmountOnTile(worldName: any, stackGrid: any) {
  if (!stackGrid || !isGridInWorld(stackGrid.x, stackGrid.y)) return 0;

  const state = ensureWorldState(worldName);
  let total: any = 0;
  for (const drop of state.drops.values()) {
    const dropItemId = clampString(drop?.item_type || drop?.item_id || "", MAX_ITEM_ID_LENGTH);
    const dropCategory = resolveInventoryCategory(dropItemId, drop?.item_category || drop?.category || "");
    if (!isGemCurrencyDrop(dropItemId, dropCategory)) continue;

    const dropGrid = getDropStackGridFromDrop(drop);
    if (!dropGrid || dropGrid.x !== stackGrid.x || dropGrid.y !== stackGrid.y) continue;

    total += clampInteger(drop?.amount || 0, 0, MAX_DROP_TILE_AMOUNT);
    if (total >= MAX_DROP_TILE_AMOUNT) return MAX_DROP_TILE_AMOUNT;
  }

  return Math.min(MAX_DROP_TILE_AMOUNT, total);
}

/**
 * @param {PixelMania.WorldName | string} worldName
 * @param {PixelMania.ItemId | string} itemType
 * @param {string} itemCategory
 * @param {number} amount
 * @param {number} x
 * @param {number} y
 * @param {number} pickupDelay
 * @param {PixelMania.TilePosition | null} stackGrid
 * @returns {PixelMania.SanitizedDropCreate | null}
 */
function createServerDrop(worldName: any, itemType: any, itemCategory: any, amount: any, x: any, y: any, pickupDelay: any = SERVER_DROP_PICKUP_DELAY, stackGrid: any = null) {
  const itemId = clampString(itemType || "");
  if (!ItemDatabase.hasItem(itemId)) return null;

  const resolvedCategory = resolveInventoryCategory(itemId, itemCategory);
  if (!ItemDatabase.canStoreItemInCategory(itemId, resolvedCategory)) return null;

  let safeAmount: any = clampInteger(amount || 1, 1, MAX_DROP_TILE_AMOUNT);
  const dropX = Number(x) || 0;
  const dropY = Number(y) || 0;
  const explicitStackGrid = stackGrid && Number.isFinite(Number(stackGrid.x)) && Number.isFinite(Number(stackGrid.y))
    ? { x: Math.trunc(Number(stackGrid.x)), y: Math.trunc(Number(stackGrid.y)) }
    : null;
  const resolvedStackGrid = explicitStackGrid || getDropGridFromPosition({ x: dropX, y: dropY });
  if (isGemCurrencyDrop(itemId, resolvedCategory) && resolvedStackGrid) {
    const remainingTileCapacity = Math.max(0, MAX_DROP_TILE_AMOUNT - getGemDropTotalAmountOnTile(worldName, resolvedStackGrid));
    safeAmount = Math.min(safeAmount, remainingTileCapacity);
    if (safeAmount <= 0) return null;
  }
  const payload: any = {
    type: "drop_spawned",
    world: cleanWorld(worldName),
    drop_id: makeServerDropId(worldName, itemId),
    item_type: itemId,
    item_category: resolvedCategory,
    is_seed: resolvedCategory === "seed",
    amount: safeAmount,
    x: dropX,
    y: dropY,
    pickup_delay: Math.max(0, Number(pickupDelay) || 0),
  };
  if (resolvedStackGrid) {
    payload.stack_grid_x = resolvedStackGrid.x;
    payload.stack_grid_y = resolvedStackGrid.y;
  }

  applyDropCreateToWorldState(worldName, payload);
  return payload;
}

function getFixedBreakDropAmount(fixedDrop: any) {
  if (!fixedDrop || typeof fixedDrop !== "object") return 0;

  const amountRange = Array.isArray(fixedDrop.amount_range)
    ? fixedDrop.amount_range
    : (Array.isArray(fixedDrop.amountRange) ? fixedDrop.amountRange : null);
  if (amountRange && amountRange.length >= 2) {
    const minAmount = clampInteger(amountRange[0], 0, MAX_DROP_TILE_AMOUNT);
    const maxAmount = clampInteger(amountRange[1], minAmount, MAX_DROP_TILE_AMOUNT);
    return randomRangeInclusive(Math.min(minAmount, maxAmount), Math.max(minAmount, maxAmount));
  }

  return clampInteger(fixedDrop.amount || 1, 1, MAX_DROP_TILE_AMOUNT);
}

function getBreakDropFromRuleEntry(ruleEntry: any) {
  if (!ruleEntry || typeof ruleEntry !== "object") return null;

  const dropItemId = clampString(ruleEntry.item_id || ruleEntry.item_type || "");
  if (dropItemId === "" || !ItemDatabase.hasItem(dropItemId)) return null;

  const dropCategory = resolveInventoryCategory(dropItemId, ruleEntry.item_category || ruleEntry.category || "");
  if (!ItemDatabase.canStoreItemInCategory(dropItemId, dropCategory)) return null;

  const amount = getFixedBreakDropAmount(ruleEntry);
  if (amount <= 0) return null;

  return {
    item_id: dropItemId,
    item_category: dropCategory,
    amount,
  };
}

function rollWeightedBreakDrop(lootTable: any) {
  if (!Array.isArray(lootTable)) return null;

  const candidates: any = [];
  let totalWeight: any = 0;
  for (const entry of lootTable) {
    if (!entry || typeof entry !== "object") continue;
    const drop = getBreakDropFromRuleEntry(entry);
    if (!drop) continue;

    const weight = Math.max(0, Number(entry.weight) || 0);
    if (weight <= 0) continue;

    totalWeight += weight;
    candidates.push({ drop, weight });
  }

  if (totalWeight <= 0 || candidates.length === 0) return null;

  let roll: any = Math.random() * totalWeight;
  for (const candidate of candidates) {
    roll -= candidate.weight;
    if (roll < 0) return candidate.drop;
  }

  return candidates[candidates.length - 1].drop;
}

function getConfiguredDropsFromRules(rules: any) {
  if (!rules || typeof rules !== "object") return null;

  const lootTable = Array.isArray(rules.loot_table)
    ? rules.loot_table
    : (Array.isArray(rules.weighted_drops) ? rules.weighted_drops : null);
  if (lootTable) {
    const weightedDrop = rollWeightedBreakDrop(lootTable);
    return weightedDrop ? [weightedDrop] : [];
  }

  if (!Array.isArray(rules.fixed_drops)) return null;

  const drops: any = [];
  for (const fixedDrop of rules.fixed_drops) {
    const chance = Object.prototype.hasOwnProperty.call(fixedDrop, "chance")
      ? Math.max(0, Math.min(1, Number(fixedDrop.chance) || 0))
      : 1;
    if (Math.random() > chance) continue;

    const drop = getBreakDropFromRuleEntry(fixedDrop);
    if (drop) drops.push(drop);
  }
  return drops;
}

function getBreakDropsForBlock(blockType: any, layer: any) {
  const itemId = clampString(blockType || "");
  const definition = ItemDatabase.getItemDefinition(itemId);
  if (!definition || definition.category !== "block") return [];
  if (getDirectBreakInventoryReturn(itemId)) return [];

  const drops: any = [];
  const rules = definition.drop_rules && typeof definition.drop_rules === "object" ? definition.drop_rules : {};
  const configuredDrops = getConfiguredDropsFromRules(rules);
  if (configuredDrops) return configuredDrops;

  if (isVendBlockType(itemId)) {
    drops.push({ item_id: VEND_BLOCK_TYPE, item_category: "block", amount: 1 });
  } else if (itemId === "crafting_station") {
    drops.push({ item_id: "crafting_station", item_category: "block", amount: 1 });
  } else if (
    itemId !== "crafting_station_left" &&
    itemId !== "crafting_station_right" &&
    ItemDatabase.isDropableItem(itemId) &&
    (shouldAlwaysReturnBlockOnBreak(itemId, definition, rules) || randomChance(getBlockDropChanceForRarity(definition.rarity)))
  ) {
    drops.push({ item_id: itemId, item_category: "block", amount: 1 });
  }

  const seedId = clampString(definition.seed || "");
  const seedChance = shouldSuppressRaritySeedDrop(rules) ? 0 : getSeedDropChanceForRarity(definition.rarity);
  if (seedId !== "" && ItemDatabase.hasItem(seedId) && randomChance(seedChance)) {
    drops.push({ item_id: seedId, item_category: "seed", amount: 1 });
  }

  if (layer === "foreground" && ItemDatabase.hasItem("gem")) {
    const configuredRange = shouldSuppressRarityGemDrop(rules) ? [0, 0] : getGemDropRangeForRarity(definition.rarity);
    const gemAmount = randomRangeInclusive(configuredRange[0], configuredRange[1]);
    if (gemAmount > 0) {
      drops.push({ item_id: "gem", item_category: "currency", amount: gemAmount });
    }
  }

  return drops;
}

function getTreeHarvestDropsForBlock(blockType: any) {
  const itemId = clampString(blockType || "");
  const definition = ItemDatabase.getItemDefinition(itemId);
  if (!definition || definition.category !== "block") return null;

  const rules = definition.tree_drop_rules && typeof definition.tree_drop_rules === "object"
    ? definition.tree_drop_rules
    : (definition.harvest_drop_rules && typeof definition.harvest_drop_rules === "object" ? definition.harvest_drop_rules : null);
  return getConfiguredDropsFromRules(rules);
}

function isWaterBucketScoopBreak(update: any) {
  return Boolean(update
    && update.action === "break"
    && update.block_type === WATER_BLOCK_TYPE
    && String(update.water_bucket_action || "").trim().toLowerCase() === "scoop");
}

function createBreakDrops(worldName: any, update: any) {
  if (!update || update.action !== "break" || update.block_type === "") return [];
  if (isWaterBucketScoopBreak(update)) return [];

  const position = getGridCenterPixels(update.x, update.y);
  const drops = getBreakDropsForBlock(update.block_type, update.layer);
  const createdDrops: any = [];
  for (const drop of drops) {
    const payload = createServerDrop(
      worldName,
      drop.item_id,
      drop.item_category,
      drop.amount,
      position.x,
      position.y,
      SERVER_DROP_PICKUP_DELAY
    );
    if (!payload) continue;
    createdDrops.push(payload);
  }
  return createdDrops;
}

function emitBreakDrops(worldName: any, update: any, socket: any = null, player: any = null) {
  const createdDrops = createBreakDrops(worldName, update);
  for (const payload of createdDrops) {
    if (socket && player) {
      sendWorldUpdateToRequesterAndWorld(socket, player, worldName, payload);
    } else {
      queueWorldUpdateBroadcast(worldName, payload);
    }
  }
  return createdDrops;
}

/**
 * @returns {Promise<PixelMania.WorldInventoryValidationResult>}
 */
async function prepareVendBreakInventoryReturn(socket: any, player: any, worldName: any, update: any) {
  const vend = getVendStateAt(worldName, update.x, update.y, false);
  const listing = vend.listing && Number(vend.listing.stock) > 0 ? vend.listing : null;
  const pendingWls = clampInteger(vend.pending_wls || 0, 0, ItemDatabase.getStackLimit("world_lock"));
  const machineReturn = getDirectBreakInventoryReturn(update.block_type);

  if (!listing && pendingWls <= 0 && !machineReturn) {
    return { ok: true, playerState: null, message: "" };
  }

  if (!canPlayerManageVend(player, vend, worldName)) {
    sendActionRejected(socket, "world_block_update", isWorldLocked(worldName) ? "Only the world owner can break this vending machine." : "Only the vending machine owner can break it while it has items.", {
      reason: isWorldLocked(worldName) ? "vending_owner_required" : "vending_owner_required",
      block_type: update.block_type,
    });
    return { ok: false };
  }

  const state = ensureWritablePlayerState(player.account_username);
  if (!state) {
    sendActionRejected(socket, "world_block_update", "Could not load your server inventory.", {
      reason: "inventory_unavailable",
      block_type: update.block_type,
    });
    return { ok: false };
  }

  const beforeState = cloneJson(state);
  const stagedState = cloneJson(state);
  const originalVend = cloneJson(vend);
  const returned: string[] = [];
  const returnedEntries: Array<{
    item_id: string;
    item_category: string;
    amount: number;
    reason: string;
    listing_transaction_id?: string;
  }> = [];
  if (machineReturn) {
    if (!canAddItemToState(stagedState, machineReturn.item_id, machineReturn.item_category, machineReturn.amount)) {
      sendActionRejected(socket, "world_block_update", "Your inventory cannot hold the vending machine.", {
        reason: "insufficient_capacity",
        block_type: update.block_type,
        item_id: machineReturn.item_id,
      });
      return { ok: false };
    }

    addItemToState(stagedState, machineReturn.item_id, machineReturn.item_category, machineReturn.amount);
    returned.push("Vending Machine x1");
    returnedEntries.push({
      item_id: machineReturn.item_id,
      item_category: machineReturn.item_category,
      amount: machineReturn.amount,
      reason: "vending_machine_break_recovery",
    });
  }

  if (listing) {
    const itemId = clampString(listing.item_id || "");
    const itemCategory = resolveInventoryCategory(itemId, listing.item_category || "");
    const stock = clampInteger(listing.stock || 0, 1, ItemDatabase.getStackLimit(itemId));
    if (!canAddItemToState(stagedState, itemId, itemCategory, stock)) {
      sendActionRejected(socket, "world_block_update", "Your inventory cannot hold the vending item.", {
        reason: "insufficient_capacity",
        block_type: update.block_type,
        item_id: itemId,
      });
      return { ok: false };
    }

    addItemToState(stagedState, itemId, itemCategory, stock);
    returned.push(`${itemId} x${stock}`);
    returnedEntries.push({
      item_id: itemId,
      item_category: itemCategory,
      amount: stock,
      reason: "vending_stock",
      listing_transaction_id: listing.listing_id || listing.transaction_id || "",
    });
  }

  if (pendingWls > 0) {
    if (!canAddItemToState(stagedState, "world_lock", "block", pendingWls)) {
      sendActionRejected(socket, "world_block_update", "Your inventory cannot hold those World Locks.", {
        reason: "insufficient_capacity",
        block_type: update.block_type,
        item_id: "world_lock",
      });
      return { ok: false };
    }

    addItemToState(stagedState, "world_lock", "block", pendingWls);
    returned.push(`World Lock x${pendingWls}`);
    returnedEntries.push({
      item_id: "world_lock",
      item_category: "block",
      amount: pendingWls,
      reason: "vending_pending_wls",
    });
  }

  if (listing) {
    vend.listing = null;
  }
  if (pendingWls > 0) {
    vend.pending_wls = 0;
  }

  const rollbackWorldState = serializeWorldState(worldName);
  setVendStateAt(worldName, vend);
  const vendBreakTransactionId = makeAuditId("vend_break");
  const vendBreakWorldChange = buildWorldObjectChangeEntry(
    socket,
    player,
    worldName,
    {
      type: "world_interaction_update",
      source_type: "vending_break_return",
      source_id: vendBreakTransactionId,
      action: "vending_break_return",
      x: vend.x,
      y: vend.y,
      block_type: update.block_type,
      object_type: "vending",
      state: vend,
    },
    originalVend,
    vend,
    vendBreakTransactionId,
    { returned_entries: returnedEntries }
  );
  const vendBreakMetadata: any = { transaction_id: vendBreakTransactionId, x: vend.x, y: vend.y, returned_entries: returnedEntries };
  if (isPostgresAuthoritativeReady()) {
    return {
      ok: true,
      playerState: stagedState,
      inventoryDeltas: buildInventoryDeltasBetweenStates(beforeState, stagedState),
      deferred_inventory_commit: InventoryContracts.buildDeferredInventoryCommit({
        username: player.account_username,
        beforeState,
        afterState: stagedState,
        options: {
          source: "vending",
          action: "vending_break_return",
          reason: "vending_break_return",
          request_id: "",
          world: worldName,
          metadata: vendBreakMetadata,
          failure_message: "Server inventory changed. Try again.",
        },
      }),
      rollbackWorldState,
      worldChanges: [vendBreakWorldChange],
      postCommitLogs: {
        vendingTransaction: {
          transaction_id: vendBreakTransactionId,
          action: "break_return",
          world: worldName,
          x: vend.x,
          y: vend.y,
          owner_username: vend.owner_username,
          amount: returnedEntries.reduce((total, entry) => total + Number(entry.amount || 0), 0),
          stock_after: 0,
          pending_wls_after: 0,
          details: { returned_entries: returnedEntries },
        },
        itemLedgerEntries: returnedEntries.map((entry) => ({
          item_id: entry.item_id,
          item_category: entry.item_category,
          amount: entry.amount,
          source_type: "vending_break_return",
          source_id: vendBreakTransactionId,
          reason: entry.reason,
          details: { x: vend.x, y: vend.y },
        })),
      },
      message: returned.length > 0 ? `Returned ${returned.join(", ")}.` : "",
    };
  }

  const serializedWorld = serializeWorldState(worldName);
  const commit = await commitPlayerInventoryState(socket, player, player.account_username, beforeState, stagedState, {
    source: "vending",
    action: "vending_break_return",
    reason: "vending_break_return",
    request_id: "",
    world: worldName,
    metadata: vendBreakMetadata,
    world_state: serializedWorld,
    failure_message: "Server inventory changed. Try again.",
  });
  if (!commit.ok) {
    setVendStateAt(worldName, originalVend);
    sendActionRejected(socket, "world_block_update", commit.message, {
      reason: commit.reason || "inventory_commit_failed",
      block_type: update.block_type,
    });
    return { ok: false };
  }
  const committedState = commit.state;
  persistWorldStateAfterInventoryCommit(worldName, commit.postgres_committed, serializedWorld);
  logVendingTransaction(socket, player, {
    transaction_id: vendBreakTransactionId,
    action: "break_return",
    world: worldName,
    x: vend.x,
    y: vend.y,
    owner_username: vend.owner_username,
    amount: returnedEntries.reduce((total, entry) => total + Number(entry.amount || 0), 0),
    stock_after: 0,
    pending_wls_after: 0,
    details: { returned_entries: returnedEntries },
  });
  logWorldChange(socket, player, {
    source_type: "vending_break_return",
    source_id: vendBreakTransactionId,
    world: worldName,
    action: "vending_break_return",
    x: vend.x,
    y: vend.y,
    block_type: update.block_type,
    details: { returned_entries: returnedEntries },
  });
  for (const entry of returnedEntries) {
    logItemLedgerForState(socket, player, player.account_username, committedState, entry.item_id, entry.item_category, entry.amount, "vending_break_return", vendBreakTransactionId, entry.reason, worldName, {
      x: vend.x,
      y: vend.y,
    }, { skipPostgres: commit.postgres_committed });
  }

  return {
    ok: true,
    playerState: committedState,
    inventoryDeltas: Array.isArray(commit.deltas) ? commit.deltas : [],
    postgres_committed: commit.postgres_committed,
    message: returned.length > 0 ? `Returned ${returned.join(", ")}.` : "",
  };
}

/**
 * @param {PixelMania.InventoryCommitOptions} options
 * @returns {Promise<PixelMania.WorldInventoryValidationResult>}
 */
async function validateBlockUpdateAgainstServerState(socket: any, player: any, worldName: any, update: any, requestId: any = "", options: any = {}) {
  const state = ensureWorldState(worldName);
  let key: any = gridKey(update.x, update.y);

  const reachPixels = getBlockActionReachPixels(update);
  if (!isPlayerNearGrid(player, update.x, update.y, reachPixels, { action: `world_block_${update.action}`, world: worldName })) {
    const position = getPlayerValidationPosition(player, { action: `world_block_${update.action}`, world: worldName });
    if (usesTrustedMovementPosition(player) && !position.ok) {
      rejectMissingTrustedPosition(socket, "world_block_update", player, position, {
        target_x: update.x,
        target_y: update.y,
        max_reach_tiles: update.action === "place" ? MAX_PLACE_REACH_TILES : MAX_BREAK_REACH_TILES,
      });
      return { ok: false };
    }
    sendActionRejected(socket, "world_block_update", "Too far away.", {
      reason: "too_far",
      target_x: update.x,
      target_y: update.y,
      max_reach_tiles: update.action === "place" ? MAX_PLACE_REACH_TILES : MAX_BREAK_REACH_TILES,
      block_type: update.block_type,
    });
    return { ok: false };
  }

  if (update.action === "break" || update.action === "hit") {
    const targetLayer = getWorldLayerMap(state, update.layer);
    const removedLayer = getWorldRemovedLayerMap(state, update.layer);
    let serverBlock: any = targetLayer.get(key);
    if (!serverBlock && update.layer === "foreground") {
      const anchorBlock = getCollisionAreaAnchorInState(state, update.x, update.y);
      if (anchorBlock) {
        update.x = anchorBlock.x;
        update.y = anchorBlock.y;
        key = gridKey(update.x, update.y);
        serverBlock = targetLayer.get(key);
      }
      if (!serverBlock) {
        serverBlock = getEffectiveGeneratedBottomForegroundBlockAt(worldName, state, update.x, update.y);
      }
    }
    const blockType = serverBlock ? serverBlock.block_type : update.block_type;

    if (removedLayer.has(key) && !serverBlock) {
      sendActionRejected(socket, "world_block_update", "That block is already broken.", {
        reason: "already_broken",
        block_type: update.block_type,
      });
      return { ok: false };
    }

    if (blockType === "") {
      sendActionRejected(socket, "world_block_update", "Server needs a block type to break.", {
        reason: "missing_block_type",
      });
      return { ok: false };
    }

    if (serverBlock && update.block_type !== "" && serverBlock.block_type !== update.block_type) {
      if (arePunchToggleBlockVariants(serverBlock.block_type, update.block_type)) {
        update.block_type = serverBlock.block_type;
        update.item_id = ItemAtlasDB.getItemIdForKey(update.block_type) || update.item_id;
      } else {
        sendActionRejected(socket, "world_block_update", "That block changed on the server.", {
          reason: "block_changed",
          block_type: update.block_type,
          server_block_type: serverBlock.block_type,
        });
        return { ok: false };
      }
    }

    const expectedLayer = ItemDatabase.getPlaceLayer(blockType);
    if (expectedLayer !== "" && expectedLayer !== update.layer) {
      sendActionRejected(socket, "world_block_update", "That block is on a different layer.", {
        reason: "wrong_layer",
        block_type: blockType,
        expected_layer: expectedLayer,
        requested_layer: update.layer,
      });
      return { ok: false };
    }

    update.block_type = blockType;

    if (update.block_type !== "" && !ItemDatabase.canBreakBlock(update.block_type)) {
      sendActionRejected(socket, "world_block_update", "That block cannot be broken.", {
        reason: "unbreakable",
        block_type: update.block_type,
      });
      return { ok: false };
    }

    if (update.block_type === WATER_BLOCK_TYPE && update.water_bucket_action !== "scoop") {
      sendActionRejected(socket, "world_block_update", "Use a Water Bucket to collect water.", {
        reason: "water_bucket_required",
        block_type: update.block_type,
      });
      return { ok: false };
    }

    if (update.layer === "foreground" && isDoorBlockType(update.block_type) && isPlayerStandingOnGrid(player, update.x, update.y)) {
      sendActionRejected(socket, "world_block_update", "Step off the door to break it.", {
        reason: "standing_on_door",
        block_type: update.block_type,
      });
      return { ok: false };
    }

    if (isWorldLockBlockType(update.block_type) && hasWorldLockProtectedStorageBlocks(worldName)) {
      sendActionRejected(socket, "world_block_update", "Remove all Safes, Donation Boxes, vending machines, Fish Mongers, and displays before breaking the World Lock.", {
        reason: "protected_storage_blocks",
        block_type: update.block_type,
      });
      return { ok: false };
    }

    if (update.layer === "foreground" && isAreaLockBlockType(update.block_type)) {
      const areaLock = getAreaLockAtGrid(state, update.x, update.y);
      if (!areaLock || !canPlayerManageAreaLock(player, worldName, areaLock)) {
        sendActionRejected(socket, "world_block_update", "Only the area lock owner can break this lock.", {
          reason: "area_lock_owner_required",
          block_type: update.block_type,
        });
        return { ok: false };
      }
    } else if (!canPlayerBuildAtGrid(player, worldName, update.x, update.y)) {
      sendActionRejected(socket, "world_block_update", "This area is locked.", {
        reason: "area_lock_permission_denied",
        block_type: update.block_type,
      });
      return { ok: false };
    }

    const isVendBreak = isVendBlockType(update.block_type);
    const isSafeBreak = isSafeBlockType(update.block_type);
    const isDonationBoxBreak = isDonationBoxBlockType(update.block_type);
    const isDisplayBreak = isDisplayBlockType(update.block_type);
    const isFishMongerBreak = isFishMongerBlockType(update.block_type);

    if (isFishMongerBreak && !canPlayerBreakFishMonger(player, worldName, update)) {
      sendActionRejected(socket, "world_block_update", "Only the world owner or players with access can break the Fish Monger.", {
        reason: "fish_monger_permission_denied",
        block_type: update.block_type,
      });
      return { ok: false };
    }

    if (isVendBreak) {
      if (!canPlayerBreakVendingMachine(player, worldName, update)) {
        sendActionRejected(socket, "world_block_update", isWorldLocked(worldName) ? "Only the world owner can break vending machines." : "Lock the world before breaking vending machines.", {
          reason: isWorldLocked(worldName) ? "vending_owner_required" : "world_lock_required",
          block_type: update.block_type,
        });
        return { ok: false };
      }
    }

    if (isSafeBreak) {
      if (!canPlayerBreakSafe(player, worldName, update)) {
        sendActionRejected(socket, "world_block_update", isWorldLocked(worldName) ? "Only the world owner can break safes." : "Lock the world before breaking safes.", {
          reason: isWorldLocked(worldName) ? "safe_owner_required" : "world_lock_required",
          block_type: update.block_type,
        });
        return { ok: false };
      }
    }

    if (isDonationBoxBreak) {
      if (!canPlayerBreakDonationBox(player, worldName, update)) {
        sendActionRejected(socket, "world_block_update", isWorldLocked(worldName) ? "Only the world owner can break Donation Boxes." : "Lock the world before breaking Donation Boxes.", {
          reason: isWorldLocked(worldName) ? "donation_box_owner_required" : "world_lock_required",
          block_type: update.block_type,
        });
        return { ok: false };
      }
    }

    if (isDisplayBreak) {
      if (!canPlayerBreakDisplay(player, worldName, update)) {
        sendActionRejected(socket, "world_block_update", isWorldLocked(worldName) ? "Only the world owner can break displays." : "Lock the world before breaking displays.", {
          reason: isWorldLocked(worldName) ? "display_owner_required" : "world_lock_required",
          block_type: update.block_type,
        });
        return { ok: false };
      }
    }

    if (isFishHangerBlockType(update.block_type)) {
      const fishHangerDisplay = getDisplayStateAt(worldName, update.x, update.y, false);
      const fishHangerSlot = sanitizeDisplaySlot(fishHangerDisplay.slot);
      if (fishHangerSlot) {
        clearServerBlockDamage(worldName, update);
        await handleDisplayWithdraw(socket, player, {
          type: "inventory_transaction_request",
          action: "display_withdraw",
          request_id: requestId,
          world: worldName,
          x: update.x,
          y: update.y,
          item_id: fishHangerSlot.item_id,
          item_type: fishHangerSlot.item_id,
          item_category: fishHangerSlot.item_category,
          amount: 1,
        }, worldName, fishHangerDisplay);
        return { ok: false };
      }
    }

    if (update.block_type === WATER_BLOCK_TYPE && update.water_bucket_action === "scoop") {
      update.action = "break";
      if (!validateBlockBreakPace(socket, player, update)) {
        return { ok: false };
      }
      return prepareWaterBucketScoopInventoryReturn(socket, player, worldName, update, requestId, {
        allow_dev_json_fallback: options.allow_dev_json_fallback === true,
      });
    }

    if (!validateBlockHitPace(socket, player, update)) {
      return { ok: false };
    }

    const damageResult = applyServerBlockDamage(player, worldName, update);
    if (!damageResult.ok) return { ok: false };
    update.hit_power = clampInteger(damageResult.hitPower || 1, 1, MAX_BLOCK_HIT_METRIC);
    update.hit_count = clampInteger(damageResult.damage || 0, 0, MAX_BLOCK_HIT_METRIC);
    update.max_hits = clampInteger(damageResult.required || 1, 1, MAX_BLOCK_HIT_METRIC);
    update.damage_reset_ms = BLOCK_DAMAGE_RESET_MS;
    if (!damageResult.shouldBreak) {
      const nextToggleBlockType = update.layer === "foreground"
        ? getPunchToggleNextBlockType(update.block_type)
        : "";
      if (nextToggleBlockType !== "") {
        const previousToggleBlockType = update.block_type;
        update.action = "place";
        update.block_type = nextToggleBlockType;
        update.item_id = ItemAtlasDB.getItemIdForKey(nextToggleBlockType) || update.item_id;
        update.toggle_action = "punch_toggle";
        update.toggle_from_block_type = previousToggleBlockType;
        update.toggle_to_block_type = nextToggleBlockType;
        return {
          ok: true,
          toggledBlock: true,
          toggle_from_block_type: previousToggleBlockType,
          toggle_to_block_type: nextToggleBlockType,
          toggled_to_solid: isSolidMovementCollisionBlock(nextToggleBlockType),
        };
      }
      update.action = "hit";
      return { ok: true, pendingHit: true };
    }

    update.action = "break";

    if (!validateBlockBreakPace(socket, player, update)) {
      return { ok: false };
    }

    if (isVendBreak) {
      const vendReturn = await prepareVendBreakInventoryReturn(socket, player, worldName, update);
      if (!vendReturn.ok) return { ok: false };
      return {
        ok: true,
        playerState: vendReturn.playerState || null,
        inventoryDeltas: Array.isArray(vendReturn.inventoryDeltas) ? vendReturn.inventoryDeltas : [],
        postgres_committed: vendReturn.postgres_committed,
        deferred_inventory_commit: vendReturn.deferred_inventory_commit || null,
        rollbackWorldState: vendReturn.rollbackWorldState || null,
        worldChanges: Array.isArray(vendReturn.worldChanges) ? vendReturn.worldChanges : [],
        postCommitLogs: vendReturn.postCommitLogs || null,
        message: vendReturn.message || "",
      };
    }

    if (isSafeBreak) {
      const safeReturn = await prepareSafeBreakInventoryReturn(socket, player, worldName, update);
      if (!safeReturn.ok) return { ok: false };
      return {
        ok: true,
        playerState: safeReturn.playerState || null,
        inventoryDeltas: Array.isArray(safeReturn.inventoryDeltas) ? safeReturn.inventoryDeltas : [],
        postgres_committed: safeReturn.postgres_committed,
        deferred_inventory_commit: safeReturn.deferred_inventory_commit || null,
        rollbackWorldState: safeReturn.rollbackWorldState || null,
        worldChanges: Array.isArray(safeReturn.worldChanges) ? safeReturn.worldChanges : [],
        postCommitLogs: safeReturn.postCommitLogs || null,
        message: safeReturn.message || "",
      };
    }
    if (isDonationBoxBreak) {
      const donationReturn = await prepareDonationBoxBreakInventoryReturn(socket, player, worldName, update);
      if (!donationReturn.ok) return { ok: false };
      return {
        ok: true,
        playerState: donationReturn.playerState || null,
        inventoryDeltas: Array.isArray(donationReturn.inventoryDeltas) ? donationReturn.inventoryDeltas : [],
        postgres_committed: donationReturn.postgres_committed,
        deferred_inventory_commit: donationReturn.deferred_inventory_commit || null,
        rollbackWorldState: donationReturn.rollbackWorldState || null,
        worldChanges: Array.isArray(donationReturn.worldChanges) ? donationReturn.worldChanges : [],
        postCommitLogs: donationReturn.postCommitLogs || null,
        message: donationReturn.message || "",
      };
    }
    if (isDisplayBreak) {
      const displayReturn = await prepareDisplayBreakInventoryReturn(socket, player, worldName, update);
      if (!displayReturn.ok) return { ok: false };
      return {
        ok: true,
        playerState: displayReturn.playerState || null,
        inventoryDeltas: Array.isArray(displayReturn.inventoryDeltas) ? displayReturn.inventoryDeltas : [],
        postgres_committed: displayReturn.postgres_committed,
        deferred_inventory_commit: displayReturn.deferred_inventory_commit || null,
        rollbackWorldState: displayReturn.rollbackWorldState || null,
        worldChanges: Array.isArray(displayReturn.worldChanges) ? displayReturn.worldChanges : [],
        postCommitLogs: displayReturn.postCommitLogs || null,
        message: displayReturn.message || "",
      };
    }
    if (getDirectBreakInventoryReturn(update.block_type)) {
      const directReturn: any = await prepareDirectBlockBreakInventoryReturn(socket, player, worldName, update, requestId, {
        allow_dev_json_fallback: options.allow_dev_json_fallback === true,
      });
      if (!directReturn.ok) return { ok: false };
      return {
        ok: true,
        playerState: directReturn.playerState || null,
        inventoryDeltas: Array.isArray(directReturn.inventoryDeltas) ? directReturn.inventoryDeltas : [],
        postgres_committed: directReturn.postgres_committed,
        deferred_inventory_commit: directReturn.deferred_inventory_commit || null,
        rollbackWorldState: directReturn.rollbackWorldState || null,
        worldChanges: Array.isArray(directReturn.worldChanges) ? directReturn.worldChanges : [],
        postCommitLogs: directReturn.postCommitLogs || null,
        message: directReturn.message || "",
      };
    }
    return { ok: true };
  }

  if (update.block_type === "crafting_station_left" || update.block_type === "crafting_station_right") {
    sendActionRejected(socket, "world_block_update", "Crafting Station is one block now. Please update your game.", {
      reason: "deprecated_block",
      block_type: update.block_type,
    });
    return { ok: false };
  }

  if (isElectricalLayerItem(update.block_type)) {
    sendActionRejected(socket, "world_block_update", "Place that on the electrical layer.", {
      reason: "electrical_layer_required",
      block_type: update.block_type,
    });
    return { ok: false };
  }

  if (update.block_type === WATER_BLOCK_TYPE && update.water_bucket_action !== "pour") {
    sendActionRejected(socket, "world_block_update", "Use a Water Bucket to place water.", {
      reason: "water_bucket_required",
      block_type: update.block_type,
    });
    return { ok: false };
  }

  if (!ItemDatabase.isPlaceableBlock(update.block_type)) {
    sendActionRejected(socket, "world_block_update", "That item cannot be placed.", {
      reason: "not_placeable",
      block_type: update.block_type,
    });
    return { ok: false };
  }

  if (isWorldLockBlockType(update.block_type) && isWorldLockPlacementBlocked(worldName)) {
    sendActionRejected(socket, "world_block_update", "This world already has a World Lock.", {
      reason: "world_lock_exists",
      block_type: update.block_type,
    });
    return { ok: false };
  }

  if (isAreaLockBlockType(update.block_type)) {
    const previewLock: any = {
      lock_type: normalizeAreaLockBlockType(update.block_type),
      lock_grid_x: update.x,
      lock_grid_y: update.y,
      max_tiles: getAreaLockTileLimit(update.block_type),
    };
    if (getAreaLockPositions(previewLock, state).some(
      (pos: ServerGridPoint) => getAreaLockCoveringGrid(state, pos.x, pos.y),
    )) {
      sendActionRejected(socket, "world_block_update", "That area is already protected by another lock.", {
        reason: "area_lock_overlap",
        block_type: update.block_type,
      });
      return { ok: false };
    }
  }

  if (!canPlayerBuildAtGrid(player, worldName, update.x, update.y)) {
    sendActionRejected(socket, "world_block_update", "This area is locked.", {
      reason: "area_lock_permission_denied",
      block_type: update.block_type,
    });
    return { ok: false };
  }

  if (isAntiPunchBlockType(update.block_type) && hasAntiPunchBlock(worldName)) {
    sendActionRejected(socket, "world_block_update", "This world already has an Anti-Punch block.", {
      reason: "anti_punch_exists",
      block_type: update.block_type,
    });
    return { ok: false };
  }

  if (isAntiTalkBlockType(update.block_type) && hasAntiTalkBlock(worldName)) {
    sendActionRejected(socket, "world_block_update", "This world already has an Anti-Talk block.", {
      reason: "anti_talk_exists",
      block_type: update.block_type,
    });
    return { ok: false };
  }

  if (isAntiGravityBlockType(update.block_type) && hasAntiGravityBlock(worldName)) {
    sendActionRejected(socket, "world_block_update", "This world already has an Anti-Gravity block.", {
      reason: "anti_gravity_exists",
      block_type: update.block_type,
    });
    return { ok: false };
  }

  if (isSnowRepellentBlockType(update.block_type) && hasSnowRepellentBlock(worldName)) {
    sendActionRejected(socket, "world_block_update", "This world already has a Snow Repellent block.", {
      reason: "snow_repellent_exists",
      block_type: update.block_type,
    });
    return { ok: false };
  }

  if (isFishMongerBlockType(update.block_type) && blockRequiresWorldLock(update.block_type) && !canPlayerPlaceFishMonger(player, worldName)) {
    const message = isWorldLocked(worldName) || hasWorldLockBlock(worldName)
      ? "This world is locked."
      : "You need a World Lock in this world before placing a Fish Monger.";
    sendActionRejected(socket, "world_block_update", message, {
      reason: isWorldLocked(worldName) || hasWorldLockBlock(worldName) ? "fish_monger_permission_denied" : "world_lock_required",
      block_type: update.block_type,
    });
    return { ok: false };
  }

  if (isVendBlockType(update.block_type) && !canPlayerPlaceVendingMachine(player, worldName)) {
    sendActionRejected(socket, "world_block_update", isWorldLocked(worldName) ? "Only the world owner can place vending machines." : "Lock this world before placing vending machines.", {
      reason: isWorldLocked(worldName) ? "vending_owner_required" : "world_lock_required",
      block_type: update.block_type,
    });
    return { ok: false };
  }

  if (isSafeBlockType(update.block_type) && !canPlayerPlaceSafe(player, worldName)) {
    sendActionRejected(socket, "world_block_update", isWorldLocked(worldName) ? "Only the world owner can place safes." : "Lock this world before placing safes.", {
      reason: isWorldLocked(worldName) ? "safe_owner_required" : "world_lock_required",
      block_type: update.block_type,
    });
    return { ok: false };
  }

  if (isDonationBoxBlockType(update.block_type) && !canPlayerPlaceDonationBox(player, worldName)) {
    sendActionRejected(socket, "world_block_update", isWorldLocked(worldName) ? "Only the world owner can place Donation Boxes." : "Lock this world before placing Donation Boxes.", {
      reason: isWorldLocked(worldName) ? "donation_box_owner_required" : "world_lock_required",
      block_type: update.block_type,
    });
    return { ok: false };
  }

  if (isDisplayBlockType(update.block_type) && !canPlayerPlaceDisplay(player, worldName)) {
    sendActionRejected(socket, "world_block_update", isWorldLocked(worldName) ? "Only the world owner can place displays." : "Lock this world before placing displays.", {
      reason: isWorldLocked(worldName) ? "display_owner_required" : "world_lock_required",
      block_type: update.block_type,
    });
    return { ok: false };
  }

  const requiredLayer = ItemDatabase.getPlaceLayer(update.block_type);
  if (requiredLayer !== update.layer) {
    sendActionRejected(socket, "world_block_update", `Place ${update.block_type} on the ${requiredLayer} layer.`, {
      reason: "wrong_layer",
      block_type: update.block_type,
      expected_layer: requiredLayer,
      requested_layer: update.layer,
    });
    return { ok: false };
  }

  const targetLayer = getWorldLayerMap(state, update.layer);
  const generatedBottomBlock = update.layer === "foreground"
    ? getEffectiveGeneratedBottomForegroundBlockAt(worldName, state, update.x, update.y)
    : null;
  if (targetLayer.has(key) || generatedBottomBlock) {
    sendActionRejected(socket, "world_block_update", "That spot is already occupied.", {
      reason: "occupied",
      block_type: update.block_type,
    });
    return { ok: false };
  }

  if (update.layer === "foreground" && state.seeds.has(key)) {
    sendActionRejected(socket, "world_block_update", "A seed is already planted there.", {
      reason: "seed_occupied",
      block_type: update.block_type,
    });
    return { ok: false };
  }

  if (update.layer === "foreground") {
    if (blockRequiresFullAreaClear(update.block_type)) {
      if (!validateFullCollisionAreaPlacement(socket, state, update)) return { ok: false };
    } else if (doesPlacementOverlapReservedObject(state, update.x, update.y, update.block_type)) {
      sendActionRejected(socket, "world_block_update", "Need enough empty space.", {
        reason: "reserved_space",
        block_type: update.block_type,
      });
      return { ok: false };
    }
  }

  if (!validateBlockPlacePace(socket, player, update)) {
    return { ok: false };
  }

  const cost = ItemDatabase.getPlacementCost(update.block_type);
  const spendResult = await spendServerInventoryCost(player.account_username, cost, {
    socket,
    player,
    source: "world_block_place",
    action: "world_block_place",
    reason: "placement_cost",
    request_id: requestId,
    world: worldName,
    metadata: { x: update.x, y: update.y, placed_block: update.block_type, layer: update.layer },
    allow_dev_json_fallback: options.allow_dev_json_fallback === true,
    defer_commit: isPostgresAuthoritativeReady(),
  });
  if (!spendResult.ok) {
    sendActionRejected(socket, "world_block_update", spendResult.message, {
      reason: spendResult.reason || "inventory_denied",
      item_id: cost.item_id,
      item_category: cost.item_category,
      amount: cost.amount,
      request_id: requestId,
      action: update.action,
      block_action: update.action,
      world: worldName,
      layer: update.layer,
      x: update.x,
      y: update.y,
      target_x: update.x,
      target_y: update.y,
      block_type: update.block_type,
    });
    return { ok: false };
  }

  return {
    ok: true,
    playerState: spendResult.state,
    postgres_committed: spendResult.postgres_committed,
    inventoryDeltas: Array.isArray(spendResult.deltas) ? spendResult.deltas : [],
    deferred_inventory_commit: spendResult.deferred_inventory_commit || null,
  };
}

async function validateSeedUpdateAgainstServerState(socket: any, player: any, worldName: any, update: any, requestId: any = "") {
  if (update.action !== "place") {
    sendActionRejected(socket, "world_seed_update", "Unsupported seed action.");
    return { ok: false };
  }

  if (!isPlayerNearGrid(player, update.x, update.y)) {
    sendActionRejected(socket, "world_seed_update", "Too far away.");
    return { ok: false };
  }

  if (!canPlayerBuildAtGrid(player, worldName, update.x, update.y)) {
    sendActionRejected(socket, "world_seed_update", "This area is locked.", {
      reason: "area_lock_permission_denied",
      seed_type: update.seed_type,
    });
    return { ok: false };
  }

  if (!ItemDatabase.hasItem(update.seed_type) || resolveInventoryCategory(update.seed_type) !== "seed") {
    sendActionRejected(socket, "world_seed_update", "That seed does not exist on the server.");
    return { ok: false };
  }

  const state = ensureWorldState(worldName);
  const key = gridKey(update.x, update.y);
  if (state.seeds.has(key)) {
    sendActionRejected(socket, "world_seed_update", "A seed is already planted there.");
    return { ok: false };
  }

  const spendResult = await spendServerInventoryCost(player.account_username, {
    item_id: update.seed_type,
    item_category: "seed",
    amount: 1,
  }, {
    socket,
    player,
    source: "seed_place",
    action: "world_seed_place",
    reason: "seed_plant_cost",
    request_id: requestId,
    world: worldName,
    metadata: { x: update.x, y: update.y, seed_type: update.seed_type },
  });
  if (!spendResult.ok) {
    sendActionRejected(socket, "world_seed_update", spendResult.message);
    return { ok: false };
  }

  return {
    ok: true,
    playerState: spendResult.state,
    postgres_committed: spendResult.postgres_committed,
    inventoryDeltas: Array.isArray(spendResult.deltas) ? spendResult.deltas : [],
  };
}

/**
 * @param {PixelMania.InventoryCommitOptions} options
 * @returns {Promise<PixelMania.WorldInventoryValidationResult>}
 */
async function validateElectricalLayerUpdateAgainstServerState(socket: any, player: any, worldName: any, update: any, requestId: any = "", options: any = {}) {
  if (!update) return { ok: false };

  if (!playerHasElectricToolEquipped(player)) {
    sendActionRejected(socket, "electrical_layer_update", "Equip the Electric Tool to edit wiring.", {
      reason: "electric_tool_required",
      block_type: update.block_type,
    });
    return { ok: false };
  }

  const reachPixels = update.action === "place" ? MAX_PLACE_REACH_PIXELS : MAX_BREAK_REACH_PIXELS;
  if (!isPlayerNearGrid(player, update.x, update.y, reachPixels, { action: `electrical_layer_${update.action}`, world: worldName })) {
    sendActionRejected(socket, "electrical_layer_update", "Too far away.", {
      reason: "too_far",
      target_x: update.x,
      target_y: update.y,
    });
    return { ok: false };
  }

  if (!canPlayerBuildAtGrid(player, worldName, update.x, update.y)) {
    sendActionRejected(socket, "electrical_layer_update", "This area is locked.", {
      reason: "area_lock_permission_denied",
      block_type: update.block_type,
    });
    return { ok: false };
  }

  const state = ensureWorldState(worldName);
  const key = gridKey(update.x, update.y);
  const existingEntry = state.electrical.get(key) || null;

  if (update.action === "place") {
    if (!isElectricalLayerItem(update.block_type)) {
      sendActionRejected(socket, "electrical_layer_update", "That item cannot be wired.", {
        reason: "not_electrical",
        block_type: update.block_type,
      });
      return { ok: false };
    }

    if (existingEntry && !canReplaceElectricalTile(existingEntry, update.block_type)) {
      sendActionRejected(socket, "electrical_layer_update", "That electrical spot is occupied.", {
        reason: "electrical_occupied",
        block_type: update.block_type,
      });
      return { ok: false };
    }

    const spendResult = await spendServerInventoryCost(player.account_username, {
      item_id: update.block_type,
      item_category: "block",
      amount: 1,
    }, {
      socket,
      player,
      source: "electrical_layer_place",
      action: "electrical_layer_place",
      reason: "electrical_placement_cost",
      request_id: requestId,
      world: worldName,
      metadata: { x: update.x, y: update.y, placed_block: update.block_type, layer: "electrical" },
      allow_dev_json_fallback: options.allow_dev_json_fallback === true,
      defer_commit: isPostgresAuthoritativeReady(),
    });
    if (!spendResult.ok) {
      sendActionRejected(socket, "electrical_layer_update", spendResult.message, {
        reason: spendResult.reason || "inventory_denied",
        item_id: update.block_type,
      });
      return { ok: false };
    }

    return {
      ok: true,
      playerState: spendResult.state,
      postgres_committed: spendResult.postgres_committed,
      inventoryDeltas: Array.isArray(spendResult.deltas) ? spendResult.deltas : [],
      deferred_inventory_commit: spendResult.deferred_inventory_commit || null,
    };
  }

  if (!existingEntry) {
    sendActionRejected(socket, "electrical_layer_update", "No electrical item there.", {
      reason: "missing_electrical_tile",
      block_type: update.block_type,
    });
    return { ok: false };
  }

  update.block_type = clampString(existingEntry.item_id || existingEntry.block_type || "");
  update.item_id = update.block_type;
  update.device_type = getElectricalDeviceTypeForItem(update.block_type, existingEntry.device_type || "");
  return { ok: true, previousEntry: cloneJson(existingEntry) };
}

function prepareWorldLockStateUpdate(socket: any, player: any, worldName: any, update: any) {
  const state = ensureWorldState(worldName);
  const currentLock: any = state.world_lock || {};
  const nextLock = update.state || {};

  if (currentLock.is_locked && !canPlayerControlWorldLock(player, worldName)) {
    sendActionRejected(socket, "world_lock_state", "Only the world lock owner can change this lock.");
    return false;
  }

  if (currentLock.is_locked && !nextLock.is_locked && hasWorldLockProtectedStorageBlocks(worldName)) {
    sendActionRejected(socket, "world_lock_state", "Remove all Safes, Donation Boxes, vending machines, Fish Mongers, and displays before unlocking the World Lock.");
    return false;
  }

  if (currentLock.is_locked && nextLock.is_locked && !isActiveWorldLockGrid(state, nextLock.lock_grid_x, nextLock.lock_grid_y)) {
    sendActionRejected(socket, "world_lock_state", "This world already has a World Lock.");
    return false;
  }

  if (nextLock.is_locked) {
    if (!isGridInWorld(nextLock.lock_grid_x, nextLock.lock_grid_y)) {
      sendActionRejected(socket, "world_lock_state", "World lock position is outside the world.");
      return false;
    }

    const lockBlock = state.foreground.get(gridKey(nextLock.lock_grid_x, nextLock.lock_grid_y));
    if (!lockBlock || !isWorldLockBlockType(lockBlock.block_type)) {
      sendActionRejected(socket, "world_lock_state", "Place a world lock block first.");
      return false;
    }
    nextLock.lock_block_type = normalizeWorldLockBlockType(lockBlock.block_type);
    nextLock.lock_type = nextLock.lock_block_type;

    if (!isAdmin(player)) {
      applyPlayerLockIdentityToState(nextLock, player);
    }
  }

  preserveWorldLockTradeKeyFields(currentLock, nextLock);
  update.state = nextLock;
  return true;
}

function normalizeWorldLockAccessRole(value: any, fallback: any = "builder") {
  const role = String(value || "").trim().toLowerCase();
  if (role === "access") return "builder";
  if (WORLD_LOCK_ACCESS_ROLES.has(role)) return role;
  return fallback;
}

function canWorldLockRoleBuild(role: any) {
  const cleanRole = normalizeWorldLockAccessRole(role, "");
  return cleanRole === "admin" || cleanRole === "builder";
}

function canWorldLockRoleToggleWoodenEntrance(role: any) {
  return normalizeWorldLockAccessRole(role, "") === "admin";
}

function getWorldLockRoleForAccount(lock: any, username: any) {
  const playerKey = accountKey(username);
  if (playerKey === "") return "";

  const roles = lock && typeof lock.player_roles === "object" && !Array.isArray(lock.player_roles)
    ? lock.player_roles
    : {};
  for (const [name, role] of Object.entries<any>(roles)) {
    if (accountKey(name) === playerKey) {
      return normalizeWorldLockAccessRole(role, "builder");
    }
  }

  const allowedPlayers = Array.isArray(lock?.allowed_players) ? lock.allowed_players : [];
  if (allowedPlayers.some((name: unknown) => accountKey(name) === playerKey)) {
    return "builder";
  }

  return "";
}

function getWorldLockRoleForPlayer(lock: any, player: any) {
  if (!player || !lock) return "";
  if (lockOwnerMatchesPlayer(lock, player)) return "owner";

  const identity = getPlayerLockIdentity(player);
  const rolesByAccountId = lock && typeof lock.player_roles_by_account_id === "object" && !Array.isArray(lock.player_roles_by_account_id)
    ? lock.player_roles_by_account_id
    : {};
  const rolesByPlayerId = lock && typeof lock.player_roles_by_player_id === "object" && !Array.isArray(lock.player_roles_by_player_id)
    ? lock.player_roles_by_player_id
    : {};
  if (identity.account_id !== "" && Object.prototype.hasOwnProperty.call(rolesByAccountId, identity.account_id)) {
    return normalizeWorldLockAccessRole(rolesByAccountId[identity.account_id], "builder");
  }
  if (identity.player_id !== "" && Object.prototype.hasOwnProperty.call(rolesByPlayerId, identity.player_id)) {
    return normalizeWorldLockAccessRole(rolesByPlayerId[identity.player_id], "builder");
  }

  const allowedAccountIds = Array.isArray(lock?.allowed_account_ids) ? lock.allowed_account_ids : [];
  if (identity.account_id !== "" && allowedAccountIds.some((id: unknown) => stableIdentityEquals(id, identity.account_id))) {
    return "builder";
  }
  const allowedPlayerIds = Array.isArray(lock?.allowed_player_ids) ? lock.allowed_player_ids : [];
  if (identity.player_id !== "" && allowedPlayerIds.some((id: unknown) => stableIdentityEquals(id, identity.player_id))) {
    return "builder";
  }

  return getWorldLockRoleForAccount(lock, identity.owner_name);
}

function isWorldLockOwnerAccount(lock: any, username: any) {
  const ownerKey = accountKey(lock?.owner_name || lock?.owner_username || "");
  if (ownerKey === "") return false;
  return ownerKey === accountKey(username);
}

function getWorldLockPullPermission(player: any, worldName: any) {
  if (!player || !player.authenticated) return { ok: false, role: "", lock: {} };

  const state = ensureWorldState(worldName);
  const lock: any = getEffectiveWorldLockStateInState(state);
  if (!lock.is_locked) return { ok: false, role: "", lock };

  if (lockOwnerMatchesPlayer(lock, player)) {
    return { ok: true, role: "owner", lock };
  }

  const role = normalizeWorldLockAccessRole(getWorldLockRoleForPlayer(lock, player), "");
  if (role === "admin") {
    return { ok: true, role, lock };
  }

  return { ok: false, role: "", lock };
}

function canPlayerToggleWoodenEntrance(player: any, worldName: any) {
  if (isAdmin(player)) return true;
  if (!player || !player.authenticated) return false;

  const state = ensureWorldState(worldName);
  const lock: any = getEffectiveWorldLockStateInState(state);
  if (!lock.is_locked) return true;

  const playerKey = accountKey(player.account_username);
  if (playerKey === "") return false;
  if (lockOwnerMatchesPlayer(lock, player)) return true;

  return canWorldLockRoleToggleWoodenEntrance(getWorldLockRoleForPlayer(lock, player));
}

function canPlayerPassWoodenEntrance(player: any, worldName: any) {
  if (isAdmin(player)) return true;
  if (!player || !player.authenticated) return false;

  const state = ensureWorldState(worldName);
  const lock: any = getEffectiveWorldLockStateInState(state);
  if (!lock.is_locked) return true;

  const playerKey = accountKey(player.account_username);
  if (playerKey === "") return false;
  if (lockOwnerMatchesPlayer(lock, player)) return true;

  return getWorldLockRoleForPlayer(lock, player) !== "";
}

function isSpringboardBlockType(blockType: any) {
  const clean = clampString(blockType || "");
  if (clean === "mushroom" || clean === "mushroom_1" || clean === "mushroom_2") return true;
  const definition = ItemDatabase.getItemDefinition(clean) || {};
  return Boolean(definition.springboard || definition.pinball_block || (Array.isArray(definition.springboard_animation_frames) && definition.springboard_animation_frames.length > 1));
}

function prepareSpringboardAnimationUpdate(socket: any, player: any, worldName: any, update: any) {
  const state = ensureWorldState(worldName);
  const block = state.foreground.get(gridKey(update.x, update.y));
  if (!block || !isSpringboardBlockType(block.block_type)) {
    sendActionRejected(socket, "world_interaction_update", "Springboard missing.");
    return false;
  }

  if (!isPlayerNearGrid(player, update.x, update.y)) {
    sendActionRejected(socket, "world_interaction_update", "Too far away.");
    return false;
  }

  update.block_type = block.block_type;
  return true;
}

function prepareEntrancePassUpdate(socket: any, player: any, worldName: any, update: any) {
  const state = ensureWorldState(worldName);
  const block = state.foreground.get(gridKey(update.x, update.y));
  if (!block || !isEntranceBlockType(block.block_type)) {
    sendActionRejected(socket, "world_interaction_update", "Entrance missing.");
    return false;
  }

  if (!isPlayerNearGrid(player, update.x, update.y)) {
    sendActionRejected(socket, "world_interaction_update", "Too far away.");
    return false;
  }

  const existing = state.interactions.get(gridKey(update.x, update.y)) || {};
  const locked = Boolean(existing.locked || block.entrance_locked);
  if (locked && !canPlayerPassWoodenEntrance(player, worldName)) {
    sendActionRejected(socket, "world_interaction_update", "Entrance locked.");
    return false;
  }

  update.block_type = block.block_type;
  update.walk_direction = Number(update.walk_direction) < 0 ? -1 : 1;
  return true;
}

function prepareWoodenEntranceStateUpdate(socket: any, player: any, worldName: any, update: any) {
  const state = ensureWorldState(worldName);
  const block = state.foreground.get(gridKey(update.x, update.y));
  if (!block || !isEntranceBlockType(block.block_type)) {
    sendActionRejected(socket, "world_interaction_update", "Entrance missing.");
    return false;
  }

  if (!isPlayerNearGrid(player, update.x, update.y)) {
    sendActionRejected(socket, "world_interaction_update", "Too far away.");
    return false;
  }

  if (!canPlayerToggleWoodenEntrance(player, worldName)) {
    sendActionRejected(socket, "world_interaction_update", "Only the world owner or world admins can lock this entrance.");
    return false;
  }

  update.locked = Boolean(update.locked);
  update.block_type = block.block_type;
  return true;
}

function prepareDoorStateUpdate(socket: any, player: any, worldName: any, update: any) {
  const state = ensureWorldState(worldName);
  const block = state.foreground.get(gridKey(update.x, update.y));
  if (!block || !isDoorBlockType(block.block_type)) {
    sendActionRejected(socket, "world_interaction_update", "Door missing.");
    return false;
  }

  if (!isPlayerNearGrid(player, update.x, update.y)) {
    sendActionRejected(socket, "world_interaction_update", "Too far away.");
    return false;
  }

  if (!canPlayerConfigureDoor(player, worldName)) {
    sendActionRejected(socket, "world_interaction_update", "Only the owner or trusted builders can edit this door.");
    return false;
  }

  const existing = state.interactions.get(gridKey(update.x, update.y)) || {};
  const existingLocked = Boolean(existing.locked || block.entrance_locked);
  if (Boolean(update.locked) !== existingLocked && !canPlayerToggleDoorLock(player, worldName)) {
    sendActionRejected(socket, "world_interaction_update", "Only the world owner or world admins can lock this door.");
    return false;
  }

  const passwordDoor = isPasswordDoorBlockType(block.block_type);
  const existingPassword = cleanDoorPassword(existing.password || existing.door_password || block.door_password || "");
  update.password_changed = passwordDoor && Boolean(update.password_changed);
  if (update.password_changed) {
    if (!canPlayerEditPasswordDoor(player, worldName)) {
      sendActionRejected(socket, "world_interaction_update", "Only the world owner can edit this password.");
      return false;
    }
    update.password = cleanDoorPassword(update.password || "");
  } else {
    delete update.password;
  }
  update.password_configured = update.password_changed
    ? cleanDoorPassword(update.password || "") !== ""
    : existingPassword !== "";
  if (Object.prototype.hasOwnProperty.call(update, "door_name") || Object.prototype.hasOwnProperty.call(update, "name")) {
    update.door_name = cleanDoorName(update.door_name || update.name || "");
  }
  update.locked = Boolean(update.locked);
  update.block_type = block.block_type;
  return true;
}

function sanitizeDoorEnterRequest(data: any, worldName: any) {
  const x = Number(data.x);
  const y = Number(data.y);
  if (!Number.isFinite(x) || !Number.isFinite(y)) return null;
  const gridX = Math.trunc(x);
  const gridY = Math.trunc(y);
  if (!isGridInWorld(gridX, gridY)) return null;

  return {
    x: gridX,
    y: gridY,
    world: cleanWorld(worldName),
    request_id: makeRequestId(data),
    password: cleanDoorPassword(data.password || ""),
  };
}

function getDoorStateForBlock(state: any, block: any, worldName: any) {
  if (!state || !block) return null;
  const key = gridKey(block.x, block.y);
  const interaction = state.interactions.get(key) || {};
  const destination = cleanDoorDestination(interaction.destination || interaction.door_destination || block.door_destination || block.destination || "");
  const parsedDestination = parseDoorDestination(destination, worldName);

  return {
    block,
    interaction,
    door_id: cleanDoorId(interaction.door_id || block.door_id || ""),
    door_name: cleanDoorName(interaction.door_name || block.door_name || block.name || ""),
    destination,
    target_world: cleanWorld(interaction.target_world || block.door_target_world || parsedDestination.target_world || worldName),
    target_door_id: cleanDoorId(interaction.target_door_id || block.door_target_id || parsedDestination.target_door_id || ""),
    locked: Boolean(interaction.locked || block.entrance_locked),
    password: cleanDoorPassword(interaction.password || interaction.door_password || block.door_password || ""),
  };
}

function getDoorAtGrid(worldName: any, x: any, y: any) {
  const state = ensureWorldState(worldName);
  const block = state.foreground.get(gridKey(x, y));
  if (!block || !isDoorBlockType(block.block_type)) return null;
  return {
    state,
    ...getDoorStateForBlock(state, block, worldName),
  };
}

function findDoorById(worldName: any, doorId: any) {
  const cleanId = cleanDoorId(doorId);
  if (cleanId === "") return null;

  const state = ensureWorldState(worldName);
  for (const block of state.foreground.values()) {
    if (!isDoorBlockType(block?.block_type || "")) continue;
    const doorState = getDoorStateForBlock(state, block, worldName);
    if (!doorState || doorState.door_id !== cleanId) continue;
    return {
      state,
      ...doorState,
    };
  }

  return null;
}

function rejectDoorEnter(socket: any, message: any, extra: any = {}) {
  sendActionRejected(socket, "door_enter", message, extra);
  return false;
}

async function handleDoorEnterRequest(socket: any, player: any, data: any) {
  if (!requireAuthenticated(socket, player, "enter doors")) return false;

  const sourceWorld = getPlayerCurrentWorldName(player);
  const requestWorld = cleanWorld(data.world || sourceWorld);
  if (!requireSameWorld(socket, player, requestWorld, "enter that door")) return false;
  if (await rejectIfWorldBanned(socket, player, sourceWorld, "door_enter")) return false;

  const request = sanitizeDoorEnterRequest(data, sourceWorld);
  if (!request) return rejectDoorEnter(socket, "Door missing.");

  const sourceDoor = getDoorAtGrid(sourceWorld, request.x, request.y);
  if (!sourceDoor) return rejectDoorEnter(socket, "Door missing.");

  if (!isPlayerNearGrid(player, request.x, request.y)) {
    return rejectDoorEnter(socket, "Too far away.");
  }

  if (sourceDoor.locked && !canPlayerPassDoor(player, sourceWorld)) {
    return rejectDoorEnter(socket, "Door is locked.");
  }

  if (isPasswordDoorBlockType(sourceDoor.block.block_type)) {
    const configuredPassword = cleanDoorPassword(sourceDoor.password || "");
    if (configuredPassword !== "" && cleanDoorPassword(request.password || "") !== configuredPassword) {
      return rejectDoorEnter(socket, "Password incorrect.", {
        reason: "wrong_password",
        x: request.x,
        y: request.y,
        world: sourceWorld,
      });
    }
  }

  if (sourceDoor.destination === "") {
    return rejectDoorEnter(socket, "Door is not linked.");
  }

  const targetWorld = cleanWorld(sourceDoor.target_world || sourceWorld);
  const targetDoorId = cleanDoorId(sourceDoor.target_door_id || "");
  const worldOnlyDestination = targetDoorId === "";
  if (await rejectIfWorldBanned(socket, player, targetWorld, "door_enter")) return false;

  const oldWorld = sourceWorld;
  const changedWorld = oldWorld !== targetWorld;
  // Hoisted out of the `if (changedWorld)` block below so the drops-refetch skip further
  // down (see the refreshWorldDropsFromPostgres call near the end of this function) can
  // read worldRefresh.source without a second, separate refresh call.
  let worldRefresh: any = null;
  if (changedWorld) {
    const routeCheck = await ensureWorldRouteForAction(socket, player, targetWorld, "door_enter");
    if (!routeCheck.ok) return false;

    worldRefresh = await refreshWorldStateFromPostgres(targetWorld, "door_enter");
    if (!worldRefresh.ok) {
      rejectDoorEnter(socket, "World data is still loading. Try again.", {
        reason: worldRefresh.reason || "world_state_refresh_failed",
        target_world: targetWorld,
      });
      releaseOwnedWorldRouteIfEmpty(targetWorld).catch((error) => {
        console.warn("[redis] world route door refresh cleanup failed:", error.message);
      });
      return false;
    }
  }

  let targetDoor: any = null;
  if (!worldOnlyDestination) {
    targetDoor = findDoorById(targetWorld, targetDoorId);
    if (!targetDoor) {
      if (changedWorld) {
        releaseOwnedWorldRouteIfEmpty(targetWorld).catch((error) => {
          console.warn("[redis] world route target door cleanup failed:", error.message);
        });
      }
      return rejectDoorEnter(socket, "Target door not found.", {
        target_world: targetWorld,
        target_door_id: targetDoorId,
      });
    }

    if (targetDoor.locked && !canPlayerPassDoor(player, targetWorld)) {
      if (changedWorld) {
        releaseOwnedWorldRouteIfEmpty(targetWorld).catch((error) => {
          console.warn("[redis] world route locked door cleanup failed:", error.message);
        });
      }
      return rejectDoorEnter(socket, "Target door is locked.", {
        target_world: targetWorld,
        target_door_id: targetDoorId,
      });
    }
  }

  const useEntranceSpawn = changedWorld || worldOnlyDestination;
  const targetDoorPosition = targetDoor ? getGridCenterPixels(targetDoor.block.x, targetDoor.block.y) : null;
  const targetPosition = useEntranceSpawn
    ? getJoinWorldSpawnForWorld(targetWorld)
    : {
        ...targetDoorPosition,
        grid_x: targetDoor.block.x,
        grid_y: targetDoor.block.y,
      };
  const spawnAtEntranceGate = useEntranceSpawn;
  const admission: any = changedWorld ? await reserveWorldAdmission(player, targetWorld, "door_enter") : null;
  if (changedWorld && !admission.ok) {
    if (admission.reason === "world_route_admission_mismatch") {
      return rejectWorldRouteAdmissionMismatch(socket, player, "door_enter", targetWorld, admission);
    }
    return rejectWorldCapacity(socket, "door_enter", targetWorld, player.id, { current_players: admission.current_players });
  }

  let admissionCommitted: any = false;
  try {
    if (changedWorld) {
      cancelActiveTradeForPlayer(player.id, "Trade canceled because a player changed worlds.");
      activeFishingSessions.delete(player.id);
      clearPlayerFishingPresence(player);
      const keyCleanup = await removeWorldLockKeysFromPlayerInventory(socket, player, oldWorld, "door_world_change");
      if (!keyCleanup.ok) {
        rejectDoorEnter(socket, keyCleanup.message || "Could not remove your World Lock Key. Try again.", {
          reason: keyCleanup.reason || "world_lock_key_cleanup_failed",
          world: oldWorld,
        });
        return false;
      }

      if (player.joined_world) {
        await endWorldHonorVisit(player, oldWorld, "door_world_change");
        broadcastSystemToWorld(oldWorld, `${player.name} left ${oldWorld}`, player.id);
        broadcastToWorld(oldWorld, buildPublicPlayerPresencePayload("player_left", player, oldWorld), player.id);
        clearPlayerInterestState(player.id);
      }
    }

    player.world = targetWorld;
    player.current_world = targetWorld;
    player.current_world_id = targetWorld;
    player.joined_world = true;
    updatePlayerWorldIndex(player);
    if (changedWorld) {
      await commitWorldAdmissionReservation(admission, player, oldWorld);
      admissionCommitted = true;
    }
    player.x = targetPosition.x;
    player.y = targetPosition.y;
    player.velocity_x = 0;
    player.velocity_y = 0;
    player.animation_state = "idle";
    resetPlayerMovementTracking(player);
    if (changedWorld) {
      setPlayerWorldEntrySpawnGuard(player, targetWorld, targetPosition);
    }
    clearNetfoxTrustedPlayerState(player);
    clearTrustedMovementBaseline(player);
    ensureWorldState(targetWorld);
    postgresStore.mirrorPlayerWorld(player.account_username, targetWorld);

    const response: any = {
      type: "door_enter_ok",
      request_id: request.request_id,
      world: targetWorld,
      source_world: oldWorld,
      source_x: request.x,
      source_y: request.y,
      target_door_id: targetDoor ? targetDoor.door_id : "",
      x: targetPosition.x,
      y: targetPosition.y,
      spawn_x: targetPosition.x,
      spawn_y: targetPosition.y,
      spawn_grid_x: targetPosition.grid_x,
      spawn_grid_y: targetPosition.grid_y,
      spawn_at_entrance_gate: spawnAtEntranceGate,
      same_world: !changedWorld,
      requires_world_state: changedWorld,
      message: changedWorld ? `Entering ${targetWorld}...` : "Entered door.",
    };
    sendJson(socket, response);

    if (changedWorld) {
      const existingPlayers = getPlayersInWorld(targetWorld, player.id, player);
      const joinWorldPayload: any = {
        type: "join_world_ok",
        world: targetWorld,
        players: existingPlayers,
        username: player.account_username,
        player_data: buildPlayerStateForClient(ensurePlayerState(player.account_username) || {}),
        spawn_x: targetPosition.x,
        spawn_y: targetPosition.y,
        spawn_grid_x: targetPosition.grid_x,
        spawn_grid_y: targetPosition.grid_y,
        spawn_at_entrance_gate: true,
        network_movement_guidance: buildClientMovementGuidance(targetWorld),
      };
      if (isNetfoxRealMode(player, request)) {
        joinWorldPayload.netfox_route = await buildNetfoxSpawnTicketPayload(player, targetWorld, {
          websocket_player_id: player.id,
        });
      }
      sendJson(socket, joinWorldPayload);
      sendWorldPopulationUpdate(socket, targetWorld);

      // Skip when refreshWorldStateFromPostgres (above) already did a real cold Postgres
      // load for this exact request (source === "database") -- loadWorldState's own
      // internal query just loaded state.drops for this world moments ago, and nothing
      // between there and here touches world_drops, so re-fetching is a guaranteed
      // duplicate round trip on every cold world-changing join. Left in place for the
      // memory/memory_warm sources, where this instance's in-memory drops could in theory
      // need a defensive re-sync; only the provably-redundant case is removed. See
      // world-join latency investigation, item #7 (duplicate work).
      if (worldRefresh.source !== "database") {
        await refreshWorldDropsFromPostgres(targetWorld, "door_enter");
      }
      sendWorldStateToSocket(socket, player, targetWorld, {
        receiver_player: player,
        respawn_player: true,
        force_player_position: true,
        spawn_at_entrance_gate: true,
        spawn_x: targetPosition.x,
        spawn_y: targetPosition.y,
        spawn_grid_x: targetPosition.grid_x,
        spawn_grid_y: targetPosition.grid_y,
        portal_spawn_x: targetPosition.x,
        portal_spawn_y: targetPosition.y,
        x: targetPosition.x,
        y: targetPosition.y,
        world_state_reason: "door_enter",
        message: `Entered ${targetWorld}.`,
      });
      seedDropInterestForReceiverFromWorldState(player, targetWorld);
      syncDropInterestForReceiver(socket, player, targetWorld, true);
      sendActiveWorldEventState(socket, targetWorld);
      await beginWorldHonorVisit(socket, player, targetWorld);

      publishPlayerPresenceUpdate(socket, player, targetWorld, "player_joined", player.id);
      broadcastSystemToWorld(targetWorld, `${player.name} joined ${targetWorld}`, player.id);
      broadcastWorldPopulationUpdate(oldWorld);
      broadcastWorldPopulationUpdate(targetWorld);
      releaseOwnedWorldRouteIfEmpty(oldWorld).catch((error) => {
        console.warn("[redis] world route door cleanup failed:", error.message);
      });
      notifyOnlineFriendsOfFriendState(player.account_username);
    } else {
      publishPlayerPresenceUpdate(socket, player, targetWorld, "player_position", player.id);
    }

    touchLivePresence(socket, player, { force: true });
    logWorldChange(socket, player, {
      source_type: "door_enter",
      source_id: request.request_id || makeAuditId("door"),
      world: oldWorld,
      action: "door_enter",
      layer: "interaction",
      x: request.x,
      y: request.y,
      block_type: sourceDoor.block.block_type,
      details: {
        source_door_id: sourceDoor.door_id,
        destination: sourceDoor.destination,
        target_world: targetWorld,
        target_door_id: targetDoor ? targetDoor.door_id : "",
        target_x: targetDoor ? targetDoor.block.x : targetPosition.grid_x,
        target_y: targetDoor ? targetDoor.block.y : targetPosition.grid_y,
      },
    });
    return true;
  } finally {
    if (!admissionCommitted) {
      await releaseWorldAdmissionReservation(admission);
    }
  }
}

function buildDoorDestinationText(targetWorld: any, targetDoorId: any, sourceWorld: any) {
  const cleanTargetWorld = cleanWorld(targetWorld || sourceWorld);
  const cleanSourceWorld = cleanWorld(sourceWorld || "");
  const cleanTargetDoorId = cleanDoorId(targetDoorId);
  if (cleanTargetDoorId === "") return "";
  if (cleanTargetWorld === cleanSourceWorld) {
    return `door:${cleanTargetDoorId}`;
  }
  return `${cleanTargetWorld}:door:${cleanTargetDoorId}`;
}

async function maybeApplyReciprocalDoorLink(socket: any, player: any, sourceWorld: any, update: any) {
  if (!update || update.action !== "door_state") return null;

  const sourceDoorId = cleanDoorId(update.door_id || "");
  const targetDoorId = cleanDoorId(update.target_door_id || "");
  if (sourceDoorId === "" || targetDoorId === "") return null;

  const cleanSourceWorld = cleanWorld(sourceWorld);
  const targetWorld = cleanWorld(update.target_world || cleanSourceWorld);
  if (cleanSourceWorld === "" || targetWorld === "") return null;
  if (!canPlayerBuildInWorld(player, targetWorld)) return null;

  const targetDoor = findDoorById(targetWorld, targetDoorId);
  if (!targetDoor || !targetDoor.block) return null;
  if (targetWorld === cleanSourceWorld && Number(targetDoor.block.x) === Number(update.x) && Number(targetDoor.block.y) === Number(update.y)) {
    return null;
  }

  const targetState = getDoorStateForBlock(targetDoor.state, targetDoor.block, targetWorld);
  if (!targetState) return null;
  const existingDestination = cleanDoorDestination(targetState.destination || "");
  const existingTargetDoorId = cleanDoorId(targetState.target_door_id || "");
  if (existingDestination !== "" || existingTargetDoorId !== "") return null;

  const reverseDestination = buildDoorDestinationText(cleanSourceWorld, sourceDoorId, targetWorld);
  const reverseUpdate: any = {
    type: "world_interaction_update",
    world: targetWorld,
    action: "door_state",
    x: targetDoor.block.x,
    y: targetDoor.block.y,
    door_id: cleanDoorId(targetState.door_id || targetDoor.door_id || targetDoorId),
    destination: cleanDoorDestination(reverseDestination),
    target_world: cleanSourceWorld,
    target_door_id: sourceDoorId,
    locked: isDoorBlockType(targetDoor.block.block_type) && Boolean(targetState.locked),
    block_type: targetDoor.block.block_type,
  };

  const reciprocalSourceId = makeAuditId("interact");
  const previousTargetWorldState = serializeWorldState(targetWorld);
  const objectBefore = getWorldObjectJournalData(targetWorld, reverseUpdate);
  applyInteractionUpdateToWorldState(targetWorld, reverseUpdate);
  const objectAfter = getWorldObjectJournalData(targetWorld, reverseUpdate);
  const commit = await commitWorldStateWithBlockChanges(targetWorld, [
    buildWorldObjectChangeEntry(
      socket,
      player,
      targetWorld,
      {
        ...reverseUpdate,
        source_type: "door_reciprocal_link",
      },
      objectBefore,
      objectAfter,
      reciprocalSourceId,
      {
        source_world: cleanSourceWorld,
        source_door_id: sourceDoorId,
        target_door_id: targetDoorId,
      }
    ),
  ]);

  if (!commit.ok) {
    worldStates.set(cleanWorld(targetWorld), deserializeWorldState(targetWorld, previousTargetWorldState));
    console.warn("[world-journal] reciprocal door link save failed:", commit.message || commit.reason || "unknown");
    return null;
  }
  sendWorldUpdateToRequesterAndWorld(socket, player, targetWorld, reverseUpdate);
  return reverseUpdate;
}

function prepareToggleBlockStateUpdate(socket: any, player: any, worldName: any, update: any, expectedAction: any) {
  const state = ensureWorldState(worldName);
  const block = state.foreground.get(gridKey(update.x, update.y));
  if (!block || !isToggleBlockType(block.block_type)) {
    sendActionRejected(socket, "world_interaction_update", "Toggle block missing.");
    return false;
  }

  const definition = ItemDatabase.getItemDefinition(block.block_type) || {};
  const toggleAction = clampString(definition.toggle_action || `${block.block_type}_state`);
  if (toggleAction !== expectedAction) {
    sendActionRejected(socket, "world_interaction_update", "Toggle block missing.");
    return false;
  }

  if (!isPlayerNearGrid(player, update.x, update.y)) {
    sendActionRejected(socket, "world_interaction_update", "Too far away.");
    return false;
  }

  update.on = Boolean(update.on);
  update.block_type = block.block_type;
  return true;
}

function prepareThemeMachineStateUpdate(socket: any, player: any, worldName: any, update: any) {
  const state = ensureWorldState(worldName);
  const block = state.foreground.get(gridKey(update.x, update.y));
  if (!block || !isThemeMachineBlockType(block.block_type)) {
    sendActionRejected(socket, "world_interaction_update", "Theme Machine missing.");
    return false;
  }

  if (!isPlayerNearGrid(player, update.x, update.y)) {
    sendActionRejected(socket, "world_interaction_update", "Too far away.");
    return false;
  }

  if (!canPlayerUseThemeMachineAtGrid(player, worldName, update.x, update.y)) {
    sendActionRejected(socket, "world_interaction_update", "Only world or area-lock builders can use this Theme Machine.");
    return false;
  }

  const definition = ItemDatabase.getItemDefinition(block.block_type) || {};
  const configuredTheme = sanitizeWorldBackgroundTheme(definition.theme_machine_theme || "");
  update.enabled = Boolean(update.enabled);
  update.theme = configuredTheme || sanitizeWorldBackgroundTheme(update.theme || "night") || "night";
  update.block_type = block.block_type;
  return true;
}

