function applyActionPositionFromPayload(socket: any, player: any, data: any, fallbackWorld: any = "") {
  if (!player || !player.authenticated) return false;
  if (usesTrustedMovementPosition(player)) {
    return applyTrustedActionPositionFromPayload(socket, player, data, fallbackWorld);
  }
  if (!enforceStandardMovementForSocket(socket, player, "action_position")) return false;

  const position = sanitizeActionPositionPayload(data, player, fallbackWorld);
  if (!position) return false;
  if (!acceptPlayerMovement(socket, player, position, { silent: true })) return false;

  player.x = position.x;
  player.y = position.y;
  player.facing = position.facing;
  player.in_water = position.in_water === true;
  player.in_lava_fire = position.in_lava_fire === true;
  return true;
}

