async function handleOilRefineryRequest(socket: any, player: any, data: any = {}) {
  if (!requireAuthenticated(socket, player, "use oil refineries")) return;

  const worldName = cleanWorld(data.world || player.world || "START");
  if (!requireSameWorld(socket, player, worldName, "use that oil refinery")) return;
  if (await rejectIfWorldBanned(socket, player, worldName, "oil_refinery_request")) return;

  const x = Number(data.x);
  const y = Number(data.y);
  if (!Number.isFinite(x) || !Number.isFinite(y)) return;
  const gridX = Math.trunc(x);
  const gridY = Math.trunc(y);
  if (!isGridInWorld(gridX, gridY)) return;

	let operation: any = clampString(
		data.operation
		|| data.request_operation
		|| data.command
		|| data.oil_refinery_operation
		|| data.action
		|| ""
	).toLowerCase();
	if (operation === "battery_add" || operation === "addbattery" || operation === "battery") {
		operation = "add_battery";
	}
	if (!["open", "toggle", "link_pole", "collect", "add_battery"].includes(operation)) {
		sendActionRejected(socket, "oil_refinery_request", "Unknown oil refinery action.", {
			reason: "unknown_operation",
			operation,
		});
		return;
	}

  if (!isPlayerNearGrid(player, gridX, gridY, MAX_GRID_ACTION_DISTANCE_PIXELS, { action: "oil_refinery_request", world: worldName })) {
    sendActionRejected(socket, "oil_refinery_request", "Too far away.", {
      reason: "too_far",
      target_x: gridX,
      target_y: gridY,
    });
    return;
  }

  const state = ensureWorldState(worldName);
  const block = getOilRefineryBlockAt(state, gridX, gridY);
  if (!block) {
    sendActionRejected(socket, "oil_refinery_request", "Oil refinery missing.", {
      reason: "oil_refinery_missing",
    });
    return;
  }

  if (!canPlayerBuildAtGrid(player, worldName, gridX, gridY)) {
    sendActionRejected(socket, "oil_refinery_request", "This oil refinery is locked.", {
      reason: "area_lock_permission_denied",
    });
    return;
  }

  const previousWorldState = serializeWorldState(worldName);
  const existingState = getOilRefineryStateAt(state, worldName, gridX, gridY, operation !== "open");
  const oilState = existingState || sanitizeOilRefineryState({ x: gridX, y: gridY, world: worldName }, worldName, gridX, gridY);

  if (operation === "open") {
    sendJson(socket, makeOilRefineryStatePayload(worldName, oilState, { opened: true }));
    return;
  }

  const beforeState = cloneJson(oilState || {});
  const requestId = makeRequestId(data);
  const crudeOilItemId = "crude_oil";
  const crudeOilCategory = "material";
  const batteryItemId = OIL_REFINERY_BATTERY_ITEM_ID;
  const batteryCategory = OIL_REFINERY_BATTERY_ITEM_CATEGORY;
  let collectedCount: any = 0;
  let addedBatteryCount: any = 0;
  let beforePlayerState: any = null;
  let stagedPlayerState: any = null;
  if (operation === "link_pole") {
    if (!canPlayerViewElectricalLayer(player, worldName)) {
      sendActionRejected(socket, "oil_refinery_request", "Only players with world access can link oil refineries.", {
        reason: "electrical_access_denied",
      });
      return;
    }
    if (!playerHasElectricToolEquipped(player)) {
      sendActionRejected(socket, "oil_refinery_request", "Equip the Electric Tool to link oil refineries.", {
        reason: "electric_tool_required",
      });
      return;
    }

    const poleX = Number(data.pole_x);
    const poleY = Number(data.pole_y);
    if (!Number.isFinite(poleX) || !Number.isFinite(poleY)) return;
    const gridPoleX = Math.trunc(poleX);
    const gridPoleY = Math.trunc(poleY);
    if (!isGridInWorld(gridPoleX, gridPoleY)) return;

    if (!isPlayerNearGrid(player, gridPoleX, gridPoleY, MAX_GRID_ACTION_DISTANCE_PIXELS, { action: "oil_refinery_request", world: worldName })) {
      sendActionRejected(socket, "oil_refinery_request", "Too far away.", {
        reason: "too_far",
        target_x: gridPoleX,
        target_y: gridPoleY,
      });
      return;
    }
    if (!canPlayerBuildAtGrid(player, worldName, gridPoleX, gridPoleY)) {
      sendActionRejected(socket, "oil_refinery_request", "This electric pole is locked.", {
        reason: "area_lock_permission_denied",
      });
      return;
    }

    const poleEntry = getElectricPoleDeviceStateAt(state, gridPoleX, gridPoleY);
    if (!poleEntry || poleEntry.device_type !== ELECTRICAL_DEVICE_POLE) {
      sendActionRejected(socket, "oil_refinery_request", "Tap an electric pole to link.", {
        reason: "electric_pole_missing",
      });
      return;
    }

    const poleKey = gridKey(gridPoleX, gridPoleY);
    oilState.linked_pole_key = poleKey;
    oilState.direct_power = false;
    oilState.running = false;
    oilState.battery_powered = false;
    oilState.shutdown_reason = "";
    oilState.last_tick_ms = Date.now();
  } else if (operation === "toggle") {
    const enabled = Boolean(data.enabled);
    if (enabled && oilState.output_count >= OIL_REFINERY_OUTPUT_CAPACITY) {
      sendActionRejected(socket, "oil_refinery_request", "Collect crude oil before turning the refinery on.", {
        reason: "output_full",
      });
      return;
    }
    oilState.enabled = enabled;
    oilState.auto_shutdown = false;
    oilState.shutdown_reason = "";
    oilState.last_tick_ms = Date.now();
    if (!enabled) {
      oilState.running = false;
      oilState.direct_power = false;
      oilState.battery_powered = false;
      oilState.pending_consumption_watts = 0;
    } else {
      const source = resolveOilRefineryPowerSource(worldName, state, oilState);
      const generatorSources = Array.isArray(source.generator_sources) ? source.generator_sources : [];
      const availableWatts = getTotalGeneratorSourceWatts(generatorSources);
      const availableBatteryWatts = clampInteger(oilState.battery_watts || 0, 0, OIL_REFINERY_BATTERY_WATT_CAPACITY);
      const hasPower = availableWatts > 0 || availableBatteryWatts > 0;
      oilState.running = hasPower;
      oilState.direct_power = hasPower;
      oilState.battery_powered = availableWatts <= 0 && availableBatteryWatts > 0;
      oilState.shutdown_reason = hasPower ? "" : (source.pole_entry ? "no_transformer_or_battery_power" : "no_power_source");
    }
  } else if (operation === "add_battery") {
    const batteryWatts = clampInteger(oilState.battery_watts || 0, 0, OIL_REFINERY_BATTERY_WATT_CAPACITY);
    const batteryCount = getOilRefineryBatteryCountFromWatts(batteryWatts);
    const availableSlots = Math.max(0, OIL_REFINERY_BATTERY_INPUT_CAPACITY - batteryCount);
    if (availableSlots <= 0) {
      sendActionRejected(socket, "oil_refinery_request", "Oil refinery battery input is full.", {
        reason: "battery_input_full",
        battery_capacity: OIL_REFINERY_BATTERY_INPUT_CAPACITY,
      });
      return;
    }

    const playerState = ensureWritablePlayerState(player.account_username);
    if (!playerState) {
      sendActionRejected(socket, "oil_refinery_request", "Could not load your server inventory.", {
        reason: "player_inventory_missing",
      });
      return;
    }
    const ownedBatteries = getInventoryCount(playerState, batteryItemId, batteryCategory);
    if (ownedBatteries <= 0) {
      sendActionRejected(socket, "oil_refinery_request", "You do not have any batteries.", {
        reason: "battery_missing",
        item_id: batteryItemId,
        item_category: batteryCategory,
      });
      return;
    }

    const requestedAmount = clampInteger(data.amount || availableSlots, 1, OIL_REFINERY_BATTERY_INPUT_CAPACITY);
    addedBatteryCount = Math.max(0, Math.min(requestedAmount, ownedBatteries, availableSlots));
    if (addedBatteryCount <= 0) {
      sendActionRejected(socket, "oil_refinery_request", "No batteries could be added.", {
        reason: "battery_add_empty",
      });
      return;
    }

    beforePlayerState = cloneJson(playerState);
    stagedPlayerState = cloneJson(playerState);
    if (!spendItemFromState(stagedPlayerState, batteryItemId, batteryCategory, addedBatteryCount)) {
      sendActionRejected(socket, "oil_refinery_request", "Could not spend batteries.", {
        reason: "inventory_spend_failed",
        item_id: batteryItemId,
        item_category: batteryCategory,
        amount: addedBatteryCount,
      });
      return;
    }

    oilState.battery_watts = clampInteger(
      batteryWatts + (addedBatteryCount * OIL_REFINERY_BATTERY_WATTS),
      0,
      OIL_REFINERY_BATTERY_WATT_CAPACITY
    );
    oilState.input_battery_watts = oilState.battery_watts;
    oilState.battery_count = getOilRefineryBatteryCountFromWatts(oilState.battery_watts);
    oilState.input_battery_count = oilState.battery_count;
    oilState.shutdown_reason = "";
    oilState.auto_shutdown = false;
    oilState.last_tick_ms = Date.now();
    if (oilState.enabled && oilState.output_count < OIL_REFINERY_OUTPUT_CAPACITY) {
      const source = resolveOilRefineryPowerSource(worldName, state, oilState);
      const generatorSources = Array.isArray(source.generator_sources) ? source.generator_sources : [];
      const availableWatts = getTotalGeneratorSourceWatts(generatorSources);
      const hasPower = availableWatts > 0 || oilState.battery_watts > 0;
      oilState.running = hasPower;
      oilState.direct_power = hasPower;
      oilState.battery_powered = availableWatts <= 0 && oilState.battery_watts > 0;
      oilState.shutdown_reason = hasPower ? "" : (source.pole_entry ? "no_transformer_or_battery_power" : "no_power_source");
    }
  } else if (operation === "collect") {
	if (oilState.output_count <= 0) {
		sendActionRejected(socket, "oil_refinery_request", "Oil refinery output is empty.", {
			reason: "output_empty",
      });
      return;
    }
    collectedCount = clampInteger(oilState.output_count || oilState.produced_count || 0, 0, OIL_REFINERY_OUTPUT_CAPACITY);
    const playerState = ensureWritablePlayerState(player.account_username);
    if (!playerState) {
      sendActionRejected(socket, "oil_refinery_request", "Could not load your server inventory.", {
        reason: "player_inventory_missing",
      });
      return;
    }
    if (!canAddItemToState(playerState, crudeOilItemId, crudeOilCategory, collectedCount)) {
      sendActionRejected(socket, "oil_refinery_request", "Make room for crude oil before collecting.", {
        reason: "inventory_full",
        item_id: crudeOilItemId,
        item_category: crudeOilCategory,
        amount: collectedCount,
      });
      return;
    }

    beforePlayerState = cloneJson(playerState);
    stagedPlayerState = cloneJson(playerState);
    if (!addItemToState(stagedPlayerState, crudeOilItemId, crudeOilCategory, collectedCount)) {
      sendActionRejected(socket, "oil_refinery_request", "Could not add crude oil to your inventory.", {
        reason: "inventory_add_failed",
      });
      return;
    }

    oilState.produced_count = 0;
    oilState.output_count = 0;
    oilState.auto_shutdown = false;
    oilState.shutdown_reason = "";
    oilState.last_tick_ms = Date.now();
  }

  const savedState = setOilRefineryState(state, worldName, oilState);
  const afterState = cloneJson(savedState || {});
  const payload = makeOilRefineryStatePayload(worldName, savedState, {
    operation,
    opened: operation === "open",
    collected_count: operation === "collect" ? collectedCount : 0,
    added_battery_count: operation === "add_battery" ? addedBatteryCount : 0,
  });
  const transactionId = makeAuditId("oil_refinery");
  const changeEntry = buildWorldObjectChangeEntry(
    socket,
    player,
    worldName,
    {
      action: "oil_refinery_state",
      source_type: "oil_refinery_request",
      x: gridX,
      y: gridY,
      block_type: clampString(block.block_type || OIL_REFINERY_BLOCK_TYPE),
    },
    beforeState,
    afterState,
    transactionId,
    {
      operation,
      linked_pole_key: savedState.linked_pole_key || "",
      output_count: savedState.output_count,
      output_capacity: OIL_REFINERY_OUTPUT_CAPACITY,
      battery_watts: savedState.battery_watts,
      battery_count: savedState.battery_count,
    }
  );

  if (operation === "collect") {
    const serializedWorld = serializeWorldState(worldName);
    const commit = await commitPlayerInventoryState(socket, player, player.account_username, beforePlayerState, stagedPlayerState, {
      source: "oil_refinery",
      action: "oil_refinery_collect",
      reason: "oil_refinery_output",
      request_id: requestId,
      world: worldName,
      metadata: {
        transaction_id: transactionId,
        x: gridX,
        y: gridY,
        collected_count: collectedCount,
      },
      world_state: serializedWorld,
      world_changes: [changeEntry],
      failure_message: "Could not collect crude oil.",
    });
    if (!commit.ok) {
      worldStates.set(cleanWorld(worldName), deserializeWorldState(worldName, previousWorldState));
      sendActionRejected(socket, "oil_refinery_request", commit.message || "Could not collect crude oil.", {
        reason: commit.reason || "inventory_commit_failed",
      });
      return;
    }

    const committedState = commit.state;
    const inventoryDeltas = buildInventoryDeltaClientPayloads(commit.deltas, committedState);
    persistWorldStateAfterInventoryCommit(worldName, commit.postgres_committed, serializedWorld);
    sendWorldUpdateToRequesterAndWorld(socket, player, worldName, payload);
    logWorldChange(socket, player, changeEntry, { skipPostgres: commit.postgres_committed });
    logItemLedgerForState(socket, player, player.account_username, committedState, crudeOilItemId, crudeOilCategory, collectedCount, "oil_refinery_collect", transactionId, "oil_refinery_output", worldName, {
      x: gridX,
      y: gridY,
      collected_count: collectedCount,
    }, { skipPostgres: commit.postgres_committed });
    sendInventoryTransactionResult(socket, {
      ok: true,
      request_id: requestId,
      action: "oil_refinery_collect",
      message: `Collected ${collectedCount} crude oil.`,
      username: player.account_username,
      rewards: [{ item_id: crudeOilItemId, item_category: crudeOilCategory, amount: collectedCount }],
      inventory_deltas: inventoryDeltas,
    });
    return;
  }

  if (operation === "add_battery") {
    const serializedWorld = serializeWorldState(worldName);
    const commit = await commitPlayerInventoryState(socket, player, player.account_username, beforePlayerState, stagedPlayerState, {
      source: "oil_refinery",
      action: "oil_refinery_add_battery",
      reason: "oil_refinery_battery_input",
      request_id: requestId,
      world: worldName,
      metadata: {
        transaction_id: transactionId,
        x: gridX,
        y: gridY,
        added_battery_count: addedBatteryCount,
        added_battery_watts: addedBatteryCount * OIL_REFINERY_BATTERY_WATTS,
      },
      world_state: serializedWorld,
      world_changes: [changeEntry],
      failure_message: "Could not add batteries to the oil refinery.",
    });
    if (!commit.ok) {
      worldStates.set(cleanWorld(worldName), deserializeWorldState(worldName, previousWorldState));
      sendActionRejected(socket, "oil_refinery_request", commit.message || "Could not add batteries to the oil refinery.", {
        reason: commit.reason || "inventory_commit_failed",
      });
      return;
    }

    const committedState = commit.state;
    const inventoryDeltas = buildInventoryDeltaClientPayloads(commit.deltas, committedState);
    persistWorldStateAfterInventoryCommit(worldName, commit.postgres_committed, serializedWorld);
    sendWorldUpdateToRequesterAndWorld(socket, player, worldName, payload);
    logWorldChange(socket, player, changeEntry, { skipPostgres: commit.postgres_committed });
    logItemLedgerForState(socket, player, player.account_username, committedState, batteryItemId, batteryCategory, -addedBatteryCount, "oil_refinery_add_battery", transactionId, "oil_refinery_battery_input", worldName, {
      x: gridX,
      y: gridY,
      added_battery_count: addedBatteryCount,
      added_battery_watts: addedBatteryCount * OIL_REFINERY_BATTERY_WATTS,
    }, { skipPostgres: commit.postgres_committed });
    sendInventoryTransactionResult(socket, {
      ok: true,
      request_id: requestId,
      action: "oil_refinery_add_battery",
      message: `Added ${addedBatteryCount} batteries to the oil refinery.`,
      username: player.account_username,
      rewards: [],
      inventory_deltas: inventoryDeltas,
    });
    return;
  }

  const commit = await commitWorldStateWithBlockChanges(worldName, [changeEntry], {
    player,
  });
  if (!commit.ok) {
    worldStates.set(cleanWorld(worldName), deserializeWorldState(worldName, previousWorldState));
    sendActionRejected(socket, "oil_refinery_request", commit.message || "PostgreSQL rejected the oil refinery update.", {
      reason: commit.reason || "world_commit_failed",
    });
    return;
  }

  sendWorldUpdateToRequesterAndWorld(socket, player, worldName, payload);
  if (operation === "link_pole") {
    refreshElectricalVisibilityForWorld(worldName);
  }
  logWorldChange(socket, player, changeEntry, { skipPostgres: commit.postgres_committed });
}

async function handleBatteryChargerRequest(socket: any, player: any, data: any = {}) {
  if (!requireAuthenticated(socket, player, "use battery chargers")) return;

  const worldName = cleanWorld(data.world || player.world || "START");
  if (!requireSameWorld(socket, player, worldName, "use that battery charger")) return;
  if (await rejectIfWorldBanned(socket, player, worldName, "battery_charger_request")) return;

  const x = Number(data.x);
  const y = Number(data.y);
  if (!Number.isFinite(x) || !Number.isFinite(y)) return;
  const gridX = Math.trunc(x);
  const gridY = Math.trunc(y);
  if (!isGridInWorld(gridX, gridY)) return;

  const operation = clampString(data.operation || "").toLowerCase();
  if (!["open", "toggle", "link_pole", "collect"].includes(operation)) {
    sendActionRejected(socket, "battery_charger_request", "Unknown battery charger action.", {
      reason: "unknown_operation",
    });
    return;
  }

  if (!isPlayerNearGrid(player, gridX, gridY, MAX_GRID_ACTION_DISTANCE_PIXELS, { action: "battery_charger_request", world: worldName })) {
    sendActionRejected(socket, "battery_charger_request", "Too far away.", {
      reason: "too_far",
      target_x: gridX,
      target_y: gridY,
    });
    return;
  }

  const state = ensureWorldState(worldName);
  const block = getBatteryChargerBlockAt(state, gridX, gridY);
  if (!block) {
    sendActionRejected(socket, "battery_charger_request", "Battery charger missing.", {
      reason: "battery_charger_missing",
    });
    return;
  }

  if (!canPlayerBuildAtGrid(player, worldName, gridX, gridY)) {
    sendActionRejected(socket, "battery_charger_request", "This battery charger is locked.", {
      reason: "area_lock_permission_denied",
    });
    return;
  }

  const previousWorldState = serializeWorldState(worldName);
  const existingState = getBatteryChargerStateAt(state, worldName, gridX, gridY, operation !== "open");
  const chargerState = existingState || sanitizeBatteryChargerState({ x: gridX, y: gridY, world: worldName }, worldName, gridX, gridY);

  if (operation === "open") {
    sendJson(socket, makeBatteryChargerStatePayload(worldName, chargerState, { opened: true }));
    return;
  }

  const beforeState = cloneJson(chargerState || {});
  const requestId = makeRequestId(data);
  const batteryItemId = BATTERY_CHARGER_OUTPUT_ITEM_ID;
  const batteryCategory = BATTERY_CHARGER_OUTPUT_CATEGORY;
  let collectedCount: any = 0;
  let beforePlayerState: any = null;
  let stagedPlayerState: any = null;
  if (operation === "link_pole") {
    if (!canPlayerViewElectricalLayer(player, worldName)) {
      sendActionRejected(socket, "battery_charger_request", "Only players with world access can link battery chargers.", {
        reason: "electrical_access_denied",
      });
      return;
    }
    if (!playerHasElectricToolEquipped(player)) {
      sendActionRejected(socket, "battery_charger_request", "Equip the Electric Tool to link battery chargers.", {
        reason: "electric_tool_required",
      });
      return;
    }

    const poleX = Number(data.pole_x);
    const poleY = Number(data.pole_y);
    if (!Number.isFinite(poleX) || !Number.isFinite(poleY)) return;
    const gridPoleX = Math.trunc(poleX);
    const gridPoleY = Math.trunc(poleY);
    if (!isGridInWorld(gridPoleX, gridPoleY)) return;

    if (!isPlayerNearGrid(player, gridPoleX, gridPoleY, MAX_GRID_ACTION_DISTANCE_PIXELS, { action: "battery_charger_request", world: worldName })) {
      sendActionRejected(socket, "battery_charger_request", "Too far away.", {
        reason: "too_far",
        target_x: gridPoleX,
        target_y: gridPoleY,
      });
      return;
    }
    if (!canPlayerBuildAtGrid(player, worldName, gridPoleX, gridPoleY)) {
      sendActionRejected(socket, "battery_charger_request", "This electric pole is locked.", {
        reason: "area_lock_permission_denied",
      });
      return;
    }

    const poleEntry = getElectricPoleDeviceStateAt(state, gridPoleX, gridPoleY);
    if (!poleEntry || poleEntry.device_type !== ELECTRICAL_DEVICE_POLE) {
      sendActionRejected(socket, "battery_charger_request", "Tap an electric pole to link.", {
        reason: "electric_pole_missing",
      });
      return;
    }

    const poleKey = gridKey(gridPoleX, gridPoleY);
    chargerState.linked_pole_key = poleKey;
    chargerState.direct_power = false;
    chargerState.running = false;
    chargerState.shutdown_reason = "";
    chargerState.last_tick_ms = Date.now();
  } else if (operation === "toggle") {
    const enabled = Boolean(data.enabled ?? data.running);
    if (enabled && chargerState.output_count >= BATTERY_CHARGER_OUTPUT_CAPACITY) {
      sendActionRejected(socket, "battery_charger_request", "Collect batteries before turning the charger on.", {
        reason: "output_full",
      });
      return;
    }
    chargerState.enabled = enabled;
    chargerState.auto_shutdown = false;
    chargerState.shutdown_reason = "";
    chargerState.last_tick_ms = Date.now();
    if (!enabled) {
      chargerState.running = false;
      chargerState.direct_power = false;
      chargerState.pending_consumption_watts = 0;
    } else {
      const source = resolveBatteryChargerPowerSource(worldName, state, chargerState);
      const generatorSources = Array.isArray(source.generator_sources) ? source.generator_sources : [];
      const availableWatts = getTotalGeneratorSourceWatts(generatorSources);
      chargerState.running = availableWatts > 0;
      chargerState.direct_power = availableWatts > 0;
      chargerState.shutdown_reason = availableWatts > 0 ? "" : (source.pole_entry ? "no_transformer_power" : "no_linked_power_source");
    }
  } else if (operation === "collect") {
    if (chargerState.output_count <= 0) {
      sendActionRejected(socket, "battery_charger_request", "Battery charger output is empty.", {
        reason: "output_empty",
      });
      return;
    }
    collectedCount = clampInteger(chargerState.output_count || chargerState.produced_count || 0, 0, BATTERY_CHARGER_OUTPUT_CAPACITY);
    const playerState = ensureWritablePlayerState(player.account_username);
    if (!playerState) {
      sendActionRejected(socket, "battery_charger_request", "Could not load your server inventory.", {
        reason: "player_inventory_missing",
      });
      return;
    }
    if (!canAddItemToState(playerState, batteryItemId, batteryCategory, collectedCount)) {
      sendActionRejected(socket, "battery_charger_request", "Make room for batteries before collecting.", {
        reason: "inventory_full",
        item_id: batteryItemId,
        item_category: batteryCategory,
        amount: collectedCount,
      });
      return;
    }

    beforePlayerState = cloneJson(playerState);
    stagedPlayerState = cloneJson(playerState);
    if (!addItemToState(stagedPlayerState, batteryItemId, batteryCategory, collectedCount)) {
      sendActionRejected(socket, "battery_charger_request", "Could not add batteries to your inventory.", {
        reason: "inventory_add_failed",
      });
      return;
    }

    chargerState.produced_count = 0;
    chargerState.output_count = 0;
    chargerState.auto_shutdown = false;
    chargerState.shutdown_reason = "";
    chargerState.last_tick_ms = Date.now();
  }

  const savedState = setBatteryChargerState(state, worldName, chargerState);
  const afterState = cloneJson(savedState || {});
  const payload = makeBatteryChargerStatePayload(worldName, savedState, {
    operation,
    opened: operation === "open",
    collected_count: operation === "collect" ? collectedCount : 0,
  });
  const transactionId = makeAuditId("battery_charger");
  const changeEntry = buildWorldObjectChangeEntry(
    socket,
    player,
    worldName,
    {
      action: "battery_charger_state",
      source_type: "battery_charger_request",
      x: gridX,
      y: gridY,
      block_type: clampString(block.block_type || BATTERY_CHARGER_BLOCK_TYPE),
    },
    beforeState,
    afterState,
    transactionId,
    {
      operation,
      linked_pole_key: savedState.linked_pole_key || "",
      output_count: savedState.output_count,
      output_capacity: BATTERY_CHARGER_OUTPUT_CAPACITY,
    }
  );

  if (operation === "collect") {
    const serializedWorld = serializeWorldState(worldName);
    const commit = await commitPlayerInventoryState(socket, player, player.account_username, beforePlayerState, stagedPlayerState, {
      source: "battery_charger",
      action: "battery_charger_collect",
      reason: "battery_charger_output",
      request_id: requestId,
      world: worldName,
      metadata: {
        transaction_id: transactionId,
        x: gridX,
        y: gridY,
        collected_count: collectedCount,
      },
      world_state: serializedWorld,
      world_changes: [changeEntry],
      failure_message: "Could not collect batteries.",
    });
    if (!commit.ok) {
      worldStates.set(cleanWorld(worldName), deserializeWorldState(worldName, previousWorldState));
      sendActionRejected(socket, "battery_charger_request", commit.message || "Could not collect batteries.", {
        reason: commit.reason || "inventory_commit_failed",
      });
      return;
    }

    const committedState = commit.state;
    const inventoryDeltas = buildInventoryDeltaClientPayloads(commit.deltas, committedState);
    persistWorldStateAfterInventoryCommit(worldName, commit.postgres_committed, serializedWorld);
    sendWorldUpdateToRequesterAndWorld(socket, player, worldName, payload);
    logWorldChange(socket, player, changeEntry, { skipPostgres: commit.postgres_committed });
    logItemLedgerForState(socket, player, player.account_username, committedState, batteryItemId, batteryCategory, collectedCount, "battery_charger_collect", transactionId, "battery_charger_output", worldName, {
      x: gridX,
      y: gridY,
      collected_count: collectedCount,
    }, { skipPostgres: commit.postgres_committed });
    sendInventoryTransactionResult(socket, {
      ok: true,
      request_id: requestId,
      action: "battery_charger_collect",
      message: `Collected ${collectedCount} batteries.`,
      username: player.account_username,
      rewards: [{ item_id: batteryItemId, item_category: batteryCategory, amount: collectedCount }],
      inventory_deltas: inventoryDeltas,
    });
    return;
  }

  const commit = await commitWorldStateWithBlockChanges(worldName, [changeEntry], {
    player,
  });
  if (!commit.ok) {
    worldStates.set(cleanWorld(worldName), deserializeWorldState(worldName, previousWorldState));
    sendActionRejected(socket, "battery_charger_request", commit.message || "PostgreSQL rejected the battery charger update.", {
      reason: commit.reason || "world_commit_failed",
    });
    return;
  }

  sendWorldUpdateToRequesterAndWorld(socket, player, worldName, payload);
  if (operation === "link_pole") {
    refreshElectricalVisibilityForWorld(worldName);
  }
  logWorldChange(socket, player, changeEntry, { skipPostgres: commit.postgres_committed });
}

function getGeneratorDeviceStateAt(state: any, x: any, y: any) {
  if (!state || !(state.foreground instanceof Map)) return null;
  const block = state.foreground.get(gridKey(x, y));
  if (!block || clampString(block.block_type || "").toLowerCase() !== ELECTRICAL_GENERATOR_ITEM) return null;
  return ensureElectricalDeviceStateForBlock(state, block);
}

function getMetalPadDeviceStateAt(state: any, x: any, y: any) {
  if (!state || !(state.background instanceof Map)) return null;
  const block = state.background.get(gridKey(x, y));
  if (!block || clampString(block.block_type || "").toLowerCase() !== ELECTRICAL_METAL_PAD_ITEM) return null;
  return ensureElectricalDeviceStateForBlock(state, block);
}

function getElectricPoleDeviceStateAt(state: any, x: any, y: any) {
  if (!state || !(state.foreground instanceof Map)) return null;
  const block = state.foreground.get(gridKey(x, y));
  if (!block || clampString(block.block_type || "").toLowerCase() !== ELECTRICAL_POLE_ITEM) return null;
  return ensureElectricalDeviceStateForBlock(state, block);
}

function findGeneratorLinkedToPad(state: any, padKey: any) {
  if (!state || !(state.electrical_devices instanceof Map)) return "";
  for (const entry of state.electrical_devices.values()) {
    if (!entry || entry.device_type !== ELECTRICAL_DEVICE_GENERATOR) continue;
    if (getGeneratorLinkedPadKeys(entry).includes(padKey)) {
      return gridKey(entry.x, entry.y);
    }
  }
  return "";
}

function findGeneratorLinkedToPole(state: any, poleKey: any) {
  const generatorKeys = getGeneratorKeysLinkedToPole(state, poleKey);
  return generatorKeys.length > 0 ? generatorKeys[0] : "";
}

function getGeneratorKeysLinkedToPole(state: any, poleKey: any) {
  if (!state || !(state.electrical_devices instanceof Map)) return [];
  const result: any = [];
  const seen: any = new Set();
  for (const entry of state.electrical_devices.values()) {
    if (!entry || entry.device_type !== ELECTRICAL_DEVICE_GENERATOR) continue;
    if (getGeneratorLinkedPoleKeys(entry).includes(poleKey)) {
      const generatorKey = gridKey(entry.x, entry.y);
      if (!seen.has(generatorKey)) {
        seen.add(generatorKey);
        result.push(generatorKey);
      }
    }
  }
  return result;
}

function getGeneratorKeysLinkedToPoleThroughCouplings(state: any, poleKey: any) {
  if (!state || poleKey === "") return [];
  const cache = getFreshElectricalNetworkCache(state);
  const cached = cache.linked_pole_to_generators instanceof Map
    ? cache.linked_pole_to_generators.get(poleKey)
    : null;
  if (cached instanceof Set) return Array.from<any>(cached);
  if (Array.isArray(cached)) return cached.filter((key) => clampString(key || "") !== "");
  return getGeneratorKeysLinkedToPole(state, poleKey);
}

function findGeneratorLinkedToPoleThroughCouplings(state: any, poleKey: any) {
  const generatorKeys = getGeneratorKeysLinkedToPoleThroughCouplings(state, poleKey);
  return generatorKeys.length > 0 ? generatorKeys[0] : "";
}

function getGeneratorSourcesLinkedToPoleThroughCouplings(state: any, poleKey: any) {
  const generatorKeys = getGeneratorKeysLinkedToPoleThroughCouplings(state, poleKey);
  const sources: any = [];
  const seen: any = new Set();
  for (const generatorKey of generatorKeys) {
    if (seen.has(generatorKey)) continue;
    seen.add(generatorKey);
    const generatorGrid = parseGridKey(generatorKey);
    if (!generatorGrid || !isGridInWorld(generatorGrid.x, generatorGrid.y)) continue;
    const generatorEntry = getGeneratorDeviceStateAt(state, generatorGrid.x, generatorGrid.y);
    if (!generatorEntry || generatorEntry.device_type !== ELECTRICAL_DEVICE_GENERATOR) continue;
    const maxWatts = clampInteger(generatorEntry.max_watts || ELECTRICAL_GENERATOR_MAX_WATTS, 1, ELECTRICAL_GENERATOR_MAX_WATTS);
    const watts = clampInteger(generatorEntry.watts || 0, 0, maxWatts);
    sources.push({
      generator_key: generatorKey,
      generator_grid: generatorGrid,
      generator_entry: generatorEntry,
      max_watts: maxWatts,
      watts,
    });
  }
  sources.sort((
    a: { watts: number; generator_key: unknown },
    b: { watts: number; generator_key: unknown },
  ) => (b.watts - a.watts) || String(a.generator_key).localeCompare(String(b.generator_key)));
  return sources;
}

function findBestGeneratorLinkedToPoleThroughCouplings(state: any, poleKey: any) {
  const sources = getGeneratorSourcesLinkedToPoleThroughCouplings(state, poleKey);
  return sources.length > 0 ? sources[0].generator_key : "";
}

function getTotalGeneratorSourceWatts(sources: any) {
  if (!Array.isArray(sources)) return 0;
  return sources.reduce((total, source) => {
    const entry = source?.generator_entry || null;
    if (!entry || entry.device_type !== ELECTRICAL_DEVICE_GENERATOR) return total;
    const maxWatts = clampInteger(entry.max_watts || source.max_watts || ELECTRICAL_GENERATOR_MAX_WATTS, 1, ELECTRICAL_GENERATOR_MAX_WATTS);
    return total + clampInteger(entry.watts || 0, 0, maxWatts);
  }, 0);
}

function getTotalGeneratorSourceMaxWatts(sources: any) {
  if (!Array.isArray(sources)) return 0;
  return sources.reduce((total, source) => {
    const entry = source?.generator_entry || null;
    if (!entry || entry.device_type !== ELECTRICAL_DEVICE_GENERATOR) return total;
    return total + clampInteger(entry.max_watts || source.max_watts || ELECTRICAL_GENERATOR_MAX_WATTS, 1, ELECTRICAL_GENERATOR_MAX_WATTS);
  }, 0);
}

function getAvailableGeneratorSources(sources: any) {
  if (!Array.isArray(sources)) return [];
  return sources.filter((source) => {
    const entry = source?.generator_entry || null;
    if (!entry || entry.device_type !== ELECTRICAL_DEVICE_GENERATOR) return false;
    const maxWatts = clampInteger(entry.max_watts || source.max_watts || ELECTRICAL_GENERATOR_MAX_WATTS, 1, ELECTRICAL_GENERATOR_MAX_WATTS);
    return clampInteger(entry.watts || 0, 0, maxWatts) > 0;
  });
}

function generatorSourcesIncludeKey(sources: any, generatorKey: any) {
  if (!Array.isArray(sources) || generatorKey === "") return false;
  return sources.some((source) => clampString(source?.generator_key || "") === generatorKey);
}

function consumeSharedGeneratorWatts(sources: any, requestedWatts: any, changedGenerators: any = null) {
  if (!Array.isArray(sources)) return 0;
  let remaining: any = Math.max(0, Math.trunc(Number(requestedWatts) || 0));
  let consumed: any = 0;

  while (remaining > 0) {
    const availableSources = sources
      .map((source) => {
        const entry = source?.generator_entry || null;
        if (!entry || entry.device_type !== ELECTRICAL_DEVICE_GENERATOR) return null;
        const maxWatts = clampInteger(entry.max_watts || source.max_watts || ELECTRICAL_GENERATOR_MAX_WATTS, 1, ELECTRICAL_GENERATOR_MAX_WATTS);
        const watts = clampInteger(entry.watts || 0, 0, maxWatts);
        if (watts <= 0) return null;
        return {
          ...source,
          generator_entry: entry,
          max_watts: maxWatts,
          watts,
        };
      })
      .filter(Boolean)
      .sort((a, b) => (b.watts - a.watts) || String(a.generator_key).localeCompare(String(b.generator_key)));

    if (availableSources.length === 0) break;

    const baseShare = Math.floor(remaining / availableSources.length);
    let extraShares: any = remaining % availableSources.length;
    let consumedThisPass: any = 0;

    for (const source of availableSources) {
      if (remaining <= 0) break;
      const plannedShare = baseShare + (extraShares > 0 ? 1 : 0);
      if (extraShares > 0) extraShares -= 1;
      if (plannedShare <= 0) continue;

      const take = Math.min(source.watts, plannedShare, remaining);
      if (take <= 0) continue;

      source.generator_entry.watts = clampInteger(source.watts - take, 0, source.max_watts);
      if (changedGenerators instanceof Set) changedGenerators.add(source.generator_key);
      remaining -= take;
      consumed += take;
      consumedThisPass += take;
    }

    if (consumedThisPass <= 0) break;
  }

  return consumed;
}

function removeLinkedPadFromGenerators(state: any, padKey: any) {
  if (!state || !(state.electrical_devices instanceof Map)) return false;
  let changed: any = false;
  for (const entry of state.electrical_devices.values()) {
    if (!entry || entry.device_type !== ELECTRICAL_DEVICE_GENERATOR) continue;
    const linkedPadKeys = getGeneratorLinkedPadKeys(entry);
    if (!linkedPadKeys.includes(padKey)) continue;
    setGeneratorLinkedPadKeys(entry, linkedPadKeys.filter((key: unknown) => key !== padKey));
    changed = true;
  }
  return changed;
}

function removeLinkedPoleFromGenerators(state: any, poleKey: any) {
  if (!state || !(state.electrical_devices instanceof Map)) return false;
  let changed: any = false;
  for (const entry of state.electrical_devices.values()) {
    if (!entry || entry.device_type !== ELECTRICAL_DEVICE_GENERATOR) continue;
    const linkedPoleKeys = getGeneratorLinkedPoleKeys(entry);
    if (!linkedPoleKeys.includes(poleKey)) continue;
    setGeneratorLinkedPoleKeys(entry, linkedPoleKeys.filter((key: unknown) => key !== poleKey));
    changed = true;
  }
  return changed;
}

function removeLinkedPoleFromPoleCouplings(state: any, poleKey: any) {
  if (!state || !(state.electrical_devices instanceof Map)) return false;
  let changed: any = false;
  for (const entry of state.electrical_devices.values()) {
    if (!entry || entry.device_type !== ELECTRICAL_DEVICE_POLE) continue;
    const linkedPoleKeys = getPoleLinkedPoleKeys(entry);
    if (!linkedPoleKeys.includes(poleKey)) continue;
    setPoleLinkedPoleKeys(entry, linkedPoleKeys.filter((key: unknown) => key !== poleKey));
    changed = true;
  }
  return changed;
}

function sanitizeElectricalLayerUpdate(data: any, worldName: any) {
  return WorldStateHelpers.sanitizeElectricalLayerUpdate(data, worldName);
}

function normalizeRemovedBlockEntry(rawEntry: any) {
  return WorldStateHelpers.normalizeRemovedBlockEntry(rawEntry);
}

function normalizeSeedEntry(rawEntry: any) {
  return WorldStateHelpers.normalizeSeedEntry(rawEntry);
}

function loadInteractionsIntoMap(target: any, rawEntries: any, worldName: any = "") {
  return WorldStateHelpers.loadInteractionsIntoMap(target, rawEntries, worldName);
}

/**
 * @param {PixelMania.RuntimeWorldDropMap} target
 * @param {Array<PixelMania.ActiveWorldDropPayload | PixelMania.WorldDropPayloadInput | Record<string, unknown>> | null | undefined} rawEntries
 * @returns {void}
 */
function loadDropsIntoMap(target: any, rawEntries: any) {
  return WorldStateHelpers.loadDropsIntoMap(target, rawEntries);
}

function sanitizeBlockUpdate(data: any, worldName: any) {
  return WorldStateHelpers.sanitizeBlockUpdate(data, worldName);
}

function sanitizeSeedUpdate(data: any, worldName: any) {
  const action = String(data.action || "").trim();
  if (action !== "place") return null;

  const x = Number(data.x);
  const y = Number(data.y);
  if (!Number.isFinite(x) || !Number.isFinite(y)) return null;
  const gridX = Math.trunc(x);
  const gridY = Math.trunc(y);
  if (!isGridInWorld(gridX, gridY)) return null;

  const seedType = clampString(data.seed_type || "");
  if (action === "place" && seedType.length === 0) return null;
  if (seedType !== "" && (!ItemDatabase.hasItem(seedType) || resolveInventoryCategory(seedType) !== "seed")) return null;

  const maxGrowTime = action === "place" ? getSeedConfiguredGrowTime(seedType) : SERVER_SEED_GROW_TIME_SECONDS;

  return {
    type: "world_seed_update",
    action,
    x: gridX,
    y: gridY,
    seed_type: seedType,
    grow_time: maxGrowTime,
    max_grow_time: maxGrowTime,
    world: cleanWorld(worldName),
  };
}

function getWorldBlockRevision(state: ServerPacketRecord | null | undefined) {
  return Math.max(0, Math.trunc(Number(state?.block_revision) || 0));
}

function nextWorldBlockRevision(state: ServerPacketRecord) {
  const nextRevision = Math.min(Number.MAX_SAFE_INTEGER, getWorldBlockRevision(state) + 1);
  state.block_revision = nextRevision;
  return nextRevision;
}

function applyBlockUpdateToWorldState(worldName: any, update: any) {
  const state = ensureWorldState(worldName);
  const key = gridKey(update.x, update.y);
  const target = getWorldLayerMap(state, update.layer);
  const removed = getWorldRemovedLayerMap(state, update.layer);
  const isForeground = update.layer === "foreground";
  const cctvPlacementStartsFresh = isForeground && update.action === "place" && isCctvBlockType(update.block_type) && !hasCctvBlock(worldName);

  if (update.action === "place") {
    const blockRevision = nextWorldBlockRevision(state);
    const placementRequestId = clampString(update.request_id || update.action_id || "");
    update.block_revision = blockRevision;
    update.placement_request_id = placementRequestId;
    update.world = cleanWorld(worldName);
    if (update.toggle_action !== "punch_toggle") {
      clearServerBlockDamage(worldName, update);
    }
    const blockEntry: ServerPacketRecord = {
      x: update.x,
      y: update.y,
      block_type: update.block_type,
      item_id: Math.max(0, Math.trunc(Number(update.item_id) || ItemAtlasDB.getItemIdForKey(update.block_type) || 0)),
      block_revision: blockRevision,
    };
    if (placementRequestId !== "") blockEntry.placement_request_id = placementRequestId;
    const placedByAccount = cleanAccountName(update.placed_by_account || "");
    if (placedByAccount !== "") blockEntry.placed_by_account = placedByAccount;
    target.set(key, blockEntry);
    const electricalDeviceChanged = syncElectricalDeviceStateForBlockUpdate(state, update);
    removed.delete(key);
    if (isDiceBlockType(update.block_type)) {
      state.interactions.set(key, makeEmptyDiceState(worldName, update.x, update.y));
    } else if (!isPersistentInteractionBlockType(update.block_type)) {
      state.interactions.delete(key);
    }
    if (cctvPlacementStartsFresh) {
      state.cctv_state = makeEmptyCctvWorldState(worldName);
    }
    if (electricalDeviceChanged) {
      markElectricalNetworksDirty(state);
    }
    if (isForeground) {
      invalidateMovementCollisionCache(worldName);
    }
    return;
  }

  if (update.action === "break") {
    const blockRevision = nextWorldBlockRevision(state);
    const mutationRequestId = clampString(update.request_id || update.action_id || "");
    update.block_revision = blockRevision;
    update.mutation_request_id = mutationRequestId;
    update.world = cleanWorld(worldName);
    clearServerBlockDamage(worldName, update);
    target.delete(key);
    const electricalDeviceChanged = syncElectricalDeviceStateForBlockUpdate(state, update);
    state.interactions.delete(key);
    removed.set(key, {
      x: update.x,
      y: update.y,
      block_type: update.block_type || "",
      item_id: Math.max(0, Math.trunc(Number(update.item_id) || ItemAtlasDB.getItemIdForKey(update.block_type) || 0)),
      block_revision: blockRevision,
      mutation_request_id: mutationRequestId,
    });

    if (isForeground && isWorldLockBlockType(update.block_type)) {
      state.world_lock = {};
    }
    if (isForeground && isCctvBlockType(update.block_type) && !hasCctvBlock(worldName)) {
      state.cctv_state = makeEmptyCctvWorldState(worldName);
    }
    if (electricalDeviceChanged) {
      markElectricalNetworksDirty(state);
    }
    if (isForeground) {
      invalidateMovementCollisionCache(worldName);
    }
  }
}

function applyElectricalLayerUpdateToWorldState(worldName: any, update: any) {
  const state = ensureWorldState(worldName);
  const key = gridKey(update.x, update.y);
  const previousEntry = state.electrical.get(key) || null;
  let nextEntry: any = null;

  if (update.action === "place") {
    nextEntry = makeElectricalEntryForPlace(update);
    if (nextEntry) {
      state.electrical.set(key, nextEntry);
    }
  } else if (update.action === "break") {
    state.electrical.delete(key);
  }

  markElectricalNetworksDirty(state);
  return {
    previousEntry: previousEntry ? cloneJson(previousEntry) : {},
    nextEntry: nextEntry ? cloneJson(nextEntry) : {},
  };
}

function createElectricalBreakDrops(worldName: any, update: any, previousEntry: any) {
  if (!update || update.action !== "break" || !previousEntry) return [];
  const itemId = clampString(previousEntry.item_id || previousEntry.block_type || update.block_type || "");
  if (!isElectricalLayerItem(itemId)) return [];

  const position = getGridCenterPixels(update.x, update.y);
  const payload = createServerDrop(worldName, itemId, "block", 1, position.x, position.y, SERVER_DROP_PICKUP_DELAY);
  return payload ? [payload] : [];
}

function applyElectricalGenerationForBlockBreak(worldName: any, update: any) {
  if (!update || update.action !== "break") return null;
  if (clampString(update.layer || "foreground").toLowerCase() !== "foreground") return null;
  if (clampString(update.block_type || "").toLowerCase() === ELECTRICAL_METAL_PAD_ITEM) return null;

  const state = ensureWorldState(worldName);
  const padKey = gridKey(update.x, update.y);
  const padEntry = getMetalPadDeviceStateAt(state, update.x, update.y);
  if (!padEntry || padEntry.device_type !== ELECTRICAL_DEVICE_METAL_PAD) return null;

  const cache = getFreshElectricalNetworkCache(state);
  const linkedGeneratorKey = cache.linked_pad_to_generator.get(padKey) || "";
  const generatorKey = linkedGeneratorKey !== "" ? linkedGeneratorKey : (cache.pad_to_generator.get(padKey) || "");
  if (generatorKey === "") return null;

  const network = cache.by_tile.get(padKey) || {};
  if (linkedGeneratorKey === "" && network.status !== "valid") return null;

  const generatorGrid = parseGridKey(generatorKey);
  if (!generatorGrid) return null;

  const generatorEntry = getMutableElectricalDeviceStateAt(state, generatorGrid.x, generatorGrid.y);
  if (!generatorEntry || generatorEntry.device_type !== ELECTRICAL_DEVICE_GENERATOR) return null;

  const maxWatts = clampInteger(generatorEntry.max_watts || ELECTRICAL_GENERATOR_MAX_WATTS, 1, ELECTRICAL_GENERATOR_MAX_WATTS);
  const previousWatts = clampInteger(generatorEntry.watts || 0, 0, maxWatts);
  const generatorBefore = cloneJson(generatorEntry);
  if (previousWatts >= maxWatts) {
    return {
      generated_watts: 0,
      previous_watts: previousWatts,
      next_watts: previousWatts,
      generator_before: generatorBefore,
      generator: cloneJson(generatorEntry),
      data_update: makeGeneratorDataPayload(worldName, generatorEntry, {
        generated_watts: 0,
        source_x: update.x,
        source_y: update.y,
        full: true,
      }),
      pulse: null,
    };
  }

  const nextWatts = Math.min(maxWatts, previousWatts + ELECTRICAL_PAD_GENERATION_WATTS);
  generatorEntry.watts = nextWatts;
  generatorEntry.max_watts = maxWatts;
  const generatedWatts = nextWatts - previousWatts;

  const dataUpdate = makeGeneratorDataPayload(worldName, generatorEntry, {
    generated_watts: generatedWatts,
    source_x: update.x,
    source_y: update.y,
    full: nextWatts >= maxWatts,
  });
  const pulse: any = {
    type: "generator_generation_pulse",
    world: cleanWorld(worldName),
    x: generatorEntry.x,
    y: generatorEntry.y,
    source_x: update.x,
    source_y: update.y,
    generated_watts: generatedWatts,
    watts: nextWatts,
    max_watts: maxWatts,
    network_id: clampString(dataUpdate?.network_id || ""),
  };

  return {
    generated_watts: generatedWatts,
    previous_watts: previousWatts,
    next_watts: nextWatts,
    generator_before: generatorBefore,
    generator: cloneJson(generatorEntry),
    data_update: dataUpdate,
    pulse,
  };
}

function applySeedUpdateToWorldState(worldName: any, update: any) {
  const state = ensureWorldState(worldName);
  const key = gridKey(update.x, update.y);

  if (update.action === "place" || update.action === "splice") {
    const seedEntry = makeServerSeedEntry(update.x, update.y, update.seed_type);
    state.seeds.set(key, seedEntry);
    update.grow_time = seedEntry.grow_time;
    update.max_grow_time = seedEntry.max_grow_time;
    update.mature = false;
    update.mutated = Boolean(seedEntry.mutated);
  } else if (update.action === "remove") {
    state.seeds.delete(key);
  }
}

function findEntranceGateInBlockMap(blockMap: any) {
  if (!blockMap || typeof blockMap.values !== "function") return null;

  for (const block of blockMap.values()) {
    if (clampString(block?.block_type || "") === ENTRANCE_GATE_TYPE) {
      return { x: block.x, y: block.y };
    }
  }

  return null;
}

function findEntranceGateInState(state: any) {
  return findEntranceGateInBlockMap(state?.foreground);
}

function findEntranceGatesInState(state: any) {
  const gates: any = [];
  for (const block of state.foreground.values()) {
    if (clampString(block?.block_type || "") === ENTRANCE_GATE_TYPE) {
      gates.push({ x: block.x, y: block.y });
    }
  }
  return gates;
}

function getEntranceGateSpawnForWorld(worldName: any) {
  const state = ensureWorldState(worldName);
  const gate = repairEntranceGateState(state, worldName)
    || findEntranceGateInState(state)
    || findEntranceGateInBlockMap(buildEffectiveForegroundMap(worldName, state));
  if (!gate || !isGridInWorld(gate.x, gate.y)) return null;

  return {
    x: gate.x * TILE_SIZE,
    y: gate.y * TILE_SIZE,
    grid_x: gate.x,
    grid_y: gate.y,
  };
}

function getWorldGenerationVersion(state: any) {
  return clampInteger(
    state?.world_generation_version || LEGACY_WORLD_GENERATION_VERSION,
    LEGACY_WORLD_GENERATION_VERSION,
    CURRENT_WORLD_GENERATION_VERSION
  );
}

function getGeneratedEntranceGateGridY(surfaceY: any, state: any) {
  const verticalOffset = getWorldGenerationVersion(state) >= LOWERED_ENTRANCE_GATE_GENERATION_VERSION ? 0 : -1;
  return clampInteger(surfaceY + verticalOffset, 0, Math.max(0, WORLD_HEIGHT - 2));
}

function getDefaultEntranceGateSpawnForWorld(worldName: any, state: any = null) {
  const gridX = clampInteger(Math.floor(WORLD_WIDTH * 0.5), 0, WORLD_WIDTH - 1);
  const terrain = buildServerTerrainSurface(worldName);
  const surfaceY = serverSurfaceYAt(terrain.surface, gridX);
  const resolvedState = state || ensureWorldState(worldName);
  const gridY = getGeneratedEntranceGateGridY(surfaceY, resolvedState);

  return {
    x: gridX * TILE_SIZE,
    y: gridY * TILE_SIZE,
    grid_x: gridX,
    grid_y: gridY,
  };
}

function getJoinWorldSpawnForWorld(worldName: any) {
  return getEntranceGateSpawnForWorld(worldName) || getDefaultEntranceGateSpawnForWorld(worldName);
}

function ensureEntranceGateSupportInState(state: any, gate: any) {
  if (!state || !gate) return;

  const x = gate.x;
  const y = gate.y + 1;
  if (!isGridInWorld(x, y)) return;

  const key = gridKey(x, y);
  state.foreground.set(key, { x, y, block_type: "bedrock" });
  state.removed_foreground.delete(key);
  state.interactions.delete(key);
  state.seeds.delete(key);
}

function cleanupLegacyEntranceGateSupportInState(state: any, gate: any) {
  if (!state || !gate) return;

  const y = gate.y + 1;
  for (const x of [gate.x - 1, gate.x + 1]) {
    if (!isGridInWorld(x, y)) continue;

    const key = gridKey(x, y);
    const blockType = clampString(state.foreground.get(key)?.block_type || "");
    if (blockType !== "bedrock") continue;

    state.foreground.delete(key);
    state.interactions?.delete(key);
    state.removed_foreground.set(key, { x, y, block_type: "bedrock" });
  }
}

function repairMovedDefaultEntranceGateSupportInState(state: any, gate: any, worldName: any) {
  if (!state || !gate || String(worldName || "").trim() === "") return;

  const defaultGate = getDefaultEntranceGateSpawnForWorld(worldName, state);
  const defaultGateX = Math.trunc(Number(defaultGate?.grid_x));
  const defaultGateY = Math.trunc(Number(defaultGate?.grid_y));
  if (!Number.isFinite(defaultGateX) || !Number.isFinite(defaultGateY)) return;
  if (gate.x === defaultGateX && gate.y === defaultGateY) return;

  const defaultGateKey = gridKey(defaultGateX, defaultGateY);
  const removedGateType = clampString(state.removed_foreground.get(defaultGateKey)?.block_type || "");
  if (removedGateType !== ENTRANCE_GATE_TYPE) return;

  const supportX = defaultGateX;
  const supportY = defaultGateY + 1;
  if (!isGridInWorld(supportX, supportY)) return;

  const supportKey = gridKey(supportX, supportY);
  if (state.foreground.has(supportKey)) return;
  state.removed_foreground.set(supportKey, {
    x: supportX,
    y: supportY,
    block_type: "bedrock",
  });
}

function repairEntranceGateState(state: any, worldName: any = "") {
  if (!state) return null;

  const gates = findEntranceGatesInState(state);
  if (gates.length === 0) return null;

  const keptGate = gates[gates.length - 1];
  const keptKey = gridKey(keptGate.x, keptGate.y);

  for (const gate of gates) {
    const key = gridKey(gate.x, gate.y);
    if (key === keptKey) continue;

    state.foreground.delete(key);
    state.interactions.delete(key);
    state.removed_foreground.set(key, {
      x: gate.x,
      y: gate.y,
      block_type: ENTRANCE_GATE_TYPE,
    });
  }

  ensureEntranceGateSupportInState(state, keptGate);
  cleanupLegacyEntranceGateSupportInState(state, keptGate);
  repairMovedDefaultEntranceGateSupportInState(state, keptGate, worldName);
  return keptGate;
}

function isProtectedEntranceSupportBlock(blockType: any) {
  const clean = clampString(blockType || "");
  return (
    isWorldLockBlockType(clean) ||
    clean === SAFE_BLOCK_TYPE ||
    clean === DONATION_BOX_BLOCK_TYPE ||
    isDisplayBlockType(clean) ||
    isMailboxBlockType(clean) ||
    clean === FISH_MONGER_BLOCK_TYPE ||
    isVendBlockType(clean) ||
    clean === "crafting_station" ||
    clean === "furnace" ||
    isPersistentInteractionBlockType(clean)
  );
}

function rejectEntranceMove(socket: any, message: any) {
  sendActionRejected(socket, "world_interaction_update", message);
  return { ok: false };
}

function validateEntranceGateMove(socket: any, player: any, worldName: any, update: any) {
  const state = ensureWorldState(worldName);
  const oldGate = findEntranceGateInBlockMap(buildEffectiveForegroundMap(worldName, state));

  if (!oldGate || !isGridInWorld(oldGate.x, oldGate.y)) {
    return rejectEntranceMove(socket, "Entrance Gate missing.");
  }

  if (oldGate.x === update.x && oldGate.y === update.y) {
    return rejectEntranceMove(socket, "Entrance Gate is already there.");
  }

  if (!isGridInWorld(update.x, update.y)) {
    return rejectEntranceMove(socket, "Outside world bounds.");
  }

  if (update.y <= 3 || update.y + 1 >= BEDROCK_START_Y) {
    return rejectEntranceMove(socket, "Not enough space for the Entrance Gate.");
  }

  if (!isPlayerNearGrid(player, update.x, update.y)) {
    return rejectEntranceMove(socket, "Too far away.");
  }

  const targetKey = gridKey(update.x, update.y);
  if (state.foreground.has(targetKey)) {
    return rejectEntranceMove(socket, "That spot is blocked.");
  }

  if (state.seeds.has(targetKey)) {
    return rejectEntranceMove(socket, "A seed is blocking that spot.");
  }

  for (let x: any = update.x - 1; x <= update.x + 1; x += 1) {
    const walkingKey = gridKey(x, update.y);
    if (!isGridInWorld(x, update.y)) {
      return rejectEntranceMove(socket, "Not enough walking space around the gate.");
    }

    if (x !== update.x && (state.foreground.has(walkingKey) || state.seeds.has(walkingKey))) {
      return rejectEntranceMove(socket, "Clear the walking space beside the gate first.");
    }
  }

  const underY = update.y + 1;
  if (!isGridInWorld(update.x, underY)) {
    return rejectEntranceMove(socket, "Not enough space under the gate.");
  }

  const underKey = gridKey(update.x, underY);
  if (state.seeds.has(underKey)) {
    return rejectEntranceMove(socket, "A seed is under the gate spot.");
  }

  const underBlock = state.foreground.get(underKey);
  const underType = clampString(underBlock?.block_type || "");

  if (underType === ENTRANCE_GATE_TYPE || isProtectedEntranceSupportBlock(underType)) {
    return rejectEntranceMove(socket, "A protected block is under that spot.");
  }

  if (underType !== "" && underType !== "bedrock" && !ItemDatabase.canBreakBlock(underType)) {
    return rejectEntranceMove(socket, "Unbreakable block under gate spot.");
  }

  return { ok: true, state, oldGate };
}

function applyEntranceGateMoveToWorldState(worldName: any, state: any, oldGate: any, newGate: any) {
  const updates: any = [];
  const effectiveForeground = buildEffectiveForegroundMap(worldName, state);
  const oldGateKey = gridKey(oldGate.x, oldGate.y);

  state.foreground.delete(oldGateKey);
  state.interactions.delete(oldGateKey);
  state.removed_foreground.set(oldGateKey, {
    x: oldGate.x,
    y: oldGate.y,
    block_type: ENTRANCE_GATE_TYPE,
  });
  updates.push({
    type: "world_block_update",
    action: "break",
    layer: "foreground",
    x: oldGate.x,
    y: oldGate.y,
    block_type: ENTRANCE_GATE_TYPE,
    world: cleanWorld(worldName),
  });

  for (let x: any = oldGate.x - 1; x <= oldGate.x + 1; x += 1) {
    const y = oldGate.y + 1;
    if (!isGridInWorld(x, y)) continue;

    const key = gridKey(x, y);
    const oldSupportType = clampString(effectiveForeground.get(key)?.block_type || "");
    if (oldSupportType !== "bedrock") continue;

    state.foreground.delete(key);
    state.interactions.delete(key);
    state.removed_foreground.set(key, { x, y, block_type: oldSupportType });
    updates.push({
      type: "world_block_update",
      action: "break",
      layer: "foreground",
      x,
      y,
      block_type: oldSupportType,
      world: cleanWorld(worldName),
    });
  }

  const supportX = newGate.x;
  const supportY = newGate.y + 1;
  const supportKey = gridKey(supportX, supportY);
  state.foreground.set(supportKey, { x: supportX, y: supportY, block_type: "bedrock" });
  state.removed_foreground.delete(supportKey);
  state.interactions.delete(supportKey);
  updates.push({
    type: "world_block_update",
    action: "place",
    layer: "foreground",
    x: supportX,
    y: supportY,
    block_type: "bedrock",
    world: cleanWorld(worldName),
  });

  const newGateKey = gridKey(newGate.x, newGate.y);
  state.foreground.set(newGateKey, {
    x: newGate.x,
    y: newGate.y,
    block_type: ENTRANCE_GATE_TYPE,
  });
  state.removed_foreground.delete(newGateKey);
  state.interactions.delete(newGateKey);
  updates.push({
    type: "world_block_update",
    action: "place",
    layer: "foreground",
    x: newGate.x,
    y: newGate.y,
    block_type: ENTRANCE_GATE_TYPE,
    world: cleanWorld(worldName),
  });

  repairEntranceGateState(state, worldName);
  return updates;
}

function buildEntranceGateMoveChangeEntries(socket: any, player: any, worldName: any, updates: any[], sourceId: any, oldGate: any, newGate: any) {
  return updates.map((blockUpdate: any) => {
    const isPlace = blockUpdate.action === "place";
    return {
      ...getAuditActor(socket, player),
      source_type: "entrance_gate_move",
      source_id: sourceId,
      world: cleanWorld(worldName),
      action: `entrance_gate_${blockUpdate.action}`,
      layer: blockUpdate.layer,
      x: blockUpdate.x,
      y: blockUpdate.y,
      block_type: blockUpdate.block_type,
      block_type_before: isPlace ? "" : blockUpdate.block_type,
      block_type_after: isPlace ? blockUpdate.block_type : "",
      details: {
        old_x: oldGate.x,
        old_y: oldGate.y,
        new_x: newGate.x,
        new_y: newGate.y,
        old_block_id: isPlace ? "" : blockUpdate.block_type,
        new_block_id: isPlace ? blockUpdate.block_type : "",
      },
    };
  });
}

async function handleEntranceGateMoveUpdate(socket: any, player: any, worldName: any, update: any, requestId: any = "") {
  const validation: any = validateEntranceGateMove(socket, player, worldName, update);
  if (!validation.ok) return false;

  const moveTransactionId = makeAuditId("gate_move");
  const spendResult = await spendServerInventoryCost(player.account_username, {
    item_id: "entrance_mover",
    item_category: "tool",
    amount: 1,
  }, {
    socket,
    player,
    source: "world_interaction",
    action: "entrance_gate_move",
    reason: "gate_move_cost",
    request_id: requestId,
    world: worldName,
    metadata: {
      transaction_id: moveTransactionId,
      old_x: validation.oldGate.x,
      old_y: validation.oldGate.y,
      new_x: update.x,
      new_y: update.y,
    },
    defer_commit: POSTGRES_ENABLED && POSTGRES_AUTHORITATIVE,
  });
  if (!spendResult.ok) {
    sendActionRejected(socket, "world_interaction_update", spendResult.message);
    return false;
  }

  const rollback = captureWorldMutationRollback(worldName);
  const newGate = { x: update.x, y: update.y };
  const updates = applyEntranceGateMoveToWorldState(
    worldName,
    validation.state,
    validation.oldGate,
    newGate
  );
  const worldChanges = buildEntranceGateMoveChangeEntries(
    socket,
    player,
    worldName,
    updates,
    moveTransactionId,
    validation.oldGate,
    newGate
  );
  let inventoryCommit: any = null;
  let committedInventoryState = spendResult.state;
  let inventoryDeltas = buildInventoryDeltaClientPayloads(spendResult.deltas, spendResult.state);
  let postgresCommitted = Boolean(spendResult.postgres_committed);

  if (spendResult.deferred_inventory_commit) {
    const deferred = spendResult.deferred_inventory_commit;
    const serializedWorld = serializeWorldState(worldName);
    inventoryCommit = await commitPlayerInventoryState(
      socket,
      player,
      deferred.username,
      deferred.beforeState,
      deferred.afterState,
      {
        ...(deferred.options || {}),
        world: worldName,
        world_state: serializedWorld,
        world_changes: worldChanges,
      }
    );
    if (!inventoryCommit.ok) {
      restoreWorldMutationRollback(worldName, rollback);
      sendActionRejected(socket, "world_interaction_update", inventoryCommit.message || "PostgreSQL rejected the entrance move.", {
        reason: inventoryCommit.reason || "inventory_commit_failed",
      });
      return false;
    }
    committedInventoryState = inventoryCommit.state;
    inventoryDeltas = buildInventoryDeltaClientPayloads(inventoryCommit.deltas, inventoryCommit.state);
    postgresCommitted = Boolean(inventoryCommit.postgres_committed);
    persistWorldStateAfterInventoryCommit(worldName, postgresCommitted, serializedWorld);
  } else {
    const worldCommit = await commitWorldStateWithBlockChanges(worldName, worldChanges, {
      player,
      reason: "entrance_gate_move",
    });
    if (!worldCommit.ok) {
      restoreWorldMutationRollback(worldName, rollback);
      sendActionRejected(socket, "world_interaction_update", worldCommit.message || "Could not save the entrance move.", {
        reason: worldCommit.reason || "world_commit_failed",
      });
      return false;
    }
    postgresCommitted = Boolean(worldCommit.postgres_committed);
  }

  logItemLedgerForState(socket, player, player.account_username, committedInventoryState, "entrance_mover", "tool", -1, "entrance_gate_move", moveTransactionId, "gate_move_cost", worldName, {
    old_x: validation.oldGate.x,
    old_y: validation.oldGate.y,
    new_x: update.x,
    new_y: update.y,
  }, { skipPostgres: postgresCommitted });
  logWorldChange(socket, player, {
    source_type: "entrance_gate_move",
    source_id: moveTransactionId,
    world: worldName,
    action: "entrance_gate_move",
    layer: "foreground",
    x: update.x,
    y: update.y,
    block_type: ENTRANCE_GATE_TYPE,
    details: {
      old_x: validation.oldGate.x,
      old_y: validation.oldGate.y,
      new_x: update.x,
      new_y: update.y,
      update_count: updates.length,
    },
  }, { skipPostgres: postgresCommitted });
  for (let index = 0; index < updates.length; index += 1) {
    const blockUpdate = updates[index];
    logWorldChange(socket, player, worldChanges[index], { skipPostgres: postgresCommitted });
    sendWorldUpdateToRequesterAndWorld(socket, player, worldName, blockUpdate);
  }

  sendInventoryTransactionResult(socket, {
    ok: true,
    action: "entrance_gate_move",
    message: "Entrance Gate moved.",
    username: player.account_username,
    inventory_deltas: inventoryDeltas,
  });
  return true;
}

function validateWorldLockMove(socket: any, player: any, worldName: any, update: any) {
  const state = ensureWorldState(worldName);
  const lock: any = getEffectiveWorldLockStateInState(state);

  if (!lock.is_locked) {
    sendActionRejected(socket, "world_interaction_update", "This world does not have a World Lock.", {
      reason: "world_lock_missing",
    });
    return { ok: false };
  }

  if (!canPlayerControlWorldLock(player, worldName)) {
    sendActionRejected(socket, "world_interaction_update", "Only the world lock owner can move the lock.", {
      reason: "world_lock_owner_required",
    });
    return { ok: false };
  }

  if (!isPlayerNearGrid(player, update.x, update.y, MAX_PLACE_REACH_PIXELS, { action: "world_lock_move", world: worldName })) {
    sendActionRejected(socket, "world_interaction_update", "Too far away.", {
      reason: "too_far",
      target_x: update.x,
      target_y: update.y,
      max_reach_tiles: MAX_PLACE_REACH_TILES,
    });
    return { ok: false };
  }

  const activeLockBlock = getWorldLockBlockEntry(state);
  if (!activeLockBlock) {
    sendActionRejected(socket, "world_interaction_update", "World Lock block missing.", {
      reason: "world_lock_block_missing",
    });
    return { ok: false };
  }

  if (
    Number.isFinite(Number(update.old_x)) &&
    Number.isFinite(Number(update.old_y)) &&
    (Math.trunc(Number(update.old_x)) !== activeLockBlock.x || Math.trunc(Number(update.old_y)) !== activeLockBlock.y)
  ) {
    sendActionRejected(socket, "world_interaction_update", "World Lock moved already. Try again.", {
      reason: "world_lock_position_changed",
      current_x: activeLockBlock.x,
      current_y: activeLockBlock.y,
    });
    return { ok: false };
  }

  if (update.x === activeLockBlock.x && update.y === activeLockBlock.y) {
    sendActionRejected(socket, "world_interaction_update", "World Lock is already here.", {
      reason: "same_position",
    });
    return { ok: false };
  }

  const targetKey = gridKey(update.x, update.y);
  if (state.foreground.has(targetKey)) {
    sendActionRejected(socket, "world_interaction_update", "That spot is already occupied.", {
      reason: "occupied",
      target_x: update.x,
      target_y: update.y,
    });
    return { ok: false };
  }

  if (state.seeds.has(targetKey)) {
    sendActionRejected(socket, "world_interaction_update", "A seed is already planted there.", {
      reason: "seed_occupied",
      target_x: update.x,
      target_y: update.y,
    });
    return { ok: false };
  }

  if (doesPlacementOverlapReservedObject(state, update.x, update.y, activeLockBlock.block_type)) {
    sendActionRejected(socket, "world_interaction_update", "Need enough empty space.", {
      reason: "reserved_space",
      target_x: update.x,
      target_y: update.y,
    });
    return { ok: false };
  }

  return {
    ok: true,
    state,
    lock: sanitizeWorldLockState(lock),
    oldLock: activeLockBlock,
    newLock: {
      x: update.x,
      y: update.y,
      block_type: activeLockBlock.block_type,
    },
  };
}

function applyWorldLockMoveToWorldState(worldName: any, validation: any) {
  const state = validation.state || ensureWorldState(worldName);
  const oldLock = validation.oldLock;
  const newLock = validation.newLock;
  const oldKey = gridKey(oldLock.x, oldLock.y);
  const newKey = gridKey(newLock.x, newLock.y);
  const cleanWorldName = cleanWorld(worldName);
  const updates: any = [];

  state.foreground.delete(oldKey);
  state.interactions.delete(oldKey);
  state.removed_foreground.set(oldKey, {
    x: oldLock.x,
    y: oldLock.y,
    block_type: oldLock.block_type,
  });
  updates.push({
    type: "world_block_update",
    action: "break",
    layer: "foreground",
    x: oldLock.x,
    y: oldLock.y,
    block_type: oldLock.block_type,
    world: cleanWorldName,
    source_tool: LOCK_MOVER_ITEM_TYPE,
  });

  state.foreground.set(newKey, {
    x: newLock.x,
    y: newLock.y,
    block_type: newLock.block_type,
  });
  state.removed_foreground.delete(newKey);
  state.interactions.delete(newKey);
  updates.push({
    type: "world_block_update",
    action: "place",
    layer: "foreground",
    x: newLock.x,
    y: newLock.y,
    block_type: newLock.block_type,
    world: cleanWorldName,
    source_tool: LOCK_MOVER_ITEM_TYPE,
  });

  const nextLock = sanitizeWorldLockState({
    ...(state.world_lock || {}),
    is_locked: true,
    lock_block_type: newLock.block_type,
    lock_type: newLock.block_type,
    lock_grid_x: newLock.x,
    lock_grid_y: newLock.y,
  });
  state.world_lock = nextLock;
  updates.push(makeWorldLockStatePayload(cleanWorldName, nextLock));

  return updates;
}

function buildWorldLockMoveChangeEntries(socket: any, player: any, worldName: any, validation: any, objectBefore: any, objectAfter: any, sourceId: any) {
  const oldLock = validation.oldLock;
  const newLock = validation.newLock;
  const baseDetails: any = {
    old_x: oldLock.x,
    old_y: oldLock.y,
    new_x: newLock.x,
    new_y: newLock.y,
    lock_block_type: newLock.block_type,
  };

  return [
    {
      ...getAuditActor(socket, player),
      source_type: "world_lock_move",
      source_id: sourceId,
      world: worldName,
      action: "world_lock_move_remove_old",
      layer: "foreground",
      x: oldLock.x,
      y: oldLock.y,
      block_type: oldLock.block_type,
      block_type_before: oldLock.block_type,
      block_type_after: "",
      details: {
        ...baseDetails,
        old_block_id: oldLock.block_type,
        new_block_id: "",
      },
    },
    {
      ...getAuditActor(socket, player),
      source_type: "world_lock_move",
      source_id: sourceId,
      world: worldName,
      action: "world_lock_move_place_new",
      layer: "foreground",
      x: newLock.x,
      y: newLock.y,
      block_type: newLock.block_type,
      block_type_before: "",
      block_type_after: newLock.block_type,
      details: {
        ...baseDetails,
        old_block_id: "",
        new_block_id: newLock.block_type,
      },
    },
    buildWorldObjectChangeEntry(
      socket,
      player,
      worldName,
      {
        type: "world_interaction_update",
        action: "world_lock_state",
        object_type: "world_lock",
        world: worldName,
        x: newLock.x,
        y: newLock.y,
        block_type: newLock.block_type,
        state: objectAfter,
      },
      objectBefore,
      objectAfter,
      sourceId,
      {
        ...baseDetails,
        action: "world_lock_move",
      }
    ),
  ];
}

async function handleWorldLockMoveUpdate(socket: any, player: any, worldName: any, update: any, requestId: any = "") {
  const validation: any = validateWorldLockMove(socket, player, worldName, update);
  if (!validation.ok) return false;

  const moveTransactionId = makeAuditId("lock_move");
  const spendResult = await spendServerInventoryCost(player.account_username, {
    item_id: LOCK_MOVER_ITEM_TYPE,
    item_category: "tool",
    amount: 1,
  }, {
    socket,
    player,
    source: "world_interaction",
    action: "world_lock_move",
    reason: "lock_move_cost",
    request_id: requestId,
    world: worldName,
    metadata: {
      transaction_id: moveTransactionId,
      old_x: validation.oldLock.x,
      old_y: validation.oldLock.y,
      new_x: update.x,
      new_y: update.y,
      lock_block_type: validation.oldLock.block_type,
    },
    defer_commit: isPostgresAuthoritativeReady(),
  });
  if (!spendResult.ok) {
    sendActionRejected(socket, "world_interaction_update", spendResult.message);
    return false;
  }

  const previousWorldState = serializeWorldState(worldName);
  const objectBefore = cloneJson(validation.lock);
  const updates = applyWorldLockMoveToWorldState(worldName, validation);
  const objectAfter = cloneJson(ensureWorldState(worldName).world_lock || {});
  const worldChanges = buildWorldLockMoveChangeEntries(socket, player, worldName, validation, objectBefore, objectAfter, moveTransactionId);
  let inventoryCommit: any = null;
  let requesterInventoryDeltas: any = buildInventoryDeltaClientPayloads(spendResult.deltas, spendResult.state);
  let postgresCommitted: any = Boolean(spendResult.postgres_committed);

  if (spendResult.deferred_inventory_commit) {
    const deferred = spendResult.deferred_inventory_commit;
    const serializedWorld = serializeWorldState(worldName);
    inventoryCommit = await commitPlayerInventoryState(
      socket,
      player,
      deferred.username,
      deferred.beforeState,
      deferred.afterState,
      {
        ...(deferred.options || {}),
        world: worldName,
        world_state: serializedWorld,
        world_changes: worldChanges,
      }
    );
    if (!inventoryCommit.ok) {
      worldStates.set(cleanWorld(worldName), deserializeWorldState(worldName, previousWorldState));
      sendActionRejected(socket, "world_interaction_update", inventoryCommit.message || "PostgreSQL rejected the lock move.", {
        reason: inventoryCommit.reason || "inventory_commit_failed",
      });
      return false;
    }
    requesterInventoryDeltas = buildInventoryDeltaClientPayloads(inventoryCommit.deltas, inventoryCommit.state);
    postgresCommitted = Boolean(inventoryCommit.postgres_committed);
    persistWorldStateAfterInventoryCommit(worldName, postgresCommitted, serializedWorld);
  } else {
    const worldCommit = await commitWorldStateWithBlockChanges(worldName, worldChanges, {
      player,
    });
    if (!worldCommit.ok) {
      worldStates.set(cleanWorld(worldName), deserializeWorldState(worldName, previousWorldState));
      sendActionRejected(socket, "world_interaction_update", worldCommit.message || "PostgreSQL rejected the lock move.", {
        reason: worldCommit.reason || "world_commit_failed",
      });
      return false;
    }
    postgresCommitted = Boolean(worldCommit.postgres_committed);
  }

  for (const outgoingUpdate of updates) {
    sendWorldUpdateToRequesterAndWorld(socket, player, worldName, outgoingUpdate);
  }
  for (const worldChange of worldChanges) {
    logWorldChange(socket, player, worldChange, { skipPostgres: postgresCommitted });
  }
  logItemLedgerForState(socket, player, player.account_username, inventoryCommit?.state || spendResult.state, LOCK_MOVER_ITEM_TYPE, "tool", -1, "world_lock_move", moveTransactionId, "lock_move_cost", worldName, {
    old_x: validation.oldLock.x,
    old_y: validation.oldLock.y,
    new_x: update.x,
    new_y: update.y,
    lock_block_type: validation.oldLock.block_type,
  }, { skipPostgres: postgresCommitted });

  sendInventoryTransactionResult(socket, {
    ok: true,
    action: "world_lock_move",
    message: "World Lock moved.",
    username: player.account_username,
    inventory_deltas: requesterInventoryDeltas,
  });
  return true;
}

function makeDoorMoveClientFields(doorState: any = {}) {
  const doorName = cleanDoorName(doorState.door_name || doorState.name || "");
  const destination = cleanDoorDestination(doorState.destination || doorState.door_destination || "");
  const targetWorld = cleanWorld(doorState.target_world || doorState.door_target_world || "");
  const targetDoorId = cleanDoorId(doorState.target_door_id || doorState.door_target_id || "");
  return {
    door_id: cleanDoorId(doorState.door_id || ""),
    door_name: doorName,
    name: doorName,
    door_destination: destination,
    destination,
    door_target_world: targetWorld,
    door_target_id: targetDoorId,
    entrance_locked: Boolean(doorState.locked || doorState.entrance_locked),
    door_password_configured: cleanDoorPassword(doorState.password || doorState.door_password || "") !== "",
  };
}

function makeDoorMoveBlockEntry(x: any, y: any, blockType: any, doorState: any = {}) {
  const fields = makeDoorMoveClientFields(doorState);
  const entry: any = {
    x,
    y,
    block_type: blockType,
    item_id: Math.max(0, Math.trunc(Number(ItemAtlasDB.getItemIdForKey(blockType)) || 0)),
    entrance_locked: fields.entrance_locked,
  };
  if (fields.door_id !== "") entry.door_id = fields.door_id;
  if (fields.door_name !== "") entry.door_name = fields.door_name;
  if (fields.door_destination !== "") entry.door_destination = fields.door_destination;
  if (fields.door_target_world !== "") entry.door_target_world = fields.door_target_world;
  if (fields.door_target_id !== "") entry.door_target_id = fields.door_target_id;
  return entry;
}

function makeDoorMoveInteractionUpdate(worldName: any, x: any, y: any, blockType: any, doorState: any = {}) {
  const fields = makeDoorMoveClientFields(doorState);
  return {
    type: "world_interaction_update",
    world: cleanWorld(worldName),
    action: "door_state",
    x,
    y,
    block_type: blockType,
    door_id: fields.door_id,
    door_name: fields.door_name,
    name: fields.door_name,
    destination: fields.destination,
    target_world: fields.door_target_world || cleanWorld(worldName),
    target_door_id: fields.door_target_id,
    locked: fields.entrance_locked,
    password_changed: cleanDoorPassword(doorState.password || doorState.door_password || "") !== "",
    password: cleanDoorPassword(doorState.password || doorState.door_password || ""),
  };
}

function makeDoorMoveJournalData(block: any = {}, doorState: any = {}) {
  const fields = makeDoorMoveClientFields(doorState);
  return {
    x: Math.trunc(Number(block.x) || 0),
    y: Math.trunc(Number(block.y) || 0),
    block_type: clampString(block.block_type || doorState.block_type || ""),
    door_id: fields.door_id,
    door_name: fields.door_name,
    destination: fields.destination,
    target_world: fields.door_target_world,
    target_door_id: fields.door_target_id,
    locked: fields.entrance_locked,
    password_configured: fields.door_password_configured,
  };
}

function validateDoorMove(socket: any, player: any, worldName: any, update: any) {
  const state = ensureWorldState(worldName);
  const oldKey = gridKey(update.old_x, update.old_y);
  const oldDoor = state.foreground.get(oldKey);

  if (!oldDoor || !isDoorBlockType(oldDoor.block_type)) {
    sendActionRejected(socket, "world_interaction_update", "Door missing.", {
      reason: "door_missing",
      old_x: update.old_x,
      old_y: update.old_y,
    });
    return { ok: false };
  }

  if (!canPlayerConfigureDoor(player, worldName)) {
    sendActionRejected(socket, "world_interaction_update", "Only the owner or trusted builders can move this door.", {
      reason: "door_permission_required",
    });
    return { ok: false };
  }

  if (!isPlayerNearGrid(player, update.old_x, update.old_y, MAX_PLACE_REACH_PIXELS, { action: "door_move", world: worldName })) {
    sendActionRejected(socket, "world_interaction_update", "Too far away from the door.", {
      reason: "too_far_from_old_door",
      old_x: update.old_x,
      old_y: update.old_y,
      max_reach_tiles: MAX_PLACE_REACH_TILES,
    });
    return { ok: false };
  }

  if (!isPlayerNearGrid(player, update.x, update.y, MAX_PLACE_REACH_PIXELS, { action: "door_move", world: worldName })) {
    sendActionRejected(socket, "world_interaction_update", "Too far away.", {
      reason: "too_far",
      target_x: update.x,
      target_y: update.y,
      max_reach_tiles: MAX_PLACE_REACH_TILES,
    });
    return { ok: false };
  }

  if (update.x === update.old_x && update.y === update.old_y) {
    sendActionRejected(socket, "world_interaction_update", "Door is already there.", {
      reason: "same_position",
    });
    return { ok: false };
  }

  const newKey = gridKey(update.x, update.y);
  if (state.foreground.has(newKey)) {
    sendActionRejected(socket, "world_interaction_update", "That spot is already occupied.", {
      reason: "occupied",
      target_x: update.x,
      target_y: update.y,
    });
    return { ok: false };
  }

  if (state.seeds.has(newKey)) {
    sendActionRejected(socket, "world_interaction_update", "A seed is already planted there.", {
      reason: "seed_occupied",
      target_x: update.x,
      target_y: update.y,
    });
    return { ok: false };
  }

  if (doesPlacementOverlapReservedObjectExcept(state, update.x, update.y, oldDoor.block_type, oldKey)) {
    sendActionRejected(socket, "world_interaction_update", "Need enough empty space.", {
      reason: "reserved_space",
      target_x: update.x,
      target_y: update.y,
    });
    return { ok: false };
  }

  const doorState = getDoorStateForBlock(state, oldDoor, worldName) || {};
  return {
    ok: true,
    state,
    oldDoor,
    oldDoorState: doorState,
    newDoor: {
      x: update.x,
      y: update.y,
      block_type: oldDoor.block_type,
    },
  };
}

function applyDoorMoveToWorldState(worldName: any, validation: any) {
  const state = validation.state || ensureWorldState(worldName);
  const oldDoor = validation.oldDoor;
  const newDoor = validation.newDoor;
  const oldKey = gridKey(oldDoor.x, oldDoor.y);
  const newKey = gridKey(newDoor.x, newDoor.y);
  const cleanWorldName = cleanWorld(worldName);
  const doorState = validation.oldDoorState || {};
  const clientFields = makeDoorMoveClientFields(doorState);
  const updates: any = [];

  state.foreground.delete(oldKey);
  state.interactions.delete(oldKey);
  state.removed_foreground.set(oldKey, {
    x: oldDoor.x,
    y: oldDoor.y,
    block_type: oldDoor.block_type,
  });
  updates.push({
    type: "world_block_update",
    action: "break",
    layer: "foreground",
    x: oldDoor.x,
    y: oldDoor.y,
    block_type: oldDoor.block_type,
    world: cleanWorldName,
    source_tool: DOOR_MOVER_ITEM_TYPE,
  });

  const newBlockEntry = makeDoorMoveBlockEntry(newDoor.x, newDoor.y, newDoor.block_type, doorState);
  state.foreground.set(newKey, newBlockEntry);
  state.removed_foreground.delete(newKey);
  state.interactions.delete(newKey);
  applyInteractionUpdateToWorldState(cleanWorldName, makeDoorMoveInteractionUpdate(cleanWorldName, newDoor.x, newDoor.y, newDoor.block_type, doorState));
  updates.push({
    type: "world_block_update",
    action: "place",
    layer: "foreground",
    x: newDoor.x,
    y: newDoor.y,
    block_type: newDoor.block_type,
    world: cleanWorldName,
    source_tool: DOOR_MOVER_ITEM_TYPE,
    ...clientFields,
  });

  invalidateMovementCollisionCache(cleanWorldName);
  return updates;
}

function buildDoorMoveChangeEntries(socket: any, player: any, worldName: any, validation: any, objectBefore: any, objectAfter: any, sourceId: any) {
  const oldDoor = validation.oldDoor;
  const newDoor = validation.newDoor;
  const doorState = validation.oldDoorState || {};
  const details: any = {
    old_x: oldDoor.x,
    old_y: oldDoor.y,
    new_x: newDoor.x,
    new_y: newDoor.y,
    door_id: cleanDoorId(doorState.door_id || ""),
    block_type: newDoor.block_type,
  };

  return [
    {
      ...getAuditActor(socket, player),
      source_type: "door_move",
      source_id: sourceId,
      world: cleanWorld(worldName),
      action: "door_move_remove_old",
      layer: "foreground",
      x: oldDoor.x,
      y: oldDoor.y,
      block_type: oldDoor.block_type,
      block_type_before: oldDoor.block_type,
      block_type_after: "",
      details: {
        ...details,
        old_block_id: oldDoor.block_type,
        new_block_id: "",
      },
    },
    {
      ...getAuditActor(socket, player),
      source_type: "door_move",
      source_id: sourceId,
      world: cleanWorld(worldName),
      action: "door_move_place_new",
      layer: "foreground",
      x: newDoor.x,
      y: newDoor.y,
      block_type: newDoor.block_type,
      block_type_before: "",
      block_type_after: newDoor.block_type,
      details: {
        ...details,
        old_block_id: "",
        new_block_id: newDoor.block_type,
      },
    },
    buildWorldObjectChangeEntry(
      socket,
      player,
      worldName,
      {
        type: "world_interaction_update",
        action: "door_move",
        object_type: "door",
        world: cleanWorld(worldName),
        x: newDoor.x,
        y: newDoor.y,
        block_type: newDoor.block_type,
        door_id: cleanDoorId(doorState.door_id || ""),
      },
      objectBefore,
      objectAfter,
      sourceId,
      details
    ),
  ];
}

async function handleDoorMoveUpdate(socket: any, player: any, worldName: any, update: any, requestId: any = "") {
  const validation: any = validateDoorMove(socket, player, worldName, update);
  if (!validation.ok) return false;

  const moveTransactionId = makeAuditId("door_move");
  const spendResult = await spendServerInventoryCost(player.account_username, {
    item_id: DOOR_MOVER_ITEM_TYPE,
    item_category: "tool",
    amount: 1,
  }, {
    socket,
    player,
    source: "world_interaction",
    action: "door_move",
    reason: "door_move_cost",
    request_id: requestId,
    world: worldName,
    metadata: {
      transaction_id: moveTransactionId,
      old_x: validation.oldDoor.x,
      old_y: validation.oldDoor.y,
      new_x: update.x,
      new_y: update.y,
      door_id: cleanDoorId(validation.oldDoorState?.door_id || ""),
      door_block_type: validation.oldDoor.block_type,
    },
    defer_commit: isPostgresAuthoritativeReady(),
  });
  if (!spendResult.ok) {
    sendActionRejected(socket, "world_interaction_update", spendResult.message);
    return false;
  }

  const previousWorldState = serializeWorldState(worldName);
  const objectBefore = makeDoorMoveJournalData(validation.oldDoor, validation.oldDoorState);
  const updates = applyDoorMoveToWorldState(worldName, validation);
  const nextDoorBlock = ensureWorldState(worldName).foreground.get(gridKey(validation.newDoor.x, validation.newDoor.y)) || validation.newDoor;
  const nextDoorState = getDoorStateForBlock(ensureWorldState(worldName), nextDoorBlock, worldName) || validation.oldDoorState;
  const objectAfter = makeDoorMoveJournalData(nextDoorBlock, nextDoorState);
  const worldChanges = buildDoorMoveChangeEntries(socket, player, worldName, validation, objectBefore, objectAfter, moveTransactionId);
  let inventoryCommit: any = null;
  let requesterInventoryDeltas: any = buildInventoryDeltaClientPayloads(spendResult.deltas, spendResult.state);
  let postgresCommitted: any = Boolean(spendResult.postgres_committed);

  if (spendResult.deferred_inventory_commit) {
    const deferred = spendResult.deferred_inventory_commit;
    const serializedWorld = serializeWorldState(worldName);
    inventoryCommit = await commitPlayerInventoryState(
      socket,
      player,
      deferred.username,
      deferred.beforeState,
      deferred.afterState,
      {
        ...(deferred.options || {}),
        world: worldName,
        world_state: serializedWorld,
        world_changes: worldChanges,
      }
    );
    if (!inventoryCommit.ok) {
      worldStates.set(cleanWorld(worldName), deserializeWorldState(worldName, previousWorldState));
      sendActionRejected(socket, "world_interaction_update", inventoryCommit.message || "PostgreSQL rejected the door move.", {
        reason: inventoryCommit.reason || "inventory_commit_failed",
      });
      return false;
    }
    requesterInventoryDeltas = buildInventoryDeltaClientPayloads(inventoryCommit.deltas, inventoryCommit.state);
    postgresCommitted = Boolean(inventoryCommit.postgres_committed);
    persistWorldStateAfterInventoryCommit(worldName, postgresCommitted, serializedWorld);
  } else {
    const worldCommit = await commitWorldStateWithBlockChanges(worldName, worldChanges, {
      player,
    });
    if (!worldCommit.ok) {
      worldStates.set(cleanWorld(worldName), deserializeWorldState(worldName, previousWorldState));
      sendActionRejected(socket, "world_interaction_update", worldCommit.message || "PostgreSQL rejected the door move.", {
        reason: worldCommit.reason || "world_commit_failed",
      });
      return false;
    }
    postgresCommitted = Boolean(worldCommit.postgres_committed);
  }

  for (const outgoingUpdate of updates) {
    sendWorldUpdateToRequesterAndWorld(socket, player, worldName, outgoingUpdate);
  }
  for (const worldChange of worldChanges) {
    logWorldChange(socket, player, worldChange, { skipPostgres: postgresCommitted });
  }
  logItemLedgerForState(socket, player, player.account_username, inventoryCommit?.state || spendResult.state, DOOR_MOVER_ITEM_TYPE, "tool", -1, "door_move", moveTransactionId, "door_move_cost", worldName, {
    old_x: validation.oldDoor.x,
    old_y: validation.oldDoor.y,
    new_x: update.x,
    new_y: update.y,
    door_id: cleanDoorId(validation.oldDoorState?.door_id || ""),
    door_block_type: validation.oldDoor.block_type,
  }, { skipPostgres: postgresCommitted });

  sendInventoryTransactionResult(socket, {
    ok: true,
    action: "door_move",
    message: "Door moved.",
    username: player.account_username,
    inventory_deltas: requesterInventoryDeltas,
  });
  return true;
}

