async function handleBulkDropPickup(socket: any, player: any, data: any, worldName: any, requestId: any) {
  const bulkUpdate = sanitizeBulkDropPickup(data, worldName, player);
  if (!bulkUpdate) {
    sendActionRejected(socket, "world_item_drop_pickup", "That drop is not available.", {
      world: cleanWorld(worldName),
    });
    return;
  }

  debugActionPositionFlow("world_item_drop_pickup bulk request start", player, {
    count: bulkUpdate.drop_ids.length,
    first_drop_id: bulkUpdate.drop_id,
  });

  if (!usesTrustedMovementPosition(player) && bulkUpdate.action_position && acceptPlayerMovement(socket, player, bulkUpdate.action_position, { silent: true })) {
    player.x = bulkUpdate.action_position.x;
    player.y = bulkUpdate.action_position.y;
    player.facing = bulkUpdate.action_position.facing;
  }

  if (!isPostgresAuthoritativeReady()) {
    handleLegacyBulkDropPickup(socket, player, bulkUpdate, worldName, requestId);
    return;
  }

  const bulkTransactionId = makeAuditId("pickup_bulk");
  const lockedDropEntries: any = [];
  const pickupResults: any = [];
  let inventoryLocks: any = null;
  let successCount = 0;
  let successAmount = 0;
  let latestPickupState: any = null;
  let successWorld: any = cleanWorld(bulkUpdate.world || worldName);
  let worldStateDirty = false;
  let duplicateAckCount = 0;
  const worldUpdates: any = [];
  const rewardEntries: any = [];
  const deltaMap: any = new Map();

  try {
    for (const dropId of bulkUpdate.drop_ids) {
      const singleUpdate: any = { ...bulkUpdate, drop_id: dropId };
      const initialPlan = prepareDropPickup(bulkUpdate.world, player, singleUpdate);
      if (!initialPlan.ok) {
        if (wasDropJustCollectedByPlayer(bulkUpdate.world, dropId, player)) {
          acknowledgeDropAlreadyCollected(socket, player, bulkUpdate.world, dropId);
          duplicateAckCount += 1;
          continue;
        }
        pickupResults.push(makeBulkDropPickupFailure(dropId, initialPlan.reason, getPreparedDropPickupFailureMessage(initialPlan)));
        continue;
      }

      const dropLockKey = `${initialPlan.world}:${initialPlan.dropId}`;
      const dropLock = await acquireLiveActionLock(worldDropActionLocks, "drop", dropLockKey, player.id);
      if (!dropLock.acquired) {
        pickupResults.push(makeBulkDropPickupFailure(dropId, "drop_locked", "That drop is already being picked up."));
        continue;
      }
      lockedDropEntries.push({ dropLock, dropId, singleUpdate });
    }

    if (lockedDropEntries.length === 0) {
      // Every id was a duplicate of a pickup that already succeeded for this
      // player. They have been told the drops are gone; an error on top of that
      // would report a failure that never happened.
      if (duplicateAckCount > 0 && pickupResults.length === 0) return;
      sendActionRejected(socket, "world_item_drop_pickup", "Those drops are not available.", {
        drop_id: bulkUpdate.drop_id,
        drop_ids: bulkUpdate.drop_ids,
        world: bulkUpdate.world,
        pickup_results: pickupResults,
      });
      return;
    }

    inventoryLocks = await acquirePlayerInventoryLocksWithWait([player.account_username], `bulk_drop:${bulkUpdate.world}:${bulkTransactionId}`);
    if (!inventoryLocks.acquired) {
      sendActionRejected(socket, "world_item_drop_pickup", "Inventory is busy. Try again.", {
        drop_id: bulkUpdate.drop_id,
        drop_ids: bulkUpdate.drop_ids,
        world: bulkUpdate.world,
        reason: "inventory_locked",
        blocked_resource: inventoryLocks.blocked_resource || "",
      });
      return;
    }

    const sessionAccount = accounts.get(accountKey(player.account_username)) || {};
    for (const entry of lockedDropEntries) {
      let pickupPlan: any = prepareDropPickup(bulkUpdate.world, player, entry.singleUpdate);
      if (!pickupPlan.ok) {
        if (wasDropJustCollectedByPlayer(bulkUpdate.world, entry.dropId, player)) {
          acknowledgeDropAlreadyCollected(socket, player, bulkUpdate.world, entry.dropId);
          duplicateAckCount += 1;
          continue;
        }
        pickupResults.push(makeBulkDropPickupFailure(entry.dropId, pickupPlan.reason, getPreparedDropPickupFailureMessage(pickupPlan)));
        continue;
      }

      const pickupTransactionId = makeAuditId("pickup");
      const pickedDrop = {
        ...pickupPlan.drop,
        amount: pickupPlan.pickedAmount,
      };
      const worldChange = {
        source_type: "world_item_drop_pickup",
        source_id: pickupTransactionId,
        request_id: requestId,
        world: pickupPlan.world,
        action: "drop_pickup",
        x: pickedDrop.x,
        y: pickedDrop.y,
        block_type: pickedDrop.item_type,
        details: {
          drop_id: pickedDrop.drop_id,
          item_category: pickedDrop.item_category,
          amount: pickedDrop.amount,
          request_id: requestId,
          bulk_request_id: bulkTransactionId,
          remaining: pickupPlan.remaining,
        },
      };
      const persistence = await runOwnedWorldPersistence(
        pickupPlan.world,
        "drop_pickup",
        async (ownership) => postgresStore.applyDropPickupTransaction({
          account_username: player.account_username,
          world: pickupPlan.world,
          drop_id: pickupPlan.dropId,
          item_type: pickupPlan.item_type,
          item_category: pickupPlan.item_category,
          amount: pickupPlan.pickedAmount,
          expected_before_amount: pickupPlan.currentCount,
          expected_drop_before_amount: pickupPlan.dropAmount,
          stack_limit: pickupPlan.stackLimit,
          allow_state_repair: true,
          allow_world_drop_repair: true,
          request_id: requestId || bulkTransactionId,
          source_id: pickupTransactionId,
          drop_x: pickupPlan.drop.x,
          drop_y: pickupPlan.drop.y,
          stack_grid_x: pickupPlan.drop.stack_grid_x,
          stack_grid_y: pickupPlan.drop.stack_grid_y,
          pickup_delay: pickupPlan.drop.pickup_delay,
          drop_amount: pickupPlan.dropAmount,
          // Deliberately no world_state / world_changes here. Passing a snapshot
          // taken before this await made the transaction persist a stale world:
          // any drop another request created meanwhile was missing from it, so
          // mirrorWorldDropsState marked that drop 'removed', and a concurrent
          // block break that bumped the revision first made this save fail with
          // stale_world_revision. The live world is persisted after the batch
          // instead, from state serialized at persist time.
          world_persistence: ownership,
          ip_address: getSocketAddress(socket),
          user_agent: getSocketUserAgent(socket, data),
          session_token_hash: cleanAccountName(sessionAccount.session_token_hash || ""),
          device_info: getSocketDeviceInfo(socket, data),
          at: new Date().toISOString(),
        })
      );
      const postgresPickup = persistence.ok && persistence.value
        ? persistence.value
        : DropContracts.buildPostgresDropPickupFailure({
          reason: persistence.reason || "world_ownership_unverified",
        });

      if (!postgresPickup.ok) {
        // Nothing was mutated in live world state before the transaction, so
        // there is nothing to roll back and no other request's world mutation
        // to clobber. The drop simply stays where it is.
        const postgresPickupReason = DropContracts.getPostgresDropPickupFailureReason(postgresPickup);
        logDropPickupInventoryIssue(postgresPickupReason, player, pickupPlan.world, entry.dropId, pickupPlan, postgresPickup);
        // Only remove the drop when PostgreSQL proved it was actually collected.
        // Any other failure rolled the transaction back with no inventory change, so
        // the drop must survive or the item is destroyed for good.
        if (DropContracts.isPostgresDropPickupCollectedFailure(postgresPickup)) {
          const removal = removeUnavailableDropFromWorldState(pickupPlan.world, pickupPlan.dropId, pickupPlan);
          if (removal.ok && removal.payload) {
            worldUpdates.push({ world: pickupPlan.world, payload: removal.payload });
            worldStateDirty = true;
          }
        }
        pickupResults.push(makeBulkDropPickupFailure(
          entry.dropId,
          postgresPickupReason,
          getPostgresInventoryFailureMessage(postgresPickup, "Could not pick up that item right now.")
        ));
        continue;
      }

      const pickupState = pickupPlan.playerState;
      const inventoryField = getInventoryFieldForCategory(pickupPlan.item_category, pickupPlan.item_type);
      if (!pickupState[inventoryField] || typeof pickupState[inventoryField] !== "object" || Array.isArray(pickupState[inventoryField])) {
        pickupState[inventoryField] = {};
      }
      const committedAfterAmountRaw = Number(postgresPickup.after_amount);
      const committedAfterAmount = Number.isFinite(committedAfterAmountRaw)
        ? clampInteger(committedAfterAmountRaw, 0, pickupPlan.stackLimit)
        : clampInteger(pickupPlan.currentCount + pickupPlan.pickedAmount, 0, pickupPlan.stackLimit);
      pickupState[inventoryField][pickupPlan.item_type] = committedAfterAmount;
      persistPlayerInventoryChange(player.account_username, pickupState, { postgresCommitted: true });

      const committedDropAfterAmountRaw = Number(postgresPickup.drop_after_amount);
      pickupPlan.remaining = Number.isFinite(committedDropAfterAmountRaw)
        ? Math.max(0, Math.trunc(committedDropAfterAmountRaw))
        : pickupPlan.remaining;
      // PostgreSQL committed the inventory and consumed the authoritative drop
      // row, so the live world may now drop it too. Doing this after the commit
      // (like the single-drop route) means a failed pickup never mutates the
      // world and never needs a world-wide rollback.
      const worldApply = applyDropPickupWorldState(pickupPlan.world, pickupPlan);
      const pickupUpdate = worldApply.ok
        ? worldApply.payload
        : removeUnavailableDropFromWorldState(pickupPlan.world, pickupPlan.dropId, pickupPlan).payload || null;
      if (pickupUpdate) {
        worldUpdates.push({ world: pickupPlan.world, payload: pickupUpdate });
      }
      worldStateDirty = true;

      logWorldChange(socket, player, worldChange);
      logItemLedgerForState(socket, player, player.account_username, pickupState, pickedDrop.item_type, pickedDrop.item_category, pickedDrop.amount, "world_item_drop_pickup", pickupTransactionId, "drop_pickup", pickupPlan.world, {
        drop_id: pickedDrop.drop_id,
        bulk_request_id: bulkTransactionId,
      }, { skipPostgres: true });

      addBulkPickupDelta(deltaMap, pickedDrop.item_type, pickedDrop.item_category, pickedDrop.amount);
      rewardEntries.push(InventoryContracts.buildInventoryRewardEntry({
        itemId: pickedDrop.item_type,
        itemCategory: pickedDrop.item_category,
        amount: pickedDrop.amount,
      }));
      pickupResults.push({
        ok: true,
        drop_id: pickedDrop.drop_id,
        item_type: pickedDrop.item_type,
        item_category: pickedDrop.item_category,
        amount: pickedDrop.amount,
        remaining: pickupPlan.remaining,
        remaining_amount: pickupPlan.remaining,
        removed: pickupPlan.remaining <= 0,
        requested_by: player.id,
        requested_by_name: cleanName(player.name),
      });
      successCount += 1;
      successAmount += pickedDrop.amount;
      latestPickupState = pickupState;
      successWorld = pickupPlan.world;
    }

    if (worldStateDirty) {
      // Serialized at persist time from the live world, so drops other requests
      // created while this batch awaited PostgreSQL are included instead of
      // being mirrored away as 'removed'.
      const bulkWorldPersistResult = await persistAuthoritativeWorldState(successWorld, null, "drop_pickup");
      if (!bulkWorldPersistResult.ok) {
        console.warn("[drop_pickup_world_persist_failed]", {
          world: successWorld,
          bulk_request_id: bulkTransactionId,
          drop_ids: bulkUpdate.drop_ids,
          reason: bulkWorldPersistResult.reason || "unknown",
        });
      }
    }

    if (successCount <= 0) {
      if (duplicateAckCount > 0 && pickupResults.length === 0) return;
      sendActionRejected(socket, "world_item_drop_pickup", "Those drops are not available.", {
        drop_id: bulkUpdate.drop_id,
        drop_ids: bulkUpdate.drop_ids,
        world: bulkUpdate.world,
        pickup_results: pickupResults,
      });
      return;
    }

    const inventoryDeltas = buildInventoryDeltaClientPayloads(Array.from<any>(deltaMap.values()), latestPickupState || ensureWritablePlayerState(player.account_username) || {});
    const bulkClientResultPayload = makeBulkDropPickupWorldResultPayload(successWorld, player, bulkUpdate.drop_ids, pickupResults, worldUpdates, successAmount);
    sendInventoryTransactionResult(socket, InventoryContracts.buildDropPickupInventoryTransactionResult({
      ok: true,
      request_id: requestId || bulkTransactionId,
      server_action_id: bulkTransactionId,
      bulk_pickup: true,
      world: successWorld,
      drop_id: pickupResults.find((result: ServerPacketRecord | null) => result && result.ok)?.drop_id || bulkUpdate.drop_id,
      drop_ids: bulkUpdate.drop_ids,
      removed_drop_ids: bulkClientResultPayload.removed_drop_ids || [],
      updated_drops: bulkClientResultPayload.updated_drops || [],
      pickup_results: pickupResults,
      amount: successAmount,
      requested_by: player.id,
      requested_by_name: cleanName(player.name),
      message: `Picked up ${successAmount} items.`,
      username: player.account_username,
      inventory_delta: inventoryDeltas,
      inventory_deltas: inventoryDeltas,
      rewards: rewardEntries,
    }));

    sendBulkDropPickupWorldResult(socket, player, successWorld, bulkUpdate.drop_ids, pickupResults, worldUpdates, successAmount, latestPickupState || undefined);

    debugActionPositionFlow("world_item_drop_pickup bulk request end", player, {
      count: successCount,
      amount: successAmount,
    });
  } finally {
    if (inventoryLocks) releasePlayerInventoryLocks(inventoryLocks);
    for (const entry of lockedDropEntries) {
      if (entry?.dropLock) releaseLiveActionLock(entry.dropLock);
    }
  }
}

/**
 * @param {*} socket
 * @param {PixelMania.RuntimePlayer} player
 * @param {PixelMania.SanitizedBulkDropPickup} bulkUpdate
 * @param {PixelMania.WorldName | string} worldName
 * @param {PixelMania.RequestId | string} requestId
 * @returns {void}
 */
function handleLegacyBulkDropPickup(socket: any, player: any, bulkUpdate: any, worldName: any, requestId: any) {
  const pickupResults: any = [];
  const worldUpdates: any = [];
  const rewardEntries: any = [];
  const deltaMap: any = new Map();
  let successCount: any = 0;
  let successAmount: any = 0;
  let latestPickupState: any = null;
  let successWorld: any = cleanWorld(bulkUpdate.world || worldName);

  for (const dropId of bulkUpdate.drop_ids) {
    const pickupResult = applyDropPickupToWorldState(bulkUpdate.world, { ...bulkUpdate, drop_id: dropId }, player);
    if (!pickupResult.ok) {
      pickupResults.push(makeBulkDropPickupFailure(dropId, pickupResult.reason, getPreparedDropPickupFailureMessage(pickupResult)));
      continue;
    }

    const pickedDrop = pickupResult.drop;
    latestPickupState = pickupResult.playerState;
    successWorld = cleanWorld(bulkUpdate.world || worldName);
    worldUpdates.push({ world: successWorld, payload: pickupResult.update });
    addBulkPickupDelta(deltaMap, pickedDrop.item_type, pickedDrop.item_category, pickedDrop.amount);
    rewardEntries.push(InventoryContracts.buildInventoryRewardEntry({
      itemId: pickedDrop.item_type,
      itemCategory: pickedDrop.item_category,
      amount: pickedDrop.amount,
    }));
    pickupResults.push({
      ok: true,
      drop_id: pickedDrop.drop_id,
      item_type: pickedDrop.item_type,
      item_category: pickedDrop.item_category,
      amount: pickedDrop.amount,
      remaining: pickupResult.remaining,
      remaining_amount: pickupResult.remaining,
      removed: pickupResult.remaining <= 0,
      requested_by: player.id,
      requested_by_name: cleanName(player.name),
    });
    successCount += 1;
    successAmount += pickedDrop.amount;
  }

  if (successCount <= 0) {
    sendActionRejected(socket, "world_item_drop_pickup", "Those drops are not available.", {
      drop_id: bulkUpdate.drop_id,
      drop_ids: bulkUpdate.drop_ids,
      world: bulkUpdate.world,
      pickup_results: pickupResults,
    });
    return;
  }

  persistPlayerInventoryChange(player.account_username, latestPickupState);
  queueWorldSave(successWorld);
  const inventoryDeltas = buildInventoryDeltaClientPayloads(Array.from<any>(deltaMap.values()), latestPickupState);
  const bulkClientResultPayload = makeBulkDropPickupWorldResultPayload(successWorld, player, bulkUpdate.drop_ids, pickupResults, worldUpdates, successAmount);
  sendInventoryTransactionResult(socket, InventoryContracts.buildDropPickupInventoryTransactionResult({
    ok: true,
    request_id: requestId,
    bulk_pickup: true,
    world: successWorld,
    drop_id: pickupResults.find((result: ServerPacketRecord | null) => result && result.ok)?.drop_id || bulkUpdate.drop_id,
    drop_ids: bulkUpdate.drop_ids,
    removed_drop_ids: bulkClientResultPayload.removed_drop_ids || [],
    updated_drops: bulkClientResultPayload.updated_drops || [],
    pickup_results: pickupResults,
    amount: successAmount,
    requested_by: player.id,
    requested_by_name: cleanName(player.name),
    message: `Picked up ${successAmount} items.`,
    username: player.account_username,
    inventory_delta: inventoryDeltas,
    inventory_deltas: inventoryDeltas,
    rewards: rewardEntries,
  }));

  sendBulkDropPickupWorldResult(socket, player, successWorld, bulkUpdate.drop_ids, pickupResults, worldUpdates, successAmount, latestPickupState || undefined);
}


/**
 * @param {PixelMania.WorldName | string} worldName
 * @param {PixelMania.DropPickupWorldResolveInput} update
 * @returns {PixelMania.WorldName}
 */
function resolveDropPickupWorldName(worldName: any, update: any = {}) {
  const fallbackWorld = cleanWorld(worldName || "START");
  const found = findDropForPickup(fallbackWorld, update.drop_id, update.requested_world);
  return cleanWorld(found?.world || fallbackWorld);
}

function sanitizeOptionalDropPickupPosition(data: any, player: any, worldName: any) {
  if (!Object.prototype.hasOwnProperty.call(data, "x") || !Object.prototype.hasOwnProperty.call(data, "y")) {
    return null;
  }

  const position = sanitizePlayerPosition({
    x: data.x,
    y: data.y,
    facing: data.facing,
    world: data.world || worldName,
  }, player);
  if (!position) return null;
  if (cleanWorld(position.world) !== cleanWorld(worldName)) return null;
  return position;
}

/**
 * Development-only tombstones for drops that recently left live world state.
 * They exist so a "That drop is not available." rejection can be classified as
 * never-created / collected / rolled-back / emptied instead of guessed at. They
 * are never authoritative: nothing reads them to decide inventory or ownership.
 */
const dropRemovalTombstones = new Map<string, {
  world: string;
  reason: string;
  at_ms: number;
  collector: string;
  created_at_ms: number;
}>();
const dropCreationTimes = new Map<string, number>();

function pruneDropLifecycleHistory() {
  while (dropRemovalTombstones.size > MAX_DROP_TOMBSTONE_HISTORY) {
    const oldestKey = dropRemovalTombstones.keys().next().value;
    if (oldestKey === undefined) break;
    dropRemovalTombstones.delete(oldestKey);
  }
  while (dropCreationTimes.size > MAX_DROP_TOMBSTONE_HISTORY) {
    const oldestKey = dropCreationTimes.keys().next().value;
    if (oldestKey === undefined) break;
    dropCreationTimes.delete(oldestKey);
  }
}

function recordDropRemovalTombstone(worldName: unknown, dropId: unknown, reason: unknown, collector: unknown = "") {
  const cleanDropId = clampString(dropId || "", MAX_DROP_ID_LENGTH);
  if (cleanDropId === "") return;
  dropRemovalTombstones.delete(cleanDropId);
  dropRemovalTombstones.set(cleanDropId, {
    world: cleanWorld(worldName),
    reason: clampString(reason || "unknown", 64),
    at_ms: Date.now(),
    collector: cleanAccountName(collector || ""),
    created_at_ms: dropCreationTimes.get(cleanDropId) || 0,
  });
  pruneDropLifecycleHistory();
}

function recordDropCreationTime(dropId: unknown) {
  const cleanDropId = clampString(dropId || "", MAX_DROP_ID_LENGTH);
  if (cleanDropId === "") return;
  dropCreationTimes.set(cleanDropId, Date.now());
  dropRemovalTombstones.delete(cleanDropId);
  pruneDropLifecycleHistory();
}

/**
 * Removal reasons that prove the drop actually entered someone's inventory.
 * Anything else (rollback discard, emptied, expired) is NOT a collection and
 * must never be answered as one.
 */
/** Only the fields a duplicate-pickup answer actually reads off the requester. */
type DropPickupRequester = { account_username?: unknown; id?: unknown; name?: unknown } | null | undefined;

const DROP_COLLECTED_TOMBSTONE_REASONS = new Set([
  "picked_up",
  "picked_up_legacy",
  "postgres_reported_collected",
]);

/**
 * True when this exact player collected this exact drop moments ago, i.e. the
 * request is a duplicate of one that already succeeded. Auto-pickup can re-send
 * a drop id before the first response lands, and answering that with a hard
 * "not available" is what players see as a spurious error on a pickup that in
 * fact worked.
 *
 * The tombstone is read ONLY to choose the response. It never grants an item,
 * never moves inventory, and never authorises removing anything: the drop is
 * already gone from authoritative state by the time this can match.
 */
function wasDropJustCollectedByPlayer(worldName: unknown, dropId: unknown, player: DropPickupRequester): boolean {
  const cleanDropId = clampString(dropId || "", MAX_DROP_ID_LENGTH);
  if (cleanDropId === "") return false;

  const tombstone = dropRemovalTombstones.get(cleanDropId);
  if (!tombstone) return false;
  if (!DROP_COLLECTED_TOMBSTONE_REASONS.has(tombstone.reason)) return false;
  if (tombstone.world !== cleanWorld(worldName)) return false;

  const requester = cleanAccountName(player?.account_username || "");
  if (requester === "" || tombstone.collector !== requester) return false;

  return Math.max(0, Date.now() - tombstone.at_ms) <= DUPLICATE_DROP_PICKUP_GRACE_MS;
}

/**
 * Idempotent answer to a duplicate pickup: confirm to the one client that asked
 * that the drop is gone. No error, no inventory change, no broadcast — the rest
 * of the world removed this drop when it was actually collected.
 */
function acknowledgeDropAlreadyCollected(socket: unknown, player: DropPickupRequester, worldName: unknown, dropId: unknown) {
  const cleanWorldName = cleanWorld(worldName);
  const cleanDropId = clampString(dropId || "", MAX_DROP_ID_LENGTH);
  const payload = DropContracts.buildDropPickupRemovePayload({
    world: cleanWorldName,
    dropId: cleanDropId,
    requestedBy: String(player?.id || ""),
    requestedByName: cleanName(player?.name || ""),
    reason: "already_collected",
  });
  sendJson(socket, sanitizeWorldInteractionPayloadForClient(payload, cleanWorldName));
  console.warn("[drop_pickup_duplicate_ack]", {
    username: cleanAccountName(player?.account_username || ""),
    world: cleanWorldName,
    drop_id: cleanDropId,
    collected_ms_ago: Math.max(0, Date.now() - (dropRemovalTombstones.get(cleanDropId)?.at_ms || 0)),
  });
}

/**
 * @param {PixelMania.WorldName | string} worldName
 * @param {PixelMania.RuntimeWorldDropCreateInput} update
 * @returns {void}
 */
function applyDropCreateToWorldState(worldName: any, update: any) {
  const state = ensureWorldState(worldName);
  recordDropCreationTime(update.drop_id);
  state.drops.set(update.drop_id, {
    drop_id: update.drop_id,
    item_type: update.item_type,
    item_category: update.item_category,
    is_seed: update.is_seed,
    amount: update.amount,
    x: update.x,
    y: update.y,
    stack_grid_x: Number.isFinite(Number(update.stack_grid_x)) ? Math.trunc(Number(update.stack_grid_x)) : undefined,
    stack_grid_y: Number.isFinite(Number(update.stack_grid_y)) ? Math.trunc(Number(update.stack_grid_y)) : undefined,
    pickup_delay: update.pickup_delay,
  });
}

/**
 * @param {PixelMania.WorldName | string} worldName
 * @param {PixelMania.RuntimeWorldDropUpdateInput} update
 * @returns {void}
 */
function applyDropUpdateToWorldState(worldName: any, update: any) {
  const state = ensureWorldState(worldName);
  const drop = state.drops.get(update.drop_id);
  if (!drop) return;

  if (Object.prototype.hasOwnProperty.call(update, "amount")) {
    if (update.amount <= 0) {
      state.drops.delete(update.drop_id);
      recordDropRemovalTombstone(worldName, update.drop_id, "drop_update_emptied");
      return;
    }
    drop.amount = Math.min(update.amount, drop.amount);
  }

  if (
    Object.prototype.hasOwnProperty.call(update, "x") &&
    Object.prototype.hasOwnProperty.call(update, "y")
  ) {
    drop.x = update.x;
    drop.y = update.y;
  }
}

/**
 * @param {PixelMania.WorldName | string} worldName
 * @param {PixelMania.SanitizedDropPickup | PixelMania.SanitizedBulkDropPickup | PixelMania.DropPickupUpdateInput} update
 * @param {PixelMania.RuntimePlayer} player
 * @returns {PixelMania.LegacyDropPickupResult}
 */
function applyDropPickupToWorldState(worldName: any, update: any, player: any) {
  const found = findDropForPickup(worldName, update.drop_id);
  const state = found.state;
  const drop = found.drop;
  const authoritativeDropId = found.publicDropId;
  const dropStateKey = found.key;
  if (!drop) return DropContracts.buildDropPickupFailure({ reason: "not_available" });
  const validationPosition = getPlayerValidationPosition(player, {
    action: "world_item_drop_pickup",
    world: cleanWorld(worldName),
  });
  const pickupPosition = validationPosition.ok ? validationPosition : player;
  if (!isPositionNearDrop(pickupPosition, drop)) return DropContracts.buildDropPickupFailure({ reason: "too_far", drop });

  const itemId = clampString(drop.item_type || "");
  if (!ItemDatabase.hasItem(itemId)) return DropContracts.buildDropPickupFailure({ reason: "not_available" });
  const itemCategory = resolveInventoryCategory(itemId, drop.item_category || "");
  if (!ItemDatabase.canStoreItemInCategory(itemId, itemCategory)) return DropContracts.buildDropPickupFailure({ reason: "not_available" });

  const playerState = ensureWritablePlayerState(player.account_username);
  if (!playerState) return DropContracts.buildDropPickupFailure({ reason: "inventory_unavailable" });

  const stackLimit = ItemDatabase.getStackLimit(itemId);
  const dropAmount = clampInteger(drop.amount || 0, 0, Math.min(MAX_DROP_TILE_AMOUNT, stackLimit));
  if (dropAmount <= 0) {
    state.drops.delete(dropStateKey);
    recordDropRemovalTombstone(worldName, authoritativeDropId || dropStateKey, "empty_drop");
    return DropContracts.buildDropPickupFailure({ reason: "not_available" });
  }

  const currentCount = getInventoryCount(playerState, itemId, itemCategory);
  const availableSpace = Math.max(0, stackLimit - currentCount);
  if (availableSpace <= 0) return DropContracts.buildDropPickupFailure({ reason: "inventory_full", drop });

  const pickedAmount = Math.min(dropAmount, availableSpace);
  const remaining = Math.max(0, dropAmount - pickedAmount);
  const pickedDrop: any = {
    ...drop,
    drop_id: authoritativeDropId,
    item_type: itemId,
    item_category: itemCategory,
    amount: pickedAmount,
  };

  const addResult = addItemToState(playerState, itemId, itemCategory, pickedAmount);
  if (!addResult) return DropContracts.buildDropPickupFailure({ reason: "inventory_unavailable", drop });

  playerState.saved_at = new Date().toISOString();
  setPlayerState(player.account_username, playerState);
  queuePlayerSave(player.account_username);

  let pickupUpdate;
  if (remaining <= 0) {
    state.drops.delete(dropStateKey);
    recordDropRemovalTombstone(worldName, authoritativeDropId || dropStateKey, "picked_up_legacy", player?.account_username || player?.name || "");
    pickupUpdate = DropContracts.buildDropPickupRemovePayload({
      world: cleanWorld(worldName),
      dropId: authoritativeDropId,
      requestedBy: player.id,
      requestedByName: cleanName(player.name),
    });
  } else {
    drop.amount = remaining;
    pickupUpdate = DropContracts.buildDropPickupUpdatePayload({
      world: cleanWorld(worldName),
      dropId: authoritativeDropId,
      itemType: itemId,
      itemCategory,
      amount: remaining,
      remaining,
      requestedBy: player.id,
      requestedByName: cleanName(player.name),
    });
  }

  return DropContracts.buildLegacyDropPickupSuccess({
    drop: pickedDrop,
    playerState,
    update: pickupUpdate,
    remaining,
  });
}

/**
 * @param {PixelMania.WorldName | string} worldName
 * @param {PixelMania.RuntimePlayer} player
 * @param {PixelMania.SanitizedDropPickup | PixelMania.SanitizedBulkDropPickup | PixelMania.DropPickupUpdateInput} update
 * @returns {PixelMania.PreparedDropPickupResult}
 */
function prepareDropPickup(worldName: any, player: any, update: any) {
  const found = findDropForPickup(worldName, update.drop_id, update.requested_world);
  if (!found.drop) return DropContracts.buildDropPickupFailure({ reason: "not_available" });

  const drop = found.drop;
  const dropId = found.publicDropId;
  const dropStateKey = found.key;
  const cleanWorldName = cleanWorld(found.world || worldName);
  const sessionWorldName = getPlayerCurrentWorldName(player);
  if (sessionWorldName !== cleanWorldName && !usesTrustedMovementPosition(player)) {
    return DropContracts.buildDropPickupFailure({
      reason: "wrong_world",
      drop,
      world: cleanWorldName,
      current_world: sessionWorldName,
      requested_world: update.requested_world || "",
    });
  }
  const validationPosition = getPlayerValidationPosition(player, {
    action: "world_item_drop_pickup",
    world: cleanWorldName,
  });
  if (!validationPosition.ok) {
    return DropContracts.buildDropPickupFailure({
      reason: "position_unavailable",
      position: validationPosition,
      drop,
      world: cleanWorldName,
    });
  }
  if (!isPositionNearDrop(validationPosition, drop)) {
    return DropContracts.buildDropPickupFailure({
      reason: "too_far",
      drop,
      world: cleanWorldName,
      validationPosition,
    });
  }

  const itemType = clampString(drop.item_type || "");
  if (!ItemDatabase.hasItem(itemType)) return DropContracts.buildDropPickupFailure({ reason: "not_available", drop, world: cleanWorldName });
  const itemCategory = resolveInventoryCategory(itemType, drop.item_category || "");
  if (!ItemDatabase.canStoreItemInCategory(itemType, itemCategory)) return DropContracts.buildDropPickupFailure({ reason: "not_available", drop, world: cleanWorldName });

  const playerState = ensureWritablePlayerState(player.account_username);
  if (!playerState) return DropContracts.buildDropPickupFailure({ reason: "inventory_unavailable", drop, world: cleanWorldName });

  const stackLimit = ItemDatabase.getStackLimit(itemType);
  const dropAmount = clampInteger(drop.amount || 0, 0, MAX_DROP_TILE_AMOUNT);
  if (dropAmount <= 0) return DropContracts.buildDropPickupFailure({ reason: "not_available", world: cleanWorldName });

  const currentCount = getInventoryCount(playerState, itemType, itemCategory);
  const availableSpace = Math.max(0, stackLimit - currentCount);
  if (availableSpace <= 0) {
    return DropContracts.buildDropPickupFailure({
      reason: "inventory_full",
      drop,
      world: cleanWorldName,
      item_type: itemType,
      item_category: itemCategory,
      stackLimit,
      currentCount,
      availableSpace,
      dropAmount,
    });
  }

  const pickedAmount = Math.min(dropAmount, availableSpace);
  if (pickedAmount <= 0) {
    return DropContracts.buildDropPickupFailure({
      reason: "inventory_full",
      drop,
      world: cleanWorldName,
      item_type: itemType,
      item_category: itemCategory,
      stackLimit,
      currentCount,
      availableSpace,
      dropAmount,
      pickedAmount,
    });
  }

  return DropContracts.buildPreparedDropPickupPlan({
    player: player,
    world: cleanWorldName,
    dropId,
    dropStateKey,
    drop: {
      ...drop,
      drop_id: dropId,
      item_type: itemType,
      item_category: itemCategory,
    },
    playerState,
    item_type: itemType,
    item_category: itemCategory,
    validationPosition,
    dropAmount,
    pickedAmount,
    stackLimit,
    currentCount,
    availableSpace,
    remaining: Math.max(0, dropAmount - pickedAmount),
  });
}

/**
 * @param {PixelMania.WorldName | string} worldName
 * @param {PixelMania.PreparedDropPickupPlan | null | undefined} pickupPlan
 * @returns {PixelMania.DropPickupWorldApplyResult}
 */
function applyDropPickupWorldState(worldName: any, pickupPlan: any) {
  if (!pickupPlan) return DropContracts.buildDropPickupWorldApplyFailure("not_available");
  const state = ensureWorldState(worldName);
  const dropId = clampString(pickupPlan.dropId || "", MAX_DROP_ID_LENGTH);
  const targetDropId = clampString(pickupPlan.drop?.drop_id || dropId, MAX_DROP_ID_LENGTH);
  let dropStateKey: any = clampString(pickupPlan.dropStateKey || "", MAX_DROP_ID_LENGTH);
  let drop: any = null;

  if (dropStateKey && state.drops.has(dropStateKey)) {
    drop = state.drops.get(dropStateKey);
  } else {
    for (const [candidateKey, candidateDrop] of state.drops.entries()) {
      const candidateDropId = clampString(candidateDrop?.drop_id || candidateKey || "", MAX_DROP_ID_LENGTH);
      if (candidateDropId === targetDropId) {
        drop = candidateDrop;
        dropStateKey = candidateKey;
        break;
      }
    }
  }

  if (!drop) {
    const found = findDropForPickup(worldName, dropId);
    if (found && found.drop) {
      drop = found.drop;
      dropStateKey = found.key;
    }
  }

  if (!drop || !dropStateKey) {
    return DropContracts.buildDropPickupWorldApplyFailure("not_available");
  }

  if (pickupPlan.remaining <= 0) {
    for (const [candidateKey, candidateDrop] of state.drops.entries()) {
      if (candidateKey === dropStateKey || candidateDrop === drop || clampString(candidateDrop?.drop_id || "", MAX_DROP_ID_LENGTH) === dropId) {
        state.drops.delete(candidateKey);
        recordDropRemovalTombstone(worldName, candidateDrop?.drop_id || candidateKey, "picked_up", pickupPlan.player?.account_username || pickupPlan.player?.name || "");
      }
    }
    return DropContracts.buildDropPickupWorldApplySuccess(DropContracts.buildDropPickupRemovePayload({
      world: cleanWorld(worldName),
      dropId,
      requestedBy: pickupPlan.player?.id || "",
      requestedByName: cleanName(pickupPlan.player?.name || ""),
    }));
  }

  const remainingAmount = Math.max(0, Number(pickupPlan.remaining) || 0);
  if (!state.drops.has(dropStateKey)) {
    return DropContracts.buildDropPickupWorldApplyFailure("not_available");
  }
  drop.amount = remainingAmount;

  return DropContracts.buildDropPickupWorldApplySuccess(DropContracts.buildDropPickupUpdatePayload({
    world: cleanWorld(worldName),
    dropId,
    itemType: pickupPlan.item_type,
    itemCategory: pickupPlan.item_category,
    amount: Math.max(0, Number(drop.amount || 0)),
    remaining: pickupPlan.remaining,
    requestedBy: pickupPlan.player?.id || "",
    requestedByName: cleanName(pickupPlan.player?.name || ""),
  }));
}

/**
 * @param {PixelMania.WorldName | string} worldName
 * @param {string} dropId
 * @param {PixelMania.PreparedDropPickupPlan | null} pickupPlan
 * @returns {PixelMania.DropPickupWorldApplyResult}
 */
function removeUnavailableDropFromWorldState(worldName: any, dropId: any, pickupPlan: any = null) {
  const cleanWorldName = cleanWorld(worldName);
  const state = ensureWorldState(cleanWorldName);
  const cleanDropId = clampString(dropId || pickupPlan?.dropId || pickupPlan?.drop?.drop_id || "", MAX_DROP_ID_LENGTH);
  const targetDropId = clampString(pickupPlan?.drop?.drop_id || cleanDropId, MAX_DROP_ID_LENGTH);
  const dropStateKey = clampString(pickupPlan?.dropStateKey || "", MAX_DROP_ID_LENGTH);
  let removed: any = false;

  for (const [candidateKey, candidateDrop] of Array.from<any>(state.drops.entries())) {
    const candidateDropId = clampString(candidateDrop?.drop_id || candidateKey || "", MAX_DROP_ID_LENGTH);
    if (
      candidateKey === dropStateKey ||
      candidateKey === cleanDropId ||
      candidateDropId === cleanDropId ||
      candidateDropId === targetDropId
    ) {
      state.drops.delete(candidateKey);
      recordDropRemovalTombstone(cleanWorldName, candidateDropId || candidateKey, "postgres_reported_collected", pickupPlan?.player?.account_username || pickupPlan?.player?.name || "");
      removed = true;
    }
  }

  if (!removed) return DropContracts.buildDropPickupWorldApplyFailure("not_available");
  return DropContracts.buildDropPickupWorldApplySuccess(DropContracts.buildDropPickupRemovePayload({
    world: cleanWorldName,
    dropId: cleanDropId || targetDropId,
    requestedBy: pickupPlan?.player?.id || "",
    requestedByName: cleanName(pickupPlan?.player?.name || ""),
    reason: "server_drop_unavailable",
  }));
}

/**
 * @param {PixelMania.WorldName | string} worldName
 * @param {string} dropId
 * @param {PixelMania.WorldName | string} requestedWorldName
 * @returns {PixelMania.DropPickupWorldLookupResult}
 */
function findDropForPickup(worldName: any, dropId: any, requestedWorldName: any = "") {
  const cleanWorldName = cleanWorld(worldName);
  const cleanDropId = clampString(dropId || "", MAX_DROP_ID_LENGTH);
  const searchedWorlds: any = new Set();

  const findInWorld = (candidateWorldName: unknown) => {
    const cleanCandidateWorld = cleanWorld(candidateWorldName);
    if (searchedWorlds.has(cleanCandidateWorld)) return null;
    searchedWorlds.add(cleanCandidateWorld);
    const state = ensureWorldState(cleanCandidateWorld);

    if (state.drops.has(cleanDropId)) {
      return {
        state,
        drop: state.drops.get(cleanDropId),
        key: cleanDropId,
        publicDropId: cleanDropId,
        world: cleanCandidateWorld,
      };
    }

    for (const [candidateId, candidateDrop] of state.drops.entries()) {
      const candidateDropId = clampString(candidateDrop?.drop_id || candidateId || "", MAX_DROP_ID_LENGTH);
      if (candidateDropId === cleanDropId) {
        return {
          state,
          drop: candidateDrop,
          key: candidateId,
          publicDropId: candidateDropId,
          world: cleanCandidateWorld,
        };
      }
    }

    return null;
  };

  const primary = findInWorld(cleanWorldName);
  if (primary) return primary;

  const hasRequestedWorld = String(requestedWorldName || "").trim() !== "";
  const cleanRequestedWorld = hasRequestedWorld ? cleanWorld(requestedWorldName) : "";
  if (hasRequestedWorld && cleanRequestedWorld !== cleanWorldName) {
    const requested = findInWorld(cleanRequestedWorld);
    if (requested) return requested;
  }

  for (const candidateWorldName of worldStates.keys()) {
    const loaded = findInWorld(candidateWorldName);
    if (loaded) return loaded;
  }

  return {
    state: ensureWorldState(cleanWorldName),
    drop: null,
    key: cleanDropId,
    publicDropId: cleanDropId,
    world: cleanWorldName,
  };
}

function logDropPickupNotAvailable(player: any, worldName: any, dropId: any) {
  const cleanWorldName = cleanWorld(worldName);
  const state = ensureWorldState(cleanWorldName);
  const cleanDropId = clampString(dropId || "", MAX_DROP_ID_LENGTH);
  const loadedWorldsWithDrop: any = [];
  for (const [loadedWorldName, loadedState] of worldStates.entries()) {
    if (!loadedState || !loadedState.drops) continue;
    if (loadedState.drops.has(cleanDropId)) {
      loadedWorldsWithDrop.push(loadedWorldName);
      continue;
    }
    for (const [candidateId, candidateDrop] of loadedState.drops.entries()) {
      const candidateDropId = clampString(candidateDrop?.drop_id || candidateId || "", MAX_DROP_ID_LENGTH);
      if (candidateDropId === cleanDropId) {
        loadedWorldsWithDrop.push(loadedWorldName);
        break;
      }
    }
  }
  const tombstone = dropRemovalTombstones.get(cleanDropId) || null;
  const createdAtMs = dropCreationTimes.get(cleanDropId) || tombstone?.created_at_ms || 0;
  const nowMs = Date.now();
  console.warn("[drop_pickup_missing]", {
    username: cleanAccountName(player?.account_username || player?.name || ""),
    current_world: cleanWorldName,
    player_world: cleanWorld(player?.world || "START"),
    server_instance: SERVER_INSTANCE_ID,
    requested_drop_id: cleanDropId,
    world_drop_count: state.drops.size,
    has_drop_key: state.drops.has(cleanDropId),
    loaded_worlds_with_drop: loadedWorldsWithDrop,
    // Classifies the miss: never created here / removed and why / how long the
    // drop lived before the request arrived.
    known_created: createdAtMs > 0,
    age_at_request_ms: createdAtMs > 0 ? Math.max(0, nowMs - createdAtMs) : null,
    removal_reason: tombstone?.reason || (createdAtMs > 0 ? "still_created_never_removed" : "never_created_on_this_instance"),
    removal_world: tombstone?.world || "",
    removed_ms_ago: tombstone ? Math.max(0, nowMs - tombstone.at_ms) : null,
    removal_collector: tombstone?.collector || "",
  });
}

function logDropPickupTooFar(player: any, worldName: any, dropId: any, drop: any, update: any = {}) {
  const actionPosition = update?.action_position || null;
  const validationPosition = update?.validation_position || update?.validationPosition || null;
  const sourcePosition = validationPosition && validationPosition.ok === true ? validationPosition : player;
  const dropPosition = getDropPublicPosition(drop) || {
    x: Number(drop?.x || 0),
    y: Number(drop?.y || 0),
  };
  console.warn("[drop_pickup_too_far]", {
    username: cleanAccountName(player?.account_username || player?.name || ""),
    current_world: cleanWorld(worldName),
    requested_drop_id: clampString(dropId || "", MAX_DROP_ID_LENGTH),
    player_x: Number(sourcePosition?.x || 0),
    player_y: Number(sourcePosition?.y || 0),
    player_position_source: clampString(sourcePosition?.source || (sourcePosition === player ? "player" : "")),
    trusted_age_ms: Number.isFinite(Number(sourcePosition?.age_ms)) ? Math.max(0, Math.trunc(Number(sourcePosition.age_ms))) : null,
    drop_x: Number(drop?.x || 0),
    drop_y: Number(drop?.y || 0),
    public_drop_x: dropPosition.x,
    public_drop_y: dropPosition.y,
    stack_grid_x: Number.isFinite(Number(drop?.stack_grid_x)) ? Math.trunc(Number(drop.stack_grid_x)) : null,
    stack_grid_y: Number.isFinite(Number(drop?.stack_grid_y)) ? Math.trunc(Number(drop.stack_grid_y)) : null,
    distance: Math.hypot(Number(sourcePosition?.x || 0) - dropPosition.x, Number(sourcePosition?.y || 0) - dropPosition.y),
    max_distance: MAX_PICKUP_DISTANCE_PIXELS,
    action_x: actionPosition ? Number(actionPosition.x || 0) : null,
    action_y: actionPosition ? Number(actionPosition.y || 0) : null,
  });
}

function logDropPickupInventoryIssue(reason: any, player: any, worldName: any, dropId: any, pickupPlan: any = {}, transaction: any = {}) {
  console.warn("[drop_pickup_inventory_issue]", {
    reason: cleanName(reason),
    username: cleanAccountName(player?.account_username || player?.name || ""),
    current_world: cleanWorld(worldName),
    requested_drop_id: clampString(dropId || "", MAX_DROP_ID_LENGTH),
    item_type: cleanName(pickupPlan?.item_type || transaction?.item_type || ""),
    item_category: cleanName(pickupPlan?.item_category || transaction?.item_category || ""),
    stack_limit: Number(pickupPlan?.stackLimit || transaction?.stack_limit || 0),
    current_count: Number(pickupPlan?.currentCount || 0),
    available_space: Number(pickupPlan?.availableSpace || 0),
    picked_amount: Number(pickupPlan?.pickedAmount || 0),
    drop_amount: Number(pickupPlan?.dropAmount || 0),
    before_amount: Number(transaction?.before_amount || 0),
    after_amount: Number(transaction?.after_amount || 0),
    transaction_reason: cleanName(transaction?.reason || ""),
    transaction_message: cleanName(transaction?.message || ""),
  });
}

function isPositionNearDrop(position: any, drop: any) {
  if (!position || !drop) return false;
  const playerX = Number(position.x);
  const playerY = Number(position.y);
  if (!Number.isFinite(playerX) || !Number.isFinite(playerY)) return false;
  const dropPosition = getDropPublicPosition(drop);
  if (!dropPosition) return false;

  return Math.hypot(playerX - dropPosition.x, playerY - dropPosition.y) <= MAX_PICKUP_DISTANCE_PIXELS;
}

function getForegroundNetworkPriority(entry: any) {
  return clampString(entry?.block_type || "") === ENTRANCE_GATE_TYPE ? 0 : 1;
}

function addAtlasItemIdToBlockEntry(entry: any) {
  if (!entry || typeof entry !== "object" || Array.isArray(entry)) return entry;
  const blockType = clampString(entry.block_type || "");
  const itemId = Math.max(0, Math.trunc(Number(entry.item_id) || ItemAtlasDB.getItemIdForKey(blockType) || 0));
  if (itemId > 0) {
    entry.item_id = itemId;
  }
  return entry;
}

function getForegroundBlocksForMap(blockMap: any, state: any, worldName: any = "") {
  const blocks: any = [];

  for (const block of blockMap.values()) {
    const entry: any = { ...block };
    addAtlasItemIdToBlockEntry(entry);
    const interaction = state.interactions.get(gridKey(block.x, block.y));
    const blockType = clampString(entry.block_type || "");
    if (!isDoorBlockType(blockType)) {
      delete entry.door_id;
      delete entry.door_name;
      delete entry.name;
      delete entry.door_destination;
      delete entry.door_target_world;
      delete entry.door_target_id;
      delete entry.door_password;
      delete entry.door_password_configured;
    }

    if (interaction && interaction.action === "wooden_entrance_state" && isEntranceBlockType(blockType)) {
      entry.entrance_locked = Boolean(interaction.locked);
    } else if (interaction && interaction.action === "door_state" && isEntranceBlockType(blockType)) {
      entry.entrance_locked = Boolean(interaction.locked);
    } else if (interaction && interaction.action === "door_state" && isDoorBlockType(blockType)) {
      entry.entrance_locked = Boolean(interaction.locked);
      entry.door_id = cleanDoorId(interaction.door_id || "");
      entry.door_name = cleanDoorName(interaction.door_name || interaction.name || block.door_name || block.name || "");
      entry.door_destination = cleanDoorDestination(interaction.destination || interaction.door_destination || "");
      entry.door_target_world = cleanWorld(interaction.target_world || interaction.door_target_world || worldName);
      entry.door_target_id = cleanDoorId(interaction.target_door_id || interaction.door_target_id || "");
      delete entry.door_password;
      if (isPasswordDoorBlockType(blockType)) {
        entry.door_password_configured = cleanDoorPassword(interaction.password || interaction.door_password || block.door_password || "") !== "";
      } else {
        delete entry.door_password_configured;
      }
    } else if (interaction && interaction.action === "sign_text" && isSignBlockType(blockType)) {
      entry.sign_text = String(interaction.text || "");
    } else if (interaction && interaction.action === "ceiling_lamp_state" && isToggleBlockType(blockType)) {
      entry.toggle_on = Boolean(interaction.on);
    }

    blocks.push(entry);
  }

  blocks.sort((a: ServerPacketRecord, b: ServerPacketRecord) => getForegroundNetworkPriority(a) - getForegroundNetworkPriority(b));
  return blocks;
}

function getForegroundBlocksForState(state: any, worldName: any = "") {
  return getForegroundBlocksForMap(state.foreground, state, worldName);
}

function getEffectiveForegroundBlocksForState(state: any, worldName: any = "", generatedMap: any = null) {
  return getForegroundBlocksForMap(buildEffectiveForegroundMap(worldName, state, generatedMap), state, worldName);
}

function getEffectiveBackgroundBlocksForState(state: any, worldName: any = "", generatedMap: any = null) {
  return Array.from<any>(buildEffectiveBackgroundMap(worldName, state, generatedMap).values())
    .map((entry) => addAtlasItemIdToBlockEntry({ ...entry }));
}

function getBearerTokenFromRequest(request: any) {
  const rawHeader = String(request?.headers?.authorization || request?.headers?.Authorization || "").trim();
  if (rawHeader.toLowerCase().startsWith("bearer ")) {
    return rawHeader.slice(7).trim();
  }

  return String(
    request?.headers?.["x-netfox-server-token"] ||
    request?.headers?.["x-pixelmania-netfox-server-token"] ||
    ""
  ).trim();
}

function getNetfoxSpawnTicketSecret() {
  if (NETFOX_SPAWN_TICKET_SECRET !== "") return NETFOX_SPAWN_TICKET_SECRET;
  if (NETFOX_SERVER_WORLD_STATE_TOKEN !== "") return NETFOX_SERVER_WORLD_STATE_TOKEN;
  if (/^[a-f0-9]{64}$/i.test(NETFOX_SERVER_WORLD_STATE_TOKEN_HASH)) return NETFOX_SERVER_WORLD_STATE_TOKEN_HASH;
  return "";
}

function isNetfoxSpawnTicketConfigured() {
  return getNetfoxSpawnTicketSecret() !== "";
}

function base64UrlEncode(value: any) {
  const buffer = Buffer.isBuffer(value) ? value : Buffer.from(String(value), "utf8");
  return buffer.toString("base64").replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/g, "");
}

function base64UrlDecodeToString(value: any) {
  const clean = String(value || "").replace(/-/g, "+").replace(/_/g, "/");
  if (!/^[A-Za-z0-9+/]*={0,2}$/.test(clean)) return "";
  const padded = clean.padEnd(clean.length + ((4 - (clean.length % 4)) % 4), "=");
  return Buffer.from(padded, "base64").toString("utf8");
}

function signNetfoxSpawnTicketPayload(encodedPayload: any) {
  const secret = getNetfoxSpawnTicketSecret();
  if (secret === "") return "";
  return base64UrlEncode(crypto.createHmac("sha256", secret).update(String(encodedPayload || "")).digest());
}

/**
 * @param {Record<string, unknown>} payload
 * @returns {string}
 */
function makeNetfoxSpawnTicket(payload: any) {
  if (!payload || typeof payload !== "object" || Array.isArray(payload)) return "";
  const encodedPayload = base64UrlEncode(JSON.stringify(payload));
  const signature = signNetfoxSpawnTicketPayload(encodedPayload);
  if (signature === "") return "";
  return `pmnt1.${encodedPayload}.${signature}`;
}

/**
 * @param {string} ticket
 * @returns {PixelMania.NetfoxSpawnTicketParseResult}
 */
function parseNetfoxSpawnTicket(ticket: any) {
  const cleanTicket = String(ticket || "").trim();
  const parts = cleanTicket.split(".");
  if (parts.length !== 3 || parts[0] !== "pmnt1") {
    return { ok: false, reason: "spawn_ticket_malformed", error: "Malformed Netfox spawn ticket.", status: 400 };
  }

  const expectedSignature = signNetfoxSpawnTicketPayload(parts[1]);
  if (expectedSignature === "" || !safeTimingEqualString(parts[2], expectedSignature)) {
    return { ok: false, reason: "spawn_ticket_bad_signature", error: "Netfox spawn ticket signature is invalid.", status: 401 };
  }

  try {
    const payloadText = base64UrlDecodeToString(parts[1]);
    const payload = JSON.parse(payloadText);
    if (!payload || typeof payload !== "object" || Array.isArray(payload)) {
      return { ok: false, reason: "spawn_ticket_invalid_payload", error: "Netfox spawn ticket payload is invalid.", status: 400 };
    }
    return { ok: true, payload };
  } catch (_error) {
    return { ok: false, reason: "spawn_ticket_invalid_json", error: "Netfox spawn ticket payload is not valid JSON.", status: 400 };
  }
}

/**
 * @param {PixelMania.RuntimePlayer | null | undefined} player
 * @param {PixelMania.WorldName | string} worldName
 * @param {Record<string, unknown>} overrides
 * @returns {PixelMania.NetfoxTicketIdentity}
 */
function getNetfoxTicketIdentityFromPlayer(player: any, worldName: any, overrides: any = {}) {
  const cleanWorldName = cleanWorld(worldName || getPlayerCurrentWorldName(player));
  const username = cleanAccountName(player?.account_username || player?.name || "");
  const websocketPlayerId = clampString(overrides.websocket_player_id || player?.id || "", 96);
  const gamePlayerId = clampString(player?.profile_id || player?.account_id || username || websocketPlayerId, 96);

  return {
    world: cleanWorldName,
    world_id: cleanWorldName,
    username,
    account_username: username,
    display_name: username || "Player",
    websocket_player_id: websocketPlayerId,
    game_player_id: gamePlayerId,
    account_id: clampString(player?.account_id || "", 96),
    profile_id: clampString(player?.profile_id || "", 96),
  };
}

function pruneExpiredNetfoxMovementRoutes(now: any = Date.now()) {
  for (const [worldName, route] of netfoxMovementRoutes.entries()) {
    if (!route || Number(route.expires_at_ms || 0) <= now) {
      netfoxMovementRoutes.delete(worldName);
    }
  }
}

function sanitizeNetfoxRouteHost(value: any) {
  return String(value || "").trim().slice(0, 255);
}

function sanitizeNetfoxRoutePort(value: any, fallback: any = NETFOX_MOVEMENT_PUBLIC_PORT) {
  return Math.max(1, Math.min(65535, Math.trunc(Number(value) || fallback)));
}

/**
 * @param {PixelMania.NetfoxMovementRoute | Record<string, unknown> | null | undefined} route
 * @param {PixelMania.WorldName | string} worldName
 * @returns {PixelMania.NetfoxMovementRoute | null}
 */
function normalizeNetfoxMovementRouteForBackend(route: any, worldName: any) {
  if (!route || typeof route !== "object" || Array.isArray(route)) return null;

  const cleanWorldName = cleanWorld(worldName || route.world || route.world_id || "START");
  const host = sanitizeNetfoxRouteHost(route.host || route.public_host || "");
  if (host === "") return null;

  const port = sanitizeNetfoxRoutePort(route.port || route.public_port || NETFOX_MOVEMENT_PUBLIC_PORT);
  const maxClients = Math.max(1, Math.min(512, Math.trunc(Number(route.max_clients || route.maxClients) || NETFOX_MOVEMENT_MAX_CLIENTS)));
  const registeredAtMs = Math.trunc(Number(route.registered_at_ms || 0));
  const expiresAtMs = Math.trunc(Number(route.expires_at_ms || 0));

  return {
    ...route,
    world: cleanWorldName,
    world_id: cleanWorldName,
    host,
    port,
    max_clients: maxClients,
    server_instance_id: clampString(route.server_instance_id || route.instance_id || SERVER_INSTANCE_ID, 128),
    registered_at_ms: registeredAtMs,
    registered_at: route.registered_at || (registeredAtMs > 0 ? new Date(registeredAtMs).toISOString() : ""),
    expires_at_ms: expiresAtMs,
    expires_at: route.expires_at || (expiresAtMs > 0 ? new Date(expiresAtMs).toISOString() : ""),
    source: clampString(route.source || "registered", 64),
  };
}

/**
 * @param {Record<string, unknown>} routePayload
 * @returns {Promise<PixelMania.NetfoxMovementRoute>}
 */
async function registerNetfoxMovementRoute(routePayload: any = {}) {
  const worldName = cleanWorld(routePayload.world || routePayload.world_id || "START");
  const host = sanitizeNetfoxRouteHost(routePayload.host || routePayload.public_host || NETFOX_MOVEMENT_PUBLIC_HOST);
  const port = sanitizeNetfoxRoutePort(routePayload.port || routePayload.public_port || NETFOX_MOVEMENT_PUBLIC_PORT);
  const maxClients = Math.max(1, Math.min(512, Math.trunc(Number(routePayload.max_clients || routePayload.maxClients) || NETFOX_MOVEMENT_MAX_CLIENTS)));
  const now = Date.now();
  const route: any = {
    world: worldName,
    world_id: worldName,
    host,
    port,
    max_clients: maxClients,
    server_instance_id: clampString(routePayload.server_instance_id || routePayload.instance_id || SERVER_INSTANCE_ID, 128),
    registered_at_ms: now,
    registered_at: new Date(now).toISOString(),
    expires_at_ms: now + NETFOX_MOVEMENT_ROUTE_TTL_MS,
    expires_at: new Date(now + NETFOX_MOVEMENT_ROUTE_TTL_MS).toISOString(),
    source: "registered",
  };

  netfoxMovementRoutes.set(worldName, route);
  const redisResult = await redisStore.setNetfoxMovementRoute(worldName, route, NETFOX_MOVEMENT_ROUTE_TTL_MS);
  if (redisResult && !redisResult.ok && !redisResult.fallback) {
    console.warn("[NetfoxReal] Netfox movement route Redis registration rejected.", {
      world: worldName,
      reason: redisResult.reason || "unknown",
    });
  }
  return route;
}

/**
 * @param {PixelMania.WorldName | string} worldName
 * @returns {Promise<PixelMania.NetfoxMovementRoute | null>}
 */
async function getNetfoxMovementRouteForWorld(worldName: any) {
  const cleanWorldName = cleanWorld(worldName || "START");
  pruneExpiredNetfoxMovementRoutes();
  const registered = netfoxMovementRoutes.get(cleanWorldName);
  if (registered) {
    return { ...registered };
  }

  const redisResult = await redisStore.getNetfoxMovementRoute(cleanWorldName);
  if (redisResult && redisResult.ok && redisResult.route) {
    const redisRoute = normalizeNetfoxMovementRouteForBackend(redisResult.route, cleanWorldName);
    if (redisRoute) {
      const expiresAtMs = Math.trunc(Number(redisRoute.expires_at_ms || 0));
      if (expiresAtMs > 0 && expiresAtMs <= Date.now()) {
        netfoxMovementRoutes.delete(cleanWorldName);
        await redisStore.deleteNetfoxMovementRoute(cleanWorldName);
      } else {
        netfoxMovementRoutes.set(cleanWorldName, redisRoute);
        return { ...redisRoute };
      }
    }
  }

  if (NETFOX_MOVEMENT_ALLOW_STATIC_FALLBACK && (NETFOX_MOVEMENT_STATIC_WORLD === "" || NETFOX_MOVEMENT_STATIC_WORLD === cleanWorldName)) {
    return {
      world: cleanWorldName,
      world_id: cleanWorldName,
      host: NETFOX_MOVEMENT_PUBLIC_HOST,
      port: NETFOX_MOVEMENT_PUBLIC_PORT,
      max_clients: NETFOX_MOVEMENT_MAX_CLIENTS,
      server_instance_id: SERVER_INSTANCE_ID,
      registered_at_ms: 0,
      registered_at: "",
      expires_at_ms: 0,
      expires_at: "",
      source: "static_fallback",
    };
  }

  return null;
}

/**
 * @returns {PixelMania.NetfoxMovementRouteStats}
 */
function getNetfoxMovementRouteStats() {
  pruneExpiredNetfoxMovementRoutes();
  const now = Date.now();
  const registeredRoutes: any = {};
  for (const [worldName, route] of netfoxMovementRoutes.entries()) {
    if (!route) continue;
    registeredRoutes[worldName] = {
      world: route.world,
      host: route.host,
      port: route.port,
      max_clients: route.max_clients,
      source: route.source,
      server_instance_id: route.server_instance_id,
      expires_at_ms: route.expires_at_ms,
      expires_in_ms: Math.max(0, Math.trunc(Number(route.expires_at_ms || 0) - now)),
    };
  }
  return {
    registered_worlds: netfoxMovementRoutes.size,
    route_ttl_ms: NETFOX_MOVEMENT_ROUTE_TTL_MS,
    static_fallback_enabled: NETFOX_MOVEMENT_ALLOW_STATIC_FALLBACK,
    static_world: NETFOX_MOVEMENT_STATIC_WORLD || "*",
    registered_routes: registeredRoutes,
  };
}

/**
 * @param {PixelMania.RuntimePlayer} player
 * @param {PixelMania.WorldName | string} worldName
 * @param {Record<string, unknown>} overrides
 * @returns {Promise<PixelMania.NetfoxSpawnTicketRoute>}
 */
async function buildNetfoxSpawnTicketPayload(player: any, worldName: any, overrides: any = {}) {
  const cleanWorldName = cleanWorld(worldName || getPlayerCurrentWorldName(player));
  const now = Date.now();
  const expiresAt = now + NETFOX_SPAWN_TICKET_TTL_MS;
  const movementRoute = await getNetfoxMovementRouteForWorld(cleanWorldName);
  const route: any = {
    enabled: NETFOX_MOVEMENT_ENABLED,
    world: cleanWorldName,
    world_id: cleanWorldName,
    host: movementRoute ? movementRoute.host : "",
    port: movementRoute ? movementRoute.port : 0,
    max_clients: movementRoute ? movementRoute.max_clients : NETFOX_MOVEMENT_MAX_CLIENTS,
    route_source: movementRoute ? movementRoute.source : "",
    route_expires_at_ms: movementRoute ? movementRoute.expires_at_ms : 0,
    route_expires_at: movementRoute ? movementRoute.expires_at : "",
    ticket_required: true,
    ticket_configured: isNetfoxSpawnTicketConfigured(),
    ticket_ttl_ms: NETFOX_SPAWN_TICKET_TTL_MS,
    ticket_expires_at_ms: 0,
    ticket_expires_at: "",
    server_instance_id: SERVER_INSTANCE_ID,
    ticket: "",
    reason: "",
    message: "",
  };

  if (!NETFOX_MOVEMENT_ENABLED) {
    route.reason = "netfox_movement_disabled";
    route.message = "Netfox movement routing is disabled on the backend.";
    return route;
  }

  if (!movementRoute) {
    route.reason = "netfox_route_missing";
    route.message = "No live Netfox movement server is registered for this world.";
    return route;
  }

  if (!isNetfoxSpawnTicketConfigured()) {
    route.reason = "netfox_ticket_secret_missing";
    route.message = "Netfox spawn tickets are not configured on the backend.";
    return route;
  }

  const identity = getNetfoxTicketIdentityFromPlayer(player, cleanWorldName, overrides);
  const ticketPayload: any = {
    v: 1,
    type: "netfox_spawn",
    movement_mode: MOVEMENT_MODE_NETFOX_REAL,
    iat: now,
    exp: expiresAt,
    jti: crypto.randomUUID(),
    server_instance_id: SERVER_INSTANCE_ID,
    route_source: movementRoute.source,
    route_host: movementRoute.host,
    route_port: movementRoute.port,
    ...identity,
  };

  route.ticket = makeNetfoxSpawnTicket(ticketPayload);
  route.ticket_expires_at_ms = expiresAt;
  route.ticket_expires_at = new Date(expiresAt).toISOString();
  return route;
}

/**
 * @param {Record<string, unknown>} body
 * @returns {PixelMania.NetfoxSpawnTicketVerifyResult}
 */
function verifyNetfoxSpawnTicketPayload(body: any) {
  if (!isNetfoxSpawnTicketConfigured()) {
    return { ok: false, reason: "spawn_ticket_secret_missing", error: "Netfox spawn tickets are not configured.", status: 503 };
  }

  if (!body || typeof body !== "object" || Array.isArray(body)) {
    return { ok: false, reason: "invalid_request", error: "Invalid spawn ticket verification request.", status: 400 };
  }

  const parsed = parseNetfoxSpawnTicket(body.ticket);
  if (!parsed.ok) return parsed;

  const payload = parsed.payload;
  if (payload.type !== "netfox_spawn" || Math.trunc(Number(payload.v) || 0) !== 1) {
    return { ok: false, reason: "spawn_ticket_wrong_type", error: "Netfox spawn ticket has the wrong type.", status: 400 };
  }

  const now = Date.now();
  const expiresAt = Math.trunc(Number(payload.exp) || 0);
  if (expiresAt <= now) {
    return { ok: false, reason: "spawn_ticket_expired", error: "Netfox spawn ticket expired.", status: 401 };
  }

  const ticketWorld = cleanWorld(payload.world || payload.world_id || "");
  const requestedWorld = cleanWorld(body.world || ticketWorld);
  if (requestedWorld !== ticketWorld) {
    return { ok: false, reason: "world_mismatch", error: "Netfox spawn ticket is for a different world.", status: 401 };
  }

  const peerId = Math.max(0, Math.trunc(Number(body.peer_id || payload.peer_id || 0)));
  const identity: any = {
    peer_id: peerId,
    display_name: clampString(payload.display_name || payload.username || payload.account_username || "Player", 32),
    username: cleanAccountName(payload.username || payload.account_username || ""),
    account_username: cleanAccountName(payload.account_username || payload.username || ""),
    websocket_player_id: clampString(payload.websocket_player_id || "", 96),
    game_player_id: clampString(payload.game_player_id || payload.profile_id || payload.account_id || "", 96),
    account_id: clampString(payload.account_id || "", 96),
    profile_id: clampString(payload.profile_id || "", 96),
    world_id: ticketWorld,
    world: ticketWorld,
    backend_authenticated: true,
    netfox_ticket_id: clampString(payload.jti || "", 96),
  };

  return {
    ok: true,
    world: ticketWorld,
    peer_id: peerId,
    identity,
  };
}

function isNetfoxServerWorldStateEndpointConfigured() {
  return NETFOX_SERVER_WORLD_STATE_TOKEN !== "" || /^[a-f0-9]{64}$/i.test(NETFOX_SERVER_WORLD_STATE_TOKEN_HASH);
}

function verifyNetfoxServerWorldStateRequest(request: any) {
  const token = getBearerTokenFromRequest(request);
  if (token === "") return false;

  if (NETFOX_SERVER_WORLD_STATE_TOKEN !== "" && safeTimingEqualString(token, NETFOX_SERVER_WORLD_STATE_TOKEN)) {
    return true;
  }

  if (/^[a-f0-9]{64}$/i.test(NETFOX_SERVER_WORLD_STATE_TOKEN_HASH)) {
    return safeTimingEqualString(makeTokenHash(token), NETFOX_SERVER_WORLD_STATE_TOKEN_HASH);
  }

  return false;
}

function isCustomMovementServerWorldStateEndpointConfigured() {
  return CUSTOM_MOVEMENT_SERVER_WORLD_STATE_TOKEN !== "" || /^[a-f0-9]{64}$/i.test(CUSTOM_MOVEMENT_SERVER_WORLD_STATE_TOKEN_HASH);
}

function verifyCustomMovementServerWorldStateRequest(request: any) {
  const token = getBearerTokenFromRequest(request);
  if (token === "") return false;

  if (CUSTOM_MOVEMENT_SERVER_WORLD_STATE_TOKEN !== "" && safeTimingEqualString(token, CUSTOM_MOVEMENT_SERVER_WORLD_STATE_TOKEN)) {
    return true;
  }

  if (/^[a-f0-9]{64}$/i.test(CUSTOM_MOVEMENT_SERVER_WORLD_STATE_TOKEN_HASH)) {
    return safeTimingEqualString(makeTokenHash(token), CUSTOM_MOVEMENT_SERVER_WORLD_STATE_TOKEN_HASH);
  }

  return false;
}

function getEffectiveWorldCollisionBlockCount(worldName: any, state: any) {
  const effectiveForeground = getEffectiveForegroundBlocksForState(state, worldName);
  return effectiveForeground.filter((entry: ServerPacketRecord) => {
    const blockType = clampString(entry?.block_type || "");
    const definition = ItemDatabase.getItemDefinition(blockType) || {};
    return !definition.no_collision;
  }).length;
}

function buildNetfoxWorldStateHttpPayload(worldName: any, reason: any = "netfox_server_world_load") {
  const clean = cleanWorld(worldName);
  const state = ensureWorldState(clean);
  const effectiveForeground = getEffectiveForegroundBlocksForState(state, clean);
  const worldState = buildWorldStateMessage(clean, {
    respawn_player: false,
    force_player_position: false,
    world_state_reason: reason,
  });
  const background = Array.isArray(worldState.background) ? worldState.background : [];

  return {
    ok: true,
    world: clean,
    block_count: effectiveForeground.length,
    background_block_count: background.length,
    collision_block_count: getEffectiveWorldCollisionBlockCount(clean, state),
    world_state: worldState,
  };
}

function serializeWorldState(worldName: any) {
  return PersistenceHelpers.clonePersistenceSnapshot(WorldStateHelpers.serializeWorldState(worldName));
}

function getWorldBlockTypeAt(worldName: any, x: any, y: any, layer: any = "foreground") {
  const state = ensureWorldState(worldName);
  const cleanLayer = String(layer || "").toLowerCase();
  const target = cleanLayer === "background" ? state.background : state.foreground;
  const block = target.get(gridKey(x, y));
  return clampString(block?.block_type || "");
}

function buildWorldBlockReconciliationPayload(
  player: ServerPacketRecord | null | undefined,
  data: ServerPacketRecord,
  options: WorldBlockReconciliationOptions = {},
) {
  const requestedWorld = cleanWorld(data?.world || data?.current_world || getPlayerCurrentWorldName(player));
  const currentWorld = getPlayerCurrentWorldName(player);
  const layer = String(data?.layer || "foreground").trim().toLowerCase() === "background"
    ? "background"
    : "foreground";
  const x = Math.trunc(Number(data?.x ?? data?.target_x) || 0);
  const y = Math.trunc(Number(data?.y ?? data?.target_y) || 0);
  const requestId = makeRequestId(data);
  const blockAction = String(data?.block_action || data?.requested_action || data?.action || "place").trim().toLowerCase();
  const requestedBlockType = clampString(data?.requested_block_type || data?.block_type || data?.item_id || "");
  const payload: ServerPacketRecord = {
    type: "world_block_reconcile",
    world: requestedWorld,
    current_world: currentWorld,
    request_id: requestId,
    action_id: requestId,
    block_action: blockAction,
    layer,
    x,
    y,
    requested_block_type: requestedBlockType,
    authoritative_pending: options.authoritative_pending === true,
    authoritative_present: false,
    authoritative_block_type: "",
    authoritative_item_id: 0,
    authoritative_placement_request_id: "",
    authoritative_matches_request: false,
    block_revision: 0,
    cell_revision: 0,
    reason: clampString(options.reason || "authoritative_reconcile"),
  };

  if (requestedWorld !== currentWorld || !isGridInWorld(x, y)) {
    payload.reason = requestedWorld !== currentWorld ? "wrong_world" : "invalid_grid";
    return payload;
  }

  const state = ensureWorldState(currentWorld);
  const explicitTarget = getWorldLayerMap(state, layer);
  const removed = getWorldRemovedLayerMap(state, layer);
  const key = gridKey(x, y);
  const generatedMaps = buildServerGeneratedWorldMaps(currentWorld, state);
  const effectiveTarget = layer === "background"
    ? buildEffectiveBackgroundMap(currentWorld, state, generatedMaps.background)
    : buildEffectiveForegroundMap(currentWorld, state, generatedMaps.foreground);
  const block = effectiveTarget.get(key) || null;
  const explicitBlock = explicitTarget.get(key) || null;
  const tombstone = removed.get(key) || null;
  const placementRequestId = clampString(explicitBlock?.placement_request_id || block?.placement_request_id || "");
  payload.authoritative_present = Boolean(block);
  payload.authoritative_block_type = clampString(block?.block_type || "");
  payload.authoritative_item_id = Math.max(0, Math.trunc(Number(block?.item_id) || 0));
  payload.authoritative_placement_request_id = placementRequestId;
  payload.authoritative_matches_request = requestId !== "" && placementRequestId === requestId;
  payload.block_revision = getWorldBlockRevision(state);
  payload.cell_revision = Math.max(
    Math.max(0, Math.trunc(Number(explicitBlock?.block_revision || block?.block_revision) || 0)),
    Math.max(0, Math.trunc(Number(tombstone?.block_revision) || 0)),
  );
  const playerState = ensurePlayerState(player?.account_username || player?.name || "");
  if (playerState) payload.player_data = buildPlayerStateForClient(playerState);
  return payload;
}

function sendWorldBlockReconciliation(
  socket: ServerWebSocket,
  player: ServerPacketRecord | null | undefined,
  data: ServerPacketRecord,
  options: WorldBlockReconciliationOptions = {},
) {
  if (!socket || socket.readyState !== WebSocket.OPEN) return;
  sendJson(socket, buildWorldBlockReconciliationPayload(player, data, options));
}

function handleWorldBlockReconcileRequest(
  socket: ServerWebSocket,
  player: ServerPacketRecord | null | undefined,
  data: ServerPacketRecord,
) {
  if (!requireAuthenticated(socket, player, "reconcile block placement")) return;
  sendWorldBlockReconciliation(socket, player, data, {
    authoritative_pending: false,
    reason: "client_reconcile_request",
  });
}

function getWorldLayerMap(state: any, layer: any = "foreground") {
  const cleanLayer = String(layer || "").toLowerCase();
  if (cleanLayer === "background") return state.background;
  return state.foreground;
}

function syncElectricalDeviceStateForBlockUpdate(state: any, update: any) {
  if (!state || !update) return false;
  if (!(state.electrical_devices instanceof Map)) state.electrical_devices = new Map();

  const key = gridKey(update.x, update.y);
  if (update.action === "place" && isElectricalDeviceBlockOnLayer(update.block_type, update.layer)) {
    const deviceEntry = normalizeElectricalDeviceStateEntry({
      x: update.x,
      y: update.y,
      item_id: update.block_type,
      device_type: getElectricalDeviceTypeForItem(update.block_type),
    });
    if (deviceEntry) {
      state.electrical_devices.set(key, deviceEntry);
      return true;
    }
  }

  if (update.action === "break" && isElectricalDeviceBlockOnLayer(update.block_type, update.layer)) {
    state.electrical_devices.delete(key);
    if (update.block_type === ELECTRICAL_METAL_PAD_ITEM) {
      removeLinkedPadFromGenerators(state, key);
    } else if (update.block_type === ELECTRICAL_POLE_ITEM) {
      removeLinkedPoleFromGenerators(state, key);
      removeLinkedPoleFromPoleCouplings(state, key);
    }
    return true;
  }

  return false;
}

function getWorldRemovedLayerMap(state: any, layer: any = "foreground") {
  const cleanLayer = String(layer || "").toLowerCase();
  if (cleanLayer === "background") return state.removed_background;
  return state.removed_foreground;
}

function getWorldObjectJournalType(update: any = {}) {
  const explicitType = clampString(update.object_type || "");
  if (explicitType !== "") return explicitType;
  const action = clampString(update.action || "", 80).toLowerCase();
  if (action.includes("electrical")) return action.includes("generator") ? "electrical_generator" : "electrical_tile";
  if (action.includes("vend")) return "vending";
  if (action.includes("safe")) return "safe";
  if (action.includes("mailbox")) return "mailbox";
  if (action.includes("bulletin_board")) return "bulletin_board";
  if (action.includes("display")) return "display";
  if (action.includes("tackle_box")) return "tackle_box";
  if (action.includes("chicken")) return "chicken";
  if (action.includes("cow")) return "cow";
  if (action.includes("duck")) return "duck";
  if (action.includes("dice")) return "dice";
  if (action.includes("anti_punch")) return "anti_punch";
  if (action.includes("anti_talk")) return "anti_talk";
  if (action.includes("anti_gravity")) return "anti_gravity";
  if (action.includes("theme_machine")) return "theme_machine";
  if (action.includes("cctv")) return "cctv";
  if (action === "world_lock_state" || action.includes("world_lock")) return "world_lock";
  if (action === "area_lock_state" || action.includes("area_lock")) return "area_lock";
  if (action === "sign_text" || action.includes("sign")) return "sign";
  if (action === "door_state" || action.includes("door")) return "door";
  if (action === "wooden_entrance_state" || action.includes("entrance")) return "wooden_entrance";
  if (action.includes("lamp") || action.includes("toggle")) return "toggle";
  return "interaction";
}

function getWorldObjectJournalId(worldName: any, update: any = {}, objectType: any = "") {
  const explicit = clampString(update.object_id || "");
  if (explicit !== "") return explicit;

  const cleanType = clampString(objectType || getWorldObjectJournalType(update), 80) || "interaction";
  const doorId = cleanDoorId(update.door_id || "");
  if (doorId !== "") return `door:${doorId}`;
  if (cleanType === "world_lock") return `${cleanWorld(worldName)}:world_lock`;
  if (cleanType === "area_lock") return `${cleanWorld(worldName)}:area_locks`;
  if (cleanType === "cctv") return `${cleanWorld(worldName)}:cctv`;

  const x = Number.isFinite(Number(update.x)) ? Math.trunc(Number(update.x)) : 0;
  const y = Number.isFinite(Number(update.y)) ? Math.trunc(Number(update.y)) : 0;
  return `${cleanType}:${x}:${y}`;
}

function getWorldObjectJournalData(worldName: any, update: any = {}) {
  const state = ensureWorldState(worldName);
  const action = clampString(update.action || "", 80).toLowerCase();

  if (action === "world_lock_state") {
    return cloneJson(state.world_lock || {});
  }

  if (action === "area_lock_state") {
    return cloneJson(sanitizeAreaLocksList(state.area_locks || []));
  }

  if (action === "cctv_state" || action.includes("cctv")) {
    return cloneJson(sanitizeCctvWorldState(state.cctv_state || {}, worldName));
  }

  const key = gridKey(update.x, update.y);
  if (action.includes("electrical")) {
    return cloneJson(state.electrical?.get(key) || {});
  }

  const interaction = state.interactions.get(key);
  if (!interaction) return {};

  const block = state.foreground.get(key);
  return cloneJson({
    block_type: clampString(update.block_type || block?.block_type || interaction.block_type || ""),
    ...interaction,
  });
}

function buildWorldInteractionDetails(update: any = {}) {
  const interactionDetails: any = {};
  if (update.action === "world_lock_state" && update.state) {
    interactionDetails.is_locked = Boolean(update.state.is_locked);
    interactionDetails.owner_name = cleanName(update.state.owner_name || "");
    interactionDetails.lock_grid_x = Number(update.state.lock_grid_x);
    interactionDetails.lock_grid_y = Number(update.state.lock_grid_y);
    interactionDetails.allowed_count = Array.isArray(update.state.allowed_players) ? update.state.allowed_players.length : 0;
    interactionDetails.public_build = Boolean(update.state.public_build);
  } else if (update.action === "area_lock_state") {
    const locks = sanitizeAreaLocksList(update.state?.area_locks || update.state || []);
    interactionDetails.area_lock_count = locks.length;
    interactionDetails.protected_tile_count = locks.reduce(
      (sum: number, lock: ServerAreaLockRecord) => sum + getAreaLockPositions(lock, ensureWorldState(update.world || "")).length,
      0,
    );
  } else if (update.action === "sign_text") {
    interactionDetails.text_length = String(update.text || "").length;
  } else if (update.action === "wooden_entrance_state") {
    interactionDetails.locked = Boolean(update.locked);
  } else if (update.action === "door_state") {
    interactionDetails.door_id = update.door_id;
    interactionDetails.door_name_length = cleanDoorName(update.door_name || update.name || "").length;
    interactionDetails.target_world = update.target_world;
    interactionDetails.target_door_id = update.target_door_id;
    interactionDetails.locked = Boolean(update.locked);
    interactionDetails.password_changed = Boolean(update.password_changed);
    interactionDetails.password_configured = Boolean(update.password_configured);
  } else if (update.action === "ceiling_lamp_state") {
    interactionDetails.on = Boolean(update.on);
  } else if (String(update.action || "").includes("vend")) {
    interactionDetails.vending_action = String(update.action || "");
  } else if (String(update.action || "").includes("safe")) {
    interactionDetails.safe_action = String(update.action || "");
  } else if (String(update.action || "").includes("mailbox")) {
    interactionDetails.mailbox_action = String(update.operation || update.action || "");
    const messages = update.state && Array.isArray(update.state.messages) ? update.state.messages : [];
    interactionDetails.message_count = messages.length;
  } else if (String(update.action || "").includes("bulletin_board")) {
    interactionDetails.bulletin_board_action = String(update.operation || update.action || "");
    const messages = update.state && Array.isArray(update.state.messages) ? update.state.messages : [];
    interactionDetails.message_count = messages.length;
  } else if (String(update.action || "").includes("display")) {
    interactionDetails.display_action = String(update.action || "");
    const slot = update.state && update.state.slot && typeof update.state.slot === "object" ? update.state.slot : {};
    interactionDetails.item_id = slot.item_id || "";
    interactionDetails.item_category = slot.item_category || "";
  } else if (String(update.action || "").includes("tackle_box")) {
    interactionDetails.tackle_box_action = String(update.operation || update.action || "");
    const state = update.state && typeof update.state === "object" ? update.state : {};
    interactionDetails.remaining_ms = Number(state.remaining_ms || 0);
    interactionDetails.next_harvest_at = String(state.next_harvest_at || "");
  } else if (String(update.action || "").includes("chicken")) {
    interactionDetails.chicken_action = String(update.operation || update.action || "");
    const state = update.state && typeof update.state === "object" ? update.state : {};
    interactionDetails.status = String(state.status || "");
    interactionDetails.remaining_ms = Number(state.remaining_ms || 0);
    interactionDetails.next_harvest_at = String(state.next_harvest_at || "");
    interactionDetails.dies_at = String(state.dies_at || "");
  } else if (String(update.action || "").includes("cow")) {
    interactionDetails.cow_action = String(update.operation || update.action || "");
    const state = update.state && typeof update.state === "object" ? update.state : {};
    interactionDetails.status = String(state.status || "");
    interactionDetails.remaining_ms = Number(state.remaining_ms || 0);
    interactionDetails.next_harvest_at = String(state.next_harvest_at || "");
    interactionDetails.dies_at = String(state.dies_at || "");
  } else if (String(update.action || "").includes("duck")) {
    interactionDetails.duck_action = String(update.operation || update.action || "");
    const state = update.state && typeof update.state === "object" ? update.state : {};
    interactionDetails.status = String(state.status || "");
    interactionDetails.remaining_ms = Number(state.remaining_ms || 0);
    interactionDetails.next_harvest_at = String(state.next_harvest_at || "");
    interactionDetails.dies_at = String(state.dies_at || "");
  } else if (String(update.action || "").includes("dice")) {
    const state = update.state && typeof update.state === "object" ? update.state : update;
    interactionDetails.rolled_number = Number(state.rolled_number || state.face || 1);
    interactionDetails.rolled_by = String(state.rolled_by || "");
  } else if (String(update.action || "").includes("anti_punch")) {
    interactionDetails.enabled = Boolean(update.enabled);
  } else if (String(update.action || "").includes("anti_talk")) {
    interactionDetails.enabled = Boolean(update.enabled);
  } else if (String(update.action || "").includes("anti_gravity")) {
    interactionDetails.enabled = Boolean(update.enabled);
  } else if (String(update.action || "").includes("theme_machine")) {
    interactionDetails.enabled = Boolean(update.enabled);
    interactionDetails.theme = sanitizeWorldBackgroundTheme(update.theme || "night") || "night";
  } else if (String(update.action || "").includes("cctv")) {
    const state = update.state && typeof update.state === "object" ? update.state : {};
    const entries = Array.isArray(state.entries) ? state.entries : [];
    interactionDetails.entry_count = entries.length;
    interactionDetails.event_type = String(update.event_type || "");
    interactionDetails.player_name = String(update.player_name || "");
  }
  return interactionDetails;
}

/**
 * @returns {PixelMania.WorldObjectChangeEntry}
 */
function buildWorldObjectChangeEntry(socket: any, player: any, worldName: any, update: any = {}, oldData: any = {}, newData: any = {}, sourceId: any = "", details: any = {}) {
  const objectType = getWorldObjectJournalType(update);
  return {
    ...getAuditActor(socket, player),
    source_type: String(update.source_type || "world_interaction_update"),
    source_id: String(sourceId || update.source_id || makeAuditId("interact")),
    request_id: String(update.request_id || ""),
    world: cleanWorld(worldName),
    action: String(update.action || "update"),
    layer: "object",
    x: Number.isFinite(Number(update.x)) ? Math.trunc(Number(update.x)) : null,
    y: Number.isFinite(Number(update.y)) ? Math.trunc(Number(update.y)) : null,
    block_type: clampString(update.block_type || oldData?.block_type || newData?.block_type || ""),
    object_type: objectType,
    object_id: getWorldObjectJournalId(worldName, update, objectType),
    old_data: cloneJson(oldData || {}),
    new_data: cloneJson(newData || {}),
    details,
  };
}

function getDropsForWorldStateMessage(state: any, worldName: any, receiverPlayer: any = null) {
  const drops = Array.from<any>(state.drops.values());
  if (!receiverPlayer || !isDropInterestManagementEnabled()) return drops;

  const clean = cleanWorld(worldName || receiverPlayer.world || "START");
  return drops.filter((drop) => shouldReceiverSeeDrop(receiverPlayer, drop, clean));
}

function getInteractionsForWorldStateMessage(state: any, worldName: any, receiverPlayer: any = null) {
  if (!state || !(state.interactions instanceof Map)) return [];
  return Array.from<any>(state.interactions.values())
    .filter((interaction) => Boolean(interaction))
    .map((interaction) => sanitizeWorldInteractionPayloadForClient(interaction, worldName, receiverPlayer));
}

function getActiveThemeMachineDisableUpdates(worldName: any, nextUpdate: any = {}) {
  const clean = cleanWorld(worldName);
  const state = ensureWorldState(clean);
  if (!state || !(state.interactions instanceof Map)) return [];

  const nextX = Number(nextUpdate.x);
  const nextY = Number(nextUpdate.y);
  const nextKey = Number.isFinite(nextX) && Number.isFinite(nextY)
    ? gridKey(Math.trunc(nextX), Math.trunc(nextY))
    : "";
  const updates: any = [];

  for (const interaction of state.interactions.values()) {
    if (!interaction || interaction.action !== "theme_machine_state" || !interaction.enabled) continue;
    const x = Math.trunc(Number(interaction.x));
    const y = Math.trunc(Number(interaction.y));
    if (!isGridInWorld(x, y)) continue;
    const key = gridKey(x, y);
    if (key === nextKey) continue;
    const block = state.foreground.get(key);
    if (!block || !isThemeMachineBlockType(block.block_type || "")) continue;
    updates.push({
      type: "world_interaction_update",
      world: clean,
      action: "theme_machine_state",
      x,
      y,
      enabled: false,
      theme: sanitizeWorldBackgroundTheme(interaction.theme || "night") || "night",
      block_type: clampString(block.block_type || ""),
      auto_disabled_by: "theme_machine_exclusive_activation",
    });
  }

  return updates;
}

function getActiveWorldBackgroundTheme(state: any) {
  if (!state || !(state.interactions instanceof Map)) return "";
  for (const interaction of state.interactions.values()) {
    if (!interaction || interaction.action !== "theme_machine_state" || !interaction.enabled) continue;
    const key = gridKey(interaction.x, interaction.y);
    const block = state.foreground.get(key);
    if (!block || !isThemeMachineBlockType(block.block_type || "")) continue;
    const theme = sanitizeWorldBackgroundTheme(interaction.theme || "night");
    if (theme !== "") return theme;
  }
  return "";
}

function invalidateWorldEntrySnapshotCache(worldName: unknown, reason: unknown = "invalidated"): void {
  const clean = cleanWorld(worldName);
  if (!worldEntrySnapshotCache.delete(clean)) return;
  if (WORLD_STATE_REFRESH_TRACE) {
    console.log("[world-entry]", JSON.stringify({
      event: "snapshot_cache_invalidated",
      world_id: clean,
      server_instance: SERVER_INSTANCE_ID,
      reason: clampString(reason || "invalidated"),
    }));
  }
}

function getWorldEntrySnapshotCacheKey(worldName: unknown, state: any): string {
  const clean = cleanWorld(worldName);
  const ownership = worldPersistenceOwnership.get(clean);
  return [
    clean,
    PersistenceHelpers.normalizeWorldRevision(state?.world_revision),
    getWorldBlockRevision(state),
    state?.cleared ? 1 : 0,
    ownership?.ownership_token || "unfenced",
    Math.max(0, Math.trunc(Number(ownership?.ownership_epoch) || 0)),
  ].join("|");
}

function trimWorldEntrySnapshotCache(): void {
  while (worldEntrySnapshotCache.size > WORLD_ENTRY_SNAPSHOT_CACHE_MAX_WORLDS) {
    const oldestWorld = worldEntrySnapshotCache.keys().next().value;
    if (typeof oldestWorld !== "string") break;
    worldEntrySnapshotCache.delete(oldestWorld);
  }
}

function getOrBuildWorldEntrySnapshotCache(worldName: unknown, state: any): WorldEntrySnapshotCacheEntry {
  const clean = cleanWorld(worldName);
  const cacheKey = getWorldEntrySnapshotCacheKey(clean, state);
  const existing = worldEntrySnapshotCache.get(clean);
  if (existing?.cache_key === cacheKey) {
    worldEntrySnapshotCache.delete(clean);
    worldEntrySnapshotCache.set(clean, existing);
    return existing;
  }

  const startedAt = process.hrtime.bigint();
  const ownership = worldPersistenceOwnership.get(clean);
  const generatedMaps = buildServerGeneratedWorldMaps(clean, state);
  const staticPayload: ServerPacketRecord = {
    world_state_encoding: "grid_dictionary_v1",
    world_entry_format_version: 2,
    world: clean,
    world_width: WORLD_WIDTH,
    world_height: WORLD_HEIGHT,
    tile_size: TILE_SIZE,
    ownership_token: ownership?.ownership_token || "",
    ownership_epoch: Math.max(0, Math.trunc(Number(ownership?.ownership_epoch) || 0)),
    world_revision: getWorldRevision(clean),
    block_revision: getWorldBlockRevision(state),
    cleared: Boolean(state.cleared),
    foreground: WorldStateHelpers.compactWorldLayerEntriesForNetwork(
      getEffectiveForegroundBlocksForState(state, clean, generatedMaps.foreground)
    ),
    background: WorldStateHelpers.compactWorldLayerEntriesForNetwork(
      getEffectiveBackgroundBlocksForState(state, clean, generatedMaps.background)
    ),
    removed_foreground: state.cleared ? [] : Array.from<any>(state.removed_foreground.values()),
    removed_background: state.cleared ? [] : Array.from<any>(state.removed_background.values()),
    seeds: Array.from<any>(state.seeds.values()).map(serializeSeedForMessage),
    generator_states: getGeneratorStatesForClient(state, clean),
    world_lock: getEffectiveWorldLockStateInState(state),
    area_locks: sanitizeAreaLocksList(state.area_locks || []),
  };
  let preparedSections: unknown = null;
  try {
    preparedSections = WorldStateHelpersModule.prepareWorldStateStreamSections(staticPayload, {
      targetPacketBytes: WORLD_STATE_STREAM_TARGET_PACKET_BYTES,
      maxPacketBytes: MAX_PACKET_BYTES,
    });
  } catch (error) {
    console.warn("[world-entry] static snapshot preparation failed; per-request encoding will be used", {
      world_id: clean,
      world_revision: staticPayload.world_revision,
      error: error instanceof Error ? error.message : String(error || "snapshot_prepare_failed"),
    });
  }
  const entry: WorldEntrySnapshotCacheEntry = {
    cache_key: cacheKey,
    world: clean,
    world_revision: Number(staticPayload.world_revision || 0),
    block_revision: Number(staticPayload.block_revision || 0),
    ownership_token: String(staticPayload.ownership_token || ""),
    ownership_epoch: Number(staticPayload.ownership_epoch || 0),
    static_payload: staticPayload,
    prepared_sections: preparedSections,
    build_ms: elapsedWorldEntryMs(startedAt),
    created_at_ms: Date.now(),
  };
  worldEntrySnapshotCache.set(clean, entry);
  trimWorldEntrySnapshotCache();
  return entry;
}

function buildWorldStateMessage(worldName: any, extraMessageData: any = {}) {
  const clean = cleanWorld(worldName);
  const state = ensureWorldState(clean);
  const cachedSnapshot = getOrBuildWorldEntrySnapshotCache(clean, state);
  const extras = extraMessageData && typeof extraMessageData === "object" && !Array.isArray(extraMessageData)
    ? { ...extraMessageData }
    : {};
  const receiverPlayer = extras.receiver_player || extras.receiverPlayer || null;
  delete extras.receiver_player;
  delete extras.receiverPlayer;

  return {
    type: "world_state",
    ...cachedSnapshot.static_payload,
    electrical_layer_visible: canPlayerSeeElectricalLayer(receiverPlayer, clean),
    electrical_layer: getElectricalLayerForClient(state, clean, receiverPlayer),
    generator_links: getGeneratorLinksForClient(state, clean, receiverPlayer),
    oil_refinery_links: getOilRefineryLinksForClient(state, clean, receiverPlayer),
    battery_charger_links: getBatteryChargerLinksForClient(state, clean, receiverPlayer),
    pole_links: getPoleLinksForClient(state, clean, receiverPlayer),
    interactions: getInteractionsForWorldStateMessage(state, clean, receiverPlayer),
    background_theme: getActiveWorldBackgroundTheme(state),
    cctv_state: getCctvStateForClient(clean, receiverPlayer),
    drops: getDropsForWorldStateMessage(state, clean, receiverPlayer),
    active_event_type: state.active_event_type || "",
    event_id: state.event_id || "",
    event_started_at: state.event_started_at || "",
    event_ends_at: state.event_ends_at || "",
    event_remaining_ms: getActiveWorldEventRemainingMs(state),
    active_event: buildActiveWorldEventSnapshot(state),
    ...extras,
  };
}

function supportsWorldStateStreaming(player: unknown): boolean {
  if (!WORLD_STATE_STREAMING_ENABLED) return false;
  const playerRecord = player && typeof player === "object" && !Array.isArray(player)
    ? player as ServerPacketRecord
    : {};
  const comparison = compareVersions(playerRecord.client_version || "", WORLD_STATE_STREAM_MIN_CLIENT_VERSION);
  return comparison !== null && comparison >= 0;
}

function sendWorldStateToSocket(
  socket: unknown,
  player: unknown,
  worldName: unknown,
  extraMessageData: ServerPacketRecord = {}
): ServerPacketRecord {
  const totalStartedAt = process.hrtime.bigint();
  let phaseStartedAt = totalStartedAt;
  const clean = cleanWorld(worldName);
  const cacheBeforeBuild = worldEntrySnapshotCache.get(clean);
  const payload = buildWorldStateMessage(worldName, extraMessageData) as ServerPacketRecord;
  const payloadBuildMs = elapsedWorldEntryMs(phaseStartedAt);
  const snapshotCache = worldEntrySnapshotCache.get(clean);
  const snapshotCacheHit = Boolean(snapshotCache && snapshotCache === cacheBeforeBuild);
  const cacheMetrics = {
    snapshot_cache_hit: snapshotCacheHit,
    snapshot_cache_build_ms: snapshotCacheHit ? 0 : Number(snapshotCache?.build_ms || 0),
    snapshot_cache_key: snapshotCache?.cache_key || "",
  };
  if (!supportsWorldStateStreaming(player)) {
    phaseStartedAt = process.hrtime.bigint();
    let raw = "";
    try {
      raw = JSON.stringify(payload);
    } catch (error: unknown) {
      return {
        ok: false,
        streamed: false,
        payload_build_ms: payloadBuildMs,
        serialization_ms: elapsedWorldEntryMs(phaseStartedAt),
        compression: "none",
        compression_ms: 0,
        queue_ms: 0,
        total_ms: elapsedWorldEntryMs(totalStartedAt),
        snapshot_bytes: -1,
        wire_bytes: 0,
        chunk_count: 0,
        section_count: 0,
        world_revision: Number(payload.world_revision || 0),
        block_revision: Number(payload.block_revision || 0),
        ...cacheMetrics,
        reason: error instanceof Error ? error.message : String(error || "serialization_failed"),
      };
    }
    const serializationMs = elapsedWorldEntryMs(phaseStartedAt);
    phaseStartedAt = process.hrtime.bigint();
    const sent = sendRawJsonToSocket(socket, raw, "world_state_legacy", {
      message_type: String(payload.type || "world_state"),
    });
    return {
      ok: sent,
      streamed: false,
      payload_build_ms: payloadBuildMs,
      serialization_ms: serializationMs,
      compression: "none",
      compression_ms: 0,
      queue_ms: elapsedWorldEntryMs(phaseStartedAt),
      total_ms: elapsedWorldEntryMs(totalStartedAt),
      snapshot_bytes: Buffer.byteLength(raw),
      wire_bytes: Buffer.byteLength(raw),
      chunk_count: 0,
      section_count: 0,
      world_revision: Number(payload.world_revision || 0),
      block_revision: Number(payload.block_revision || 0),
      ...cacheMetrics,
    };
  }

  try {
    phaseStartedAt = process.hrtime.bigint();
    const stream = WorldStateHelpersModule.buildWorldStateStreamPackets(payload, {
      snapshotId: crypto.randomUUID(),
      targetPacketBytes: WORLD_STATE_STREAM_TARGET_PACKET_BYTES,
      maxPacketBytes: MAX_PACKET_BYTES,
      maxChunks: WORLD_STATE_STREAM_MAX_CHUNKS,
      preparedSections: snapshotCache?.prepared_sections || null,
    });
    const streamBuildMs = elapsedWorldEntryMs(phaseStartedAt);
    phaseStartedAt = process.hrtime.bigint();
    let sent = true;
    for (let index = 0; index < stream.packetJson.length; index += 1) {
      const packet = stream.packets[index] || {};
      sent = sendRawJsonToSocket(socket, stream.packetJson[index], "world_state_stream", {
        message_type: String(packet.type || ""),
        snapshot_id: String(packet.snapshot_id || ""),
        chunk_index: Number(packet.chunk_index ?? -1),
      }) && sent;
    }
    return {
      ok: sent,
      streamed: true,
      payload_build_ms: payloadBuildMs,
      stream_build_ms: streamBuildMs,
      serialization_ms: streamBuildMs,
      compression: "none",
      compression_ms: 0,
      queue_ms: elapsedWorldEntryMs(phaseStartedAt),
      total_ms: elapsedWorldEntryMs(totalStartedAt),
      snapshot_bytes: stream.snapshotBytes,
      wire_bytes: stream.wireBytes,
      chunk_count: stream.chunkCount,
      section_count: stream.sectionCount,
      world_revision: Number(payload.world_revision || 0),
      block_revision: Number(payload.block_revision || 0),
      ...cacheMetrics,
    };
  } catch (error: unknown) {
    console.warn("[world_state_stream] falling back to legacy snapshot:", {
      world: cleanWorld(worldName),
      error: error instanceof Error ? error.message : String(error || "unknown error"),
    });
    phaseStartedAt = process.hrtime.bigint();
    let raw = "";
    try {
      raw = JSON.stringify(payload);
    } catch (serializationError: unknown) {
      return {
        ok: false,
        streamed: false,
        fallback: true,
        payload_build_ms: payloadBuildMs,
        serialization_ms: elapsedWorldEntryMs(phaseStartedAt),
        compression: "none",
        compression_ms: 0,
        queue_ms: 0,
        total_ms: elapsedWorldEntryMs(totalStartedAt),
        snapshot_bytes: -1,
        wire_bytes: 0,
        chunk_count: 0,
        section_count: 0,
        world_revision: Number(payload.world_revision || 0),
        block_revision: Number(payload.block_revision || 0),
        ...cacheMetrics,
        reason: serializationError instanceof Error
          ? serializationError.message
          : String(serializationError || "serialization_failed"),
      };
    }
    const serializationMs = elapsedWorldEntryMs(phaseStartedAt);
    phaseStartedAt = process.hrtime.bigint();
    const sent = sendRawJsonToSocket(socket, raw, "world_state_legacy_fallback", {
      message_type: String(payload.type || "world_state"),
    });
    return {
      ok: sent,
      streamed: false,
      fallback: true,
      payload_build_ms: payloadBuildMs,
      serialization_ms: serializationMs,
      compression: "none",
      compression_ms: 0,
      queue_ms: elapsedWorldEntryMs(phaseStartedAt),
      total_ms: elapsedWorldEntryMs(totalStartedAt),
      snapshot_bytes: Buffer.byteLength(raw),
      wire_bytes: Buffer.byteLength(raw),
      chunk_count: 0,
      section_count: 0,
      world_revision: Number(payload.world_revision || 0),
      block_revision: Number(payload.block_revision || 0),
      ...cacheMetrics,
      reason: error instanceof Error ? error.message : String(error || "unknown error"),
    };
  }
}

function getActiveWorldEventRemainingMs(state: any) {
  if (!state || state.active_event_type !== SNOW_STORM_EVENT_TYPE) return 0;
  const endsAt = Date.parse(state.event_ends_at || "");
  if (!Number.isFinite(endsAt)) return 0;
  return Math.max(0, endsAt - Date.now());
}

function buildActiveWorldEventSnapshot(state: any) {
  if (!state || state.active_event_type !== SNOW_STORM_EVENT_TYPE) return {};
  return {
    type: state.active_event_type,
    event_type: state.active_event_type,
    event_id: state.event_id || "",
    started_at: state.event_started_at || "",
    ends_at: state.event_ends_at || "",
    remaining_ms: getActiveWorldEventRemainingMs(state),
    changed_tile_count: Array.isArray(state.event_changed_tiles) ? state.event_changed_tiles.length : 0,
  };
}

function warnWorldPersistenceGuard(worldName: any, reason: any) {
  const clean = cleanWorld(worldName);
  const now = Date.now();
  const previousWarnAt = Number(worldPersistenceGuardWarns.get(clean) || 0);
  if (now - previousWarnAt < 15000) return;
  worldPersistenceGuardWarns.set(clean, now);
  console.warn("[world_persistence_guard] skipped whole-world save from non-owner route instance", {
    world: clean,
    reason,
    server_instance_id: SERVER_INSTANCE_ID,
    local_players: getWorldPlayerRecords(clean, { requireOpenSocket: false }).length,
    owns_route_locally: ownedWorldRoutes.has(clean),
    route_enforcement_enabled: WORLD_ROUTE_ENFORCEMENT_ENABLED,
    redis_ready: redisStore.isReady(),
  });
}

function shouldPersistWholeWorldState(worldName: any, reason: any = "world_state_save") {
  const clean = cleanWorld(worldName);
  if (!POSTGRES_ENABLED || !POSTGRES_AUTHORITATIVE || !WORLD_ROUTE_ENFORCEMENT_ENABLED) return true;
  const ownership = worldPersistenceOwnership.get(clean);
  if (ownedWorldRoutes.has(clean) && ownership?.verified && ownership.ownership_token !== "" && ownership.ownership_epoch > 0) {
    return true;
  }

  warnWorldPersistenceGuard(clean, reason);
  return false;
}

function getWorldRevision(worldName: unknown): number {
  const state = ensureWorldState(cleanWorld(worldName));
  return PersistenceHelpers.normalizeWorldRevision(state?.world_revision);
}

function getWorldBlockRevisionForWorld(worldName: unknown): number {
  return getWorldBlockRevision(ensureWorldState(cleanWorld(worldName)));
}

function rememberLoadedWorldAuthority(
  worldName: unknown,
  ownership: WorldPersistenceOwnership | null | undefined,
  persistedRevision: unknown
): void {
  const clean = cleanWorld(worldName);
  if (!ownership?.verified) {
    worldLoadedAuthorities.delete(clean);
    return;
  }
  worldLoadedAuthorities.set(clean, {
    server_instance: SERVER_INSTANCE_ID,
    ownership_token: ownership.ownership_token || "",
    ownership_epoch: Math.max(0, Math.trunc(Number(ownership.ownership_epoch) || 0)),
    persisted_revision: PersistenceHelpers.normalizeWorldRevision(persistedRevision),
  });
}

function doesLoadedWorldAuthorityMatch(
  worldName: unknown,
  ownership: WorldPersistenceOwnership | null | undefined
): boolean {
  const clean = cleanWorld(worldName);
  const loaded = worldLoadedAuthorities.get(clean);
  if (!loaded || !ownership?.verified || loaded.server_instance !== SERVER_INSTANCE_ID) return false;
  if (!ownership.require_owner) return true;
  return loaded.ownership_token !== ""
    && loaded.ownership_token === ownership.ownership_token
    && loaded.ownership_epoch === ownership.ownership_epoch;
}

function rememberUnpersistedWorldRevision(worldName: unknown, revision: unknown): void {
  const clean = cleanWorld(worldName);
  const normalizedRevision = PersistenceHelpers.normalizeWorldRevision(revision);
  const ownership = worldPersistenceOwnership.get(clean);
  worldUnpersistedRevisions.set(clean, {
    revision: normalizedRevision,
    ownership_token: ownership?.ownership_token || "",
    ownership_epoch: ownership?.ownership_epoch || 0,
  });
}

function markWorldRevisionPersisted(worldName: unknown, revision: unknown): void {
  const clean = cleanWorld(worldName);
  const persistedRevision = PersistenceHelpers.normalizeWorldRevision(revision);
  worldPersistedRevisions.set(clean, Math.max(
    PersistenceHelpers.normalizeWorldRevision(worldPersistedRevisions.get(clean)),
    persistedRevision
  ));
  const pending = worldUnpersistedRevisions.get(clean);
  if (pending && pending.revision <= persistedRevision) {
    worldUnpersistedRevisions.delete(clean);
  }
  rememberLoadedWorldAuthority(clean, worldPersistenceOwnership.get(clean), persistedRevision);
}

function captureWorldMutationRollback(worldName: unknown): WorldMutationRollback {
  const clean = cleanWorld(worldName);
  const pending = worldUnpersistedRevisions.get(clean);
  return {
    existed: worldStates.has(clean),
    state: PersistenceHelpers.clonePersistenceSnapshot(serializeWorldState(clean)),
    unpersisted: pending ? { ...pending } : null,
  };
}

/**
 * Drop ids present in a serialized world snapshot, using the same key the live
 * drops map uses (`drop_id`).
 */
function collectSerializedWorldDropIds(serialized: unknown): Set<string> {
  const ids = new Set<string>();
  const state = serialized && typeof serialized === "object" ? (serialized as any) : {};
  const rawDrops = Array.isArray(state.drops)
    ? state.drops
    : (Array.isArray(state.item_drops) ? state.item_drops : []);
  for (const rawDrop of rawDrops) {
    const dropId = clampString((rawDrop && (rawDrop as any).drop_id) || "", MAX_DROP_ID_LENGTH);
    if (dropId !== "") ids.add(dropId);
  }
  return ids;
}

/**
 * Drops that other requests added to the live world after `snapshot` was taken.
 * A rollback owns only the mutations its own request made, so these must survive
 * it: they have already been broadcast to clients, and dropping them here leaves
 * players looking at an item the authoritative world no longer knows about — the
 * exact state that answers a pickup with "That drop is not available."
 */
function collectForeignLiveWorldDrops(worldName: string, snapshot: unknown): Array<[string, any]> {
  const liveState = worldStates.get(worldName);
  const liveDrops = liveState && liveState.drops instanceof Map ? liveState.drops : null;
  if (!liveDrops || liveDrops.size === 0) return [];

  const snapshotDropIds = collectSerializedWorldDropIds(snapshot);
  const foreignDrops: Array<[string, any]> = [];
  for (const [dropKey, drop] of liveDrops.entries()) {
    const dropId = clampString((drop && drop.drop_id) || dropKey || "", MAX_DROP_ID_LENGTH);
    if (snapshotDropIds.has(dropKey) || (dropId !== "" && snapshotDropIds.has(dropId))) continue;
    foreignDrops.push([dropKey, drop]);
  }
  return foreignDrops;
}

/**
 * Restore a serialized world snapshot over the live world without destroying
 * drops other requests created while this one was awaiting PostgreSQL.
 * `discardDropIds` are the caller's own speculative drops, which the rollback
 * does have to undo.
 *
 * @param {PixelMania.WorldName | string} worldName
 * @param {*} snapshot
 * @param {Array<string | { drop_id?: string }>} discardDropIds
 */
function restoreWorldStateSnapshot(worldName: unknown, snapshot: unknown, discardDropIds: unknown = []): { preserved_drop_count: number } {
  const clean = cleanWorld(worldName);
  const discarded = new Set<string>();
  if (Array.isArray(discardDropIds)) {
    for (const rawId of discardDropIds) {
      const rawDropId = rawId && typeof rawId === "object" ? (rawId as any).drop_id : rawId;
      const dropId = clampString(rawDropId || "", MAX_DROP_ID_LENGTH);
      if (dropId !== "") discarded.add(dropId);
    }
  }

  const foreignDrops = collectForeignLiveWorldDrops(clean, snapshot).filter(([dropKey, drop]) => {
    const dropId = clampString((drop && drop.drop_id) || dropKey || "", MAX_DROP_ID_LENGTH);
    return !discarded.has(dropKey) && !(dropId !== "" && discarded.has(dropId));
  });

  const liveDropsBeforeRestore = worldStates.get(clean)?.drops;
  const restored = deserializeWorldState(clean, snapshot);
  for (const [dropKey, drop] of foreignDrops) {
    if (!restored.drops.has(dropKey)) restored.drops.set(dropKey, drop);
  }
  if (liveDropsBeforeRestore instanceof Map) {
    for (const [dropKey, drop] of liveDropsBeforeRestore.entries()) {
      if (restored.drops.has(dropKey)) continue;
      recordDropRemovalTombstone(clean, (drop && drop.drop_id) || dropKey, "world_rollback_discarded");
    }
  }
  worldStates.set(clean, restored);

  if (foreignDrops.length > 0) {
    console.warn("[world_rollback_preserved_foreign_drops]", {
      world: clean,
      preserved_drop_count: foreignDrops.length,
      discarded_drop_count: discarded.size,
      preserved_drop_ids: foreignDrops
        .slice(0, MAX_ROLLBACK_PRESERVED_DROP_IDS_LOGGED)
        .map(([dropKey, drop]) => clampString((drop && drop.drop_id) || dropKey || "", MAX_DROP_ID_LENGTH)),
    });
  }
  return { preserved_drop_count: foreignDrops.length };
}

function restoreWorldMutationRollback(worldName: unknown, rollback: WorldMutationRollback): void {
  const clean = cleanWorld(worldName);
  invalidateWorldEntrySnapshotCache(clean, "mutation_rollback");
  if (rollback.existed) {
    restoreWorldStateSnapshot(clean, rollback.state);
  } else {
    worldStates.delete(clean);
  }
  if (rollback.unpersisted) {
    worldUnpersistedRevisions.set(clean, { ...rollback.unpersisted });
  } else {
    worldUnpersistedRevisions.delete(clean);
  }
  invalidateMovementCollisionCache(clean);
  scheduleWorldEventEnd(clean);
}

function isMemoryWorldRevisionAuthoritative(
  worldName: unknown,
  revision: unknown,
  ownership: WorldPersistenceOwnership | null | undefined
): boolean {
  const clean = cleanWorld(worldName);
  const normalizedRevision = PersistenceHelpers.normalizeWorldRevision(revision);
  const pending = worldUnpersistedRevisions.get(clean);
  if (!pending || pending.revision !== normalizedRevision || !ownership?.verified) return false;
  if (!ownership.require_owner) return true;
  return pending.ownership_token !== ""
    && pending.ownership_token === ownership.ownership_token
    && pending.ownership_epoch === ownership.ownership_epoch;
}

function advanceAuthoritativeWorldRevision(worldName: unknown, reason: unknown): number {
  const clean = cleanWorld(worldName);
  invalidateWorldEntrySnapshotCache(clean, "authoritative_mutation");
  const state = ensureWorldState(clean);
  const previousRevision = PersistenceHelpers.normalizeWorldRevision(state?.world_revision);
  if (previousRevision >= Number.MAX_SAFE_INTEGER) {
    throw new Error(`World revision exhausted for ${clean}`);
  }
  const mutationRevision = previousRevision + 1;
  state.world_revision = mutationRevision;
  rememberUnpersistedWorldRevision(clean, mutationRevision);
  // Fires on every world mutation (i.e. every block place/break). The JSON.stringify plus
  // the synchronous stdout write were ungated on the hottest gameplay path; gate them
  // behind the existing trace flag. Set WORLD_STATE_REFRESH_TRACE=1 to restore.
  if (WORLD_STATE_REFRESH_TRACE) {
    const ownership = worldPersistenceOwnership.get(clean);
    console.log("[world-persistence]", JSON.stringify({
      event: "mutation",
      world_id: clean,
      server_instance: SERVER_INSTANCE_ID,
      ownership_token: ownership?.ownership_token || "",
      ownership_epoch: ownership?.ownership_epoch || 0,
      loaded_revision: previousRevision,
      mutation_revision: mutationRevision,
      requested_save_revision: 0,
      persisted_revision: 0,
      affected_row_count: 0,
      save_result: clampString(reason || "mutation") || "mutation",
    }));
  }
  return mutationRevision;
}

async function verifyWorldPersistenceOwnership(worldName: unknown): Promise<{
  ok: boolean;
  reason: string;
  ownership: WorldPersistenceOwnership;
}> {
  const clean = cleanWorld(worldName);
  const ownershipRequired = POSTGRES_ENABLED && POSTGRES_AUTHORITATIVE && WORLD_ROUTE_ENFORCEMENT_ENABLED;
  if (!ownershipRequired) {
    return {
      ok: true,
      reason: "",
      ownership: {
        require_owner: false,
        server_instance: SERVER_INSTANCE_ID,
        ownership_token: "",
        ownership_epoch: 0,
        fallback: !redisStore.isReady(),
        verified: true,
      },
    };
  }

  const localOwnership = worldPersistenceOwnership.get(clean);
  if (!localOwnership?.verified || !ownedWorldRoutes.has(clean)) {
    return {
      ok: false,
      reason: "world_ownership_not_claimed",
      ownership: localOwnership || {
        require_owner: true,
        server_instance: SERVER_INSTANCE_ID,
        ownership_token: "",
        ownership_epoch: 0,
        fallback: false,
        verified: false,
      },
    };
  }
  if (!redisStore.isReady()) {
    return { ok: false, reason: "world_ownership_redis_unavailable", ownership: localOwnership };
  }

  const route = await redisStore.getWorldRoute(clean);
  const verified = Boolean(
    route?.ok &&
    route.owner_instance_id === SERVER_INSTANCE_ID &&
    route.ownership_token === localOwnership.ownership_token &&
    Number(route.ownership_epoch || 0) === localOwnership.ownership_epoch
  );
  if (!verified) {
    invalidateWorldEntrySnapshotCache(clean, "ownership_lease_lost");
    worldLoadedAuthorities.delete(clean);
    ownedWorldRoutes.delete(clean);
    worldPersistenceOwnership.delete(clean);
    worldUnpersistedRevisions.delete(clean);
    return { ok: false, reason: "world_ownership_lease_lost", ownership: localOwnership };
  }
  return { ok: true, reason: "", ownership: localOwnership };
}

async function runOwnedWorldPersistence<T>(
  worldName: unknown,
  reason: unknown,
  operation: (ownership: WorldPersistenceOwnership) => Promise<T>
): Promise<{ ok: boolean; reason: string; value?: T }> {
  const clean = cleanWorld(worldName);
  return worldPersistenceCoordinator.enqueue(clean, async () => {
    const verification = await verifyWorldPersistenceOwnership(clean);
    if (!verification.ok) {
      warnWorldPersistenceGuard(clean, verification.reason || reason);
      return { ok: false, reason: verification.reason || "world_ownership_unverified" };
    }
    try {
      const value = await operation(verification.ownership);
      return { ok: true, reason: "", value };
    } catch (error) {
      const requestedRevision = getWorldRevision(clean);
      console.warn("[world-persistence] operation failed", {
        world_id: clean,
        server_instance: SERVER_INSTANCE_ID,
        ownership_token: verification.ownership.ownership_token,
        ownership_epoch: verification.ownership.ownership_epoch,
        loaded_revision: PersistenceHelpers.normalizeWorldRevision(worldPersistedRevisions.get(clean)),
        mutation_revision: requestedRevision,
        requested_save_revision: requestedRevision,
        persisted_revision: PersistenceHelpers.normalizeWorldRevision(worldPersistedRevisions.get(clean)),
        affected_row_count: 0,
        save_result: "world_persistence_failed",
        operation_reason: clampString(reason || "world_persistence_failed"),
        error: getErrorMessage(error),
      });
      return { ok: false, reason: "world_persistence_failed" };
    }
  });
}

function queueWorldSave(worldName: any, options: WorldSaveOptions = {}) {
  const clean = cleanWorld(worldName);
  if (options.mutation !== false) {
    advanceAuthoritativeWorldRevision(clean, options.reason || "queued_world_mutation");
  }
  const existingTimer = worldSaveTimers.get(clean);
  if (existingTimer) {
    clearTimeout(existingTimer);
    worldSaveTimers.delete(clean);
  }

  // Authoritative state is captured immediately. The per-world coordinator
  // serializes the database writes, so debouncing here only widens the crash
  // window and risks serializing a later mutable state under an older intent.
  //
  // The exception is options.coalesce: the machine ticks sweep every loaded world every
  // 5-60s and each change used to force an immediate full-world write here, producing a
  // steady stream of whole-world writes into a serial write queue before any player has
  // acted. Those saves carry only regenerating machine state, so landing a beat later
  // cannot duplicate or lose anything. The "older intent" concern does not apply either:
  // saveWorldState re-serializes at flush time rather than capturing at queue time.
  if (POSTGRES_ENABLED && POSTGRES_AUTHORITATIVE && options.coalesce !== true) {
    return saveWorldState(clean, {
      mutation: false,
      reason: options.reason || "queued_world_save",
    });
  }
  const debounceMs = Math.max(0, Math.trunc(Number(options?.critical === true ? SAVE_DEBOUNCE_MS : WORLD_NON_CRITICAL_WORLD_SAVE_DEBOUNCE_MS) || SAVE_DEBOUNCE_MS));

  worldSaveTimers.set(clean, setTimeout(() => {
    worldSaveTimers.delete(clean);
    saveWorldState(clean, { mutation: false, reason: options.reason || "queued_world_save" });
  }, debounceMs));
  return null;
}

function saveWorldState(worldName: any, options: WorldSaveOptions = {}) {
  const clean = cleanWorld(worldName);
  if (!shouldPersistWholeWorldState(clean, options.reason || "saveWorldState")) return null;
  if (options.mutation !== false) {
    advanceAuthoritativeWorldRevision(clean, options.reason || "direct_world_mutation");
  }
  const serialized = serializeWorldState(clean);
  if (isPostgresAuthoritativeReady() || (!POSTGRES_AUTHORITATIVE && postgresStore.isReady())) {
    const operation = runOwnedWorldPersistence(clean, options.reason || "saveWorldState", async (ownership) => {
      const saved = await postgresStore.saveWorldState(clean, serialized, ownership);
      if (saved) {
        markWorldRevisionPersisted(clean, serialized.world_revision);
        writeWorldStateJsonBackup(clean, serialized);
      }
      return saved;
    }).then((result) => result.ok && result.value === true);
    const write = trackPersistenceWrite(operation, `world state ${clean}`);
    worldSaveWrites.set(clean, write);
    return write;
  }

  writeWorldStateJsonBackup(clean, serialized);
  if (POSTGRES_ENABLED && POSTGRES_AUTHORITATIVE) {
    console.warn("[world-persistence] authoritative save rejected while PostgreSQL is unavailable", {
      world_id: clean,
      server_instance: SERVER_INSTANCE_ID,
      ownership_token: worldPersistenceOwnership.get(clean)?.ownership_token || "",
      ownership_epoch: worldPersistenceOwnership.get(clean)?.ownership_epoch || 0,
      loaded_revision: PersistenceHelpers.normalizeWorldRevision(worldPersistedRevisions.get(clean)),
      mutation_revision: PersistenceHelpers.normalizeWorldRevision(serialized.world_revision),
      requested_save_revision: PersistenceHelpers.normalizeWorldRevision(serialized.world_revision),
      persisted_revision: PersistenceHelpers.normalizeWorldRevision(worldPersistedRevisions.get(clean)),
      affected_row_count: 0,
      save_result: "postgres_unavailable",
    });
    const failedWrite = trackPersistenceWrite(
      Promise.resolve(false),
      `world state ${clean}`
    ) as Promise<boolean>;
    worldSaveWrites.set(clean, failedWrite);
    return failedWrite;
  }
  markWorldRevisionPersisted(clean, serialized.world_revision);
  return Promise.resolve(true);
}

/**
 * @param {string} worldName
 * @param {PixelMania.WorldChangeEntry[]} changes
 * @param {PixelMania.CommitWorldStateWithBlockChangesOptions} options
 * @returns {Promise<PixelMania.CommitWorldStateWithBlockChangesResult>}
 */
async function commitWorldStateWithBlockChanges(worldName: any, changes: any = [], options: any = {}) {
  const clean = cleanWorld(worldName);
  advanceAuthoritativeWorldRevision(clean, options.reason || changes?.[0]?.action || "world_state_change");
  const serialized = serializeWorldState(clean);

  if (isPostgresAuthoritativeReady()) {
    const persistence = await runOwnedWorldPersistence(clean, options.reason || "world_state_change", (ownership) => (
      postgresStore.saveWorldStateWithWorldChanges(clean, serialized, changes, ownership)
    ));
    const result = persistence.value as ServerPacketRecord | undefined;
    if (!persistence.ok || !result || result.ok !== true) {
      return {
        ok: false,
        reason: persistence.reason || result?.reason || "postgres_failed",
        message: result?.reason === "postgres_unavailable"
          ? "PostgreSQL is not ready."
          : "PostgreSQL rejected the world update.",
      };
    }
    markWorldRevisionPersisted(clean, serialized.world_revision);
    writeWorldStateJsonBackup(clean, serialized);
    return { ok: true, postgres_committed: true, serialized };
  }

  if (POSTGRES_ENABLED && POSTGRES_AUTHORITATIVE && !shouldAllowPhase7DevJsonFallback(options.player || null, null, {
    ...options,
    world: clean,
  })) {
    return { ok: false, reason: "postgres_unavailable", message: "PostgreSQL is not ready." };
  }

  saveWorldState(clean, { mutation: false, reason: options.reason || "world_state_change" });
  return { ok: true, postgres_committed: false, serialized };
}

/**
 * @param {string} worldName
 * @returns {Promise<PixelMania.WorldStateCommitResult>}
 */
async function commitWorldEventStateOnly(worldName: any) {
  const clean = cleanWorld(worldName);
  if (!shouldPersistWholeWorldState(clean, "world_event_state")) {
    return { ok: false, postgres_committed: false, skipped: true, reason: "non_owner_route" };
  }
  advanceAuthoritativeWorldRevision(clean, "world_event_state");
  const serialized = serializeWorldState(clean);

  if (isPostgresAuthoritativeReady()) {
    const persistence = await runOwnedWorldPersistence(clean, "world_event_state", (ownership) => (
      postgresStore.saveWorldState(clean, serialized, ownership)
    ));
    if (!persistence.ok || persistence.value !== true) {
      return { ok: false, reason: "database_error", message: "PostgreSQL rejected the world event update." };
    }
    markWorldRevisionPersisted(clean, serialized.world_revision);
    writeWorldStateJsonBackup(clean, serialized);
    return { ok: true, postgres_committed: true, serialized };
  }

  if (POSTGRES_ENABLED && POSTGRES_AUTHORITATIVE) {
    return { ok: false, reason: "postgres_unavailable", message: "PostgreSQL is not ready." };
  }

  saveWorldState(clean, { mutation: false, reason: "world_event_state" });
  return { ok: true, postgres_committed: false, serialized };
}

function clearWorldEventState(state: any) {
  if (!state) return;
  state.active_event_type = "";
  state.event_id = "";
  state.event_started_at = "";
  state.event_ends_at = "";
  state.event_changed_tiles = [];
}

function hasActiveSnowStormEvent(state: any) {
  if (!state || state.active_event_type !== SNOW_STORM_EVENT_TYPE) return false;
  const endsAt = Date.parse(state.event_ends_at || "");
  return Number.isFinite(endsAt) && endsAt > Date.now();
}

function consumeSnowStormCommandCooldown(worldName: any) {
  if (SNOW_STORM_EVENT_COMMAND_COOLDOWN_MS <= 0) return { ok: true, retry_ms: 0 };

  const key = `${cleanWorld(worldName)}:${SNOW_STORM_EVENT_TYPE}`;
  const now = Date.now();
  const lastActionAt = Number(worldEventCommandCooldowns.get(key) || 0);
  const retryMs = SNOW_STORM_EVENT_COMMAND_COOLDOWN_MS - (now - lastActionAt);
  if (retryMs > 0) {
    return { ok: false, retry_ms: retryMs };
  }

  worldEventCommandCooldowns.set(key, now);
  return { ok: true, retry_ms: 0 };
}

function buildWorldEventStartedMessage(worldName: any, state: any) {
  return {
    type: "event_started",
    world: cleanWorld(worldName),
    event_type: SNOW_STORM_EVENT_TYPE,
    event_name: SNOW_STORM_EVENT_TYPE,
    event_id: state?.event_id || "",
    started_at: state?.event_started_at || "",
    ends_at: state?.event_ends_at || "",
    duration_ms: SNOW_STORM_EVENT_DURATION_MS,
    remaining_ms: getActiveWorldEventRemainingMs(state),
    message: SNOW_STORM_SYSTEM_MESSAGE,
  };
}

function buildActiveWorldEventTileUpdates(worldName: any, state: any) {
  const clean = cleanWorld(worldName);
  if (!hasActiveSnowStormEvent(state)) return [];
  const eventId = state.event_id || "";
  const tiles = Array.isArray(state.event_changed_tiles) ? state.event_changed_tiles : [];
  const updates: any = [];

  for (const rawTile of tiles) {
    const tile = normalizeWorldEventTileEntry(rawTile, eventId);
    if (tile.event_block_id === "") continue;
    updates.push({
      type: "world_block_update",
      action: "place",
      layer: "foreground",
      x: tile.x,
      y: tile.y,
      block_type: tile.event_block_id,
      world: clean,
    });
  }

  return updates;
}

function sendEventTileUpdatesToSocket(socket: any, worldName: any, eventId: any, phase: any, updates: any = []) {
  const clean = cleanWorld(worldName);
  const safeUpdates = Array.isArray(updates) ? updates : [];
  const batchCount = Math.ceil(safeUpdates.length / SNOW_STORM_EVENT_TILE_BATCH_SIZE);

  for (let index: any = 0; index < safeUpdates.length; index += SNOW_STORM_EVENT_TILE_BATCH_SIZE) {
    sendJson(socket, {
      type: "event_tile_updates",
      world: clean,
      event_type: SNOW_STORM_EVENT_TYPE,
      event_id: eventId || "",
      phase,
      batch_index: Math.floor(index / SNOW_STORM_EVENT_TILE_BATCH_SIZE),
      batch_count: batchCount,
      updates: safeUpdates.slice(index, index + SNOW_STORM_EVENT_TILE_BATCH_SIZE),
    });
  }
}

function sendActiveWorldEventState(socket: any, worldName: any) {
  const state = ensureWorldState(worldName);
  if (!hasActiveSnowStormEvent(state)) return;
  sendJson(socket, buildWorldEventStartedMessage(worldName, state));
  sendEventTileUpdatesToSocket(
    socket,
    worldName,
    state.event_id || "",
    "sync",
    buildActiveWorldEventTileUpdates(worldName, state)
  );
}

function buildWorldEventEndedMessage(worldName: any, eventId: any = "", endedAt: any = new Date().toISOString()) {
  return {
    type: "event_ended",
    world: cleanWorld(worldName),
    event_type: SNOW_STORM_EVENT_TYPE,
    event_name: SNOW_STORM_EVENT_TYPE,
    event_id: eventId,
    ended_at: endedAt,
  };
}

function broadcastEventSystemMessage(worldName: any, eventId: any, message: any) {
  broadcastToWorld(worldName, {
    type: "event_system_message",
    world: cleanWorld(worldName),
    event_type: SNOW_STORM_EVENT_TYPE,
    event_id: eventId || "",
    message,
  });
  broadcastSystemToWorld(worldName, message);
}

function buildSnowStormCountdownMessage(label: any) {
  return `Snow Storm has ${label} left.`;
}

function clearWorldEventCountdownTimers(worldName: any) {
  const clean = cleanWorld(worldName);
  const timers = worldEventCountdownTimers.get(clean);
  if (Array.isArray(timers)) {
    for (const timer of timers) {
      clearTimeout(timer);
    }
  }
  worldEventCountdownTimers.delete(clean);
}

function scheduleWorldEventCountdowns(worldName: any) {
  const clean = cleanWorld(worldName);
  clearWorldEventCountdownTimers(clean);

  const state = ensureWorldState(clean);
  if (state.active_event_type !== SNOW_STORM_EVENT_TYPE) return;

  const endsAt = Date.parse(state.event_ends_at || "");
  if (!Number.isFinite(endsAt)) return;

  const eventId = state.event_id || "";
  const timers: any = [];
  for (const countdown of SNOW_STORM_COUNTDOWN_MESSAGES) {
    const fireInMs = endsAt - countdown.remainingMs - Date.now();
    if (fireInMs <= 0) continue;
    const timer = setTimeout(() => {
      const liveState = ensureWorldState(clean);
      if (liveState.active_event_type !== SNOW_STORM_EVENT_TYPE) return;
      if ((liveState.event_id || "") !== eventId) return;
      broadcastEventSystemMessage(clean, liveState.event_id || "", buildSnowStormCountdownMessage(countdown.label));
    }, fireInMs);
    if (typeof timer.unref === "function") timer.unref();
    timers.push(timer);
  }

  if (timers.length > 0) {
    worldEventCountdownTimers.set(clean, timers);
  }
}

function sleepMs(ms: any) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

async function broadcastEventTileUpdates(worldName: any, eventId: any, phase: any, updates: any = []) {
  const clean = cleanWorld(worldName);
  const safeUpdates = Array.isArray(updates) ? updates : [];
  const batchCount = Math.ceil(safeUpdates.length / SNOW_STORM_EVENT_TILE_BATCH_SIZE);
  for (let index: any = 0; index < safeUpdates.length; index += SNOW_STORM_EVENT_TILE_BATCH_SIZE) {
    const batch = safeUpdates.slice(index, index + SNOW_STORM_EVENT_TILE_BATCH_SIZE);
    broadcastToWorld(clean, {
      type: "event_tile_updates",
      world: clean,
      event_type: SNOW_STORM_EVENT_TYPE,
      event_id: eventId || "",
      phase,
      batch_index: Math.floor(index / SNOW_STORM_EVENT_TILE_BATCH_SIZE),
      batch_count: batchCount,
      updates: batch,
    });
    if (
      SNOW_STORM_EVENT_BROADCAST_BATCH_DELAY_MS > 0 &&
      index + SNOW_STORM_EVENT_TILE_BATCH_SIZE < safeUpdates.length
    ) {
      await sleepMs(SNOW_STORM_EVENT_BROADCAST_BATCH_DELAY_MS);
    }
  }
}

function scheduleWorldEventEnd(worldName: any) {
  const clean = cleanWorld(worldName);
  const existing = worldEventTimers.get(clean);
  if (existing) clearTimeout(existing);
  worldEventTimers.delete(clean);
  scheduleWorldEventCountdowns(clean);

  const state = ensureWorldState(clean);
  if (state.active_event_type !== SNOW_STORM_EVENT_TYPE) return;

  const endsAt = Date.parse(state.event_ends_at || "");
  if (!Number.isFinite(endsAt)) return;
  const timer = setTimeout(() => {
    worldEventTimers.delete(clean);
    endSnowStormEvent(clean, { reason: "timer" }).catch((error) => {
      console.warn("[world_event] snow_storm end failed:", error.message);
    });
  }, Math.max(0, endsAt - Date.now()));
  if (typeof timer.unref === "function") timer.unref();
  worldEventTimers.set(clean, timer);
}

async function recoverWorldEventsAfterLoad() {
  for (const [worldName, state] of worldStates.entries()) {
    if (!state || state.active_event_type !== SNOW_STORM_EVENT_TYPE) continue;
    const endsAt = Date.parse(state.event_ends_at || "");
    if (!Number.isFinite(endsAt) || endsAt <= Date.now()) {
      await endSnowStormEvent(worldName, { reason: "startup_expired", broadcast: false });
    } else {
      scheduleWorldEventEnd(worldName);
    }
  }
}

function startWorldEventRandomScheduler() {
  if (!SNOW_STORM_RANDOM_EVENTS_ENABLED || worldEventRandomTimer) return;
  worldEventRandomTimer = setInterval(() => {
    tryStartRandomSnowStormEvent().catch((error) => {
      console.warn("[world_event] random snow_storm start failed:", error.message);
    });
  }, SNOW_STORM_RANDOM_INTERVAL_MS);
  if (typeof worldEventRandomTimer.unref === "function") worldEventRandomTimer.unref();
}

function getActiveWorldNamesForEvents() {
  const names: any = [];
  for (const worldName of Array.from<any>(worldPlayers.keys())) {
    if (getWorldPopulationCount(worldName) > 0) names.push(worldName);
  }
  return names;
}

async function tryStartRandomSnowStormEvent() {
  const activeWorlds = getActiveWorldNamesForEvents()
    .filter((worldName: string) =>
      !hasActiveSnowStormEvent(ensureWorldState(worldName)) &&
      !hasSnowRepellentBlock(worldName) &&
      !ServerLandfillEventModule.isLandfillWorldName(worldName));
  if (activeWorlds.length === 0) return { ok: false, reason: "no_active_world" };
  if (!randomChance(SNOW_STORM_RANDOM_CHANCE)) return { ok: false, reason: "chance_missed" };

  const worldName = activeWorlds[crypto.randomInt(0, activeWorlds.length)];
  return startSnowStormEvent(worldName, { reason: "random" });
}

function makeDeterministicRng(seedText: any) {
  const digest = crypto.createHash("sha256").update(String(seedText || "")).digest();
  let state: any = digest.readUInt32LE(0) || 0x6d2b79f5;
  return () => {
    state = (state + 0x6d2b79f5) >>> 0;
    let value: any = state;
    value = Math.imul(value ^ (value >>> 15), value | 1);
    value ^= value + Math.imul(value ^ (value >>> 7), value | 61);
    return ((value ^ (value >>> 14)) >>> 0) / 4294967296;
  };
}

function deterministicInt(rng: any, min: any, max: any) {
  const safeMin = Math.trunc(Number(min) || 0);
  const safeMax = Math.trunc(Number(max) || safeMin);
  if (safeMax <= safeMin) return safeMin;
  return safeMin + Math.floor(rng() * (safeMax - safeMin + 1));
}

function deterministicTileVariantIndex(x: any, y: any, count: any, salt: any = 0) {
  const safeCount = Math.trunc(Number(count) || 0);
  if (safeCount <= 1) return 0;
  const value = (
    Math.trunc(Number(x) || 0) * 73856093 +
    Math.trunc(Number(y) || 0) * 19349663 +
    Math.trunc(Number(salt) || 0) * 83492791
  );
  return ((value % safeCount) + safeCount) % safeCount;
}

function serverWorldGenerationSeed(worldName: any) {
  const source = `PIXELMANIA_WORLD_${cleanWorld(worldName).toUpperCase() || "START"}`;
  let value: any = 173;
  for (let i: any = 0; i < source.length; i += 1) {
    value = (value * 131 + source.charCodeAt(i)) % 2147483647;
  }
  return Math.max(1, value);
}

function serverCellNoise(generationSeed: any, x: any, y: any, salt: any = 0) {
  const seedOffset = (generationSeed % 1000003) * 0.0001;
  const value = Math.sin((Number(x) || 0) * 12.9898 + (Number(y) || 0) * 78.233 + (Number(salt) || 0) * 37.719 + seedOffset) * 43758.5453123;
  return value - Math.floor(value);
}

// worldName is optional -- omitted, these reproduce the exact generic (non-Landfill) numbers every
// other world already used, so the few call sites that can't easily thread a worldName through
// (e.g. serverSurfaceBlockType's flatness heuristic) are unaffected. Passed, they switch to the
// LANDFILL_TERRAIN_* shape for any world isLandfillWorldName recognizes.
function serverGenerationMinSurfaceY(worldName: unknown = null) {
  const isLandfill = ServerLandfillEventModule.isLandfillWorldName(worldName);
  const offset = isLandfill ? LANDFILL_TERRAIN_SURFACE_VERTICAL_OFFSET : SERVER_TERRAIN_SURFACE_VERTICAL_OFFSET;
  const range = isLandfill ? LANDFILL_TERRAIN_EXTRA_HILL_RANGE : SERVER_TERRAIN_EXTRA_HILL_RANGE;
  return Math.max(3, (BEDROCK_START_Y - 15) + offset - range);
}

function serverGenerationMaxSurfaceY(worldName: unknown = null) {
  const isLandfill = ServerLandfillEventModule.isLandfillWorldName(worldName);
  const offset = isLandfill ? LANDFILL_TERRAIN_SURFACE_VERTICAL_OFFSET : SERVER_TERRAIN_SURFACE_VERTICAL_OFFSET;
  const range = isLandfill ? LANDFILL_TERRAIN_EXTRA_HILL_RANGE : SERVER_TERRAIN_EXTRA_HILL_RANGE;
  return Math.max(serverGenerationMinSurfaceY(worldName), (BEDROCK_START_Y - 8) + offset + range);
}

function serverGenerationSurfaceBaseY(worldName: unknown = null) {
  const isLandfill = ServerLandfillEventModule.isLandfillWorldName(worldName);
  const offset = isLandfill ? LANDFILL_TERRAIN_SURFACE_VERTICAL_OFFSET : SERVER_TERRAIN_SURFACE_VERTICAL_OFFSET;
  return clampInteger(
    (BEDROCK_START_Y - 9) + offset,
    serverGenerationMinSurfaceY(worldName),
    serverGenerationMaxSurfaceY(worldName)
  );
}

function isServerSpawnSafeColumn(x: any) {
  return Math.abs(Math.trunc(Number(x) || 0) - 10) <= 3;
}

function buildServerTerrainSurface(worldName: any) {
  const generationSeed = serverWorldGenerationSeed(worldName);
  const isLandfill = ServerLandfillEventModule.isLandfillWorldName(worldName);
  const baseSurfaceY = serverGenerationSurfaceBaseY(worldName);
  const minSurfaceY = serverGenerationMinSurfaceY(worldName);
  const maxSurfaceY = serverGenerationMaxSurfaceY(worldName);
  const phaseA = serverCellNoise(generationSeed, 1, 1, 5001) * Math.PI * 2;
  const phaseB = serverCellNoise(generationSeed, 2, 1, 5002) * Math.PI * 2;
  const phaseC = serverCellNoise(generationSeed, 3, 1, 5003) * Math.PI * 2;
  // Landfill uses a lower-frequency, similar-or-larger-amplitude wave (broad sweeping mounds) and a
  // smaller per-column jitter range (less small-scale jaggedness) -- see the LANDFILL_TERRAIN_*
  // constants for why. Every non-Landfill world keeps the exact original numbers.
  const wave1Frequency = isLandfill ? LANDFILL_TERRAIN_WAVE1_FREQUENCY : 0.070;
  const wave1Amplitude = isLandfill ? LANDFILL_TERRAIN_WAVE1_AMPLITUDE : 4.8;
  const wave2Frequency = isLandfill ? LANDFILL_TERRAIN_WAVE2_FREQUENCY : 0.145;
  const wave2Amplitude = isLandfill ? LANDFILL_TERRAIN_WAVE2_AMPLITUDE : 2.4;
  const wave3Frequency = isLandfill ? LANDFILL_TERRAIN_WAVE3_FREQUENCY : 0.310;
  const wave3Amplitude = isLandfill ? LANDFILL_TERRAIN_WAVE3_AMPLITUDE : 1.2;
  const driftRange = isLandfill ? LANDFILL_TERRAIN_DRIFT_RANGE : 4;
  const surface: any = new Map();

  for (let x: any = 0; x < WORLD_WIDTH; x += 1) {
    if (isServerSpawnSafeColumn(x)) {
      surface.set(x, baseSurfaceY);
      continue;
    }

    const drift = Math.round((serverCellNoise(generationSeed, Math.floor(x / 6), 0, 5004) - 0.5) * driftRange);
    const wave1 = Math.sin(x * wave1Frequency + phaseA) * wave1Amplitude;
    const wave2 = Math.sin(x * wave2Frequency + phaseB) * wave2Amplitude;
    const wave3 = Math.sin(x * wave3Frequency + phaseC) * wave3Amplitude;
    surface.set(x, clampInteger(Math.round(baseSurfaceY + wave1 + wave2 + wave3 + drift), minSurfaceY, maxSurfaceY));
  }

  for (let pass: any = 0; pass < 3; pass += 1) {
    for (let x: any = 1; x < WORLD_WIDTH - 1; x += 1) {
      if (isServerSpawnSafeColumn(x)) {
        surface.set(x, baseSurfaceY);
        continue;
      }

      let current: any = surface.get(x);
      const left = surface.get(x - 1);
      const right = surface.get(x + 1);
      if (current < left - 1) current = left - 1;
      if (current > left + 1) current = left + 1;
      if (current < right - 1) current = right - 1;
      if (current > right + 1) current = right + 1;
      surface.set(x, clampInteger(current, minSurfaceY, maxSurfaceY));
    }
  }

  return { generationSeed, surface };
}

function serverSurfaceYAt(surface: any, x: any) {
  const safeX = clampInteger(x, 0, WORLD_WIDTH - 1);
  return surface.has(safeX) ? surface.get(safeX) : serverGenerationSurfaceBaseY();
}

function serverPickWeightedBlock(generationSeed: any, x: any, y: any, options: any) {
  const total = options.reduce(
    (sum: number, option: ServerPacketRecord) => sum + Math.max(0, Number(option.weight) || 0),
    0,
  );
  if (total <= 0) return "dirt";
  let roll: any = serverCellNoise(generationSeed, x, y, 9047) * total;
  for (const option of options) {
    roll -= Math.max(0, Number(option.weight) || 0);
    if (roll <= 0) return option.type || "dirt";
  }
  return options[options.length - 1]?.type || "dirt";
}

function isServerBottomLavaStoneLayer(y: any) {
  const depth = BEDROCK_START_Y - Math.trunc(Number(y) || 0);
  return depth >= 1 && depth <= SERVER_BOTTOM_LAVA_STONE_HEIGHT;
}

function getEffectiveGeneratedBottomForegroundBlockAt(worldName: any, state: any, x: any, y: any) {
  const gridX = Math.trunc(Number(x) || 0);
  const gridY = Math.trunc(Number(y) || 0);
  if (!state || state.cleared || !isGridInWorld(gridX, gridY) || !isServerBottomLavaStoneLayer(gridY)) {
    return null;
  }

  const key = gridKey(gridX, gridY);
  if (state.foreground.has(key)) return state.foreground.get(key);
  if (state.removed_foreground.has(key)) return null;

  const generationSeed = serverWorldGenerationSeed(worldName);
  const blockType = serverGeneratedBlockType(
    worldName,
    generationSeed,
    gridX,
    gridY,
    serverGenerationSurfaceBaseY(worldName)
  );
  if (blockType === "") return null;

  return {
    x: gridX,
    y: gridY,
    block_type: blockType,
    source: "generated",
  };
}

function serverShallowCaveAxis(generationSeed: any, x: any, surfaceY: any) {
  return surfaceY + 13 + Math.round((serverCellNoise(generationSeed, x, surfaceY, 801) - 0.5) * 5.6 + (serverCellNoise(generationSeed, surfaceY, x, 802) - 0.5) * 4.0);
}

function serverDeepCaveAxis(generationSeed: any, x: any, surfaceY: any) {
  return surfaceY + 23 + Math.round((serverCellNoise(generationSeed, x, surfaceY, 803) - 0.5) * 7.6 + (serverCellNoise(generationSeed, surfaceY, x, 804) - 0.5) * 3.6);
}

function shouldServerGenerateCavePocket(worldName: unknown, generationSeed: any, x: any, y: any, surfaceY: any) {
  // Landfill: "full" terrain per Hassan -- no hollow cave pockets underground at all.
  if (ServerLandfillEventModule.isLandfillWorldName(worldName)) return false;
  const depth = y - surfaceY;
  if (depth < SERVER_CAVE_MIN_DEPTH) return false;
  if (isServerSpawnSafeColumn(x)) return false;
  if (y >= BEDROCK_START_Y - SERVER_CAVE_BOTTOM_SOLID_PADDING) return false;
  if (isServerBottomLavaStoneLayer(y)) return false;

  if (depth >= SERVER_SHALLOW_CAVE_START_DEPTH) {
    const axis = serverShallowCaveAxis(generationSeed, x, surfaceY);
    const distance = Math.abs(y - axis);
    const width = 1.2 + (serverCellNoise(generationSeed, x, surfaceY, 1203) * 1.35);
    if (distance <= width && serverCellNoise(generationSeed, x, y, 2281) < 0.90) return true;
    if (distance <= width + 1 && serverCellNoise(generationSeed, x, y, 3359) < 0.22) return true;
  }

  if (depth >= SERVER_DEEP_CAVE_START_DEPTH) {
    const axis = serverDeepCaveAxis(generationSeed, x, surfaceY);
    const distance = Math.abs(y - axis);
    const width = 0.9 + (serverCellNoise(generationSeed, x, surfaceY, 3359) * 1.1);
    if (serverCellNoise(generationSeed, surfaceY, y, 2281) > 0.72) {
      if (distance <= width && serverCellNoise(generationSeed, x, y, 401) < 0.85) return true;
      if (distance <= width + 1 && serverCellNoise(generationSeed, x, y, 402) < 0.18) return true;
    }
  }

  if (depth >= 12 && serverCellNoise(generationSeed, x * 3, y * 3, 601) > 0.68 && serverCellNoise(generationSeed, x, y, 602) < 0.28) return true;
  if (depth >= 16 && serverCellNoise(generationSeed, x, y, 603) < 0.018) return true;
  return false;
}

function serverSurfaceBlockType(generationSeed: any, x: any, y: any, surfaceY: any) {
  if (isServerSpawnSafeColumn(x)) {
    return serverPickWeightedBlock(generationSeed, x, y, [
      { type: "dirt", weight: 86 },
      { type: "sand", weight: 7 },
      { type: "stone", weight: 7 },
    ]);
  }

  const span = Math.max(1, serverGenerationMaxSurfaceY() - serverGenerationMinSurfaceY());
  const flatness = Math.max(0, Math.min(1, (surfaceY - serverGenerationMinSurfaceY()) / span));
  if (flatness > 0.73 && serverCellNoise(generationSeed, x, surfaceY, 901) < 0.20) return "sand";
  if (serverCellNoise(generationSeed, surfaceY, x, 902) > 0.90) {
    return serverPickWeightedBlock(generationSeed, x, y, [
      { type: "stone", weight: 56 },
      { type: "dirt", weight: 34 },
      { type: "sand", weight: 10 },
    ]);
  }
  return serverPickWeightedBlock(generationSeed, x, y, [
    { type: "dirt", weight: 84 },
    { type: "sand", weight: 9 },
    { type: "stone", weight: 7 },
  ]);
}

function serverNormalUndergroundBlockType(generationSeed: any, x: any, y: any, depth: any) {
  if (depth <= 5) {
    return serverPickWeightedBlock(generationSeed, x, y, [
      { type: "dirt", weight: 89 },
      { type: "stone", weight: 7 },
      { type: "sand", weight: 4 },
    ]);
  }
  if (depth <= 16) {
    return serverPickWeightedBlock(generationSeed, x, y, [
      { type: "dirt", weight: 80 },
      { type: "stone", weight: 13 },
      { type: "sand", weight: 7 },
    ]);
  }
  if (depth <= 24) {
    return serverPickWeightedBlock(generationSeed, x, y, [
      { type: "dirt", weight: 68 },
      { type: "stone", weight: 24 },
      { type: "sand", weight: 8 },
    ]);
  }
  if (depth <= 34) {
    return serverPickWeightedBlock(generationSeed, x, y, [
      { type: "dirt", weight: 55 },
      { type: "stone", weight: 37 },
      { type: "sand", weight: 8 },
    ]);
  }
  return serverPickWeightedBlock(generationSeed, x, y, [
    { type: "dirt", weight: 40 },
    { type: "stone", weight: 53 },
    { type: "sand", weight: 8 },
  ]);
}

function serverGeneratedBlockType(worldName: unknown, generationSeed: any, x: any, y: any, surfaceY: any) {
  if (y >= BEDROCK_START_Y) return "bedrock";
  if (y < surfaceY) return "";
  if (y === surfaceY) return serverSurfaceBlockType(generationSeed, x, y, surfaceY);
  const depth = y - surfaceY;
  if (isServerBottomLavaStoneLayer(y)) {
    return serverPickWeightedBlock(generationSeed, x, y, [
      { type: "stone", weight: 62 },
      { type: "lava", weight: 28 },
      { type: "dirt", weight: 10 },
    ]);
  }
  if (isServerSpawnSafeColumn(x)) {
    return serverPickWeightedBlock(generationSeed, x, y, depth <= 9
      ? [
        { type: "dirt", weight: 88 },
        { type: "stone", weight: 9 },
        { type: "sand", weight: 3 },
      ]
      : [
        { type: "dirt", weight: 80 },
        { type: "stone", weight: 15 },
        { type: "sand", weight: 5 },
      ]);
  }
  if (shouldServerGenerateCavePocket(worldName, generationSeed, x, y, surfaceY)) return "";
  return serverNormalUndergroundBlockType(generationSeed, x, y, depth);
}

function serverMapSet(map: any, x: any, y: any, blockType: any) {
  const key = gridKey(x, y);
  if (blockType === "") {
    map.delete(key);
    return;
  }
  map.set(key, { x, y, block_type: blockType, source: "generated" });
}

function serverMapSetIfEmpty(map: any, x: any, y: any, blockType: any) {
  const key = gridKey(x, y);
  if (map.has(key)) return false;
  serverMapSet(map, x, y, blockType);
  return true;
}

function serverMapClear(map: any, x: any, y: any) {
  if (!map) return;
  map.delete(gridKey(x, y));
}

function shouldServerPlaceCaveBackground(worldName: unknown, generationSeed: any, blockType: any, x: any, y: any, surfaceY: any) {
  if (y <= surfaceY) return false;
  if (y >= BEDROCK_START_Y) return false;
  if (blockType === "water") return false;
  if (["dirt", "sand", "stone", "lava"].includes(blockType)) return true;
  return blockType === "" && shouldServerGenerateCavePocket(worldName, generationSeed, x, y, surfaceY);
}

function serverCanGenerateNaturalPond(map: any, surface: any, centerX: any, width: any) {
  const half = Math.floor(width * 0.5);
  let minSurface: any = 999999;
  let maxSurface: any = -999999;
  for (let x: any = centerX - half; x <= centerX + half; x += 1) {
    if (x <= 2 || x >= WORLD_WIDTH - 3) return false;
    if (isServerSpawnSafeColumn(x)) return false;
    const surfaceY = serverSurfaceYAt(surface, x);
    minSurface = Math.min(minSurface, surfaceY);
    maxSurface = Math.max(maxSurface, surfaceY);
    const top = map.get(gridKey(x, surfaceY))?.block_type || "";
    const below = map.get(gridKey(x, surfaceY + 1))?.block_type || "";
    if (!["dirt", "sand", "stone", "grass"].includes(top)) return false;
    if (!["dirt", "sand", "stone"].includes(below)) return false;
  }
  return maxSurface - minSurface <= 1;
}

function serverCreateNaturalPond(map: any, surface: any, rng: any, centerX: any, width: any, backgroundMap: any = null) {
  const half = Math.floor(width * 0.5);
  const startX = centerX - half;
  const endX = centerX + half;
  let surfaceYForPond: any = -999999;
  const profileNoise = deterministicInt(rng, 0, 2147483646);
  for (let x: any = startX; x <= endX; x += 1) {
    surfaceYForPond = Math.max(surfaceYForPond, serverSurfaceYAt(surface, x));
  }
  const waterSurfaceY = surfaceYForPond + 1;

  for (let x: any = startX; x <= endX; x += 1) {
    const distanceFromCenter = Math.abs(x - centerX);
    const edgeCurve = Math.floor(SERVER_POND_EDGE_DEPTH + Math.sin(distanceFromCenter * 0.65 + profileNoise * 0.001));
    const carveDepth = clampInteger(SERVER_POND_CENTER_DEPTH + edgeCurve, SERVER_POND_EDGE_DEPTH, SERVER_POND_CENTER_DEPTH + 2);

    for (let y: any = serverSurfaceYAt(surface, x); y <= waterSurfaceY + SERVER_POND_CENTER_DEPTH + 1; y += 1) {
      const localDepth = y - waterSurfaceY;
      serverMapClear(backgroundMap, x, y);
      if (x === startX || x === endX) {
        serverMapSet(map, x, y, "dirt");
        continue;
      }
      if (y < waterSurfaceY) {
        serverMapSet(map, x, y, "");
        continue;
      }
      let localVariation: any = 0;
      if (Math.abs(distanceFromCenter) > 1) {
        localVariation = (0.22 - serverCellNoise(1, x, distanceFromCenter, profileNoise % 1000)) * 1.4;
      }
      const pondDepth = clampInteger(carveDepth + Math.round(localVariation), SERVER_POND_EDGE_DEPTH, SERVER_POND_CENTER_DEPTH + 2);
      serverMapSet(map, x, y, localDepth < pondDepth ? "water" : "dirt");
    }
  }

  serverMapSet(map, startX + 1, waterSurfaceY, "dirt");
  serverMapSet(map, endX - 1, waterSurfaceY, "dirt");
  serverMapClear(backgroundMap, startX + 1, waterSurfaceY);
  serverMapClear(backgroundMap, endX - 1, waterSurfaceY);
}

function serverGenerateNaturalPonds(map: any, surface: any, rng: any, backgroundMap: any = null) {
  const pondCount = deterministicInt(rng, SERVER_POND_COUNT_MIN, SERVER_POND_COUNT_MAX);
  const usedCenters: any = [];
  let created: any = 0;
  for (let attempt: any = 0; attempt < SERVER_POND_ATTEMPT_LIMIT && created < pondCount; attempt += 1) {
    let width: any = deterministicInt(rng, SERVER_POND_WIDTH_MIN, SERVER_POND_WIDTH_MAX);
    if (width % 2 === 0) width += 1;
    const centerX = deterministicInt(rng, 8, WORLD_WIDTH - 9);
    const minSpacing = Math.max(7, width);
    if (isServerSpawnSafeColumn(centerX)) continue;
    if (usedCenters.some((usedX: number) => Math.abs(usedX - centerX) < minSpacing)) continue;
    if (!serverCanGenerateNaturalPond(map, surface, centerX, width)) continue;
    serverCreateNaturalPond(map, surface, rng, centerX, width, backgroundMap);
    usedCenters.push(centerX);
    created += 1;
  }
}

function serverGenerateSurfaceDecorations(map: any, surface: any, generationSeed: any, backgroundMap: any = null) {
  for (let x: any = 2; x < WORLD_WIDTH - 2; x += 1) {
    const surfaceY = serverSurfaceYAt(surface, x);
    const key = gridKey(x, surfaceY);
    const surfaceType = map.get(key)?.block_type || "";
    if (!["dirt", "sand", "stone"].includes(surfaceType)) continue;
    if (serverCellNoise(generationSeed, x, surfaceY, 7201) > SERVER_SURFACE_DECORATION_CHANCE) continue;
    if (serverCellNoise(generationSeed, Math.trunc(x * SERVER_SURFACE_DECORATION_NOISE_SCALE_X), Math.trunc(surfaceY * SERVER_SURFACE_DECORATION_NOISE_SCALE_Y), 7202) > SERVER_SURFACE_DECORATION_SPACING_GAP_MAX) continue;

    const selectionRoll = serverCellNoise(generationSeed, x, surfaceY + 1, 7201);
    const total = SERVER_SURFACE_DECORATION_GRASS_CHANCE + SERVER_SURFACE_DECORATION_ROSE_CHANCE + SERVER_SURFACE_DECORATION_TULIP_CHANCE;
    const normalized = total > 0 ? selectionRoll / total : 1;
    let decoration: any = "grass";
    if (normalized < (SERVER_SURFACE_DECORATION_TULIP_CHANCE / total)) {
      decoration = "sunflower";
    } else if (normalized < ((SERVER_SURFACE_DECORATION_TULIP_CHANCE + SERVER_SURFACE_DECORATION_ROSE_CHANCE) / total)) {
      decoration = "rose";
    }
    serverMapSet(map, x, surfaceY, decoration);
    serverMapClear(backgroundMap, x, surfaceY);
  }
}

function serverCreateTree(map: any, surface: any, generationSeed: any, rng: any, x: any, backgroundMap: any = null) {
  if (x <= 1 || x >= WORLD_WIDTH - 2) return false;
  const surfaceY = serverSurfaceYAt(surface, x);
  const groundType = map.get(gridKey(x, surfaceY))?.block_type || "";
  if (!["grass", "dirt", "sand", "stone", "rose", "sunflower"].includes(groundType)) return false;
  if (Math.abs(serverSurfaceYAt(surface, x - 1) - surfaceY) > 1) return false;
  if (Math.abs(serverSurfaceYAt(surface, x + 1) - surfaceY) > 1) return false;

  serverMapSet(map, x, surfaceY, "dirt");
  serverMapClear(backgroundMap, x, surfaceY);
  const baseY = surfaceY - 1;
  const trunkHeight = deterministicInt(rng, SERVER_TREE_MIN_HEIGHT, SERVER_TREE_MAX_HEIGHT);
  let trunkTilt: any = 0;
  if (serverCellNoise(generationSeed, x, surfaceY, 7101) > 0.9) {
    const tiltNoise = serverCellNoise(generationSeed, x + 10, surfaceY, 7102);
    if (tiltNoise < 0.33) trunkTilt = -1;
    else if (tiltNoise > 0.66) trunkTilt = 1;
  }

  const trunkPositions: any = [];
  for (let i: any = 0; i < trunkHeight; i += 1) {
    const trunkX = x + trunkTilt * Math.floor(i / 2);
    const trunkY = baseY - i;
    serverMapSetIfEmpty(map, trunkX, trunkY, "wood");
    trunkPositions.push({ x: trunkX, y: trunkY });
  }

  const top = trunkPositions[trunkPositions.length - 1];
  const leafCoreY = baseY - trunkHeight;
  let leafSpreadX: any = 2;
  if (trunkHeight >= 6) leafSpreadX = 3;
  if (trunkHeight >= 7) leafSpreadX = 4;

  for (let dy: any = -4; dy < 2; dy += 1) {
    let rowSpan: any = leafSpreadX;
    if (dy >= -1) rowSpan = Math.max(2, leafSpreadX - 1);
    else if (dy <= -3) rowSpan = Math.max(3, leafSpreadX + 1);
    else rowSpan = leafSpreadX + 1;
    rowSpan = clampInteger(rowSpan + Math.round((serverCellNoise(generationSeed, x, leafCoreY + dy, 7401) - 0.5) * 1.2), 2, leafSpreadX + 2);

    for (let dx: any = -rowSpan; dx <= rowSpan; dx += 1) {
      const leafX = top.x + dx;
      const leafY = leafCoreY + dy;
      if (!isGridInWorld(leafX, leafY)) continue;
      const dist = Math.abs(dx) + Math.abs(dy);
      if (dist > 8) continue;
      const leafNoise = serverCellNoise(generationSeed, leafX, leafY, 7400);
      const isEdge = Math.abs(dx) === rowSpan || dist >= 5;
      if (dy < -1 && dist <= 2 && leafNoise < 0.03) continue;
      if (isEdge && leafNoise < 0.28) continue;
      if (dist > 4 && leafNoise < 0.16) continue;
      if (dist > 5 && leafNoise < 0.35) continue;
      serverMapSetIfEmpty(map, leafX, leafY, "leaf");
    }
  }

  return true;
}

function isRefreshTokenValid(account: any, token: any) {
  return getServerAccountSessionHelpers().isRefreshTokenValid(account, token);
}

function serverGenerateTrees(map: any, surface: any, generationSeed: any, rng: any, backgroundMap: any = null) {
  let lastTreeX: any = -999;
  for (let x: any = 4; x < WORLD_WIDTH - 4; x += 1) {
    if (isServerSpawnSafeColumn(x)) continue;
    if (x - lastTreeX < 3) continue;
    const surfaceY = serverSurfaceYAt(surface, x);
    if (serverCellNoise(generationSeed, x, surfaceY, 7001) > SERVER_TREE_SURFACE_NOISE_THRESHOLD) continue;
    if (serverCellNoise(generationSeed, x * 2, surfaceY, 7002) < 0.03) continue;
    if (rng() >= SERVER_TREE_RANDOM_PLACEMENT_CHANCE) continue;
    if (serverCreateTree(map, surface, generationSeed, rng, x, backgroundMap)) lastTreeX = x;
  }
}

function applyServerDefaultEntranceGateToGeneratedMaps(worldName: any, state: any, foregroundMap: any, backgroundMap: any, surface: any) {
  if (!foregroundMap || state?.cleared || (state && findEntranceGateInState(state))) return;

  const gateX = clampInteger(Math.floor(WORLD_WIDTH * 0.5), 0, WORLD_WIDTH - 1);
  const surfaceY = serverSurfaceYAt(surface, gateX);
  const gateY = getGeneratedEntranceGateGridY(surfaceY, state);
  const gatePos: any = { x: gateX, y: gateY };
  const minX = Math.max(1, gateX - 3);
  const maxX = Math.min(WORLD_WIDTH - 2, gateX + 3);

  for (let x: any = minX; x <= maxX; x += 1) {
    for (let y: any = surfaceY - 5; y < surfaceY; y += 1) {
      if (!isGridInWorld(x, y)) continue;
      foregroundMap.delete(gridKey(x, y));
      serverMapClear(backgroundMap, x, y);
    }

    if (isGridInWorld(x, surfaceY)) {
      serverMapSet(foregroundMap, x, surfaceY, "grass");
      serverMapClear(backgroundMap, x, surfaceY);
    }

    for (let y: any = surfaceY + 1; y < Math.min(surfaceY + 4, BEDROCK_START_Y); y += 1) {
      if (!isGridInWorld(x, y)) continue;
      serverMapSet(foregroundMap, x, y, "dirt");
    }
  }

  ensureEntranceGateSupportInState({ foreground: foregroundMap, removed_foreground: new Map(), interactions: new Map(), seeds: new Map() }, gatePos);
  cleanupLegacyEntranceGateSupportInState({ foreground: foregroundMap, removed_foreground: new Map() }, gatePos);
  serverMapSet(foregroundMap, gatePos.x, gatePos.y, ENTRANCE_GATE_TYPE);
  serverMapClear(backgroundMap, gatePos.x, gatePos.y);
}

// The procedurally generated base terrain is a pure function of the world's generation
// seed, which serverWorldGenerationSeed derives solely from cleanWorld(worldName). It
// never changes at runtime -- player edits live in state.foreground / removed_foreground
// and are overlaid downstream by buildEffectiveForegroundMap.
//
// It was nonetheless rebuilt from scratch on every call: a WORLD_WIDTH x WORLD_HEIGHT
// noise pass plus pond, decoration and tree generation (~7,000 tiles, thousands of grid-key
// strings and entry objects, 3-10ms synchronously). Because every block place/break calls
// invalidateMovementCollisionCache, the next movement packet in that world paid the whole
// cost -- which is exactly the build-adjacent stutter players notice.
//
// Cache the base maps per world and clone them per call. Entries are never mutated in
// place (serverMapSet always assigns a fresh object and every consumer spread-copies), so
// a shallow clone is safe. Only the entrance-gate overlay, which reads live `state`, is
// re-applied per call.
const serverGeneratedBaseTerrainByWorld: Map<string, {
  foreground: Map<string, unknown>;
  background: Map<string, unknown>;
  surface: unknown;
}> = new Map();

function serverPickLandfillJunkBlock(generationSeed: unknown, x: unknown, y: unknown) {
  const total = LANDFILL_TRASH_JUNK_BLOCKS.reduce((sum, option) => sum + option.weight, 0);
  let roll = Number(serverCellNoise(generationSeed, x, y, 8402)) * total;
  for (const option of LANDFILL_TRASH_JUNK_BLOCKS) {
    roll -= option.weight;
    if (roll <= 0) return option.type;
  }
  return LANDFILL_TRASH_JUNK_BLOCKS[LANDFILL_TRASH_JUNK_BLOCKS.length - 1].type;
}

// Landfill-only post-process: randomly reskins the terrain that was just generated normally
// (dirt/sand/stone/grass/flowers/cave-background) with the trash blocks registered in
// atlas_items.json. No-op for every non-Landfill world. Runs AFTER decorations/trees so it sees
// (and can override) their output too, matching the design spec ("trash related blocks appear
// randomly, gets replaced by regular dirt/stone/sand/cave background/grass/flowers"). Confined to
// everywhere except the bottom lava/stone band and bedrock -- see the constants above for why.
// Builds (place=true) or tears down (place=false) the VISIBLE shifty-block starting pen that
// confines racers before GO.
//
// The invisible movement clamp (getLandfillEntryPenBounds -> applyLandfillEntryPenClamp) still
// backs this up; this exists so players can SEE the boundary instead of walking into nothing. Both
// are driven by the SAME state transition -- the pen is torn down at COUNTDOWN -> RACING, which is
// the same moment getLandfillEntryPenBounds starts returning null -- so the wall you can see and
// the wall you can feel can never disagree.
//
// Only the perimeter is filled, leaving the interior walkable, and only AIR cells are used:
// overwriting real terrain would leave holes in it when the pen came down, permanently scarring
// the map the race is about to run on. Teardown likewise removes only cells still holding a pen
// block, so nothing else can be destroyed by it.
function setLandfillEntryPenBlocks(worldName: unknown, bounds: unknown, place: unknown) {
  const clean = cleanWorld(worldName);
  const box = (bounds || {}) as { minX?: unknown; maxX?: unknown; minY?: unknown; maxY?: unknown };
  const minTileX = Math.max(0, Math.floor(Number(box.minX) / TILE_SIZE));
  const maxTileX = Math.min(WORLD_WIDTH - 1, Math.floor(Number(box.maxX) / TILE_SIZE));
  const minTileY = Math.max(0, Math.floor(Number(box.minY) / TILE_SIZE));
  const maxTileY = Math.min(WORLD_HEIGHT - 1, Math.floor(Number(box.maxY) / TILE_SIZE));
  if (!Number.isFinite(minTileX) || !Number.isFinite(maxTileX)) return;
  if (!Number.isFinite(minTileY) || !Number.isFinite(maxTileY)) return;
  if (minTileX > maxTileX || minTileY > maxTileY) return;

  const shouldPlace = place === true;
  const state = ensureWorldState(clean);
  const foreground = getWorldLayerMap(state, "foreground");
  const updates: Array<Record<string, unknown>> = [];

  for (let x = minTileX; x <= maxTileX; x += 1) {
    for (let y = minTileY; y <= maxTileY; y += 1) {
      if (x !== minTileX && x !== maxTileX && y !== minTileY && y !== maxTileY) continue;
      const existingType = String(foreground.get(gridKey(x, y))?.block_type || "");
      if (shouldPlace ? existingType !== "" : existingType !== LANDFILL_ENTRY_PEN_BLOCK) continue;

      const update: Record<string, unknown> = {
        action: shouldPlace ? "place" : "break",
        layer: "foreground",
        x,
        y,
        block_type: LANDFILL_ENTRY_PEN_BLOCK,
        world: clean,
      };
      // The canonical mutation path -- it assigns the block revision, keeps the removed-layer map
      // consistent and invalidates the movement collision cache, none of which a raw map.set would.
      applyBlockUpdateToWorldState(clean, update);
      update.type = "world_block_update";
      updates.push(update);
    }
  }

  if (updates.length === 0) return;
  console.log("[landfill] entry pen " + (shouldPlace ? "built" : "cleared"), {
    world: clean,
    cells: updates.length,
    tile_box: `${minTileX},${minTileY} -> ${maxTileX},${maxTileY}`,
  });
  queueWorldSave(clean);
  // Reuses the bulk-tile channel the Snow Storm event already uses and the client already renders
  // (handle_world_event_tile_updates), rather than emitting one packet per cell. That handler does
  // not filter on event_type, so a Landfill-specific type is safe here.
  broadcastToWorld(clean, {
    type: "event_tile_updates",
    world: clean,
    event_type: "landfill_entry_pen",
    event_id: clean,
    phase: shouldPlace ? "start" : "end",
    batch_index: 0,
    batch_count: 1,
    updates,
  });
}

function serverApplyLandfillTrashOverlay(
  worldName: unknown,
  foreground: Map<string, any>,
  background: Map<string, any>,
  surface: unknown,
  generationSeed: unknown,
) {
  if (!ServerLandfillEventModule.isLandfillWorldName(worldName)) return;
  for (let x = 0; x < WORLD_WIDTH; x += 1) {
    const surfaceY = serverSurfaceYAt(surface, x);
    for (let y = surfaceY; y < WORLD_HEIGHT; y += 1) {
      if (y >= BEDROCK_START_Y || isServerBottomLavaStoneLayer(y)) continue;
      const key = gridKey(x, y);
      const foregroundType = foreground.get(key)?.block_type || "";
      if (y === surfaceY) {
        if (["dirt", "sand", "stone", "grass", "rose", "sunflower"].includes(foregroundType)) {
          if (serverCellNoise(generationSeed, x, y, 8401) < LANDFILL_TRASH_JUNK_CHANCE) {
            serverMapSet(foreground, x, y, serverPickLandfillJunkBlock(generationSeed, x, y));
          } else if (serverCellNoise(generationSeed, x, y, 8403) < LANDFILL_TRASH_SURFACE_CHANCE) {
            serverMapSet(foreground, x, y, "trash_dirt_top");
          }
        }
      } else if (["dirt", "sand", "stone"].includes(foregroundType)) {
        // Same junk items as the surface (broken bottle/jar/flask, garbage box, vending machine),
        // now buried underground too -- distinct noise salt (8406) so this roll is independent of
        // the surface junk roll (8401) rather than mirroring it column-by-column.
        if (serverCellNoise(generationSeed, x, y, 8406) < LANDFILL_TRASH_JUNK_CHANCE) {
          serverMapSet(foreground, x, y, serverPickLandfillJunkBlock(generationSeed, x, y));
        } else if (serverCellNoise(generationSeed, x, y, 8404) < LANDFILL_TRASH_UNDERGROUND_CHANCE) {
          serverMapSet(foreground, x, y, "trash_dirt_below");
        }
      }
      const backgroundType = background.get(key)?.block_type || "";
      if (backgroundType === "cave_background" && serverCellNoise(generationSeed, x, y, 8405) < LANDFILL_TRASH_WALLPAPER_CHANCE) {
        serverMapSet(background, x, y, "trash_wallpaper");
      }
    }
  }
}

function getServerGeneratedBaseTerrain(worldName: unknown) {
  const clean = cleanWorld(worldName);
  const cached = serverGeneratedBaseTerrainByWorld.get(clean);
  if (cached) return cached;

  const foreground = new Map();
  const background = new Map();
  const isLandfill = ServerLandfillEventModule.isLandfillWorldName(clean);
  const { generationSeed, surface } = buildServerTerrainSurface(clean);
  for (let x: any = 0; x < WORLD_WIDTH; x += 1) {
    const surfaceY = serverSurfaceYAt(surface, x);
    for (let y: any = surfaceY; y < WORLD_HEIGHT; y += 1) {
      const blockType = serverGeneratedBlockType(clean, generationSeed, x, y, surfaceY);
      if (blockType !== "") serverMapSet(foreground, x, y, blockType);
      if (shouldServerPlaceCaveBackground(clean, generationSeed, blockType, x, y, surfaceY)) {
        serverMapSet(background, x, y, "cave_background");
      }
    }
  }

  const rng = makeDeterministicRng(`generated:${clean}:${generationSeed}`);
  // Landfill: no water, no trees/trunks, no grass/flowers -- per Hassan's first-pass spec. These
  // three are purely additive passes on top of the base terrain loop above, so skipping them for
  // Landfill worlds leaves nothing else to special-case; every non-Landfill world is unaffected.
  if (!isLandfill) {
    serverGenerateNaturalPonds(foreground, surface, rng, background);
    serverGenerateSurfaceDecorations(foreground, surface, generationSeed, background);
    serverGenerateTrees(foreground, surface, generationSeed, rng, background);
  }
  serverApplyLandfillTrashOverlay(clean, foreground, background, surface, generationSeed);

  const entry = { foreground, background, surface };
  serverGeneratedBaseTerrainByWorld.set(clean, entry);
  while (serverGeneratedBaseTerrainByWorld.size > SERVER_GENERATED_TERRAIN_CACHE_MAX_WORLDS) {
    const oldestKey = serverGeneratedBaseTerrainByWorld.keys().next().value;
    if (!oldestKey) break;
    serverGeneratedBaseTerrainByWorld.delete(oldestKey);
  }
  return entry;
}

function buildServerGeneratedWorldMaps(worldName: any, state: any) {
  const foreground = new Map();
  const background = new Map();
  if (state?.cleared) return { foreground, background };

  const base = getServerGeneratedBaseTerrain(worldName);
  for (const [key, entry] of base.foreground) foreground.set(key, entry);
  for (const [key, entry] of base.background) background.set(key, entry);

  applyServerDefaultEntranceGateToGeneratedMaps(worldName, state, foreground, background, base.surface);
  return { foreground, background };
}

function buildServerGeneratedForegroundMap(worldName: any, state: any) {
  return buildServerGeneratedWorldMaps(worldName, state).foreground;
}

function buildServerGeneratedBackgroundMap(worldName: any, state: any) {
  return buildServerGeneratedWorldMaps(worldName, state).background;
}

function buildEffectiveForegroundMap(worldName: any, state: any, generatedMap: any = null) {
  const map: any = new Map();
  const baseMap = generatedMap || buildServerGeneratedForegroundMap(worldName, state);
  for (const [key, entry] of baseMap.entries()) {
    map.set(key, { ...entry, source: "generated" });
  }
  for (const key of state.removed_foreground.keys()) {
    map.delete(key);
  }
  for (const [key, entry] of state.foreground.entries()) {
    map.set(key, { ...entry, source: "explicit" });
  }
  return map;
}

function buildEffectiveBackgroundMap(worldName: any, state: any, generatedMap: any = null) {
  const map: any = new Map();
  const baseMap = generatedMap || buildServerGeneratedBackgroundMap(worldName, state);
  for (const [key, entry] of baseMap.entries()) {
    map.set(key, { ...entry, source: "generated" });
  }
  for (const key of state.removed_background.keys()) {
    map.delete(key);
  }
  for (const [key, entry] of state.background.entries()) {
    map.set(key, { ...entry, source: "explicit" });
  }
  return map;
}

function getSnowStormIceEventBlock(x: any, y: any) {
  const roll = deterministicTileVariantIndex(x, y, 100, SNOW_STORM_ICE_VARIANT_SALT);
  if (roll < 2) return "ice_fossil";
  if (roll < 7) return "ice_treasure";
  return "ice_block";
}

function getSnowStormEventBlockForOriginal(originalBlockId: any, effectiveMap: any, x: any, y: any) {
  switch (originalBlockId) {
    case "dirt":
      return getSnowStormDirtEventBlock(effectiveMap, x, y);
    case "water":
      return getSnowStormIceEventBlock(x, y);
    case "sand":
      return "snow_bank";
    case "stone":
      return "snow_stone";
    case "grass":
      return "frozen_grass";
    case "leaf":
      return isSnowStormTopLeaf(effectiveMap, x, y) ? "snow_leaf" : "";
    default:
      return "";
  }
}

function getSnowStormBlockTypeAt(effectiveMap: any, x: any, y: any) {
  if (!effectiveMap || !isGridInWorld(x, y)) return "";
  const entry = effectiveMap.get(gridKey(x, y));
  return clampString(entry?.block_type || "");
}

function getSnowStormDirtEventBlock(effectiveMap: any, x: any, y: any) {
  const aboveY = Number(y) - 1;
  const aboveBlockId = getSnowStormBlockTypeAt(effectiveMap, x, aboveY);
  if (aboveBlockId !== "dirt") return "snow_block";

  const aboveAboveBlockId = getSnowStormBlockTypeAt(effectiveMap, x, aboveY - 1);
  if (aboveAboveBlockId !== "dirt") return "snow_dirt";

  return "";
}

function isSnowStormTopLeaf(effectiveMap: any, x: any, y: any) {
  const aboveY = Number(y) - 1;
  if (!isGridInWorld(x, aboveY)) return true;
  const aboveKey = gridKey(x, aboveY);
  const above = effectiveMap.get(aboveKey);
  return clampString(above?.block_type || "") !== "leaf";
}

function canSpawnSnowStormPileAt(state: any, occupancyMap: any, x: any, y: any) {
  if (!state || !occupancyMap || !isGridInWorld(x, y)) return false;
  const key = gridKey(x, y);
  if (state.foreground.has(key)) return false;
  if (state.seeds.has(key)) return false;
  return !occupancyMap.has(key);
}

function makeSnowStormWorldChange(worldName: any, tile: any, action: any, sourceId: any, reason: any) {
  return {
    source_type: "world_event",
    source_id: sourceId,
    world: cleanWorld(worldName),
    action,
    reason,
    layer: "foreground",
    x: tile.x,
    y: tile.y,
    block_type: action === "break" ? tile.event_block_id : tile.event_block_id,
    block_type_before: tile.original_block_id || "",
    block_type_after: action === "break" ? "" : tile.event_block_id,
    details: {
      event_type: SNOW_STORM_EVENT_TYPE,
      event_id: sourceId,
      original_block_id: tile.original_block_id || "",
      event_block_id: tile.event_block_id || "",
      tile_source: tile.source || "",
      reason: tile.reason || reason,
    },
  };
}

async function startSnowStormEvent(worldName: any, options: any = {}) {
  const clean = cleanWorld(worldName);
  // Landfill worlds never get Snow Storm -- neither the random picker (filtered out above in
  // tryStartRandomSnowStormEvent) nor a developer's /forceevent or /event command should be able to
  // start it there. Checked here, at the single function every start path funnels through, rather
  // than only at the random picker, so a manual dev command can't bypass it.
  if (ServerLandfillEventModule.isLandfillWorldName(clean)) return { ok: false, reason: "landfill_world_excluded" };
  const lockKey = `${clean}:${SNOW_STORM_EVENT_TYPE}`;
  if (worldEventActionLocks.has(lockKey)) return { ok: false, reason: "locked" };
  worldEventActionLocks.add(lockKey);
  let previousWorldState: any = null;

  try {
    const state = ensureWorldState(clean);
    if (hasActiveSnowStormEvent(state)) return { ok: false, reason: "already_active" };
    if (hasSnowRepellentBlock(clean)) return { ok: false, reason: "snow_repellent_active" };

    previousWorldState = serializeWorldState(clean);
    const eventId = makeAuditId("snow_storm");
    const startedAt = new Date();
    const endsAt = new Date(startedAt.getTime() + SNOW_STORM_EVENT_DURATION_MS);
    const changedTiles: any = [];
    const updates: any = [];
    const convertedSnowDirtTiles: any = [];
    const stats: any = {
      dirt_converted: 0,
      water_converted: 0,
      sand_converted: 0,
      stone_converted: 0,
      grass_converted: 0,
      leaf_converted: 0,
      piles_spawned: 0,
      capped: false,
    };
    const effectiveMap = buildEffectiveForegroundMap(clean, state);
    const originalOccupancyMap = effectiveMap;
    const occupancyMap: any = new Map();
    for (const [key, entry] of originalOccupancyMap.entries()) {
      occupancyMap.set(key, { ...entry });
    }

    for (const entry of effectiveMap.values()) {
      if (changedTiles.length >= SNOW_STORM_MAX_CHANGED_TILES) {
        stats.capped = true;
        break;
      }

      const originalBlockId = clampString(entry?.block_type || "");
      if (originalBlockId === "") continue;
      const eventBlockId = getSnowStormEventBlockForOriginal(originalBlockId, originalOccupancyMap, entry.x, entry.y);
      if (eventBlockId === "" || eventBlockId === originalBlockId) continue;

      const key = gridKey(entry.x, entry.y);
      const source = clampString(entry.source || "") === "explicit" ? "explicit" : "generated";
      state.foreground.set(key, { x: entry.x, y: entry.y, block_type: eventBlockId });
      state.removed_foreground.delete(key);
      state.interactions.delete(key);
      occupancyMap.set(key, { x: entry.x, y: entry.y, block_type: eventBlockId, source });
      const changedTile: any = {
        x: entry.x,
        y: entry.y,
        original_block_id: originalBlockId,
        event_block_id: eventBlockId,
        event_id: eventId,
        changed_at: startedAt.toISOString(),
        source,
        reason: "snow_storm_start",
      };
      changedTiles.push(changedTile);
      updates.push({
        type: "world_block_update",
        action: "place",
        layer: "foreground",
        x: entry.x,
        y: entry.y,
        block_type: eventBlockId,
        world: clean,
      });

      if (originalBlockId === "dirt") {
        stats.dirt_converted += 1;
        if (eventBlockId === "snow_dirt") {
          convertedSnowDirtTiles.push(changedTile);
        }
      }
      else if (originalBlockId === "water") stats.water_converted += 1;
      else if (originalBlockId === "sand") stats.sand_converted += 1;
      else if (originalBlockId === "stone") stats.stone_converted += 1;
      else if (originalBlockId === "grass") stats.grass_converted += 1;
      else if (originalBlockId === "leaf") stats.leaf_converted += 1;
    }

    for (const entry of occupancyMap.values()) {
      if (changedTiles.length >= SNOW_STORM_MAX_CHANGED_TILES) {
        stats.capped = true;
        break;
      }
      if (clampString(entry?.source || "") !== "generated") continue;
      if (clampString(entry?.block_type || "") !== "water") continue;

      const key = gridKey(entry.x, entry.y);
      if (state.foreground.has(key)) continue;

      const eventBlockId = getSnowStormIceEventBlock(entry.x, entry.y);
      state.foreground.set(key, { x: entry.x, y: entry.y, block_type: eventBlockId });
      state.removed_foreground.delete(key);
      state.interactions.delete(key);
      occupancyMap.set(key, { x: entry.x, y: entry.y, block_type: eventBlockId, source: "generated" });

      const changedTile: any = {
        x: entry.x,
        y: entry.y,
        original_block_id: "water",
        event_block_id: eventBlockId,
        event_id: eventId,
        changed_at: startedAt.toISOString(),
        source: "generated",
        reason: "snow_storm_generated_water_freeze",
      };
      changedTiles.push(changedTile);
      updates.push({
        type: "world_block_update",
        action: "place",
        layer: "foreground",
        x: entry.x,
        y: entry.y,
        block_type: eventBlockId,
        world: clean,
      });
      stats.water_converted += 1;
    }

    const pileRng = makeDeterministicRng(`${eventId}:${clean}:pile_of_snow`);
    for (const snowDirtTile of convertedSnowDirtTiles) {
      if (changedTiles.length >= SNOW_STORM_MAX_CHANGED_TILES) {
        stats.capped = true;
        break;
      }
      if (pileRng() >= SNOW_STORM_PILE_OF_SNOW_CHANCE) continue;

      const pileX = snowDirtTile.x;
      const pileY = snowDirtTile.y - 1;
      if (!canSpawnSnowStormPileAt(state, occupancyMap, pileX, pileY)) continue;

      const pileKey = gridKey(pileX, pileY);
      state.foreground.set(pileKey, { x: pileX, y: pileY, block_type: "pile_of_snow" });
      state.removed_foreground.delete(pileKey);
      occupancyMap.set(pileKey, { x: pileX, y: pileY, block_type: "pile_of_snow", source: "event_spawn" });

      const pileTile: any = {
        x: pileX,
        y: pileY,
        original_block_id: "",
        event_block_id: "pile_of_snow",
        event_id: eventId,
        changed_at: startedAt.toISOString(),
        source: "event_spawn",
        reason: "snow_storm_pile_spawn",
      };
      changedTiles.push(pileTile);
      updates.push({
        type: "world_block_update",
        action: "place",
        layer: "foreground",
        x: pileX,
        y: pileY,
        block_type: "pile_of_snow",
        world: clean,
      });
      stats.piles_spawned += 1;
    }

    state.active_event_type = SNOW_STORM_EVENT_TYPE;
    state.event_id = eventId;
    state.event_started_at = startedAt.toISOString();
    state.event_ends_at = endsAt.toISOString();
    state.event_changed_tiles = changedTiles;

    const commit = await commitWorldEventStateOnly(clean);
    if (!commit.ok) {
      worldStates.set(clean, deserializeWorldState(clean, previousWorldState));
      return { ok: false, reason: commit.reason || "commit_failed", message: commit.message || "" };
    }

    scheduleWorldEventEnd(clean);
    if (options.broadcast !== false) {
      broadcastToWorld(clean, buildWorldEventStartedMessage(clean, state));
      broadcastEventSystemMessage(clean, eventId, SNOW_STORM_SYSTEM_MESSAGE);
      await broadcastEventTileUpdates(clean, eventId, "start", updates);
    }

    console.log("[world_event] snow_storm started", {
      world: clean,
      event_id: eventId,
      reason: options.reason || "system",
      ends_at: state.event_ends_at,
      changed_tiles: changedTiles.length,
      ...stats,
    });

    return { ok: true, event_id: eventId, stats, changed_tiles: changedTiles.length };
  } catch (error) {
    if (previousWorldState != null) {
      worldStates.set(clean, deserializeWorldState(clean, previousWorldState));
    }
    console.warn("[world_event] snow_storm start exception:", getErrorStack(error));
    return { ok: false, reason: "exception", message: getErrorMessage(error) };
  } finally {
    worldEventActionLocks.delete(lockKey);
  }
}

async function endSnowStormEvent(worldName: any, options: any = {}) {
  const clean = cleanWorld(worldName);
  const lockKey = `${clean}:${SNOW_STORM_EVENT_TYPE}`;
  if (worldEventActionLocks.has(lockKey)) return { ok: false, reason: "locked" };
  worldEventActionLocks.add(lockKey);
  let previousWorldState: any = null;

  try {
    const state = ensureWorldState(clean);
    if (state.active_event_type !== SNOW_STORM_EVENT_TYPE) return { ok: false, reason: "not_active" };
    const eventId = state.event_id || "";
    previousWorldState = serializeWorldState(clean);
    const changedTiles = Array.isArray(state.event_changed_tiles) ? state.event_changed_tiles.slice() : [];
    const endedAt = new Date().toISOString();
    const updates: any = [];
    const stats: any = {
      reverted: 0,
      removed_piles: 0,
      removed_generated_overrides: 0,
      skipped_player_changed: 0,
    };
    const existingTimer = worldEventTimers.get(clean);
    if (existingTimer) clearTimeout(existingTimer);
    worldEventTimers.delete(clean);
    clearWorldEventCountdownTimers(clean);

    for (const rawTile of changedTiles) {
      const tile = normalizeWorldEventTileEntry(rawTile, eventId);
      if (!tile) continue;
      const key = gridKey(tile.x, tile.y);
      const currentBlockId = clampString(state.foreground.get(key)?.block_type || "");
      if (currentBlockId !== tile.event_block_id) {
        stats.skipped_player_changed += 1;
        continue;
      }

      const wasGeneratedOverride = clampString(tile.source || "") === "generated";
      if (tile.original_block_id !== "") {
        if (wasGeneratedOverride) {
          state.foreground.delete(key);
          state.removed_foreground.delete(key);
          stats.removed_generated_overrides += 1;
          updates.push({
            type: "world_block_update",
            action: "place",
            layer: "foreground",
            x: tile.x,
            y: tile.y,
            block_type: tile.original_block_id,
            world: clean,
          });
        } else {
          state.foreground.set(key, { x: tile.x, y: tile.y, block_type: tile.original_block_id });
          state.removed_foreground.delete(key);
          stats.reverted += 1;

          updates.push({
            type: "world_block_update",
            action: "place",
            layer: "foreground",
            x: tile.x,
            y: tile.y,
            block_type: tile.original_block_id,
            world: clean,
          });
        }
      } else {
        state.foreground.delete(key);
        state.removed_foreground.delete(key);
        updates.push({
          type: "world_block_update",
          action: "break",
          layer: "foreground",
          x: tile.x,
          y: tile.y,
          block_type: tile.event_block_id,
          world: clean,
        });
        if (wasGeneratedOverride) {
          stats.removed_generated_overrides += 1;
        } else {
          stats.removed_piles += 1;
        }
      }
    }

    clearWorldEventState(state);
    const commit = await commitWorldEventStateOnly(clean);
    if (!commit.ok) {
      worldStates.set(clean, deserializeWorldState(clean, previousWorldState));
      scheduleWorldEventEnd(clean);
      return { ok: false, reason: commit.reason || "commit_failed", message: commit.message || "" };
    }

    if (options.broadcast !== false) {
      broadcastToWorld(clean, buildWorldEventEndedMessage(clean, eventId, endedAt));
      await broadcastEventTileUpdates(clean, eventId, "end", updates);
    }

    console.log("[world_event] snow_storm ended", {
      world: clean,
      event_id: eventId,
      reason: options.reason || "system",
      changed_tiles: changedTiles.length,
      ...stats,
    });

    return { ok: true, event_id: eventId, stats, updates: updates.length };
  } catch (error) {
    if (previousWorldState != null) {
      worldStates.set(clean, deserializeWorldState(clean, previousWorldState));
      scheduleWorldEventEnd(clean);
    }
    console.warn("[world_event] snow_storm end exception:", getErrorStack(error));
    return { ok: false, reason: "exception", message: getErrorMessage(error) };
  } finally {
    worldEventActionLocks.delete(lockKey);
  }
}

async function handleFrozenTreasureOpen(socket: any, player: any, worldName: any, update: any, requestId: any = "") {
  const clean = cleanWorld(worldName);
  const key = gridKey(update.x, update.y);
  const lockKey = `${clean}:${key}`;
  if (worldFrozenTreasureOpenLocks.has(lockKey)) {
    sendActionRejected(socket, "world_block_update", "That treasure is already opening.");
    return false;
  }
  worldFrozenTreasureOpenLocks.add(lockKey);

  try {
    const state = ensureWorldState(clean);
    const currentBlock = state.foreground.get(key);
    if (clampString(currentBlock?.block_type || "") !== "frozen_treasure") {
      sendActionRejected(socket, "world_block_update", "That frozen treasure is already open.");
      return false;
    }

    const previousWorldState = serializeWorldState(clean);
    const transactionId = makeAuditId("frozen_treasure");
    const openedUpdate: any = {
      type: "world_block_update",
      action: "place",
      layer: "foreground",
      x: update.x,
      y: update.y,
      block_type: "frozen_treasure_2",
      world: clean,
    };
    const cleanupUpdate: any = {
      type: "world_block_update",
      action: "break",
      layer: "foreground",
      x: update.x,
      y: update.y,
      block_type: "frozen_treasure_2",
      world: clean,
    };

    state.foreground.set(key, { x: update.x, y: update.y, block_type: "frozen_treasure_2" });
    state.removed_foreground.delete(key);
    clearServerBlockDamage(clean, update);

    const dropPosition = getGridCenterPixels(update.x, update.y);
    const rewardDrop = createServerDrop(clean, "snow_block", "block", 1, dropPosition.x, dropPosition.y, SERVER_DROP_PICKUP_DELAY);
    if (!rewardDrop) {
      worldStates.set(clean, deserializeWorldState(clean, previousWorldState));
      sendActionRejected(socket, "world_block_update", "Could not create the treasure reward.");
      return false;
    }

    state.foreground.delete(key);
    state.interactions.delete(key);
    state.removed_foreground.set(key, {
      x: update.x,
      y: update.y,
      block_type: "frozen_treasure_2",
    });

    const openChange: any = {
      ...getAuditActor(socket, player),
      source_type: "server_event",
      source_id: transactionId,
      request_id: requestId || "",
      world: clean,
      action: "place",
      reason: "frozen_treasure_open",
      layer: "foreground",
      x: update.x,
      y: update.y,
      block_type: "frozen_treasure_2",
      block_type_before: "frozen_treasure",
      block_type_after: "frozen_treasure_2",
      details: {
        event_type: SNOW_STORM_EVENT_TYPE,
        opened_block: "frozen_treasure",
        reward_item: "snow_block",
      },
    };
    const cleanupChange: any = {
      ...getAuditActor(socket, player),
      source_type: "server_event",
      source_id: transactionId,
      request_id: requestId || "",
      world: clean,
      action: "break",
      reason: "frozen_treasure_open_cleanup",
      layer: "foreground",
      x: update.x,
      y: update.y,
      block_type: "frozen_treasure_2",
      block_type_before: "frozen_treasure_2",
      block_type_after: "",
      details: {
        event_type: SNOW_STORM_EVENT_TYPE,
        opened_block: "frozen_treasure",
        cleanup_block: "frozen_treasure_2",
        reward_item: "snow_block",
      },
    };
    const rewardChange: any = {
      ...getAuditActor(socket, player),
      source_type: "server_event",
      source_id: transactionId,
      request_id: requestId || "",
      world: clean,
      action: "drop_create",
      reason: "frozen_treasure_reward",
      layer: "foreground",
      x: update.x,
      y: update.y,
      block_type: rewardDrop.item_type,
      details: {
        event_type: SNOW_STORM_EVENT_TYPE,
        drop_id: rewardDrop.drop_id,
        item_category: rewardDrop.item_category,
        amount: rewardDrop.amount,
        source_block: "frozen_treasure",
      },
    };

    const commit = await commitWorldStateWithBlockChanges(clean, [openChange, cleanupChange, rewardChange]);
    if (!commit.ok) {
      worldStates.set(clean, deserializeWorldState(clean, previousWorldState));
      sendActionRejected(socket, "world_block_update", commit.message || "PostgreSQL rejected the treasure reward.");
      return false;
    }

    sendWorldUpdateToRequesterAndWorld(socket, player, clean, openedUpdate);
    sendWorldUpdateToRequesterAndWorld(socket, player, clean, cleanupUpdate);
    sendWorldUpdateToRequesterAndWorld(socket, player, clean, rewardDrop);
    logWorldChange(socket, player, openChange, { skipPostgres: commit.postgres_committed });
    logWorldChange(socket, player, cleanupChange, { skipPostgres: commit.postgres_committed });
    logWorldChange(socket, player, rewardChange, { skipPostgres: commit.postgres_committed });

    console.log("[world_event] frozen_treasure opened", {
      world: clean,
      x: update.x,
      y: update.y,
      actor: player?.account_username || player?.name || "",
      reward_drop_id: rewardDrop.drop_id,
      reward_item: rewardDrop.item_type,
      cleanup_block: "frozen_treasure_2",
    });
    return true;
  } finally {
    worldFrozenTreasureOpenLocks.delete(lockKey);
  }
}

function loadAccountsFromJson() {
  accounts.clear();
  const data = readJsonFile(ACCOUNTS_SAVE_PATH);

  if (!data || typeof data !== "object" || Array.isArray(data)) {
    return;
  }

  const rawAccounts = Array.isArray(data.accounts) ? data.accounts : [];
  for (const rawAccount of rawAccounts) {
    const account = sanitizeAccountState(rawAccount);
    if (!account) continue;
    accounts.set(accountKey(account.username), account);
  }
}

function sanitizeAccountState(rawAccount: any) {
  if (!rawAccount || typeof rawAccount !== "object" || Array.isArray(rawAccount)) return null;

  const username = cleanAccountName(rawAccount.username || rawAccount.account_username || rawAccount.name || "");
  if (username === "") return null;
  const hasEmailVerifiedField = Object.prototype.hasOwnProperty.call(rawAccount, "email_verified");
  const passwordHash = String(rawAccount.password_hash || "");

  return {
    account_id: cleanStableIdentityId(rawAccount.account_id || ""),
    player_id: cleanStableIdentityId(rawAccount.player_id || rawAccount.profile_id || ""),
    profile_id: cleanStableIdentityId(rawAccount.profile_id || rawAccount.player_id || ""),
    username,
    email: cleanEmail(rawAccount.email || ""),
    password_salt: String(rawAccount.password_salt || ""),
    password_hash: passwordHash,
    password_algorithm: String(rawAccount.password_algorithm || (passwordHash ? "legacy_scrypt" : "")),
    session_token_hash: String(rawAccount.session_token_hash || ""),
    session_token_expires_at: String(rawAccount.session_token_expires_at || ""),
    refresh_token_hash: String(rawAccount.refresh_token_hash || ""),
    refresh_token_expires_at: String(rawAccount.refresh_token_expires_at || ""),
    email_verified: hasEmailVerifiedField ? Boolean(rawAccount.email_verified) : passwordHash !== "",
    email_verified_at: String(rawAccount.email_verified_at || ""),
    email_verification_token_hash: String(rawAccount.email_verification_token_hash || ""),
    email_verification_expires_at: String(rawAccount.email_verification_expires_at || ""),
    role: String(rawAccount.role || getAccountRole(username)),
    created_at: String(rawAccount.created_at || new Date().toISOString()),
    last_seen_at: String(rawAccount.last_seen_at || ""),
    friends: sanitizeAccountNameArray(rawAccount.friends, 200),
    friend_requests_in: sanitizeAccountNameArray(rawAccount.friend_requests_in || rawAccount.pending_friend_requests || [], 200),
    friend_requests_out: sanitizeAccountNameArray(rawAccount.friend_requests_out || [], 200),
  };
}

function accountKey(username: any) {
  return cleanAccountName(username).toLowerCase();
}

function upsertAccount(rawAccount: any) {
  const incoming = sanitizeAccountState(rawAccount);
  if (!incoming) return null;

  const key = accountKey(incoming.username);
  const existing = accounts.get(key) || {};
  const account: any = {
    account_id: existing.account_id || incoming.account_id || "",
    player_id: existing.player_id || existing.profile_id || incoming.player_id || incoming.profile_id || "",
    profile_id: existing.profile_id || existing.player_id || incoming.profile_id || incoming.player_id || "",
    username: existing.username || incoming.username,
    email: incoming.email || existing.email || "",
    password_salt: existing.password_salt || incoming.password_salt || "",
    password_hash: existing.password_hash || incoming.password_hash || "",
    password_algorithm: existing.password_algorithm || incoming.password_algorithm || (existing.password_hash || incoming.password_hash ? "legacy_scrypt" : ""),
    session_token_hash: existing.session_token_hash || incoming.session_token_hash || "",
    session_token_expires_at: existing.session_token_expires_at || incoming.session_token_expires_at || "",
    refresh_token_hash: existing.refresh_token_hash || incoming.refresh_token_hash || "",
    refresh_token_expires_at: existing.refresh_token_expires_at || incoming.refresh_token_expires_at || "",
    email_verified: Object.prototype.hasOwnProperty.call(existing, "email_verified") ? Boolean(existing.email_verified) : Boolean(incoming.email_verified),
    email_verified_at: existing.email_verified_at || incoming.email_verified_at || "",
    email_verification_token_hash: existing.email_verification_token_hash || incoming.email_verification_token_hash || "",
    email_verification_expires_at: existing.email_verification_expires_at || incoming.email_verification_expires_at || "",
    role: existing.role || incoming.role || getAccountRole(incoming.username),
    created_at: existing.created_at || incoming.created_at || new Date().toISOString(),
    last_seen_at: new Date().toISOString(),
    friends: sanitizeAccountNameArray(existing.friends || incoming.friends || [], 200),
    friend_requests_in: sanitizeAccountNameArray(existing.friend_requests_in || incoming.friend_requests_in || existing.pending_friend_requests || [], 200),
    friend_requests_out: sanitizeAccountNameArray(existing.friend_requests_out || incoming.friend_requests_out || [], 200),
  };

  accounts.set(key, account);
  queueAccountsSave();
  postgresStore.mirrorAccount(account, { touchLogin: false });
  return account;
}

function queueAccountsSave() {
  if (accountsSaveTimer) clearTimeout(accountsSaveTimer);

  accountsSaveTimer = setTimeout(() => {
    accountsSaveTimer = null;
    saveAccounts();
  }, SAVE_DEBOUNCE_MS);
}

function saveAccounts() {
  const payload: any = {
    account_state_version: 1,
    saved_at: new Date().toISOString(),
    accounts: Array.from<any>(accounts.values()),
  };
  // This writes EVERY registered account, and queueAccountsSave fires it on a 250ms
  // debounce from every login, join_world and player_state_save. Synchronously, that is
  // ~40ms of blocked event loop at 2,000 accounts and ~83ms at 5,000 -- up to a third of
  // the loop spent inside one writeFileSync. The async form is atomic in exactly the same
  // way (temp file + rename) and trackPersistenceWrite keeps it drained on shutdown, so
  // the only change is that it no longer stops the world while it writes.
  trackPersistenceWrite(writeJsonFileAtomicAsync(ACCOUNTS_SAVE_PATH, payload), "account states JSON backup");
  if (postgresStore.isReady()) {
    trackPersistenceWrite(postgresStore.saveAccountStates(payload.accounts), "account states");
  }
}

