function sanitizePlayerState(rawState: any, username: any) {
  return PlayerStateHelpers.sanitizePlayerState(rawState, username);
}

function ensurePlayerState(username: any) {
  const clean = cleanAccountName(username);
  if (clean === "") return null;

  const key = accountKey(clean);
  if (playerStates.has(key)) {
    return playerStates.get(key);
  }

  if (isPostgresAuthoritativeReady()) {
    return null;
  }

  const data = readJsonFile(getPlayerSavePath(clean));
  if (!data || typeof data !== "object" || Array.isArray(data)) {
    return null;
  }

  const state = sanitizePlayerState(data.player_data || data, clean);
  if (!state) return null;

  playerStates.set(key, state);
  return state;
}

function setPlayerState(username: any, state: any) {
  const clean = cleanAccountName(username);
  if (clean === "") return;

  if (state && typeof state === "object" && !Array.isArray(state)) {
    state.inventory_slot_count = resolveInventorySlotCount(state);
  }
  playerStates.set(accountKey(clean), state);
}

function queuePlayerSave(username: any) {
  const key = accountKey(username);
  if (key === "") return;

  const existingTimer = playerSaveTimers.get(key);
  if (existingTimer) clearTimeout(existingTimer);

  playerSaveTimers.set(key, setTimeout(() => {
    playerSaveTimers.delete(key);
    savePlayerState(username);
  }, SAVE_DEBOUNCE_MS));
}

function savePlayerState(username: any) {
  const clean = cleanAccountName(username);
  if (clean === "") return null;

  const state = playerStates.get(accountKey(clean));
  if (!state) return null;
  state.inventory_slot_count = resolveInventorySlotCount(state);
  normalizePlayerHotbarState(state);
  applyProgressionFieldsToState(state, state);

  writePlayerStateJsonBackup(clean, state);
  if (postgresStore.isReady()) {
    const write = trackPersistenceWrite(postgresStore.savePlayerState(clean, state), `player state ${clean}`);
    playerSaveWrites.set(accountKey(clean), write);
    return write;
  } else {
    postgresStore.mirrorInventorySnapshot(clean, state);
  }
  return null;
}

function triggerPendingWorldSave(worldName: any) {
  const clean = cleanWorld(worldName || "");
  if (clean === "") return null;
  const timer = worldSaveTimers.get(clean);
  if (timer) {
    clearTimeout(timer);
    worldSaveTimers.delete(clean);
    return saveWorldState(clean, { mutation: false, reason: "flush_pending_world_save" });
  }
  return worldSaveWrites.get(clean) || null;
}

function triggerPendingPlayerSave(username: any) {
  const clean = cleanAccountName(username || "");
  if (clean === "") return null;
  const key = accountKey(clean);
  const timer = playerSaveTimers.get(key);
  if (timer) {
    clearTimeout(timer);
    playerSaveTimers.delete(key);
    return savePlayerState(clean);
  }
  return playerSaveWrites.get(key) || null;
}

// Waits only for the writes that belong to this player and this world, instead of
// draining the process-wide PostgreSQL write queue. Every write still chains onto
// the global queue in the same order as before, so ordering and durability are
// unchanged -- the difference is that a joining player no longer blocks behind an
// unrelated player's inventory save. Awaiting the latest write for a key is
// sufficient: because the queue is serial, the newest write for a key can only
// resolve after every write enqueued before it has already resolved.
async function drainScopedSessionPersistence(cleanUsername: string, cleanWorldName: string): Promise<void> {
  const scoped: any[] = [];
  if (cleanWorldName !== "") {
    const pendingWorldWrite = worldSaveWrites.get(cleanWorldName);
    if (pendingWorldWrite && typeof pendingWorldWrite.then === "function") scoped.push(pendingWorldWrite);
  }
  if (cleanUsername !== "") {
    const pendingPlayerWrite = playerSaveWrites.get(accountKey(cleanUsername));
    if (pendingPlayerWrite && typeof pendingPlayerWrite.then === "function") scoped.push(pendingPlayerWrite);
  }
  if (scoped.length > 0) {
    await Promise.allSettled(scoped);
    return;
  }
  // Nothing has ever been written for this key on this instance, so there is no
  // scoped tail to wait on. Fall back to the historical global drain.
  if (typeof postgresStore.flushWriteQueue === "function") {
    await postgresStore.flushWriteQueue();
  } else {
    await waitForPersistenceWrites();
  }
}

async function flushPendingSessionPersistence(username: any = "", worldName: any = "", reason: any = "session_transition") {
  const cleanUsername = cleanAccountName(username || "");
  const cleanWorldName = String(worldName || "").trim() === "" ? "" : cleanWorld(worldName);
  const writes: any = [];
  const worldWrite = cleanWorldName === "" ? null : triggerPendingWorldSave(cleanWorldName);
  const playerWrite = cleanUsername === "" ? null : triggerPendingPlayerSave(cleanUsername);
  if (worldWrite && typeof worldWrite.then === "function") writes.push(worldWrite);
  if (playerWrite && typeof playerWrite.then === "function") writes.push(playerWrite);

  const results = writes.length > 0 ? await Promise.allSettled(writes) : [];
  await drainScopedSessionPersistence(cleanUsername, cleanWorldName);

  let failed: any = results.find((result) => (
    result.status === "rejected"
    || (result.status === "fulfilled" && result.value !== true)
  ));
  let flushedWriteCount: any = writes.length;
  if (failed) {
    const retryWrites: any = [];
    const worldRetry = cleanWorldName === ""
      ? null
      : saveWorldState(cleanWorldName, { mutation: false, reason: "session_flush_retry" });
    const playerRetry = cleanUsername === "" ? null : savePlayerState(cleanUsername);
    if (worldRetry && typeof worldRetry.then === "function") retryWrites.push(worldRetry);
    if (playerRetry && typeof playerRetry.then === "function") retryWrites.push(playerRetry);
    flushedWriteCount += retryWrites.length;

    const retryResults = retryWrites.length > 0 ? await Promise.allSettled(retryWrites) : [];
    await drainScopedSessionPersistence(cleanUsername, cleanWorldName);
    failed = retryResults.length === 0
      ? failed
      : retryResults.find((result) => (
        result.status === "rejected"
        || (result.status === "fulfilled" && result.value !== true)
      ));
  }
  if (failed) {
    console.warn("[persistence] session transition flush failed", {
      username: cleanUsername,
      world: cleanWorldName,
      reason,
      failure: failed.status === "rejected" ? String(failed.reason || "") : "save_returned_false",
    });
    return { ok: false, reason: "persistence_save_failed" };
  }

  return {
    ok: true,
    username: cleanUsername,
    world: cleanWorldName,
    reason,
    flushed_write_count: flushedWriteCount,
  };
}

