function cleanIndexedWorldName(value: any) {
  const raw = String(value || "").trim();
  return raw === "" ? "" : cleanWorld(raw);
}

function getWorldPlayerIdSet(worldName: any, create: any = false) {
  const clean = cleanWorld(worldName || "START");
  let set: any = worldPlayers.get(clean);
  if (!set && create) {
    set = new Set();
    worldPlayers.set(clean, set);
  }
  return set || null;
}

function removePlayerFromWorldIndex(playerOrId: any, worldName: any = "") {
  const player = playerOrId && typeof playerOrId === "object" ? playerOrId : players.get(String(playerOrId || "").trim());
  const playerId = String(player?.id || playerOrId || "").trim();
  if (playerId === "") return;

  const clean = cleanIndexedWorldName(worldName || player?.indexed_world || "");
  if (clean !== "") {
    const set = worldPlayers.get(clean);
    if (set) {
      set.delete(playerId);
      if (set.size === 0) worldPlayers.delete(clean);
    }
    if (player && cleanIndexedWorldName(player.indexed_world || "") === clean) {
      player.indexed_world = "";
    }
    return;
  }

  for (const [indexedWorld, set] of worldPlayers.entries()) {
    set.delete(playerId);
    if (set.size === 0) worldPlayers.delete(indexedWorld);
  }
  if (player) player.indexed_world = "";
}

function updatePlayerWorldIndex(player: any) {
  if (!player) return;
  const playerId = String(player.id || "").trim();
  if (playerId === "") return;

  const previousWorld = cleanIndexedWorldName(player.indexed_world || "");
  const nextWorld = player.joined_world ? cleanWorld(player.world || player.current_world || "START") : "";
  if (previousWorld !== "" && previousWorld !== nextWorld) {
    removePlayerFromWorldIndex(player, previousWorld);
  }

  if (nextWorld === "") {
    player.indexed_world = "";
    return;
  }

  getWorldPlayerIdSet(nextWorld, true).add(playerId);
  player.indexed_world = nextWorld;
}

function clearPlayerWorldIndex(playerOrId: any) {
  removePlayerFromWorldIndex(playerOrId);
}

function getWorldPlayerRecords(worldName: any, options: any = {}) {
  const clean = cleanWorld(worldName || "START");
  const excluded = String(options.excludePlayerId || "").trim();
  const includeSocket = options.includeSocket === true;
  const requireOpenSocket = options.requireOpenSocket !== false;
  const set = getWorldPlayerIdSet(clean, false);
  if (!set || set.size === 0) return [];

  const records: any = [];
  for (const playerId of Array.from<any>(set)) {
    if (excluded !== "" && playerId === excluded) continue;

    const player = players.get(playerId);
    const socket = socketByPlayerId.get(playerId) || null;
    const stale = !player ||
      !player.joined_world ||
      cleanWorld(player.world || "START") !== clean ||
      (requireOpenSocket && (!socket || socket.readyState !== WebSocket.OPEN));
    if (stale) {
      set.delete(playerId);
      if (player && cleanIndexedWorldName(player.indexed_world || "") === clean) {
        player.indexed_world = "";
      }
      continue;
    }

    records.push(includeSocket ? { playerId, player, socket } : { playerId, player });
  }

  if (set.size === 0) worldPlayers.delete(clean);
  return records;
}

function getPendingWorldEntryPlayerRecords(
  worldName: unknown,
  options: { excludePlayerId?: unknown } = {},
): Array<{ playerId: string; socket: ServerWebSocket }> {
  const clean = cleanWorld(worldName || "START");
  const excluded = String(options.excludePlayerId || "").trim();
  const records: Array<{ playerId: string; socket: ServerWebSocket }> = [];
  const pendingPlayers = players as Map<string, Record<string, unknown>>;
  const playerSockets = socketByPlayerId as Map<string, ServerWebSocket>;

  for (const [playerId, player] of pendingPlayers.entries()) {
    if (excluded !== "" && playerId === excluded) continue;
    if (!player || player.joined_world === true) continue;
    if (String(player.world_entry_state || "") !== "snapshot_sent") continue;
    if (player.world_entry_snapshot_queued !== true) continue;
    if (cleanWorld(player.world_entry_world || player.world || "START") !== clean) continue;

    const socket = playerSockets.get(playerId);
    if (!socket || socket.readyState !== WebSocket.OPEN) continue;
    records.push({ playerId, socket });
  }

  return records;
}

function getWorldIndexStatsSnapshot() {
  const worlds: any = [];
  let indexedPlayerCount: any = 0;
  let largestWorldPopulation: any = 0;

  for (const worldName of Array.from<any>(worldPlayers.keys())) {
    const population = getWorldPopulationCount(worldName);
    if (population <= 0) continue;
    const clean = cleanWorld(worldName);
    indexedPlayerCount += population;
    largestWorldPopulation = Math.max(largestWorldPopulation, population);
    worlds.push({
      world: clean,
      players: population,
    });
  }

  worlds.sort((left: { world: string; players: number }, right: { world: string; players: number }) => {
    const populationCompare = Number(right.players || 0) - Number(left.players || 0);
    if (populationCompare !== 0) return populationCompare;
    return String(left.world || "").localeCompare(String(right.world || ""));
  });

  return {
    active_world_count: worlds.length,
    indexed_player_count: indexedPlayerCount,
    largest_world_population: largestWorldPopulation,
    sample_worlds: worlds.slice(0, 10),
  };
}

function getWorldRouteStatsSnapshot() {
  const sampleWorlds = Array.from<any>(ownedWorldRoutes.values())
    .map((worldName) => cleanIndexedWorldName(worldName))
    .filter(Boolean)
    .sort((left, right) => left.localeCompare(right))
    .slice(0, 10)
    .map((worldName) => ({
      world: worldName,
      players: getWorldPopulationCount(worldName),
    }));

  return {
    instance_id: SERVER_INSTANCE_ID,
    ws_url: SERVER_INSTANCE_WS_URL,
    enforcement_enabled: WORLD_ROUTE_ENFORCEMENT_ENABLED,
    ttl_ms: WORLD_ROUTE_TTL_MS,
    redis_required_for_enforcement: REDIS_REQUIRED_FOR_ROUTE_ENFORCEMENT,
    local_owned_world_count: ownedWorldRoutes.size,
    checks: Number(worldRouteStats.checks || 0),
    allowed: Number(worldRouteStats.allowed || 0),
    redirects: Number(worldRouteStats.redirects || 0),
    unavailable: Number(worldRouteStats.unavailable || 0),
    bypasses: Number(worldRouteStats.bypasses || 0),
    conflicts: Number(worldRouteStats.conflicts || 0),
    redis_unhealthy: Number(worldRouteStats.redis_unhealthy || 0),
    admission_mismatches: Number(worldRouteStats.admission_mismatches || 0),
    sample_owned_worlds: sampleWorlds,
  };
}

function warnWorldRouteConflict(label: any, worldName: any, route: any = {}) {
  const clean = cleanWorld(worldName || "START");
  const now = Date.now();
  const previous = Number(worldRouteConflictLogAt.get(clean) || 0);
  if (now - previous < 10000) return;
  worldRouteStats.conflicts += 1;

  worldRouteConflictLogAt.set(clean, now);
  console.warn("[redis] world route conflict", {
    label,
    world: clean,
    server_instance_id: SERVER_INSTANCE_ID,
    owner_instance_id: route.owner_instance_id || "",
    redirect_ws_url: route.ws_url || "",
    enforcement_enabled: WORLD_ROUTE_ENFORCEMENT_ENABLED,
  });
}

function warnWorldRouteAdmissionMismatch(label: any, worldName: any, route: any = {}) {
  const clean = cleanWorld(worldName || "START");
  const now = Date.now();
  const previous = Number(worldRouteAdmissionMismatchLogAt.get(clean) || 0);
  if (now - previous < 10000) return;
  worldRouteAdmissionMismatchLogAt.set(clean, now);
  worldRouteStats.admission_mismatches += 1;
  console.warn("[redis] world route admission mismatch", {
    label,
    world: clean,
    server_instance_id: SERVER_INSTANCE_ID,
    owner_instance_id: route.owner_instance_id || "",
    redirect_ws_url: route.ws_url || "",
    action: String(route.action || ""),
    reason: route.reason || "world_route_admission_mismatch",
  });
}

function rejectWorldRouteUnavailable(socket: any, action: any, worldName: any) {
  const clean = cleanWorld(worldName || "START");
  sendActionRejected(socket, action, "World routing is temporarily unavailable.", {
    reason: "world_route_unavailable",
    world: clean,
    server_instance_id: SERVER_INSTANCE_ID,
  });
  return false;
}

function rejectWorldRouteAdmissionMismatch(socket: any, player: any, action: any, worldName: any, route: any = {}) {
  const clean = cleanWorld(worldName || "START");
  const ownerInstanceId = String(route.owner_instance_id || "").trim();
  const redirectWsUrl = String(route.ws_url || "").trim();
  if (ownerInstanceId || redirectWsUrl) {
    return rejectWorldRouteRedirect(socket, action, clean, {
      owner_instance_id: ownerInstanceId,
      ws_url: redirectWsUrl,
    });
  }

  logSecurityEvent(socket, player, "world_route_admission_mismatch", {
    action,
    world: clean,
    reason: route.reason || "world_route_admission_mismatch",
    owner_instance_id: ownerInstanceId,
    redirect_ws_url: redirectWsUrl,
    server_instance_id: SERVER_INSTANCE_ID,
  }, "warning");
  return rejectWorldRouteUnavailable(socket, action, clean);
}

function rejectWorldRouteRedirect(socket: any, action: any, worldName: any, route: any = {}) {
  const clean = cleanWorld(worldName || "START");
  const ownerInstanceId = String(route.owner_instance_id || "").trim();
  const redirectWsUrl = String(route.ws_url || "").trim();
  worldRouteStats.redirects += 1;
  const payload: any = {
    type: "world_route_redirect",
    action,
    world: clean,
    owner_instance_id: ownerInstanceId,
    redirect_ws_url: redirectWsUrl,
    server_instance_id: SERVER_INSTANCE_ID,
    message: "That world is hosted by another server.",
  };
  sendJson(socket, payload);
  sendActionRejected(socket, action, "That world is hosted by another server.", {
    reason: "world_route_redirect",
    world: clean,
    owner_instance_id: ownerInstanceId,
    redirect_ws_url: redirectWsUrl,
    server_instance_id: SERVER_INSTANCE_ID,
  });
  return false;
}

/**
 * @param {PixelMania.WorldName | string} worldName
 * @returns {Promise<PixelMania.WorldRouteClaimResult>}
 */
async function claimWorldRouteForCurrentInstance(worldName: any) {
  const clean = cleanWorld(worldName || "START");
  if (clean === "") {
    return { ok: false, fallback: false, reason: "invalid_world_route", world: clean };
  }

  if (!redisStore.isReady()) {
    if (POSTGRES_ENABLED && POSTGRES_AUTHORITATIVE && WORLD_ROUTE_ENFORCEMENT_ENABLED) {
      invalidateWorldEntrySnapshotCache(clean, "route_redis_unavailable");
      worldLoadedAuthorities.delete(clean);
      ownedWorldRoutes.delete(clean);
      worldPersistenceOwnership.delete(clean);
      worldUnpersistedRevisions.delete(clean);
      return {
        ok: false,
        fallback: true,
        reason: "world_route_redis_unavailable",
        world: clean,
        owner_instance_id: "",
        ws_url: "",
      };
    }
    const fallbackOwnership: WorldPersistenceOwnership = {
      require_owner: false,
      server_instance: SERVER_INSTANCE_ID,
      ownership_token: `${SERVER_PROCESS_OWNERSHIP_ID}:0`,
      ownership_epoch: 0,
      fallback: true,
      verified: true,
    };
    ownedWorldRoutes.add(clean);
    worldPersistenceOwnership.set(clean, fallbackOwnership);
    return {
      ok: true,
      fallback: true,
      world: clean,
      owner_instance_id: SERVER_INSTANCE_ID,
      ws_url: SERVER_INSTANCE_WS_URL,
      ownership_token: fallbackOwnership.ownership_token,
      ownership_epoch: fallbackOwnership.ownership_epoch,
    };
  }

  let route = await redisStore.claimWorldRoute(
    clean,
    SERVER_INSTANCE_ID,
    SERVER_INSTANCE_WS_URL,
    WORLD_ROUTE_TTL_MS,
    SERVER_PROCESS_OWNERSHIP_ID
  );
  if (route.ok) {
    let ownership: WorldPersistenceOwnership = {
      require_owner: POSTGRES_ENABLED && POSTGRES_AUTHORITATIVE && WORLD_ROUTE_ENFORCEMENT_ENABLED,
      server_instance: SERVER_INSTANCE_ID,
      ownership_token: clampString(route.ownership_token || "", MAX_WORLD_OWNERSHIP_TOKEN_LENGTH),
      ownership_epoch: Math.max(0, Math.trunc(Number(route.ownership_epoch) || 0)),
      fallback: route.fallback === true,
      verified: route.fallback !== true,
    };
    if (ownership.require_owner) {
      if (ownership.ownership_token === "" || ownership.ownership_epoch <= 0) {
        ownedWorldRoutes.delete(clean);
        worldPersistenceOwnership.delete(clean);
        worldUnpersistedRevisions.delete(clean);
        return { ...route, ok: false, reason: "world_route_missing_fence" };
      }
      const existing = worldPersistenceOwnership.get(clean);
      const alreadyFenced = existing?.verified
        && existing.ownership_token === ownership.ownership_token
        && existing.ownership_epoch === ownership.ownership_epoch;
      if (!alreadyFenced) {
        invalidateWorldEntrySnapshotCache(clean, "ownership_fence_changed");
        worldLoadedAuthorities.delete(clean);
        worldUnpersistedRevisions.delete(clean);
        let claimed = await postgresStore.claimWorldPersistenceOwnership(clean, ownership);
        if (!claimed?.ok && claimed?.reason === "world_ownership_fence_rejected") {
          // PostgreSQL's world_owner_epoch high-water mark is never cleared, but the
          // Redis counter that mints epochs CAN be lost (TTL expiry, flush, replica
          // failover). When it is, every claim asks for a smaller epoch than
          // PostgreSQL already holds and the world becomes PERMANENTLY unjoinable --
          // this took TEST offline on 2026-08-05 (epoch 322 in PostgreSQL, 3 in
          // Redis). Recover by reading the PostgreSQL floor and re-minting the Redis
          // epoch above it, then retrying the claim exactly once.
          const fenceEpoch = await postgresStore.getWorldOwnerEpoch(clean);
          const reseeded = await redisStore.claimWorldRoute(
            clean,
            SERVER_INSTANCE_ID,
            SERVER_INSTANCE_WS_URL,
            WORLD_ROUTE_TTL_MS,
            SERVER_PROCESS_OWNERSHIP_ID,
            fenceEpoch
          );
          const reseededEpoch = Math.max(0, Math.trunc(Number(reseeded.ownership_epoch) || 0));
          if (reseeded.ok && reseededEpoch > fenceEpoch) {
            route = reseeded;
            ownership = {
              ...ownership,
              ownership_token: clampString(reseeded.ownership_token || "", MAX_WORLD_OWNERSHIP_TOKEN_LENGTH),
              ownership_epoch: reseededEpoch,
              fallback: reseeded.fallback === true,
              verified: reseeded.fallback !== true,
            };
            claimed = await postgresStore.claimWorldPersistenceOwnership(clean, ownership);
          }
        }
        if (!claimed?.ok) {
          await redisStore.releaseWorldRoute(clean, SERVER_INSTANCE_ID, ownership.ownership_token);
          ownedWorldRoutes.delete(clean);
          worldPersistenceOwnership.delete(clean);
          worldUnpersistedRevisions.delete(clean);
          return {
            ...route,
            ok: false,
            reason: claimed?.reason || "world_persistence_fence_failed",
          };
        }
        worldPersistedRevisions.set(
          clean,
          PersistenceHelpers.normalizeWorldRevision(claimed.persisted_revision ?? claimed.loaded_revision)
        );
      }
    }
    ownedWorldRoutes.add(clean);
    worldPersistenceOwnership.set(clean, ownership);
    return route;

  }

  ownedWorldRoutes.delete(clean);
  invalidateWorldEntrySnapshotCache(clean, "route_claim_failed");
  worldLoadedAuthorities.delete(clean);
  worldPersistenceOwnership.delete(clean);
  worldUnpersistedRevisions.delete(clean);
  return route;
}

// Shutdown used to leave every owned world route claimed in Redis until its 45s TTL
// expired. Because SERVER_PROCESS_OWNERSHIP_ID embeds a fresh randomUUID per process, the
// restarted process could not reclaim its own worlds under the stale fence -- and with
// route enforcement on it redirected players to its own WS URL, a loop back to itself. So
// a routine restart locked every player out for up to 45 seconds and produced a retry
// storm. Releasing the leases we hold collapses that window to roughly zero on a graceful
// SIGTERM. Crash exits still rely on the TTL, which is the correct fallback.
async function releaseOwnedWorldRoutesForShutdown() {
  if (!redisStore.isReady()) return { released: 0, failed: 0, skipped: 0 };

  const worldNames = Array.from<string>(ownedWorldRoutes.values());
  let released = 0;
  let failed = 0;
  let skipped = 0;

  await Promise.all(worldNames.map(async (worldName) => {
    const clean = cleanWorld(worldName);
    const ownership = worldPersistenceOwnership.get(clean);
    const ownershipToken = String(ownership?.ownership_token || "");
    // Without our fencing token the release script would refuse anyway; leave the TTL to
    // reclaim it rather than risk releasing a route another instance now owns.
    if (ownershipToken === "") {
      skipped += 1;
      return;
    }

    try {
      const result = await redisStore.releaseWorldRoute(clean, SERVER_INSTANCE_ID, ownershipToken);
      if (result && result.ok === false) failed += 1;
      else released += 1;
    } catch {
      failed += 1;
    }
    ownedWorldRoutes.delete(clean);
  }));

  return { released, failed, skipped };
}

/**
 * @param {*} socket
 * @param {PixelMania.RuntimePlayer} player
 * @param {PixelMania.WorldName | string} worldName
 * @param {string} action
 * @returns {Promise<PixelMania.WorldRouteActionResult>}
 */
async function ensureWorldRouteForAction(socket: any, player: any, worldName: any, action: any) {
  const clean = cleanWorld(worldName || player?.world || "START");
  worldRouteStats.checks += 1;
  if (WORLD_ROUTE_ENFORCEMENT_ENABLED && !redisStore.isReady()) {
    worldRouteStats.unavailable += 1;
    worldRouteStats.redis_unhealthy += 1;
    const now = Date.now();
    if (now - Number(lastWorldRouteRedisUnhealthyWarnAt || 0) >= 15000) {
      lastWorldRouteRedisUnhealthyWarnAt = now;
      console.warn("[redis] world route enforcement requires Redis, but Redis is not ready.", {
        action,
        world: clean,
        server_instance_id: SERVER_INSTANCE_ID,
        redis_enabled: REDIS_ENABLED,
        redis_required: REDIS_REQUIRED_FOR_ROUTE_ENFORCEMENT,
      });
      logSecurityEvent(socket, player, "world_route_redis_unavailable", {
        action,
        world: clean,
        reason: "world_route_redis_unavailable",
        server_instance_id: SERVER_INSTANCE_ID,
        redis_enabled: REDIS_ENABLED,
        redis_required: REDIS_REQUIRED_FOR_ROUTE_ENFORCEMENT,
      }, "warning");
    }
    if (!REDIS_REQUIRED_FOR_ROUTE_ENFORCEMENT) {
      const fallbackRoute = await claimWorldRouteForCurrentInstance(clean);
      worldRouteStats.bypasses += 1;
      warnWorldRouteConflict(`${action} allowed on local-only routing because REDIS_REQUIRED_FOR_ROUTE_ENFORCEMENT is false`, clean, fallbackRoute);
      return { ok: true, route: fallbackRoute };
    }
    return { ok: rejectWorldRouteUnavailable(socket, action, clean), reason: "world_route_unavailable", world: clean };
  }

  const route = await claimWorldRouteForCurrentInstance(clean);
  if (route.ok) {
    worldRouteStats.allowed += 1;
    return { ok: true, route };
  }

  if (!WORLD_ROUTE_ENFORCEMENT_ENABLED) {
    worldRouteStats.bypasses += 1;
    warnWorldRouteConflict(`${action} allowed while world route enforcement is disabled`, clean, route);
    return { ok: true, route };
  }

  if (route.fallback && REDIS_ENABLED) {
    worldRouteStats.unavailable += 1;
    return { ok: rejectWorldRouteUnavailable(socket, action, clean), reason: "world_route_unavailable", route };
  }

  warnWorldRouteConflict(`${action} rejected by world route owner`, clean, route);
  return { ok: rejectWorldRouteRedirect(socket, action, clean, route), reason: "world_route_redirect", route };
}

async function refreshWorldRouteForPlayer(player: any) {
  if (!player || !player.joined_world) return;
  const clean = cleanWorld(player.world || player.current_world || "START");
  if (clean === "") return;

  const route = await claimWorldRouteForCurrentInstance(clean);
  if (!route.ok) {
    warnWorldRouteConflict("presence refresh could not renew local world route", clean, route);
  }
}

async function refreshOwnedWorldPersistenceLeases() {
  const worldNames = Array.from<string>(ownedWorldRoutes.values());
  let refreshed = 0;
  let failed = 0;
  for (const worldName of worldNames) {
    const previousOwnership = worldPersistenceOwnership.get(worldName);
    const route = await claimWorldRouteForCurrentInstance(worldName);
    if (route?.ok) {
      refreshed += 1;
      continue;
    }
    failed += 1;
    console.warn("[world-persistence] active ownership lease refresh failed", {
      world_id: worldName,
      server_instance: SERVER_INSTANCE_ID,
      ownership_token: previousOwnership?.ownership_token || "",
      ownership_epoch: previousOwnership?.ownership_epoch || 0,
      loaded_revision: PersistenceHelpers.normalizeWorldRevision(worldPersistedRevisions.get(worldName)),
      mutation_revision: worldStates.has(worldName) ? getWorldRevision(worldName) : 0,
      requested_save_revision: 0,
      persisted_revision: PersistenceHelpers.normalizeWorldRevision(worldPersistedRevisions.get(worldName)),
      affected_row_count: 0,
      save_result: route?.reason || "lease_refresh_failed",
    });
  }
  return { ok: failed === 0, refreshed, failed };
}

async function releaseOwnedWorldRouteIfEmpty(worldName: any) {
  const clean = cleanIndexedWorldName(worldName || "");
  if (clean === "") return;
  if (getWorldAdmissionCount(clean) > 0) return;

  const pendingSave = triggerPendingWorldSave(clean);
  if (pendingSave) {
    const saved = await pendingSave;
    if (saved !== true) {
      queueWorldSave(clean, { critical: true, mutation: false, reason: "route_release_retry" });
      console.warn("[world-persistence] retaining route after failed final save", {
        world_id: clean,
        server_instance: SERVER_INSTANCE_ID,
        save_result: "route_release_save_failed",
      });
      return;
    }
  }
  await worldPersistenceCoordinator.wait(clean);
  if (getWorldAdmissionCount(clean) > 0) return;
  const ownership = worldPersistenceOwnership.get(clean);
  const persistedRevision = PersistenceHelpers.normalizeWorldRevision(worldPersistedRevisions.get(clean));
  const mutationRevision = worldStates.has(clean) ? getWorldRevision(clean) : persistedRevision;
  if (redisStore.isReady() && ownership?.ownership_token) {
    const released = await redisStore.releaseWorldRoute(clean, SERVER_INSTANCE_ID, ownership.ownership_token);
    if (!released?.released && !released?.fallback) {
      console.warn("[world-persistence] route release fence rejected", {
        world_id: clean,
        server_instance: SERVER_INSTANCE_ID,
        ownership_token: ownership.ownership_token,
        ownership_epoch: ownership.ownership_epoch,
        save_result: released?.reason || "route_release_rejected",
      });
    }
  }
  if (getWorldAdmissionCount(clean) > 0) {
    await claimWorldRouteForCurrentInstance(clean);
    return;
  }
  ownedWorldRoutes.delete(clean);
  invalidateWorldEntrySnapshotCache(clean, "idle_world_unload");
  worldLoadedAuthorities.delete(clean);
  worldPersistenceOwnership.delete(clean);
  worldUnpersistedRevisions.delete(clean);
  worldPersistedRevisions.delete(clean);
  worldSaveWrites.delete(clean);

  const eventTimer = worldEventTimers.get(clean);
  if (eventTimer) clearTimeout(eventTimer);
  worldEventTimers.delete(clean);
  clearWorldEventCountdownTimers(clean);

  const broadcastTimer = pendingWorldUpdateBroadcastTimers.get(clean);
  if (broadcastTimer) clearTimeout(broadcastTimer);
  pendingWorldUpdateBroadcastTimers.delete(clean);
  pendingWorldUpdateBroadcasts.delete(clean);
  movementCollisionCacheByWorld.delete(clean);
  movementCollisionWorldRevision.delete(clean);
  worldStates.delete(clean);

  console.log("[world-persistence]", JSON.stringify({
    event: "idle_unload",
    world_id: clean,
    server_instance: SERVER_INSTANCE_ID,
    ownership_token: ownership?.ownership_token || "",
    ownership_epoch: ownership?.ownership_epoch || 0,
    loaded_revision: persistedRevision,
    mutation_revision: mutationRevision,
    requested_save_revision: 0,
    persisted_revision: persistedRevision,
    affected_row_count: 0,
    save_result: "unloaded_after_route_release",
  }));
}

function getWorldPopulationCount(worldName: any, excludePlayerId: any = "") {
  const clean = cleanWorld(worldName || "START");
  return getWorldPlayerRecords(clean, { excludePlayerId }).length;
}

function addActiveWorldDirectoryPlayer(
  worldPlayersByName: Map<string, Set<string>>,
  worldName: unknown,
  playerIdentity: unknown,
) {
  const rawWorldName = String(worldName || "").trim();
  const identity = String(playerIdentity || "").trim();
  if (rawWorldName === "" || identity === "") return;

  const cleanWorldName = cleanWorld(rawWorldName);
  if (cleanWorldName === "") return;
  let identities = worldPlayersByName.get(cleanWorldName);
  if (!identities) {
    identities = new Set<string>();
    worldPlayersByName.set(cleanWorldName, identities);
  }
  identities.add(identity);
}

async function buildGlobalActiveWorldPopulationCounts(): Promise<Record<string, number>> {
  const worldPlayersByName = new Map<string, Set<string>>();

  if (redisStore.isReady()) {
    const presenceRecords = await redisStore.listPresence(ACTIVE_WORLD_DIRECTORY_PRESENCE_LIMIT);
    for (const presence of presenceRecords) {
      if (!presence || presence.joined_world !== true) continue;
      const identity = presence.username || presence.player_id;
      if (!identity) continue;
      addActiveWorldDirectoryPlayer(
        worldPlayersByName,
        presence.world,
        presence.username ? `account:${presence.username}` : `player:${identity}`,
      );
    }
  }

  // Merge this route's live records so a join appears before its Redis write
  // completes and so the directory remains useful during a Redis interruption.
  for (const runtimePlayer of players.values()) {
    if (!runtimePlayer || !runtimePlayer.authenticated || !runtimePlayer.joined_world || runtimePlayer.disconnected) continue;
    addActiveWorldDirectoryPlayer(
      worldPlayersByName,
      runtimePlayer.world,
      runtimePlayer.account_username ? `account:${runtimePlayer.account_username}` : `player:${runtimePlayer.id}`,
    );
  }

  const entries = [...worldPlayersByName.entries()]
    .map(([world, identities]) => ({ world, count: identities.size }))
    .filter((entry) => entry.count > 0)
    .sort((left, right) => right.count - left.count || left.world.localeCompare(right.world));

  const counts: Record<string, number> = {};
  for (const entry of entries) {
    counts[entry.world] = entry.count;
  }
  return counts;
}

async function getGlobalActiveWorldPopulationCounts(): Promise<Record<string, number>> {
  const now = Date.now();
  if (now < activeWorldDirectoryCacheExpiresAt) {
    return { ...activeWorldDirectoryCache };
  }
  if (activeWorldDirectoryBuildPromise) {
    return { ...(await activeWorldDirectoryBuildPromise) };
  }

  activeWorldDirectoryBuildPromise = buildGlobalActiveWorldPopulationCounts();
  try {
    const counts = await activeWorldDirectoryBuildPromise;
    activeWorldDirectoryCache = { ...counts };
    activeWorldDirectoryCacheExpiresAt = Date.now() + ACTIVE_WORLD_DIRECTORY_CACHE_MS;
    return { ...counts };
  } finally {
    activeWorldDirectoryBuildPromise = null;
  }
}

async function handleWorldPopulationRequest(
  socket: unknown,
  player: ServerPacketRecord,
  _data: ServerPacketRecord,
  _context: ServerRouteContext,
) {
  if (!requireAuthenticated(socket, player, "view active worlds")) return;

  const worldCounts = await getGlobalActiveWorldPopulationCounts();
  sendJson(socket, {
    type: "world_population",
    world_counts: worldCounts,
    clear_unreported: true,
    global: true,
    generated_at: new Date().toISOString(),
  });
}

function getWorldPopulationForBatching(worldName: any) {
  const clean = cleanWorld(worldName || "START");
  const set = getWorldPlayerIdSet(clean, false);
  return set && set.size ? set.size : 0;
}

