function getAdaptiveWorldUpdateBatchProfile(worldName: any) {
  return ServerPhase6Helpers.getAdaptiveWorldUpdateBatchProfile(worldName);
}

function getPlayerPositionHeartbeatIntervalMs(worldName: any) {
  return ServerPhase6Helpers.getPlayerPositionHeartbeatIntervalMs(worldName);
}

/**
 * @param {PixelMania.WorldName | string} worldName
 * @returns {PixelMania.ClientMovementGuidance}
 */
function buildClientMovementGuidance(worldName: any) {
  return ServerPhase6Helpers.buildClientMovementGuidance(worldName);
}

function getPendingWorldAdmissionCount(worldName: any, excludePlayerId: any = "") {
  const clean = cleanWorld(worldName || "START");
  const excluded = String(excludePlayerId || "").trim();
  const pending = pendingWorldAdmissions.get(clean);
  if (!pending || pending.size === 0) return 0;
  let count: any = 0;
  for (const playerId of pending.values()) {
    if (excluded !== "" && playerId === excluded) continue;
    count += 1;
  }
  return count;
}

function getWorldAdmissionCount(worldName: any, excludePlayerId: any = "") {
  const clean = cleanWorld(worldName || "START");
  return getWorldPopulationCount(clean, excludePlayerId) + getPendingWorldAdmissionCount(clean, excludePlayerId);
}

function canPlayerJoinWorld(player: any, worldName: any) {
  if (!player) return false;
  const clean = cleanWorld(worldName || "START");
  const playerId = String(player.id || "").trim();
  if (player.joined_world && cleanWorld(player.world || "START") === clean) {
    return true;
  }
  return getWorldAdmissionCount(clean, playerId) < MAX_PLAYERS_PER_WORLD;
}

/**
 * @param {PixelMania.RuntimePlayer} player
 * @param {PixelMania.WorldName | string} worldName
 * @returns {PixelMania.WorldAdmissionReservation}
 */
function reserveLocalWorldAdmission(player: any, worldName: any) {
  if (!player) return { ok: false, reason: "missing_player" };
  const clean = cleanWorld(worldName || "START");
  const playerId = String(player.id || "").trim();
  if (playerId === "") return { ok: false, reason: "missing_player_id" };
  if (player.joined_world && cleanWorld(player.world || "START") === clean) {
    return { ok: true, reserved: false, world: clean, player_id: playerId };
  }
  if (!canPlayerJoinWorld(player, clean)) {
    return { ok: false, reason: "world_full", world: clean, player_id: playerId };
  }

  let pending: any = pendingWorldAdmissions.get(clean);
  if (!pending) {
    pending = new Set();
    pendingWorldAdmissions.set(clean, pending);
  }
  pending.add(playerId);
  return { ok: true, reserved: true, world: clean, player_id: playerId };
}

function releaseLocalWorldAdmissionReservation(reservation: any) {
  if (!reservation || reservation.local_reserved !== true) return;
  const clean = cleanWorld(reservation.world || "");
  const playerId = String(reservation.player_id || "").trim();
  if (clean === "" || playerId === "") return;
  const pending = pendingWorldAdmissions.get(clean);
  if (!pending) return;
  pending.delete(playerId);
  if (pending.size === 0) pendingWorldAdmissions.delete(clean);
  reservation.local_reserved = false;
}

async function releaseRedisWorldAdmission(worldName: any, playerId: any) {
  const clean = cleanIndexedWorldName(worldName || "");
  const cleanPlayerId = String(playerId || "").trim();
  if (clean === "" || cleanPlayerId === "" || !redisStore.isReady()) return;
  await redisStore.releaseWorldAdmission(clean, cleanPlayerId);
}

async function releasePlayerWorldAdmission(playerOrId: any, worldName: any = "") {
  const player = playerOrId && typeof playerOrId === "object" ? playerOrId : players.get(String(playerOrId || "").trim());
  const playerId = String(player?.id || playerOrId || "").trim();
  if (playerId === "") return;

  const clean = cleanIndexedWorldName(worldName || player?.redis_admission_world || player?.indexed_world || player?.world || "");
  if (clean === "") return;
  if (player && cleanIndexedWorldName(player.redis_admission_world || "") === clean) {
    player.redis_admission_world = "";
  }
  await releaseRedisWorldAdmission(clean, playerId);
}

async function refreshPlayerWorldAdmission(player: any) {
  const entryPending = player
    && !player.joined_world
    && String(player.world_entry_state || "") === "snapshot_sent"
    && cleanIndexedWorldName(player.redis_admission_world || "") !== "";
  if (!redisStore.isReady() || !player || (!player.joined_world && !entryPending)) return;
  const playerId = String(player.id || "").trim();
  const clean = cleanWorld(player.world || player.current_world || "START");
  if (playerId === "" || clean === "") return;

  const previousWorld = cleanIndexedWorldName(player.redis_admission_world || "");
  if (previousWorld !== "" && previousWorld !== clean) {
    await releaseRedisWorldAdmission(previousWorld, playerId);
    player.redis_admission_world = "";
  }

  const result: any = await redisStore.refreshWorldAdmission(clean, playerId, MAX_PLAYERS_PER_WORLD, WORLD_ADMISSION_TTL_MS);
  if (result.ok && !result.fallback) {
    player.redis_admission_world = clean;
    return;
  }

  if (!result.ok) {
    const now = Date.now();
    if (now - Number(player.last_world_admission_warning_at || 0) > 10000) {
      player.last_world_admission_warning_at = now;
      console.warn("[redis] world admission refresh rejected", {
        player_id: playerId,
        username: player.account_username || player.name || "",
        world: clean,
        current_players: Number(result.count || 0),
        max_players: MAX_PLAYERS_PER_WORLD,
      });
    }
  }
}

/**
 * @param {PixelMania.RuntimePlayer} player
 * @param {PixelMania.WorldName | string} worldName
 * @param {string} action
 * @returns {Promise<PixelMania.WorldAdmissionReservation>}
 */
async function reserveWorldAdmission(player: any, worldName: any, action: any = "join_world") {
  if (!player) return { ok: false, reason: "missing_player" };
  const clean = cleanWorld(worldName || "START");
  const playerId = String(player.id || "").trim();
  if (playerId === "") return { ok: false, reason: "missing_player_id" };
  if (player.joined_world && cleanWorld(player.world || "START") === clean) {
    await refreshPlayerWorldAdmission(player);
    return { ok: true, reserved: false, world: clean, player_id: playerId };
  }
  if (!canPlayerJoinWorld(player, clean)) {
    return { ok: false, reason: "world_full", world: clean, player_id: playerId };
  }

  if (WORLD_ROUTE_ENFORCEMENT_ENABLED && redisStore.isReady()) {
    const route = await claimWorldRouteForCurrentInstance(clean);
    if (!route.ok || route.owner_instance_id !== SERVER_INSTANCE_ID) {
      const routeOwner = String(route.owner_instance_id || "").trim();
      const routeWsUrl = String(route.ws_url || "").trim();
      warnWorldRouteAdmissionMismatch(`${action} route ownership changed after admission check`, clean, {
        ...route,
        action,
        reason: route.reason || "world_route_admission_mismatch",
      });
      logSecurityEvent(null, player, "world_route_admission_mismatch", {
        action,
        reason: route.reason || "world_route_admission_mismatch",
        world: clean,
        owner_instance_id: routeOwner,
        redirect_ws_url: routeWsUrl,
        server_instance_id: SERVER_INSTANCE_ID,
      }, "warning");
      return {
        ok: false,
        reason: "world_route_admission_mismatch",
        route_reason: route.reason || "world_route_admission_mismatch",
        world: clean,
        player_id: playerId,
        owner_instance_id: routeOwner,
        ws_url: routeWsUrl,
      };
    }
  }

  let redisAdmission: any = null;
  if (redisStore.isReady()) {
    redisAdmission = await redisStore.reserveWorldAdmission(clean, playerId, MAX_PLAYERS_PER_WORLD, WORLD_ADMISSION_TTL_MS);
    if (!redisAdmission.ok) {
      return {
        ok: false,
        reason: redisAdmission.reason || "world_full",
        world: clean,
        player_id: playerId,
        current_players: Number(redisAdmission.count || 0),
      };
    }
  }

  const localAdmission = reserveLocalWorldAdmission(player, clean);
  if (!localAdmission.ok) {
    if (redisAdmission && !redisAdmission.fallback) {
      await releaseRedisWorldAdmission(clean, playerId);
    }
    return localAdmission;
  }

  return {
    ok: true,
    reserved: true,
    local_reserved: localAdmission.reserved === true,
    redis_reserved: Boolean(redisAdmission && redisAdmission.ok && !redisAdmission.fallback),
    fallback: !redisAdmission || redisAdmission.fallback === true,
    world: clean,
    player_id: playerId,
    current_players: redisAdmission && Number.isFinite(Number(redisAdmission.count)) ? Number(redisAdmission.count) : getWorldAdmissionCount(clean),
  };
}

/**
 * @param {PixelMania.WorldAdmissionReservation | null | undefined} reservation
 * @param {PixelMania.RuntimePlayer | null | undefined} player
 * @param {PixelMania.WorldName | string} previousWorld
 * @returns {Promise<void>}
 */
async function commitWorldAdmissionReservation(reservation: any, player: any, previousWorld: any = "") {
  if (!reservation || !reservation.ok) return;
  releaseLocalWorldAdmissionReservation(reservation);

  const clean = cleanWorld(reservation.world || "");
  const playerId = String(player?.id || reservation.player_id || "").trim();
  if (playerId === "" || clean === "") return;

  const oldRedisWorld = cleanIndexedWorldName(previousWorld || player?.redis_admission_world || "");
  if (oldRedisWorld !== "" && oldRedisWorld !== clean) {
    await releaseRedisWorldAdmission(oldRedisWorld, playerId);
  }

  if (player && reservation.redis_reserved === true) {
    player.redis_admission_world = clean;
  }
  reservation.committed = true;
}

/**
 * @param {PixelMania.WorldAdmissionReservation | null | undefined} reservation
 * @returns {Promise<void>}
 */
async function releaseWorldAdmissionReservation(reservation: any) {
  if (!reservation || reservation.committed === true) return;
  releaseLocalWorldAdmissionReservation(reservation);
  if (reservation.redis_reserved === true) {
    await releaseRedisWorldAdmission(reservation.world, reservation.player_id);
  }
}

function rejectWorldCapacity(socket: any, action: any, worldName: any, playerId: any = "", options: any = {}) {
  const clean = cleanWorld(worldName || "START");
  const overrideCount = Number(options.current_players ?? options.currentPlayers);
  const currentPlayers = Number.isFinite(overrideCount) ? Math.max(0, Math.trunc(overrideCount)) : getWorldAdmissionCount(clean, playerId);
  sendActionRejected(socket, action, "That world is full.", {
    reason: "world_full",
    world: clean,
    current_players: currentPlayers,
    max_players: MAX_PLAYERS_PER_WORLD,
  });
  return false;
}

/**
 * @param {PixelMania.WorldName | string} worldName
 * @returns {PixelMania.WorldPopulationUpdatePayload}
 */
function buildWorldPopulationUpdatePayload(worldName: any) {
  return ServerPhase6Helpers.buildWorldPopulationUpdatePayload(worldName);
}

function sendWorldPopulationUpdate(socket: any, worldName: any) {
  sendJson(socket, buildWorldPopulationUpdatePayload(worldName));
}

function broadcastWorldPopulationUpdate(worldName: any) {
  const clean = cleanWorld(worldName || "START");
  broadcastToWorld(clean, buildWorldPopulationUpdatePayload(clean));
}

function isDropInterestManagementEnabled() {
  return DROP_INTEREST_MANAGEMENT_ENABLED && DROP_INTEREST_RADIUS_PIXELS > 0;
}

function isPlayerInterestManagementEnabled() {
  return PLAYER_INTEREST_MANAGEMENT_ENABLED && PLAYER_INTEREST_RADIUS_PIXELS > 0;
}

function getPlayerInterestSet(receiverPlayerId: any, create: any = false) {
  const receiverId = String(receiverPlayerId || "").trim();
  if (receiverId === "") return null;

  let set: any = playerInterestByReceiver.get(receiverId);
  if (!set && create) {
    set = new Set();
    playerInterestByReceiver.set(receiverId, set);
  }
  return set || null;
}

function isPlayerMarkedInInterest(receiverPlayerId: any, subjectPlayerId: any) {
  const set = getPlayerInterestSet(receiverPlayerId, false);
  return Boolean(set && set.has(String(subjectPlayerId || "").trim()));
}

function setPlayerInterestVisible(receiverPlayerId: any, subjectPlayerId: any, visible: any) {
  const receiverId = String(receiverPlayerId || "").trim();
  const subjectId = String(subjectPlayerId || "").trim();
  if (receiverId === "" || subjectId === "" || receiverId === subjectId) return;

  if (visible) {
    getPlayerInterestSet(receiverId, true).add(subjectId);
    return;
  }

  const set = getPlayerInterestSet(receiverId, false);
  if (!set) return;
  set.delete(subjectId);
  if (set.size === 0) playerInterestByReceiver.delete(receiverId);
}

function clearPlayerInterestState(playerId: any) {
  const cleanId = String(playerId || "").trim();
  if (cleanId === "") return;

  playerInterestByReceiver.delete(cleanId);
  clearDropInterestStateForReceiver(cleanId);
  for (const [receiverId, set] of playerInterestByReceiver.entries()) {
    set.delete(cleanId);
    if (set.size === 0) playerInterestByReceiver.delete(receiverId);
  }
}

function getDropInterestSet(receiverPlayerId: any, create: any = false) {
  const receiverId = String(receiverPlayerId || "").trim();
  if (receiverId === "") return null;

  let set: any = dropInterestByReceiver.get(receiverId);
  if (!set && create) {
    set = new Set();
    dropInterestByReceiver.set(receiverId, set);
  }
  return set || null;
}

function isDropMarkedInInterest(receiverPlayerId: any, dropId: any) {
  const set = getDropInterestSet(receiverPlayerId, false);
  return Boolean(set && set.has(clampString(dropId || "", MAX_DROP_ID_LENGTH)));
}

function setDropInterestVisible(receiverPlayerId: any, dropId: any, visible: any) {
  const receiverId = String(receiverPlayerId || "").trim();
  const cleanDropId = clampString(dropId || "", MAX_DROP_ID_LENGTH);
  if (receiverId === "" || cleanDropId === "") return;

  if (visible) {
    getDropInterestSet(receiverId, true).add(cleanDropId);
    return;
  }

  const set = getDropInterestSet(receiverId, false);
  if (!set) return;
  set.delete(cleanDropId);
  if (set.size === 0) dropInterestByReceiver.delete(receiverId);
}

function clearDropInterestStateForReceiver(playerId: any) {
  const cleanId = String(playerId || "").trim();
  if (cleanId === "") return;
  dropInterestByReceiver.delete(cleanId);
}

function clearDropInterestStateForDrop(dropId: any) {
  const cleanDropId = clampString(dropId || "", MAX_DROP_ID_LENGTH);
  if (cleanDropId === "") return;
  for (const [receiverId, set] of dropInterestByReceiver.entries()) {
    set.delete(cleanDropId);
    if (set.size === 0) dropInterestByReceiver.delete(receiverId);
  }
}

function getDropPublicId(drop: any) {
  return ServerPhase6Helpers.getDropPublicId(drop);
}

function getDropPublicPosition(drop: any) {
  return ServerPhase6Helpers.getDropPublicPosition(drop);
}

function getSquaredDropDistance(player: any, drop: any) {
  return ServerPhase6Helpers.getSquaredDropDistance(player, drop);
}

function getDropInterestReceiverPosition(receiver: any, worldName: any = "") {
  if (!receiver || !usesTrustedMovementPosition(receiver)) return receiver;

  const trusted = getPlayerValidationPosition(receiver, {
    action: "drop_interest",
    world: cleanWorld(worldName || receiver.world || "START"),
  });
  return trusted.ok ? trusted : receiver;
}

function isReceiverEligibleForDropVisibility(receiver: unknown, worldName: unknown = "") {
  if (!receiver || typeof receiver !== "object") return false;

  const record = receiver as ServerPacketRecord;
  const clean = cleanWorld(worldName || record.world || record.current_world || record.world_entry_world || "START");
  const receiverWorld = cleanWorld(record.world || record.current_world || "START");
  if (record.joined_world === true && receiverWorld === clean) return true;

  const entryWorld = cleanWorld(record.world_entry_world || record.world || record.current_world || "");
  return record.joined_world !== true
    && String(record.world_entry_state || "") === "snapshot_sent"
    && entryWorld === clean;
}

function shouldReceiverSeeDrop(receiver: any, drop: any, worldName: any = "") {
  if (!receiver || !drop) return false;

  const clean = cleanWorld(worldName || receiver.world || drop.world || "START");
  if (!isReceiverEligibleForDropVisibility(receiver, clean)) return false;
  if (cleanWorld(receiver.world || receiver.current_world || receiver.world_entry_world || "START") !== clean) return false;
  if (!isDropInterestManagementEnabled()) return true;

  const receiverPosition = getDropInterestReceiverPosition(receiver, clean);
  const distanceSq = getSquaredDropDistance(receiverPosition, drop);
  if (distanceSq === null) return true;

  const dropId = getDropPublicId(drop);
  const wasVisible = isDropMarkedInInterest(receiver.id, dropId);
  const radius = wasVisible ? DROP_INTEREST_LEAVE_RADIUS_PIXELS : DROP_INTEREST_RADIUS_PIXELS;
  return distanceSq <= radius * radius;
}

function getSquaredPlayerDistance(a: any, b: any) {
  const ax = Number(a?.x);
  const ay = Number(a?.y);
  const bx = Number(b?.x);
  const by = Number(b?.y);
  // Called once per (receiver, subject) pair per broadcast flush -- millions of times a
  // second at 500 players. The previous `[ax, ay, bx, by].every(...)` allocated a throwaway
  // array and a closure call on every check.
  if (!Number.isFinite(ax) || !Number.isFinite(ay) || !Number.isFinite(bx) || !Number.isFinite(by)) return null;

  const dx = ax - bx;
  const dy = ay - by;
  return dx * dx + dy * dy;
}

function shouldReceiverSeeSubject(receiver: any, subject: any, worldName: any = "") {
  if (!receiver || !subject) return false;
  if (receiver.id === subject.id) return false;
  if (!receiver.joined_world || !subject.joined_world) return false;

  // This runs once per (receiver, subject) pair per broadcast flush. cleanWorld() is a
  // trim + uppercase + two regex replaces + slice, and it was being called three times
  // per pair -- millions of string allocations per second at 500 players. cleanWorld is
  // idempotent, so a raw value that already equals `clean` needs no second normalization,
  // and the hot callers all pass an already-cleaned world name.
  const clean = cleanWorld(worldName || receiver.world || subject.world || "START");
  const receiverWorld = receiver.world || "START";
  if (receiverWorld !== clean && cleanWorld(receiverWorld) !== clean) return false;
  const subjectWorld = subject.world || "START";
  if (subjectWorld !== clean && cleanWorld(subjectWorld) !== clean) return false;
  if (!isPlayerInterestManagementEnabled()) return true;

  const distanceSq = getSquaredPlayerDistance(receiver, subject);
  if (distanceSq === null) return true;

  const wasVisible = isPlayerMarkedInInterest(receiver.id, subject.id);
  const radius = wasVisible ? PLAYER_INTEREST_LEAVE_RADIUS_PIXELS : PLAYER_INTEREST_RADIUS_PIXELS;
  return distanceSq <= radius * radius;
}

function buildInterestCullPayload(subject: any, worldName: any) {
  return {
    ...buildPublicPlayerPresencePayload("player_left", subject, worldName),
    interest_cull: true,
    reason: "out_of_interest",
  };
}

function sendRawPresenceToSocket(socket: any, raw: any, subject: any, worldName: any, messageType: any) {
  if (sendRawJsonToSocket(socket, raw, "player_interest", {
    player_id: String(socket?.playerId || ""),
    subject_player_id: String(subject?.id || ""),
    world: cleanWorld(worldName || subject?.world || "START"),
    message_type: String(messageType || ""),
  })) {
    playerNetworkStats.individual_presence_packets_sent += 1;
    if (String(messageType || "") === "player_left") {
      playerNetworkStats.interest_culls_sent += 1;
    }
  }
}

function supportsPlayerPositionBatch(player: any) {
  if (!PLAYER_POSITION_BATCHING_ENABLED) return false;
  const comparison = compareVersions(player?.client_version || "", PLAYER_POSITION_BATCH_MIN_CLIENT_VERSION);
  return comparison !== null && comparison >= 0;
}

function queuePlayerPositionBatchPayload(batches: any, socket: any, payload: any, worldName: any = "") {
  if (!batches || !socket || socket.readyState !== WebSocket.OPEN || !payload) return false;

  const receiver = players.get(socket.playerId);
  if (!supportsPlayerPositionBatch(receiver)) return false;

  const receiverId = String(socket.playerId || "").trim();
  if (receiverId === "") return false;

  let batch: any = batches.get(receiverId);
  if (!batch) {
    batch = {
      socket,
      world: cleanWorld(worldName || receiver?.world || payload.world || "START"),
      players: [],
      left: [],
    };
    batches.set(receiverId, batch);
  }

  if (payload.type === "player_left") {
    batch.left.push(payload);
  } else {
    batch.players.push(payload);
  }
  return true;
}

function deliverPlayerPresencePayload(socket: any, payload: any, worldName: any = "", batches: any = null) {
  if (!socket || socket.readyState !== WebSocket.OPEN || !payload) return;
  if (queuePlayerPositionBatchPayload(batches, socket, payload, worldName)) return;
  sendJson(socket, payload);
  playerNetworkStats.individual_presence_packets_sent += 1;
  if (batches) playerNetworkStats.batch_fallback_individual_sends += 1;
  if (payload.type === "player_left") playerNetworkStats.interest_culls_sent += 1;
}

function flushPlayerPositionBatches(batches: any) {
  if (!batches || batches.size === 0) return;

  for (const batch of batches.values()) {
    if (!batch?.socket || batch.socket.readyState !== WebSocket.OPEN) continue;
    if (batch.players.length === 0 && batch.left.length === 0) continue;
    const profile = getAdaptivePlayerPositionBatchProfile(batch.world);
    const maxItems = clampBatchMaxItems(profile.max_items, PLAYER_POSITION_BATCH_MAX_ITEMS);

    let playerIndex: any = 0;
    let leftIndex: any = 0;
    while (playerIndex < batch.players.length || leftIndex < batch.left.length) {
      const payload: any = {
        type: "player_position_batch",
        world: batch.world,
      };

      const players = batch.players.slice(playerIndex, playerIndex + maxItems);
      playerIndex += players.length;
      let remainingSlots: any = Math.max(0, maxItems - players.length);
      const left = batch.left.slice(leftIndex, leftIndex + remainingSlots);
      leftIndex += left.length;

      if (players.length > 0) payload.players = players;
      if (left.length > 0) payload.left = left;
      ServerSocketDeliveryHelpers.sendPlayerPositionBatch(batch.socket, payload, maxItems);
    }
  }
}

function broadcastPlayerPresenceToInterestedPlayers(subject: any, payload: any, excludePlayerId: any = "") {
  if (!subject || !payload) return;
  const clean = cleanWorld(payload.world || subject.world || "START");
  if (!isPlayerInterestManagementEnabled()) {
    broadcastToWorld(clean, payload, excludePlayerId);
    return;
  }

  let raw;
  try {
    raw = JSON.stringify(payload);
  } catch (error) {
    console.warn("[broadcast_serialize_error]", {
      world: clean,
      message: getErrorMessage(error),
    });
    return;
  }

  let cullRaw: any = "";
  for (const { player: receiver, socket: client } of getWorldPlayerRecords(clean, {
    includeSocket: true,
    excludePlayerId,
  })) {
    if (receiver.id === subject.id) continue;

    if (shouldReceiverSeeSubject(receiver, subject, clean)) {
      setPlayerInterestVisible(receiver.id, subject.id, true);
      sendRawPresenceToSocket(client, raw, subject, clean, payload.type);
      continue;
    }

    if (!isPlayerMarkedInInterest(receiver.id, subject.id)) continue;
    if (cullRaw === "") cullRaw = JSON.stringify(buildInterestCullPayload(subject, clean));
    setPlayerInterestVisible(receiver.id, subject.id, false);
    sendRawPresenceToSocket(client, cullRaw, subject, clean, "player_left");
  }
}

function queuePlayerPresenceToInterestedPlayers(subject: any, payload: any, excludePlayerId: any = "", batches: any = null, sharedRecords: any = null) {
  if (!subject || !payload) return;
  const clean = cleanWorld(payload.world || subject.world || "START");

  // sharedRecords lets the broadcast flush build the world's recipient list ONCE per flush
  // instead of once per moving player. getWorldPlayerRecords allocates an Array.from copy
  // of the world id set plus one record object per recipient, so rebuilding it per mover
  // was O(players^2) allocations per flush. When a shared list is supplied we apply the
  // excludePlayerId filter here, exactly as getWorldPlayerRecords would have.
  const excludedPlayerId = String(excludePlayerId || "").trim();
  const recipientRecords = sharedRecords || getWorldPlayerRecords(clean, {
    includeSocket: true,
    excludePlayerId,
  });

  for (const { playerId, player: receiver, socket: client } of recipientRecords) {
    if (sharedRecords && excludedPlayerId !== "" && playerId === excludedPlayerId) continue;

    if (!isPlayerInterestManagementEnabled() || shouldReceiverSeeSubject(receiver, subject, clean)) {
      setPlayerInterestVisible(receiver.id, subject.id, true);
      playerNetworkStats.interest_visible_deliveries += 1;
      deliverPlayerPresencePayload(client, payload, clean, batches);
      continue;
    }

    if (!isPlayerMarkedInInterest(receiver.id, subject.id)) continue;
    setPlayerInterestVisible(receiver.id, subject.id, false);
    deliverPlayerPresencePayload(client, buildInterestCullPayload(subject, clean), clean, batches);
  }
}

function syncPlayerInterestForReceiver(socket: any, receiver: any, worldName: any = "", batches: any = null, sharedRecords: any = null) {
  if (!socket || socket.readyState !== WebSocket.OPEN) return;
  if (!receiver || !receiver.joined_world) return;
  if (!isPlayerInterestManagementEnabled()) return;

  const clean = cleanWorld(worldName || receiver.world || "START");
  playerNetworkStats.receiver_interest_syncs += 1;
  // See queuePlayerPresenceToInterestedPlayers: a shared per-flush record list avoids
  // rebuilding the world recipient list once per moving player. Records built with
  // includeSocket still expose .player, so the socket-bearing list is safe to reuse here.
  for (const { player: subject } of (sharedRecords || getWorldPlayerRecords(clean))) {
    if (subject.id === receiver.id) continue;

    const shouldSee = shouldReceiverSeeSubject(receiver, subject, clean);
    const wasVisible = isPlayerMarkedInInterest(receiver.id, subject.id);
    if (shouldSee && !wasVisible) {
      setPlayerInterestVisible(receiver.id, subject.id, true);
      deliverPlayerPresencePayload(socket, buildPublicPlayerPresencePayload("player_position", subject, clean), clean, batches);
    } else if (!shouldSee && wasVisible) {
      setPlayerInterestVisible(receiver.id, subject.id, false);
      deliverPlayerPresencePayload(socket, buildInterestCullPayload(subject, clean), clean, batches);
    }
  }
}

function publishPlayerPresenceUpdate(socket: any, player: any, worldName: any, type: any = "player_position", excludePlayerId: any = "") {
  const clean = cleanWorld(worldName || player?.world || "START");
  broadcastPlayerPresenceToInterestedPlayers(
    player,
    buildPublicPlayerPresencePayload(type, player, clean),
    excludePlayerId
  );
  syncPlayerInterestForReceiver(socket || getSocketByPlayerId(player?.id), player, clean);
}

function broadcastPlayerActionToInterestedPlayers(worldName: any, payload: any, actors: any = []) {
  const clean = cleanWorld(worldName || payload?.world || "START");
  const actorList = Array.isArray(actors) ? actors.filter(Boolean) : [];
  if (!PLAYER_ACTION_INTEREST_MANAGEMENT_ENABLED || actorList.length === 0) {
    broadcastToWorld(clean, payload);
    return;
  }

  const actorIds: any = new Set(actorList.map((actor) => String(actor?.id || "")).filter((id) => id !== ""));
  // `payload` is identical for every receiver -- serialize once, not per recipient.
  const rawPayload = serializeBroadcastPayloadOnce(payload, "player_action_effect");
  if (rawPayload === null) return;
  const payloadType = String(payload?.type || "");

  for (const { player: receiver, socket: client } of getWorldPlayerRecords(clean, { includeSocket: true })) {
    const receiverId = String(receiver.id || client.playerId || "");
    let shouldSend: any = actorIds.has(receiverId);
    if (!shouldSend) {
      shouldSend = actorList.some((actor) => shouldReceiverSeeSubject(receiver, actor, clean));
    }

    if (!shouldSend) {
      playerNetworkStats.action_effect_packets_skipped += 1;
      continue;
    }

    sendRawJsonToSocket(client, rawPayload, "direct_send", { message_type: payloadType });
    playerNetworkStats.action_effect_packets_sent += 1;
  }
}

function getPlayersInWorld(worldName: any, excludePlayerId: any = "", receiverPlayer: any = null) {
  const result: any = [];
  const clean = cleanWorld(worldName || "START");
  const now = Date.now();

  for (const { player } of getWorldPlayerRecords(clean, { excludePlayerId })) {
    if (receiverPlayer && !shouldReceiverSeeSubject(receiverPlayer, player, clean)) continue;

    if (receiverPlayer && isPlayerInterestManagementEnabled()) {
      setPlayerInterestVisible(receiverPlayer.id, player.id, true);
    }
    refreshPlayerFishingPresence(player, clean);
    const equipmentSlots = player.equipment_slots || {};
    const fishingTargetX = Number.isInteger(player.fishing_target_x) ? player.fishing_target_x : -1;
    const fishingTargetY = Number.isInteger(player.fishing_target_y) ? player.fishing_target_y : -1;
    const fishingActive = player.fishing_active === true && isGridInWorld(fishingTargetX, fishingTargetY);
    const damageFlash = getPublicPlayerDamageFlash(player);
    result.push({
      player_id: player.id,
      ...getPublicPlayerIdentity(player),
      x: player.x,
      y: player.y,
	      facing: player.facing,
	      world: player.world,
	      animation_state: player.animation_state || "idle",
      movement_sequence: Math.max(0, Math.trunc(Number(player.movement_sequence) || 0)),
      server_time_msec: Math.max(0, Math.trunc(Number(player.movement_server_time_msec) || now)),
      velocity_x: sanitizePlayerVelocity(player.velocity_x || 0),
      velocity_y: sanitizePlayerVelocity(player.velocity_y || 0),
      on_floor: player.on_floor !== false,
      in_water: player.in_water === true,
      in_lava_fire: player.in_lava_fire === true,
      chat_typing: player?.chat_typing === true,
      ...damageFlash,
      fishing_active: fishingActive,
      fishing_target_x: fishingActive ? fishingTargetX : -1,
      fishing_target_y: fishingActive ? fishingTargetY : -1,
      fishing_lure_id: fishingActive ? clampString(player.fishing_lure_id || "") : "",
      fishing_rod_id: fishingActive ? clampString(player.fishing_rod_id || "") : "",
      equipment_slots: equipmentSlots,
      equipped_tool: clampString(equipmentSlots.hand || ""),
      equipped_back_item: clampString(equipmentSlots.back || ""),
      equipped_back: clampString(equipmentSlots.back || ""),
      equipped_hat_item: clampString(equipmentSlots.hat || ""),
      equipped_hair_item: clampString(equipmentSlots.hair || ""),
      equipped_eyewear_item: clampString(equipmentSlots.eyewear || ""),
      equipped_shirt_item: clampString(equipmentSlots.shirt || ""),
      equipped_pants_item: clampString(equipmentSlots.pants || ""),
      equipped_shoes_item: clampString(equipmentSlots.shoes || ""),
      equipped_ride_item: clampString(equipmentSlots.ride || ""),
    });
  }

  return result;
}

function broadcastSystemToWorld(worldName: any, message: any, excludePlayerId: any = "") {
  broadcastToWorld(worldName, {
    type: "chat",
    player_id: "system",
    name: "System",
    message,
    world: worldName,
  }, excludePlayerId);
}

function queuePlayerPositionBroadcast(worldName: any, message: any, excludePlayerId: any = "") {
  const clean = cleanWorld(worldName || message?.world || "START");
  const playerId = String(message?.player_id || excludePlayerId || "").trim();
  if (!clean || !playerId) return;

  let worldQueue: any = pendingPlayerPositionBroadcasts.get(clean);
  if (!worldQueue) {
    worldQueue = new Map();
    pendingPlayerPositionBroadcasts.set(clean, worldQueue);
  }

  worldQueue.set(playerId, {
    playerId,
    excludePlayerId: String(excludePlayerId || ""),
    message,
  });
  playerNetworkStats.queued_player_position_updates += 1;
  const profile = getAdaptivePlayerPositionBatchProfile(clean);
  const timerMs = Math.max(0, Math.trunc(Number(profile.interval_ms || PLAYER_POSITION_BROADCAST_INTERVAL_MS) || 0));
  if (timerMs <= 0) {
    const existingTimer = pendingPlayerPositionBroadcastTimers.get(clean);
    if (existingTimer) {
      clearTimeout(existingTimer);
      pendingPlayerPositionBroadcastTimers.delete(clean);
    }
    flushQueuedPlayerPositionBroadcasts(clean);
    return;
  }

  if (pendingPlayerPositionBroadcastTimers.has(clean)) return;

  const timer = setTimeout(() => {
    pendingPlayerPositionBroadcastTimers.delete(clean);
    flushQueuedPlayerPositionBroadcasts(clean);
  }, timerMs);
  if (typeof timer.unref === "function") timer.unref();
  pendingPlayerPositionBroadcastTimers.set(clean, timer);
}

function flushQueuedPlayerPositionBroadcasts(worldName: any) {
  const clean = cleanWorld(worldName || "START");
  const worldQueue = pendingPlayerPositionBroadcasts.get(clean);
  if (!worldQueue) return;

  pendingPlayerPositionBroadcasts.delete(clean);
  const batches: any = new Map();

  // One recipient-list build per flush, shared by every moving player, instead of two
  // rebuilds per mover. Delivery helpers re-check that each socket is open, so a snapshot
  // taken here stays correct even if a client disconnects mid-flush.
  const worldRecords = getWorldPlayerRecords(clean, { includeSocket: true });

  for (const entry of worldQueue.values()) {
    const player = players.get(entry.playerId);
    if (!player || !player.joined_world || cleanWorld(player.world || "START") !== clean) continue;
    queuePlayerPresenceToInterestedPlayers(player, entry.message, entry.excludePlayerId, batches, worldRecords);
    syncPlayerInterestForReceiver(getSocketByPlayerId(entry.playerId), player, clean, batches, worldRecords);
    syncDropInterestForReceiver(getSocketByPlayerId(entry.playerId), player, clean);
  }

  flushPlayerPositionBatches(batches);
}

function supportsWorldUpdateBatch(player: any) {
  return ServerPhase6Helpers.supportsWorldUpdateBatch(player);
}

function isDropWorldUpdatePayload(message: any) {
  return ServerPhase6Helpers.isDropWorldUpdatePayload(message);
}

function isDropRemoveWorldUpdatePayload(message: any) {
  return ServerPhase6Helpers.isDropRemoveWorldUpdatePayload(message);
}

function buildDropCreatePayload(drop: any, worldName: any) {
  return ServerPhase6Helpers.buildDropCreatePayload(drop, worldName);
}

function buildDropInterestCullPayload(drop: any, worldName: any) {
  return ServerPhase6Helpers.buildDropInterestCullPayload(drop, worldName);
}

function sendWorldUpdatePayloadsToSocket(socket: any, worldName: any, updates: any) {
  if (!socket || socket.readyState !== WebSocket.OPEN) return;
  const safeUpdates = Array.isArray(updates) ? updates.filter(Boolean) : [];
  if (safeUpdates.length === 0) return;

  const receiver = players.get(socket.playerId);
  if (!supportsWorldUpdateBatch(receiver) || safeUpdates.length === 1) {
    for (const update of safeUpdates) {
      sendJson(socket, update);
      worldNetworkStats.batch_fallback_individual_sends += 1;
    }
    return;
  }

  const clean = cleanWorld(worldName || receiver?.world || "START");
  const profile = getAdaptiveWorldUpdateBatchProfile(clean);
  const maxItems = clampBatchMaxItems(profile.max_items, WORLD_UPDATE_BATCH_MAX_ITEMS);
  for (let index: any = 0; index < safeUpdates.length; index += maxItems) {
    const batchUpdates = safeUpdates.slice(index, index + maxItems);
    sendJson(socket, {
      type: "world_update_batch",
      world: clean,
      updates: batchUpdates,
    });
    worldNetworkStats.batch_world_packets_sent += 1;
    worldNetworkStats.batch_world_items_sent += batchUpdates.length;
  }
}

function findDropStateForPayload(worldName: any, payload: any) {
  const cleanDropId = clampString(payload?.drop_id || payload?.id || "", MAX_DROP_ID_LENGTH);
  const state = ensureWorldState(worldName);
  if (cleanDropId !== "") {
    if (state.drops.has(cleanDropId)) return state.drops.get(cleanDropId);
    for (const drop of state.drops.values()) {
      if (getDropPublicId(drop) === cleanDropId) return drop;
    }
  }
  return payload;
}

function seedDropInterestForReceiverFromWorldState(receiver: any, worldName: any) {
  if (!isDropInterestManagementEnabled() || !receiver) return;
  const clean = cleanWorld(worldName || receiver.world || "START");
  clearDropInterestStateForReceiver(receiver.id);
  const state = ensureWorldState(clean);
  for (const drop of state.drops.values()) {
    const dropId = getDropPublicId(drop);
    if (dropId !== "" && shouldReceiverSeeDrop(receiver, drop, clean)) {
      setDropInterestVisible(receiver.id, dropId, true);
    }
  }
}

function syncDropInterestForReceiver(socket: any, receiver: any, worldName: any = "", force: any = false) {
  if (!socket || socket.readyState !== WebSocket.OPEN) return;
  if (!receiver || !receiver.joined_world) return;
  if (!isDropInterestManagementEnabled()) return;

  const clean = cleanWorld(worldName || receiver.world || "START");
  const now = Date.now();
  if (!force && DROP_INTEREST_SYNC_INTERVAL_MS > 0 && now - Number(receiver.last_drop_interest_sync_at || 0) < DROP_INTEREST_SYNC_INTERVAL_MS) {
    return;
  }
  receiver.last_drop_interest_sync_at = now;
  worldNetworkStats.drop_interest_syncs += 1;

  const updates: any = [];
  const state = ensureWorldState(clean);
  for (const drop of state.drops.values()) {
    const dropId = getDropPublicId(drop);
    if (dropId === "") continue;

    const shouldSee = shouldReceiverSeeDrop(receiver, drop, clean);
    const wasVisible = isDropMarkedInInterest(receiver.id, dropId);
    if (shouldSee && !wasVisible) {
      setDropInterestVisible(receiver.id, dropId, true);
      const payload = buildDropCreatePayload(drop, clean);
      if (payload) {
        updates.push(payload);
        worldNetworkStats.drop_interest_visible_deliveries += 1;
      }
    } else if (!shouldSee && wasVisible) {
      setDropInterestVisible(receiver.id, dropId, false);
      const payload = buildDropInterestCullPayload(drop, clean);
      if (payload) {
        updates.push(payload);
        worldNetworkStats.drop_interest_culls_sent += 1;
      }
    }
  }

  sendWorldUpdatePayloadsToSocket(socket, clean, updates);
}

function noteRequesterDropInterest(player: any, payload: any, worldName: any) {
  if (!isDropInterestManagementEnabled() || !player || !payload || !isDropWorldUpdatePayload(payload)) return;
  const clean = cleanWorld(worldName || payload.world || player.world || "START");
  const dropId = clampString(payload.drop_id || payload.id || "", MAX_DROP_ID_LENGTH);
  if (dropId === "") return;

  if (isDropRemoveWorldUpdatePayload(payload)) {
    setDropInterestVisible(player.id, dropId, false);
    return;
  }

  const drop = findDropStateForPayload(clean, payload);
  if (shouldReceiverSeeDrop(player, drop, clean)) {
    setDropInterestVisible(player.id, dropId, true);
  }
}

function deliverDropWorldUpdateToInterestedPlayers(worldName: any, message: any, excludePlayerId: any = "") {
  const clean = cleanWorld(worldName || message?.world || "START");
  const dropId = clampString(message?.drop_id || message?.id || "", MAX_DROP_ID_LENGTH);
  if (dropId === "") return;

  const isRemove = isDropRemoveWorldUpdatePayload(message);
  const drop = isRemove ? message : findDropStateForPayload(clean, message);

  // `message` does not vary by receiver -- serialize it once instead of per recipient.
  const rawMessage = serializeBroadcastPayloadOnce(message, "drop_world_update");
  if (rawMessage === null) return;
  const messageType = String(message?.type || "");

  for (const { player: receiver, socket: client } of getWorldPlayerRecords(clean, {
    includeSocket: true,
    excludePlayerId,
  })) {

    const wasVisible = isDropMarkedInInterest(receiver.id, dropId);
    if (isRemove) {
      if (!wasVisible) continue;
      setDropInterestVisible(receiver.id, dropId, false);
      sendRawJsonToSocket(client, rawMessage, "direct_send", { message_type: messageType });
      worldNetworkStats.drop_interest_culls_sent += 1;
      continue;
    }

    if (shouldReceiverSeeDrop(receiver, drop, clean)) {
      setDropInterestVisible(receiver.id, dropId, true);
      sendRawJsonToSocket(client, rawMessage, "direct_send", { message_type: messageType });
      worldNetworkStats.drop_interest_visible_deliveries += 1;
    } else if (wasVisible) {
      setDropInterestVisible(receiver.id, dropId, false);
      const cullPayload = buildDropInterestCullPayload({ ...drop, drop_id: dropId }, clean);
      if (cullPayload) {
        sendJson(client, cullPayload);
        worldNetworkStats.drop_interest_culls_sent += 1;
      }
    }
  }

  if (isRemove) clearDropInterestStateForDrop(dropId);
}

function queueWorldUpdateBroadcast(worldName: any, message: any, excludePlayerId: any = "") {
  const clean = cleanWorld(worldName || message?.world || "START");
  if (!message || typeof message !== "object" || Array.isArray(message)) {
    broadcastToWorld(clean, message, excludePlayerId);
    return;
  }
  if (
    String(message.type || "").toLowerCase() === "world_block_update" &&
    String(message.layer || "foreground").toLowerCase() === "foreground"
  ) {
    invalidateMovementCollisionCache(clean);
  }
  if (
    isDropInterestManagementEnabled() &&
    isDropWorldUpdatePayload(message) &&
    clampString(message?.drop_id || message?.id || "", MAX_DROP_ID_LENGTH) !== ""
  ) {
    deliverDropWorldUpdateToInterestedPlayers(clean, message, excludePlayerId);
    return;
  }
  if (!WORLD_UPDATE_BATCHING_ENABLED) {
    broadcastToWorld(clean, message, excludePlayerId);
    return;
  }

  let worldQueue: any = pendingWorldUpdateBroadcasts.get(clean);
  if (!worldQueue) {
    worldQueue = [];
    pendingWorldUpdateBroadcasts.set(clean, worldQueue);
  }

  worldQueue.push({
    excludePlayerId: String(excludePlayerId || ""),
    message,
  });
  worldNetworkStats.queued_world_updates += 1;

  if (pendingWorldUpdateBroadcastTimers.has(clean)) return;

  const profile = getAdaptiveWorldUpdateBatchProfile(clean);
  const timerMs = Math.max(0, Math.trunc(Number(profile.interval_ms || WORLD_UPDATE_BATCH_INTERVAL_MS) || 0));
  if (timerMs <= 0) {
    const existingTimer = pendingWorldUpdateBroadcastTimers.get(clean);
    if (existingTimer) {
      clearTimeout(existingTimer);
      pendingWorldUpdateBroadcastTimers.delete(clean);
    }
    flushQueuedWorldUpdateBroadcasts(clean);
    return;
  }

  const timer = setTimeout(() => {
    pendingWorldUpdateBroadcastTimers.delete(clean);
    flushQueuedWorldUpdateBroadcasts(clean);
  }, timerMs);
  if (typeof timer.unref === "function") timer.unref();
  pendingWorldUpdateBroadcastTimers.set(clean, timer);
}

function flushQueuedWorldUpdateBroadcasts(worldName: any) {
  const clean = cleanWorld(worldName || "START");
  const worldQueue = pendingWorldUpdateBroadcasts.get(clean);
  if (!worldQueue || worldQueue.length === 0) return;

  pendingWorldUpdateBroadcasts.delete(clean);

  // The batch payload is byte-identical for every receiver that shares an exclude id,
  // and in practice the queue carries only a handful of distinct exclude ids. Building
  // and serializing it once per receiver was O(players) redundant JSON.stringify calls
  // per flush (~62/s per world). Group by exclude id instead; the wire bytes are
  // unchanged, they are just computed once per group.
  // Sentinel for "this receiver is not the excluded actor of any queued update". It must
  // never compare === to a real excludePlayerId (including undefined/""), so it is an
  // object identity rather than a string.
  const NO_EXCLUDE_KEY = {};
  const excludedActorIds = new Set();
  for (const entry of worldQueue) {
    if (!entry?.message) continue;
    const excludeId = entry.excludePlayerId;
    if (excludeId !== undefined && excludeId !== null && excludeId !== "") excludedActorIds.add(excludeId);
  }

  const profile = getAdaptiveWorldUpdateBatchProfile(clean);
  const maxItems = clampBatchMaxItems(profile.max_items, WORLD_UPDATE_BATCH_MAX_ITEMS);
  const updatesByExcludeId = new Map();
  const rawBatchesByExcludeId = new Map();

  function getUpdatesForExcludeId(excludeId: unknown) {
    const cached = updatesByExcludeId.get(excludeId);
    if (cached) return cached;
    const updates = [];
    for (const entry of worldQueue) {
      if (!entry?.message) continue;
      if (excludeId === entry.excludePlayerId) continue;
      updates.push(entry.message);
    }
    updatesByExcludeId.set(excludeId, updates);
    return updates;
  }

  function getRawBatchesForExcludeId(excludeId: unknown) {
    const cached = rawBatchesByExcludeId.get(excludeId);
    if (cached) return cached;
    const updates = getUpdatesForExcludeId(excludeId);
    const batches = [];
    for (let index = 0; index < updates.length; index += maxItems) {
      const batchUpdates = updates.slice(index, index + maxItems);
      let raw;
      try {
        raw = JSON.stringify({
          type: "world_update_batch",
          world: clean,
          updates: batchUpdates,
        });
      } catch (error) {
        console.warn("[world_update_batch_serialize_error]", {
          world: clean,
          message: getErrorMessage(error),
        });
        continue;
      }
      batches.push({ raw, item_count: batchUpdates.length });
    }
    rawBatchesByExcludeId.set(excludeId, batches);
    return batches;
  }

  for (const { player: receiver, socket: client } of getWorldPlayerRecords(clean, { includeSocket: true })) {
    // Receivers that are not the actor of any queued update all share one payload.
    const excludeId = excludedActorIds.has(client.playerId) ? client.playerId : NO_EXCLUDE_KEY;

    if (!supportsWorldUpdateBatch(receiver)) {
      const updates = getUpdatesForExcludeId(excludeId);
      if (updates.length === 0) continue;
      for (const update of updates) {
        sendJson(client, update);
        worldNetworkStats.batch_fallback_individual_sends += 1;
      }
      continue;
    }

    for (const batch of getRawBatchesForExcludeId(excludeId)) {
      sendRawJsonToSocket(client, batch.raw, "direct_send", { message_type: "world_update_batch" });
      worldNetworkStats.batch_world_packets_sent += 1;
      worldNetworkStats.batch_world_items_sent += batch.item_count;
    }
  }

  for (const { playerId, socket: client } of getPendingWorldEntryPlayerRecords(clean)) {
    for (const entry of worldQueue) {
      if (!entry?.message || String(entry.message.type || "") !== "world_block_update") continue;
      if (String(playerId) === String(entry.excludePlayerId || "")) continue;
      sendJson(client, entry.message);
    }
  }
}

function broadcastToWorld(worldName: any, message: any, excludePlayerId: any = "") {
  const clean = cleanWorld(worldName || message?.world || "START");
  let raw;
  try {
    raw = JSON.stringify(message);
  } catch (error) {
    console.warn("[broadcast_serialize_error]", {
      world: clean,
      message: getErrorMessage(error),
    });
    return;
  }

  for (const { socket: client } of getWorldPlayerRecords(clean, { includeSocket: true, excludePlayerId })) {
    sendRawJsonToSocket(client, raw, "world_broadcast", {
      player_id: String(client.playerId || ""),
      world: clean,
      message_type: String(message?.type || ""),
    });
  }

  if (String(message?.type || "") === "world_block_update") {
    for (const { socket: client } of getPendingWorldEntryPlayerRecords(clean, { excludePlayerId })) {
      sendRawJsonToSocket(client, raw, "world_entry_catchup_broadcast", {
        player_id: String(client.playerId || ""),
        world: clean,
        message_type: "world_block_update",
      });
    }
  }
}

function broadcastToAuthenticatedPlayers(message: any, excludePlayerId: any = "") {
  let raw;
  try {
    raw = JSON.stringify(message);
  } catch (error) {
    console.warn("[broadcast_serialize_error]", {
      authenticated: true,
      message: getErrorMessage(error),
    });
    return;
  }

  for (const client of wss.clients) {
    if (client.readyState !== WebSocket.OPEN) continue;
    if (client.playerId === excludePlayerId) continue;

    const player = players.get(client.playerId);
    if (!player || !player.authenticated) continue;

    sendRawJsonToSocket(client, raw, "authenticated_broadcast", {
      player_id: String(client.playerId || ""),
      authenticated: true,
      message_type: String(message?.type || ""),
    });
  }
}

function flushPendingSaves(options: any = {}) {
  return ServerPhase11bLifecycle.flushPendingSaves(options);
}

function startPeriodicSaveScheduler() {
  return ServerPhase11bLifecycle.startPeriodicSaveScheduler();
}

function getWorldSnapshotSchedulerRunning() {
  return ServerPhase11bLifecycle.getWorldSnapshotSchedulerRunning();
}

function stopGameplaySchedulersForShutdown() {
  if (worldEventRandomTimer) {
    clearInterval(worldEventRandomTimer);
    worldEventRandomTimer = null;
  }
  if (oilRefineryTimer) {
    clearInterval(oilRefineryTimer);
    oilRefineryTimer = null;
  }
  if (batteryChargerTimer) {
    clearInterval(batteryChargerTimer);
    batteryChargerTimer = null;
  }
  if (chickenTimer) {
    clearInterval(chickenTimer);
    chickenTimer = null;
  }
  if (cowTimer) {
    clearInterval(cowTimer);
    cowTimer = null;
  }
  if (duckTimer) {
    clearInterval(duckTimer);
    duckTimer = null;
  }
  for (const session of activeWorldHonorVisits.values()) {
    if (session.timer) clearTimeout(session.timer);
  }
  activeWorldHonorVisits.clear();
  worldHonorTopCommandCooldowns.clear();
  for (const timer of worldEventTimers.values()) {
    clearTimeout(timer);
  }
  worldEventTimers.clear();
  for (const timers of worldEventCountdownTimers.values()) {
    if (Array.isArray(timers)) {
      for (const timer of timers) {
        clearTimeout(timer);
      }
    }
  }
  worldEventCountdownTimers.clear();
}

async function shutdown(signal: any = "") {
  return ServerPhase11bLifecycle.shutdown(signal);
}

function handleShutdownSignal(signal: any) {
  return ServerPhase11bLifecycle.handleShutdownSignal(signal);
}

ServerPhase11bLifecycle.installShutdownHandlers();
